window.EXAMS=[{"key": "tc101", "label": "101統測", "year": 101, "kind": "統測", "total": 38, "count": 15}, {"key": "tc102", "label": "102統測", "year": 102, "kind": "統測", "total": 38, "count": 12}, {"key": "tc103", "label": "103統測", "year": 103, "kind": "統測", "total": 38, "count": 13}, {"key": "tc104", "label": "104統測", "year": 104, "kind": "統測", "total": 38, "count": 15}, {"key": "tc105", "label": "105統測", "year": 105, "kind": "統測", "total": 38, "count": 13}, {"key": "tc106", "label": "106統測", "year": 106, "kind": "統測", "total": 38, "count": 12}, {"key": "tc107", "label": "107統測", "year": 107, "kind": "統測", "total": 38, "count": 11}, {"key": "tc108", "label": "108統測", "year": 108, "kind": "統測", "total": 38, "count": 12}, {"key": "tc109", "label": "109統測", "year": 109, "kind": "統測", "total": 38, "count": 12}, {"key": "tc110", "label": "110統測", "year": 110, "kind": "統測", "total": 38, "count": 12}, {"key": "tc111", "label": "111統測", "year": 111, "kind": "統測", "total": 38, "count": 9}, {"key": "tc112", "label": "112統測", "year": 112, "kind": "統測", "total": 38, "count": 10}, {"key": "tc113", "label": "113統測", "year": 113, "kind": "統測", "total": 38, "count": 10}, {"key": "tc114", "label": "114統測", "year": 114, "kind": "統測", "total": 38, "count": 10}, {"key": "tc115", "label": "115統測", "year": 115, "kind": "統測", "total": 38, "count": 8}];
window.ITEMS=[{"id": "tc101-01", "exam": "tc101", "nums": [1], "form": "單題", "img": "img/tc101-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "失其所與／吾誰與歸；未果，尋病終／尋蒙國恩；微夫人之力不及此／微管仲，吾其被髮左衽矣；親賢臣，遠小人／遠罪豐家", "translation": "「失其所與」：失去了結盟的對象。「吾誰與歸」：我要和誰一起同道呢？「未果，尋病終」：沒有成行，不久就病死了。「尋蒙國恩」：不久蒙受國家恩典。「微夫人之力不及此」：如果沒有那個人的力量，我到不了今天。「微管仲，吾其被髮左衽矣」：如果沒有管仲，我們恐怕要披散頭髮、衣襟左開（淪為夷狄）了。「親賢臣，遠小人」：親近賢臣，疏遠小人。「遠罪豐家」：遠離罪過，使家業豐厚。", "keywords": [{"w": "與", "m": "結交、同盟的對象（名詞）；和、跟（介詞）"}, {"w": "尋", "m": "不久"}, {"w": "微", "m": "如果沒有"}, {"w": "遠", "m": "使……遠離、疏遠"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列「」內的字，何者意義不相同？", "options": {"A": "失其所「與」／吾誰「與」歸", "B": "未果，「尋」病終／「尋」蒙國恩", "C": "「微」夫人之力不及此／「微」管仲，吾其被髮左衽矣", "D": "親賢臣，「遠」小人／「遠」罪豐家"}, "answer": "A", "explain": "(A)正確答案，前後意思不同。「失其所與」出自〈燭之武退秦師〉，「與」是名詞，指結盟、親附的對象；「吾誰與歸」出自〈岳陽樓記〉，「與」是介詞「和、跟」，整句是「我要和誰同道」。(B)兩個「尋」都是「不久」：〈桃花源記〉「未果，尋病終」、〈陳情表〉「尋蒙國恩」。(C)兩個「微」都是「如果沒有」：前句出自〈燭之武退秦師〉，後句出自《論語》。(D)兩個「遠」都當動詞，是「使……遠離、疏遠」：疏遠小人、遠離罪過。", "skill": "同一個字比較詞義時，先判斷它在句中的詞性：一邊是名詞、一邊是介詞，意思通常就不同。"}], "difficulty": "中", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-03", "exam": "tc101", "nums": [3], "form": "單題", "img": "img/tc101-03.png", "source": "賈誼〈過秦論〉", "author": "賈誼", "genre": "說理議論", "types": ["字詞解釋", "句意理解"], "passage": "信臣精卒，陳利兵而誰何。俛首係頸，委命下吏。謫戍之眾，非抗於九國之師也。行軍用兵之道，非及曩時之士也。", "translation": "秦派可靠的大臣、精銳的士兵，陳列銳利的兵器，盤查往來的行人。（六國君王）低頭用繩子繫住脖子投降，把性命交給秦的官吏處置。（陳涉）那群被罰去守邊的人，比不上九國的軍隊；他行軍用兵的方法，也比不上從前六國的謀士。", "keywords": [{"w": "誰何", "m": "盤問「是誰」，即呵問、盤查"}, {"w": "俛首係頸", "m": "低頭，用繩子綁住脖子，表示投降"}, {"w": "委命下吏", "m": "把性命交給獄吏處置"}, {"w": "抗", "m": "抗衡、匹敵"}, {"w": "曩時", "m": "從前"}], "questions": [{"n": 3, "qtype": "單選", "stem": "有關賈誼〈過秦論〉的語詞解釋，下列何者錯誤？", "options": {"A": "信臣精卒，「陳利兵而誰何」：面對勇猛的敵軍，該靠誰解圍", "B": "「俛首係頸，委命下吏」：低下頭來，將繩子套在頭上，將生命交付獄吏處置", "C": "謫戍之眾，非「抗」於九國之師也：抗衡、匹敵", "D": "行軍用兵之道，非及「曩時」之士也：從前"}, "answer": "A", "explain": "這段是秦統一天下後的防守布局，不是在說打敗仗。(A)錯，所以是答案。「誰何」是「呵問：是誰？」，整句指秦派親信、精兵陳列利器，盤查來往的人，跟「靠誰解圍」無關。(B)正確，六國君王低頭、以繩繫頸表示投降，把命交給秦的官吏。(C)正確，「抗」是抗衡、匹敵，說陳涉的戍卒比不上九國軍隊。(D)正確，「曩時」就是從前。", "skill": "「誰何」「何如」這類疑問詞放在動詞位置時常當動詞用；先看上下文是在守還是在逃，就能排除離題的解釋。"}], "difficulty": "中", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-04", "exam": "tc101", "nums": [4], "form": "單題", "img": "img/tc101-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "夕舂未下；夜縋而出；羽扇綸巾；鞭笞天下", "translation": "「夕舂未下」：夕陽還沒落下（袁宏道〈晚遊六橋待月記〉）。「夜縋而出」：夜裡用繩子把人從城牆上垂放下去（〈燭之武退秦師〉）。「羽扇綸巾」：手拿羽扇、頭戴青絲帶頭巾（蘇軾〈念奴嬌〉）。「鞭笞天下」：用武力奴役天下（賈誼〈過秦論〉）。", "keywords": [{"w": "舂", "m": "ㄔㄨㄥ，夕舂指夕陽"}, {"w": "縋", "m": "ㄓㄨㄟˋ，用繩子垂吊而下"}, {"w": "綸巾", "m": "綸讀ㄍㄨㄢ，青絲帶做的頭巾"}, {"w": "笞", "m": "ㄔ，用鞭、杖打"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列各組「」內的字音，何者正確？", "options": {"A": "夕「舂」未下：ㄔㄨㄣ", "B": "夜「縋」而出：ㄓㄨㄟˋ", "C": "羽扇「綸」巾：ㄌㄨㄣˊ", "D": "鞭「笞」天下：ㄊㄞˊ"}, "answer": "B", "explain": "(A)錯，「舂」讀ㄔㄨㄥ，和「春」只差一筆，別看錯字。(B)正確，「縋」讀ㄓㄨㄟˋ，燭之武就是被人用繩子從城上垂下去見秦伯。(C)錯，「綸巾」的綸讀ㄍㄨㄢ，指青絲帶頭巾；讀ㄌㄨㄣˊ是「經綸」「綸音」。(D)錯，「笞」讀ㄔ，「鞭笞」是鞭打；ㄊㄞˊ是「苔」「颱」的音。", "skill": "遇到形近字，先把字形看清楚（舂／春、笞／苔），再想它在課文裡的意思，破音字依詞義決定讀音。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-05", "exam": "tc101", "nums": [5], "form": "單題", "img": "img/tc101-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["人物情感", "比較閱讀", "詩詞賞析"], "passage": "今張君不以謫為患，竊會計之餘功，而自放山水之間，此其中宜有以過人者。（蘇轍〈黃州快哉亭記〉）", "translation": "如今張君不把被貶當作憂患，利用處理錢糧公務之外的空閒，在山水間自在遨遊，他心中一定有勝過常人的地方。", "keywords": [{"w": "謫", "m": "被貶官"}, {"w": "患", "m": "憂慮、禍患"}, {"w": "會計之餘功", "m": "處理錢穀公務之餘的空閒"}, {"w": "自放", "m": "自在放任、縱情"}], "questions": [{"n": 5, "qtype": "單選", "stem": "蘇轍〈黃州快哉亭記〉：「今張君不以謫為患，竊會計之餘功，而自放山水之間，此其中宜有以過人者。」文中的曠達自適心境與下列何者不同？", "options": {"A": "惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色。取之無禁，用之不竭，是造物者之無盡藏也，而吾與子之所共適(蘇軾〈赤壁賦〉)", "B": "采菊東籬下，悠然見南山。山氣日夕佳，飛鳥相與還。此中有真意，欲辨已忘言(陶潛〈飲酒〉)", "C": "賦命有厚薄，委心任窮通。通當為大鵬，舉翅摩蒼穹；窮則為鷦鷯，一枝足自容。苟知此道者，身窮心不窮(白居易〈我身〉)", "D": "自許封侯在萬里，有誰知，鬢雖殘，心未死(陸游〈夜遊宮〉)"}, "answer": "D", "explain": "題幹的張夢得被貶卻不憂，在山水中自得其樂，關鍵是「曠達自適」。(D)不同，所以是答案。陸游說自己本想立功萬里、封侯拜將，如今鬢髮已殘，報國之心卻還沒死，是壯志未酬的激昂與悲憤，不是放下得失的自適。(A)蘇軾說清風明月取之不盡，和朋友一起享受，是隨遇而安。(B)陶淵明採菊見山，心中悠然，是自在恬淡。(C)白居易說命運順逆都交給天，順時當大鵬，困時當小鳥，「身窮心不窮」，也是曠達。", "skill": "比較心境題，先替題幹貼一個標籤（如「曠達」），再逐項找情緒字：「悠然」「共適」屬放下，「心未死」「自許封侯」屬執著。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-06", "exam": "tc101", "nums": [6], "form": "單題", "img": "img/tc101-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "經典語錄", "types": ["文意推論", "比較閱讀"], "passage": "老有所終，壯有所用，幼有所長，鰥寡孤獨廢疾者皆有所養。（《禮記‧禮運》）", "translation": "讓老人能安享天年，壯年人能發揮所長，孩子能好好成長；喪妻的、喪夫的、失去父母的、沒有子女的，以及身障、生病的人，都能得到照顧。", "keywords": [{"w": "鰥寡孤獨", "m": "老而無妻、老而無夫、幼而無父、老而無子"}, {"w": "廢疾", "m": "身體殘障或有重病"}, {"w": "顛連而無告", "m": "困苦流離而無處申訴"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列各組的文意，何者與《禮記．禮運》：「老有所終，壯有所用，幼有所長，鰥寡孤獨廢疾者皆有所養。」的社會福利理念不同？", "options": {"A": "尊高年，所以長其長；慈孤弱，所以幼其幼。凡天下疲癃、殘疾、惸獨、鰥寡，皆吾兄弟之顛連而無告者也(張載〈西銘〉)", "B": "老吾老，以及人之老；幼吾幼，以及人之幼，天下可運於掌(《孟子．梁惠王》)", "C": "甘其食，美其服，安其居，樂其俗。鄰國相望，雞犬之聲相聞，民至老死不相往來(《老子》)", "D": "老者安之，朋友信之，少者懷之(《論語．公冶長》)"}, "answer": "C", "explain": "〈禮運〉的重點是「照顧每一種人，尤其是弱勢」。(C)不同，所以是答案。老子描寫小國寡民的理想：人民吃得香、穿得美、住得安，國與國老死不相往來，講的是簡樸自足、少欲無為，沒有提到照顧老幼與弱勢。(A)張載說尊敬老人、慈愛孤弱，把天下病殘孤寡都當成自己受苦的兄弟，跟〈禮運〉一致。(B)孟子要人把孝敬自家長輩、疼愛自家孩子的心推到別人身上，也是照顧老幼。(D)孔子的志向是讓老人安樂、朋友信任、年輕人得到關懷，同樣是照顧各年齡層。", "skill": "「理念相同與否」題，先抓題幹的關鍵對象（老、幼、弱勢），再看選項有沒有出現同樣的對象和「照顧」的動作。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-09", "exam": "tc101", "nums": [9], "form": "單題", "img": "img/tc101-09.png", "source": "出處待查", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "甲、明看企業精機杼／和以生財織錦雲\n乙、妙技發揮鑲造瓠犀年返少／奇功施展整修編貝齒生春\n丙、育種培苗蔥蘢萬樹呈詩意／防洪抗旱聳峙層巒蘊水源", "translation": "甲：企業靠精良的織布機，和氣生財，織出如錦似雲的布料。乙：妙手鑲補像瓠瓜籽般整齊的牙齒，讓人重返年少；修整如編排貝殼般的牙齒，讓人笑口生春。丙：培育樹苗，讓萬樹蒼翠充滿詩意；林木能防洪抗旱，使層層山巒涵養水源。", "keywords": [{"w": "機杼", "m": "織布機（杼是梭子）"}, {"w": "瓠犀", "m": "瓠瓜的籽，比喻潔白整齊的牙齒"}, {"w": "編貝", "m": "排列整齊的貝殼，比喻牙齒"}, {"w": "蔥蘢", "m": "草木青翠茂盛"}], "questions": [{"n": 9, "qtype": "單選", "stem": "下列對聯內容，依序可適用於哪些行業？甲、明看企業精機杼／和以生財織錦雲　乙、妙技發揮鑲造瓠犀年返少／奇功施展整修編貝齒生春　丙、育種培苗蔥蘢萬樹呈詩意／防洪抗旱聳峙層巒蘊水源", "options": {"A": "紡織業／牙醫業／林業", "B": "電子業／美容業／農業", "C": "銀行業／牙醫業／水利業", "D": "精算業／美容業／園藝業"}, "answer": "A", "explain": "對聯題就是找「行業關鍵字」。甲有「機杼」「織錦」，是紡織業。乙有「瓠犀」「編貝」「齒」，都是牙齒的代稱，加上「鑲造」「整修」，是牙醫業。丙有「育種培苗」「萬樹」「蘊水源」，是種樹造林、涵養水源的林業。所以(A)正確。(B)電子業、美容業、農業：甲看不出電子，乙是補牙不是美容。(C)銀行業只抓到「生財」卻忽略「機杼」；丙主角是「萬樹」，不是水利工程。(D)精算業、美容業、園藝業都對不上甲、乙；丙講的是防洪蓄水的山林，不是庭園花木。", "skill": "行業對聯先圈名詞（機杼、齒、樹），名詞比形容詞更能決定行業；「生財」這種吉祥話每行都用，不能當依據。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-12", "exam": "tc101", "nums": [12], "form": "單題", "img": "img/tc101-12.png", "source": "《禮記‧禮運》", "author": "", "genre": "經典語錄", "types": ["字詞解釋"], "passage": "今大道既隱，天下為家，各親其親，各子其子，貨力為己。大人世及以為禮，城郭溝池以為固，禮義以為紀。", "translation": "如今大道已經隱沒，天下成為一家一姓的私產，人人只親愛自己的父母，只疼愛自己的子女，財物和力氣都只為自己。天子諸侯父子相傳、兄弟相繼成為制度，靠城牆和護城河來鞏固防守，用禮義作為綱紀。", "keywords": [{"w": "隱", "m": "隱沒、消失"}, {"w": "貨力為己", "m": "財貨、勞力都為了自己"}, {"w": "世及", "m": "父傳子為世，兄傳弟為及"}, {"w": "固", "m": "堅固的防守"}, {"w": "紀", "m": "綱紀、準則"}], "questions": [{"n": 12, "qtype": "單選", "stem": "閱讀下文，共有幾個錯別字？今大道既穩，天下為家，各親其親，各子其子，貨利為己。大人世及以為理，城郭溝池以為故，禮義以為紀。(〈大同與小康〉)", "options": {"A": "2個", "B": "3個", "C": "4個", "D": "5個"}, "answer": "C", "explain": "共有4個錯字，答案(C)。①「既穩」應作「既隱」：大道「隱沒」了，不是「穩定」。②「貨利為己」應作「貨力為己」：對照大同段的「貨惡其棄於地」「力惡其不出於身」，這裡是財貨和勞力都只為自己。③「以為理」應作「以為禮」：世襲制度被當成「禮制」。④「以為故」應作「以為固」：城牆溝池是用來「鞏固」防守的。其餘「天下為家」「各親其親」「各子其子」「禮義以為紀」都正確。所以(A)2個、(B)3個、(D)5個都不對。", "skill": "文言改錯字，用「意思通不通」來檢查每個關鍵字，並拿大同段與小康段對照，前後文常常互相呼應。"}], "difficulty": "中", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-14", "exam": "tc101", "nums": [14], "form": "單題", "img": "img/tc101-14.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "君王為人不忍。若入，前為壽，壽畢，請以劍舞，因擊沛公於坐。（司馬遷〈鴻門宴〉）復入深林中，林木蓊翳，大小不可辨名。老藤纏結其上，若虬龍環繞。（郁永河〈北投硫穴記〉）", "translation": "「君王為人不忍。若入……」：大王為人心軟。你進去，上前敬酒，敬完酒，請求舞劍，趁機把沛公殺死在座位上。「老藤纏結其上，若虬龍環繞」：老藤纏繞在樹上，好像蜷曲的龍盤繞著。", "keywords": [{"w": "若", "m": "你（代詞）；好像；如果"}, {"w": "為壽", "m": "敬酒祝壽"}, {"w": "蓊翳", "m": "草木茂密遮蔽"}], "questions": [{"n": 14, "qtype": "單選", "stem": "下列各句中的「若」字，可以解釋為「如果」者，共有幾個？", "options": {"A": "1個", "B": "2個", "C": "3個", "D": "4個"}, "answer": "A", "explain": "只有丙一句是「如果」，答案(A)。甲〈鴻門宴〉是范增對項莊說話，「若入」的「若」是代詞「你」：你進去敬酒。乙〈錯誤〉「恰若青石的街道」是「好像」。丙〈數字人生〉「百年後若有人考證」是「如果」，對。丁〈北投硫穴記〉「若虬龍環繞」是「好像」。所以只有1個，(B)(C)(D)都多算了。", "skill": "「若」字三大意思：你、好像、如果。把「如果」代進去讀不通（如「如果進去」顯得沒有主語），就換「你」試試。"}], "difficulty": "中", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-15", "exam": "tc101", "nums": [15], "form": "單題", "img": "img/tc101-15.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "甲、安能以身之察察，受物之汶汶者乎（屈原〈漁父〉）\n乙、無冥冥之志者，無昭昭之明；無惛惛之事者，無赫赫之功（荀子〈勸學〉）\n丙、鋤耰棘矜，非銛於鉤戟長鎩也（賈誼〈過秦論〉）\n丁、殺人如不能舉，刑人如恐不勝（司馬遷〈鴻門宴〉）", "translation": "甲：怎能讓自己潔白的身體，去沾染外物的污濁呢？乙：沒有專心致志的心志，就不會有明白通達的智慧；沒有埋頭苦幹的實踐，就不會有顯赫的功績。丙：（陳涉軍隊的）鋤頭、木柄，並不比鉤戟長矛鋒利。丁：（秦王）殺人好像怕殺不完，用刑好像怕用不盡。", "keywords": [{"w": "察察", "m": "潔白的樣子"}, {"w": "汶汶", "m": "污濁的樣子"}, {"w": "冥冥、惛惛", "m": "專心致志、默默用功的樣子"}, {"w": "舉、勝", "m": "盡、完"}, {"w": "銛", "m": "鋒利"}], "questions": [{"n": 15, "qtype": "單選", "stem": "下列各組文句中，何者前後「」中使用不同的字詞，但彼此意思卻相同？甲、安能以身之「察察」，受物之「汶汶」者乎　乙、無「冥冥」之志者，無昭昭之明；無「惛惛」之事者，無赫赫之功　丙、「鋤耰棘矜」，非銛於「鉤戟長鎩」也　丁、殺人如不能「舉」，刑人如恐不「勝」", "options": {"A": "甲丙", "B": "丙丁", "C": "乙丙", "D": "乙丁"}, "answer": "D", "explain": "乙、丁兩組意思相同，答案(D)。乙：「冥冥」「惛惛」都是專心、默默下苦功的樣子，用不同的疊字避免重複。丁：「舉」和「勝」都是「盡」，殺人怕殺不完、用刑怕用不盡。甲：「察察」是潔白，「汶汶」是污濁，意思相反。丙：「鋤耰棘矜」是農具和木柄，「鉤戟長鎩」是正規兵器，一粗一精，正好對比。所以有甲或丙的(A)(B)(C)都錯。", "skill": "對句中兩個位置相當的詞，先看是「換字同義」（避免重複）還是「刻意對比」；句子在講「A不如B」或「怎能用A受B」時，多半是對比。"}], "difficulty": "中", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-17", "exam": "tc101", "nums": [17], "form": "單題", "img": "img/tc101-17.png", "source": "書信提稱語（應用文）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "某某法師法鑒；某某夫子函丈；某某賢棣英鑒；某某金孫大鑒", "translation": "「法鑒」：請法師過目，用於宗教人士。「函丈」：請老師過目，用於師長。「英鑒」：請英明的您過目，用於平輩或同學。「大鑒」：請您過目，用於平輩。", "keywords": [{"w": "提稱語", "m": "書信開頭稱呼後面，請對方察閱的敬詞"}, {"w": "函丈", "m": "對老師用的提稱語"}, {"w": "賢棣", "m": "對學生、晚輩的稱呼"}, {"w": "如晤、知悉", "m": "對晚輩用的提稱語"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列選項中的書信提稱語(知照敬詞)，何者應用錯誤？", "options": {"A": "某老師寫信給某道士：「某某法師法鑒」", "B": "男學生寫信給男老師：「某某夫子函丈」", "C": "老師寫信給已畢業的男學生：「某某賢棣英鑒」", "D": "祖父寫信給讀大學的孫子：「某某金孫大鑒」"}, "answer": "D", "explain": "提稱語要看收信人和自己的輩分關係。(D)錯，所以是答案。祖父寫給孫子是長輩寫給晚輩，應用「如晤」「如面」「知悉」「收覽」這類詞；「大鑒」是平輩用語，祖父對孫子用就像把孫子抬成同輩，不恰當。(A)正確，寫給宗教人士用「法鑒」。(B)正確，對老師用「函丈」。(C)正確，學生已畢業成年，老師稱「賢棣」並用平輩的「英鑒」，表示客氣尊重。", "skill": "書信用語先畫輩分箭頭：寫給長輩用「尊鑒、函丈」，平輩用「大鑒、台鑒、英鑒」，晚輩用「如晤、知悉」；箭頭方向錯了，用語就錯。"}], "difficulty": "中", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-18", "exam": "tc101", "nums": [18], "form": "單題", "img": "img/tc101-18.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文化常識", "字詞解釋"], "passage": "甲、凡我多士及我友朋，惟仁惟孝，義勇奉公，以發揚種性，此則不佞之幟也（連橫〈臺灣通史序〉）\n乙、思厥先祖父，暴霜露，斬荊棘，以有尺寸之地。子孫視之不甚惜，舉以予人，如棄草芥（蘇洵〈六國論〉）\n丙、秦、晉圍鄭，鄭既知其亡矣。若亡鄭而有益於君，敢以煩執事（《左傳‧燭之武退秦師》）\n丁、有風颯然至者，王披襟當之，曰：快哉此風！寡人所與庶人共者耶（蘇轍〈黃州快哉亭記〉）", "translation": "甲：凡是我們的眾多賢士與朋友，要行仁盡孝、見義勇為、奉獻公眾，來發揚民族精神，這就是我的心願。乙：想想他們的先人，冒著風霜雨露、披荊斬棘，才有這一點點土地；子孫卻不怎麼珍惜，整片拿去送人，像丟掉小草一樣。丙：秦、晉包圍鄭國，鄭國已經知道要亡了；如果滅了鄭對您有好處，那就冒昧麻煩您的手下吧。丁：一陣風颯颯吹來，楚王敞開衣襟迎風說：「這風真暢快！這是我和百姓共享的吧！」", "keywords": [{"w": "不佞", "m": "不才，自謙詞"}, {"w": "先祖父", "m": "已故的祖先，尊稱"}, {"w": "執事", "m": "辦事的人；不敢直指對方，用來敬稱對方"}, {"w": "寡人", "m": "寡德之人，君王自謙"}], "questions": [{"n": 18, "qtype": "單選", "stem": "下列文句「」中的語詞，共有幾個不是自謙詞？", "options": {"A": "1個", "B": "2個", "C": "3個", "D": "4個"}, "answer": "B", "explain": "不是自謙詞的有乙、丙兩個，答案(B)。甲「不佞」是「沒有才能」，連橫謙稱自己，是自謙詞。乙「先祖父」是對已過世祖先的稱呼，帶有尊敬，不是自謙。丙「執事」是燭之武不敢直接說「您」，改說「您手下辦事的人」，是敬稱對方，不是自謙。丁「寡人」是「寡德之人」，楚王自稱，是自謙詞。所以(A)(C)(D)數量都不對。", "skill": "判斷謙敬詞，先問「這個詞指的是誰」：指自己的多半是謙詞，指對方或祖先的多半是敬詞。"}], "difficulty": "中", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-19", "exam": "tc101", "nums": [19], "form": "單題", "img": "img/tc101-19.png", "source": "《世說新語‧任誕》", "author": "劉義慶", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "王子猷居山陰，夜大雪，眠覺，開室，命酌酒。四望皎然，因起彷徨，詠左思〈招隱〉詩。忽憶戴安道，時戴在剡，即便夜乘小船就之。經宿方至，造門不前而返。人問其故，王曰：「吾本乘興而來，興盡而返，何必見戴？」", "translation": "王子猷住在山陰，有一夜下大雪，他睡醒了，打開房門，叫人倒酒。四處望去一片潔白，於是起身徘徊，吟詠左思的〈招隱〉詩。忽然想起戴安道，那時戴住在剡縣，他就連夜坐小船去找他。坐了一整夜才到，到了門口卻不進去就回來了。有人問他原因，王子猷說：「我本來是趁著興致去的，興致沒了就回來，何必一定要見到戴安道呢？」", "keywords": [{"w": "眠覺", "m": "睡醒"}, {"w": "皎然", "m": "潔白明亮"}, {"w": "就", "m": "前往、接近"}, {"w": "經宿", "m": "經過一夜"}, {"w": "造門", "m": "到了門前"}], "questions": [{"n": 19, "qtype": "單選", "stem": "閱讀下文，關於王子猷行事風格的形容，下列何者正確？", "options": {"A": "虎頭蛇尾", "B": "擇善固執", "C": "求真務實", "D": "隨興自得"}, "answer": "D", "explain": "關鍵句是「乘興而來，興盡而返」：他做事只看心情，重在過程的興致，不在結果。(D)隨興自得，正確。(A)虎頭蛇尾是開始很起勁、後來草草了事，帶有負面評價；王子猷是主動選擇「興盡就回」，並不是做不下去。(B)擇善固執是選定正確的事堅持到底，他反而是說走就走、說回就回。(C)求真務實是講究實際成果，他連人都沒見，談不上務實。", "skill": "人物形容題直接找人物自己說的話當證據（這裡的「乘興而來，興盡而返」），再挑意思最貼近、又沒加上多餘褒貶的成語。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-27", "exam": "tc101", "nums": [27, 28, 29], "form": "題組", "img": "img/tc101-27.png", "source": "孫光憲《北夢瑣言》卷五", "author": "孫光憲", "genre": "筆記小品", "types": ["字詞解釋", "文意推論", "主旨寓意"], "passage": "唐大中初，盧攜舉進士，風貌不揚，語亦不正，呼「攜」為「彗」，蓋短舌也。韋氏昆弟皆輕侮之，獨韋岫尚書加欽，謂其昆弟曰：「盧雖人物甚陋，觀其文章有首尾，斯人也，以是卜之，他日必為大用乎！」爾後盧果策名，竟登廊廟，獎拔京兆，至福建觀察使。向時輕薄諸弟，率不展分。所謂以貌失人者，其韋諸季乎！", "translation": "唐宣宗大中初年，盧攜去考進士，他長相平凡，說話也不標準，把「攜」唸成「彗」，大概是舌頭短的緣故。韋家兄弟都瞧不起他，只有後來當到尚書的韋岫特別敬重他，對兄弟們說：「盧攜雖然外貌很醜，但看他的文章條理分明、有頭有尾，這個人，從這一點來推斷，將來一定會被重用！」後來盧攜果然考上進士，最後當上宰相，提拔了韋岫，讓他做到福建觀察使。至於當年輕視盧攜的韋家兄弟，大都沒有得到發展。所謂「以貌取人而看錯人」，說的就是韋家這幾位弟弟吧！", "keywords": [{"w": "風貌不揚", "m": "相貌平凡不出眾"}, {"w": "呼", "m": "發音、唸"}, {"w": "昆弟", "m": "兄弟"}, {"w": "加欽", "m": "格外敬重"}, {"w": "策名", "m": "科舉登第、名列仕籍"}, {"w": "廊廟", "m": "朝廷，指宰相等高位"}, {"w": "率不展分", "m": "大都沒有得到發展"}, {"w": "諸季", "m": "幾個弟弟"}], "questions": [{"n": 27, "qtype": "單選", "stem": "文中「呼攜為彗」的「呼」字，意思為何？", "options": {"A": "呼吸", "B": "發音", "C": "命令", "D": "說明"}, "answer": "B", "explain": "前一句說他「語亦不正」，後一句說「蓋短舌也」，都在講說話咬字，所以「呼攜為彗」是把「攜」唸成「彗」，「呼」是發音，(B)正確。(A)呼吸和唸字無關。(C)命令是「呼喚、使喚」，句中沒有人被叫去做事。(D)說明是解釋事情，不合「把甲字唸成乙字」的句型。", "skill": "字義題把選項代回原句，再看前後句在講什麼主題（這裡是咬字），最貼近主題的就是答案。"}, {"n": 28, "qtype": "單選", "stem": "依據上文，「登廊廟」意思為何？", "options": {"A": "出使國外", "B": "追求名利", "C": "出任高官", "D": "擔任祭祀主祭"}, "answer": "C", "explain": "「廊廟」是朝廷殿堂，引申指朝廷中的高位；前面說「策名」（考上進士），後面說他能「獎拔」別人當觀察使，可見他已身居要職，所以「登廊廟」是出任高官（盧攜後來當到宰相），(C)正確。(A)文中沒有出使外國。(B)「追求」是還沒得到，「竟登」是已經登上，而且不是在講名利心。(D)「廟」在這裡不是宗廟祭祀，而是「廟堂」朝廷。", "skill": "「廊廟」「廟堂」「魏闕」都是朝廷的代稱，看到就聯想到「當大官」。"}, {"n": 29, "qtype": "單選", "stem": "依據上文，下列成語何者適合形容韋岫本人？", "options": {"A": "玉樹臨風", "B": "一表堂堂", "C": "慧眼獨具", "D": "器宇軒昂"}, "answer": "C", "explain": "眾兄弟都看不起盧攜，只有韋岫從文章看出他的才能，並預言他將被重用，後來果然應驗，這是有眼光、能識人，(C)慧眼獨具正確。(A)玉樹臨風、(B)一表堂堂、(D)器宇軒昂都是形容外貌或風度出眾，文章沒有描寫韋岫的長相；而且本文正是在批評只看外表的人，用外貌成語形容韋岫，方向就錯了。", "skill": "選成語形容人物時，先找文中這個人「做了什麼」，再找描述那個行為的成語；外貌類成語若文中沒寫外貌，一律先刪。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-33", "exam": "tc101", "nums": [33, 34, 35], "form": "題組", "img": "img/tc101-33.png", "source": "林紓《畏廬文集‧湖之魚》", "author": "林紓", "genre": "筆記小品", "types": ["主旨寓意", "文意推論", "寫作手法"], "passage": "林子啜茗於湖濱之肆。叢柳蔽窗，湖水皆黯碧若染，小魚百數，來會其下。戲嚼豆脯唾之，群魚爭喋，然隨喋隨逝，繼而存者，三四魚焉。再唾之，墜綴葑草之上，不食矣。始謂魚之逝者，皆飽也，尋丈之外，水紋攢動，爭喋他物如故。余方悟釣者之將下鉤，必先投食以引之，魚圖食而并吞鉤，久乃知凡下食者，皆將有鉤矣。然則名利之藪，獨無鉤乎？不及其盛下食之時而去之，其能脫鉤而逝者，幾何也？", "translation": "我在湖邊的茶館喝茶。成片的柳樹遮住窗子，湖水深綠得像染過一樣，上百條小魚聚集在窗下。我隨手把嚼過的豆乾吐給牠們，魚群搶著吃，可是一邊吃一邊游走，最後留下來的只有三四條。我再吐一次，豆乾掉在茭白草上，魚就不吃了。我起初以為游走的魚都吃飽了，沒想到一兩丈外，水紋聚集翻動，牠們照樣在搶食別的東西。我這才明白：釣魚的人要下鉤前，一定先撒餌引魚，魚貪吃就連鉤一起吞下；時間久了，魚就知道凡是有人丟食物，背後一定有鉤。這麼說來，名利聚集的地方，難道就沒有鉤嗎？如果不趁餌食撒得正多的時候離開，能脫鉤逃走的又有幾個呢？", "keywords": [{"w": "啜茗", "m": "喝茶"}, {"w": "肆", "m": "店鋪，這裡指茶館"}, {"w": "喋", "m": "魚、鳥吃東西"}, {"w": "尋丈", "m": "八尺為尋，十尺為丈，指不遠處"}, {"w": "攢動", "m": "聚集晃動"}, {"w": "藪", "m": "聚集之地"}, {"w": "幾何", "m": "多少"}], "questions": [{"n": 33, "qtype": "單選", "stem": "關於上文的意旨，下列何者正確？", "options": {"A": "羨慕游魚在水中自由自在，無憂無慮", "B": "享受在湖邊喝茶賞魚的休閒生活樂趣", "C": "感慨世人不知躲避爭名逐利的誘餌", "D": "慨嘆群魚優遊自得，卻難逃被捕的命運"}, "answer": "C", "explain": "主旨在最後的議論：「名利之藪，獨無鉤乎？」作者由魚懂得避開餌食，反過來感慨人在名利場中卻不懂得躲鉤，(C)正確。(A)魚不是無憂無慮，牠們是吃過虧才學會警覺。(B)喝茶賞魚只是開頭的情境，不是重點。(D)文中的魚反而懂得「隨喋隨逝」避開危險，並不是難逃被捕；而且重點是人，不是魚。", "skill": "「先敘後議」的文章，主旨幾乎都在最後的議論句，先看結尾的反問句。"}, {"n": 34, "qtype": "單選", "stem": "「不及其盛下食之時而去之，其能脫鉤而逝者，幾何也？」具有下列何種啟發意義？", "options": {"A": "放棄名利、甘於歸隱的人，令人不解", "B": "追逐名利的人，應要來者不拒，才能壯大", "C": "善於逢迎阿諛的人，為數眾多", "D": "追逐名利的人，應要懂得急流勇退"}, "answer": "D", "explain": "這句是說：若不趁誘餌正多（最得意）的時候抽身離開，能脫鉤的人沒幾個。意思是要在名利最盛時及時退出，(D)急流勇退正確。就像職場上，最風光時最容易被利益綁住，懂得見好就收才安全。(A)作者是肯定退隱，不是覺得不解。(B)來者不拒正好是吞鉤的魚。(C)文中沒有談逢迎拍馬。", "skill": "反問句「其能……者，幾何也？」等於「沒幾個能……」，把反問轉成肯定句，啟示就出來了。"}, {"n": 35, "qtype": "單選", "stem": "本文寫作的開展順序，下列何者正確？", "options": {"A": "先議後敘", "B": "先敘後議", "C": "全文皆敘", "D": "全文皆議"}, "answer": "B", "explain": "從「林子啜茗」到「爭喋他物如故」都是敘述喝茶餵魚的經過；從「余方悟」開始才由魚聯想到名利，提出看法。先說事、後說理，(B)正確。(A)順序顛倒。(C)後半有明顯議論。(D)前半是敘事。", "skill": "找「悟」「乃知」「然則」這類轉折字，它們通常是敘事轉議論的分界點。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc101-36", "exam": "tc101", "nums": [36, 37, 38], "form": "題組", "img": "img/tc101-36.png", "source": "《韓非子‧喻老》", "author": "韓非", "genre": "說理議論", "types": ["主旨寓意", "字詞解釋", "文意推論"], "passage": "有形之類，大必起於小；行久之物，族必起於少。故曰：「天下之難事必作於易，天下之大事必作於細。」是以欲制物者，於其細也。故曰：「圖難於其易也，為大於其細也。」千丈之堤以螻蟻之穴潰，百尺之室以突隙之煙焚。故曰：白圭之行堤也塞其穴，丈人之慎火也塗其隙。是以白圭無水難，丈人無火患。此皆慎易以避難，敬細以遠大者也。", "translation": "凡是有形體的東西，大的一定從小的開始；能長久存在的事物，眾多一定從少量開始。所以說：「天下的難事一定從容易的地方開始，天下的大事一定從細微的地方開始。」因此想要控制事物，要從它細微的時候著手。所以說：「要解決難事，就趁它還容易時處理；要做大事，就從細節做起。」千丈長的堤防，會因為螻蛄螞蟻的小洞而崩潰；百尺高的房屋，會因為煙囪縫隙冒出的火星而燒毀。所以白圭巡視堤防時會堵住小洞，老人防火時會塗好煙囪的裂縫。因此白圭沒有水災，老人沒有火災。這都是謹慎對待容易的事來避免困難，重視細節來遠離大禍的做法。", "keywords": [{"w": "族", "m": "聚集、眾多"}, {"w": "作", "m": "開始、興起"}, {"w": "制", "m": "控制、處理"}, {"w": "突", "m": "煙囪"}, {"w": "行堤", "m": "巡視堤防"}, {"w": "丈人", "m": "老人"}, {"w": "遠", "m": "使……遠離"}], "questions": [{"n": 36, "qtype": "單選", "stem": "下列何者不符合本文意旨？", "options": {"A": "牛驥同一皁，雞棲鳳凰食", "B": "蠹眾而木折，隙大而牆壞", "C": "天下之事，常發於至微，而終為大患", "D": "曲突徙薪，防患於未然"}, "answer": "A", "explain": "本文主旨是「防微杜漸、慎小避大」。(A)不符合，所以是答案。這句出自文天祥〈正氣歌〉，說牛和千里馬同槽吃草、雞和鳳凰同窩，是比喻賢愚混雜，跟防微杜漸無關。(B)蛀蟲多了樹會斷，裂縫大了牆會倒，說明小問題累積成大禍，符合。(C)天下的事常從極細微處開始，最後變成大禍，符合。(D)把煙囪改彎、把柴火移開，事先預防火災，符合「丈人之慎火」。", "skill": "意旨題先用一句話總結本文（例如「小洞不補，大洞吃苦」），再看選項是否也在講「小→大」的因果。"}, {"n": 37, "qtype": "單選", "stem": "「有形之類，大必起於小；行久之物，族必起於少。」其意思與下列何者相近？", "options": {"A": "不計得失", "B": "集腋成裘", "C": "知難行易", "D": "三思而行"}, "answer": "B", "explain": "原句說大的由小的累積、多的由少的聚成。(B)集腋成裘：收集許多狐狸腋下的小塊白毛，才能縫成一件皮衣，正是積少成多，正確。(A)不計得失是不在乎利害。(C)知難行易是孫中山的學說，指懂道理難、實行容易。(D)三思而行是做事要謹慎考慮，雖然和「慎」有關，但這句的重點是「由小積大」。", "skill": "找出原句的核心結構（小→大、少→多），再找結構相同的成語。"}, {"n": 38, "qtype": "單選", "stem": "下列「」中的字，何者意義兩兩相同？", "options": {"A": "「族」必起於少／抄家滅「族」", "B": "圖難於其「易」／寒暑「易」節", "C": "百尺之室以「突」隙之煙焚／曲「突」徙薪", "D": "敬細以「遠」大／言近旨「遠」"}, "answer": "C", "explain": "(C)兩個「突」都是煙囪，正確：「突隙」是煙囪的裂縫，「曲突」是把煙囪改彎。(A)前者是聚集、眾多；後者是家族。(B)前者是容易；後者是改變、交替（寒暑交替）。(D)前者是動詞「使遠離」；後者是形容詞「深遠」。", "skill": "兩兩比較字義時，把同一個解釋分別代入兩句，兩邊都通才算相同。"}], "difficulty": "易", "label": "101統測", "year": 101, "kind": "統測"}, {"id": "tc102-03", "exam": "tc102", "nums": [3], "form": "單題", "img": "img/tc102-03.png", "source": "徐霞客〈遊黃山日記〉", "author": "徐霞客", "genre": "山水遊記", "types": ["虛詞句式", "句意理解"], "passage": "戊午九月初三日，出白岳榔梅庵，至桃源橋。從小橋右下，陡甚，即舊向黃山路也。七十里，宿江村。", "translation": "戊午年九月初三，我從白岳山的榔梅庵出發，到達桃源橋。從小橋右邊往下走，路非常陡，這就是從前去黃山走的那條路。走了七十里，晚上住在江村。", "keywords": [{"w": "出", "m": "離開、出發"}, {"w": "至", "m": "到達"}, {"w": "從", "m": "由、經由"}, {"w": "即", "m": "就是"}], "questions": [{"n": 3, "qtype": "單選", "stem": "「戊午九月初三日，□白岳榔梅庵，□桃源橋。□小橋右下，陡甚，□舊向黃山路也。七十里，宿江村。」(徐霞客〈遊黃山日記〉)文中依序缺空的字詞，下列何者正確？", "options": {"A": "即／從／出／至", "B": "出／至／從／即", "C": "至／即／出／從", "D": "從／出／即／至"}, "answer": "B", "explain": "遊記通常是「從哪裡出發→到哪裡→經過哪裡」。第一空接起點「榔梅庵」，填「出」；第二空接目的地「桃源橋」，填「至」；第三空是「由小橋右邊下去」，填「從」；第四空說明「這就是舊時去黃山的路」，填「即」（就是）。所以是出／至／從／即，(B)正確。(A)「即白岳榔梅庵」不通。(C)「至白岳」「即桃源橋」次序顛倒、也不通。(D)「從榔梅庵、出桃源橋」勉強可讀，但「即小橋右下」「至舊向黃山路也」讀不通，「也」字結尾是判斷句，要配「即」。", "skill": "文言填空題先找句尾：以「也」收尾的判斷句前面常是「即、乃、為」；再用行程順序（出→至→從）排其他空格。"}], "difficulty": "易", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-04", "exam": "tc102", "nums": [4], "form": "單題", "img": "img/tc102-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "萬里十六歲時，椿萱俱喪；立君臣，等上下，使綱紀有序；隴州道士曾若虛者，善醫，尤得針砭之妙術；婦人左右前後跪起，皆中規矩繩墨，無敢出聲", "translation": "「椿萱俱喪」：父母都過世了。「使綱紀有序」：讓國家的法度有秩序。「尤得針砭之妙術」：特別精通用針石治病的高明醫術。「皆中規矩繩墨」：（宮女們）左右前後、跪下起身，全都合乎法度標準。", "keywords": [{"w": "椿萱", "m": "椿樹長壽比父親，萱草忘憂比母親，合指父母"}, {"w": "綱紀", "m": "本指網的大繩與絲的頭緒，引申為法度"}, {"w": "針砭", "m": "古代治病用的金屬針與石針"}, {"w": "規矩繩墨", "m": "畫圓、方、直線的工具，引申為標準、法度"}], "questions": [{"n": 4, "qtype": "單選", "stem": "「斟」本義為倒酒，「酌」本義為飲酒，「斟酌」引申為取捨考慮。下列選項「」內的詞語，何者不是引申義的用法？", "options": {"A": "萬里十六歲時，「椿萱」俱喪", "B": "立君臣，等上下，使「綱紀」有序", "C": "隴州道士曾若虛者，善醫，尤得「針砭」之妙術", "D": "婦人左右前後跪起，皆中「規矩繩墨」，無敢出聲"}, "answer": "C", "explain": "先分清「本義」是字詞原本指的東西，「引申義」是從本義延伸出去的意思。(C)不是引申義，所以是答案。「針砭」本來就是治病用的針和石針，這句說道士「善醫」，精通針砭醫術，用的正是本義；如果是「針砭時弊」（批評缺失），才是引申義。(A)「椿萱」本是椿樹和萱草，這裡指父母，是引申用法。(B)「綱紀」本是網繩和絲頭，這裡指國家法度。(D)「規矩繩墨」本是木工的工具，這裡指宮女動作都合乎標準。", "skill": "判斷本義或引申義：把詞換回它最原始的實物（樹、繩、工具、針）代進句子，讀得通就是本義，讀不通就是引申義。"}], "difficulty": "中", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-06", "exam": "tc102", "nums": [6], "form": "單題", "img": "img/tc102-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "眾人皆醉我獨醒，是以見放／齊國放其大臣孟嘗君於諸侯；彼與彼年相若也，道相似也／是非若所知也，吾之患在鼠；外人頗有公孫布被之譏，公宜少從眾／少焉，月出於東山之上；今乃棄黔首以資敵國，卻賓客以業諸侯／才下眉頭，卻上心頭", "translation": "「是以見放」：因此被放逐（屈原〈漁父〉）。「齊國放其大臣孟嘗君於諸侯」：齊國把大臣孟嘗君放逐到諸侯那裡（《戰國策》）。「彼與彼年相若也」：他和他年紀差不多（韓愈〈師說〉）。「是非若所知也」：這不是你所懂得的。「公宜少從眾」：您應該稍微順從一般人（司馬光〈訓儉示康〉）。「少焉」：不久（蘇軾〈赤壁賦〉）。「卻賓客以業諸侯」：拒絕外來的人才，讓他們去幫助其他諸侯成就功業（李斯〈諫逐客書〉）。「才下眉頭，卻上心頭」：愁緒剛從眉頭消失，卻又湧上心頭（李清照〈一翦梅〉）。", "keywords": [{"w": "放", "m": "放逐"}, {"w": "若", "m": "相似；你"}, {"w": "少", "m": "稍微；少焉＝不久"}, {"w": "卻", "m": "拒絕、使退；卻又"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下列選項「」內的詞義，何者兩兩相同？", "options": {"A": "眾人皆醉我獨醒，是以見「放」／齊國「放」其大臣孟嘗君於諸侯", "B": "彼與彼年相「若」也，道相似也／是非「若」所知也，吾之患在鼠", "C": "外人頗有公孫布被之譏，公宜「少」從眾／「少」焉，月出於東山之上", "D": "今乃棄黔首以資敵國，「卻」賓客以業諸侯／才下眉頭，「卻」上心頭"}, "answer": "A", "explain": "(A)兩個「放」都是「放逐」，正確：屈原因為獨自清醒而被放逐；齊王把孟嘗君趕出國，讓他流落到諸侯之間。(B)前者「相若」是相似；後者「若」是「你」：這不是你懂的。(C)前者「少」是稍微；後者「少焉」是不久、一會兒。(D)前者「卻」是拒絕、退還人才；後者是轉折副詞「卻又」。", "skill": "「見＋動詞」常表被動（見放＝被放逐），看到它可以快速判斷動詞的意思。"}], "difficulty": "中", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-09", "exam": "tc102", "nums": [9], "form": "單題", "img": "img/tc102-09.png", "source": "《論語》", "author": "孔子弟子及再傳弟子", "genre": "經典語錄", "types": ["句意理解"], "passage": "色難（〈為政〉）；知之為知之，不知為不知，是知也（〈為政〉）；君子坦蕩蕩，小人長戚戚（〈述而〉）；巧言令色，鮮矣仁（〈學而〉）", "translation": "「色難」：侍奉父母時，始終保持和悅的臉色最難。「知之為知之，不知為不知，是知也」：知道就說知道，不知道就說不知道，這才是真正的智慧。「小人長戚戚」：小人常常憂愁不安。「巧言令色，鮮矣仁」：說話花言巧語、表情刻意討好的人，很少是有仁德的。", "keywords": [{"w": "色難", "m": "和顏悅色最難做到"}, {"w": "戚戚", "m": "憂懼不安的樣子"}, {"w": "巧言令色", "m": "花言巧語、裝出和善的臉色"}], "questions": [{"n": 9, "qtype": "單選", "stem": "以生活語言解讀《論語》文句，下列何者最恰當？", "options": {"A": "「色難」：從「久病無孝子」可以印證", "B": "「知之為知之」：是「心有靈犀」的一種試探", "C": "「小人長戚戚」：受盡地獄般的折磨而疲憊不堪", "D": "「巧言令色」：大部分的話都在表明心跡"}, "answer": "A", "explain": "(A)正確。「色難」是說照顧父母時一直保持好臉色最難；「久病無孝子」說父母病久了，子女難免不耐煩、臉色變差，正好印證這份難處。(B)錯，「知之為知之」是誠實面對自己懂與不懂，與兩人默契的「心有靈犀」無關。(C)錯，「長戚戚」是小人患得患失、常常憂慮，說成「地獄般的折磨」太誇張。(D)錯，「巧言令色」是說好聽話、裝笑臉討好人，是不真誠，和「表明心跡」相反。", "skill": "經典名句的現代解讀，先把原句翻成白話，再檢查選項有沒有誇大或扭曲方向。"}], "difficulty": "易", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-12", "exam": "tc102", "nums": [12], "form": "單題", "img": "img/tc102-12.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "助之長者，揠苗者也。非徒無益，而又害之。（《孟子‧公孫丑》）以其無禮於晉，且貳於楚也；蓋君子審己以度人，故能免於斯累；悠悠乎與灝氣俱，而莫得其涯；與其不遜也，寧固", "translation": "「非徒無益，而又害之」：不只沒有好處，而且還傷害了它。「以其無禮於晉，且貳於楚也」：因為鄭國對晉國無禮，而且又依附楚國（〈燭之武退秦師〉）。「蓋君子審己以度人，故能免於斯累」：君子先省察自己再衡量別人，所以能避免這種毛病（曹丕〈典論論文〉）。「悠悠乎與灝氣俱，而莫得其涯」：心神悠遠，和天地之氣融為一體，卻找不到它的邊際（柳宗元〈始得西山宴遊記〉）。「與其不遜也，寧固」：與其傲慢不謙，寧可寒酸固陋（《論語》）。", "keywords": [{"w": "而", "m": "本題中表遞進，相當於「而且」"}, {"w": "且", "m": "而且、又"}, {"w": "故", "m": "所以"}, {"w": "與其……寧……", "m": "選擇句式"}], "questions": [{"n": 12, "qtype": "單選", "stem": "《孟子．公孫丑》：「助之長者，揠苗者也。非徒無益，而又害之。」句中的「而」表示一層推進一層的遞進關係，下列各項「」內的字詞，何者詞性與此相同？", "options": {"A": "以其無禮於晉，「且」貳於楚也", "B": "蓋君子審己以度人，「故」能免於斯累", "C": "悠悠乎與灝氣俱，「而」莫得其涯", "D": "「與其」不遜也，寧固"}, "answer": "A", "explain": "題幹「非徒無益，而又害之」：不只沒好處，「而且」還有害，後一層比前一層更進一步。(A)「且」也是「而且」：對晉無禮，而且還依附楚，罪狀一層加一層，正確。(B)「故」是「所以」，表因果。(C)「而」是「卻」，和天地之氣融合卻找不到邊際，表轉折。(D)「與其……寧……」是二選一的選擇關係。", "skill": "連詞題把「而且」「所以」「卻」「與其」逐一代進去，哪一個讀起來最順，就是那一種關係。"}], "difficulty": "中", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-13", "exam": "tc102", "nums": [13], "form": "單題", "img": "img/tc102-13.png", "source": "綜合（多篇古文）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "(甲)兒童強不睡，相守夜歡嘩\n(乙)馬上逢寒食，途中屬暮春\n(丙)平分秋色一輪滿，長伴雲衢千里明\n(丁)競渡深悲千載冤，忠魂一去詎能還\n(戊)無燈有月不娛人，有月無燈不算春", "translation": "甲：孩子們硬撐著不睡，一起守夜，歡鬧喧嘩（除夕守歲）。乙：在馬背上趕路時遇到寒食節，正是暮春時節（寒食）。丙：秋天正中間，一輪明月圓滿，永遠照著雲路，千里通明（中秋）。丁：划龍舟競賽，深深悲嘆屈原千年的冤屈，忠魂一去哪能回來（端午）。戊：只有燈沒有月不夠盡興，只有月沒有燈不算是春天（元宵）。", "keywords": [{"w": "守夜／守歲", "m": "除夕夜不睡，守到新年"}, {"w": "寒食", "m": "清明前一兩天，禁火吃冷食"}, {"w": "平分秋色", "m": "中秋正值秋季中間"}, {"w": "競渡", "m": "划龍舟，端午習俗"}, {"w": "燈、月、春", "m": "元宵賞燈賞月，在正月"}], "questions": [{"n": 13, "qtype": "單選", "stem": "下列文句皆描寫傳統民俗節慶，依時間先後排列，何者順序正確？", "options": {"A": "乙甲丁戊丙", "B": "丁丙甲戊乙", "C": "戊丁乙甲丙", "D": "戊乙丁丙甲"}, "answer": "D", "explain": "先找出每句的節日：戊有燈有月、還在「春」，是正月十五元宵；乙「寒食」「暮春」，約在農曆三月；丁「競渡」「忠魂」，是五月初五端午；丙「平分秋色一輪滿」，是八月十五中秋；甲「相守夜」，是除夕守歲。依一年順序是戊→乙→丁→丙→甲，(D)正確。(A)把除夕放在寒食之後、端午之前，錯。(B)以端午開頭、寒食收尾，順序全亂。(C)把端午排在寒食前，又把除夕排在中秋前，錯。", "skill": "節慶排序題先圈出每句的「節日關鍵字」（燈、寒食、競渡、秋色、守夜），換成農曆日期後再排。"}], "difficulty": "易", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-14", "exam": "tc102", "nums": [14], "form": "單題", "img": "img/tc102-14.png", "source": "白居易〈琵琶行〉", "author": "白居易", "genre": "古典詩詞曲", "types": ["詩詞賞析", "字詞解釋", "寫作手法"], "passage": "輕攏慢撚抹復挑，初為霓裳後綠腰。大弦嘈嘈如急雨，小弦切切如私語；嘈嘈切切錯雜彈，大珠小珠落玉盤。間關鶯語花底滑，幽咽泉流水下灘。", "translation": "她輕輕地攏弦、慢慢地撚弦，又抹又挑，先彈〈霓裳羽衣曲〉，再彈〈綠腰〉。粗弦的聲音低沉厚重，像急驟的雨；細弦的聲音輕細，像人在說悄悄話；粗細交錯地彈，就像大小珍珠掉落在玉盤上，清脆圓潤。一會兒像黃鶯在花下婉轉啼叫，流暢輕快；一會兒像泉水在冰下艱難流過，低沉嗚咽。", "keywords": [{"w": "攏、撚、抹、挑", "m": "彈琵琶的四種指法"}, {"w": "霓裳、綠腰", "m": "唐代曲名"}, {"w": "嘈嘈", "m": "聲音沉重繁密"}, {"w": "切切", "m": "聲音輕細急促"}, {"w": "間關", "m": "鳥叫聲的狀聲詞"}, {"w": "幽咽", "m": "低沉、像哽咽般的聲音"}], "questions": [{"n": 14, "qtype": "單選", "stem": "「輕攏慢撚抹復挑，初為霓裳後綠腰。大弦嘈嘈如急雨，小弦切切如私語；嘈嘈切切錯雜彈，大珠小珠落玉盤。間關鶯語花底滑，幽咽泉流水下灘。」關於本段文句，下列敘述何者正確？", "options": {"A": "文中攏、撚、抹、挑、切、滑皆指彈奏技法", "B": "霓裳、綠腰、間關皆是曲名", "C": "「大珠小珠落玉盤」是形容音聲緩慢婉轉", "D": "「大弦嘈嘈」與「幽咽泉流」皆屬低沉音聲"}, "answer": "D", "explain": "(D)正確：「大弦嘈嘈」是粗弦發出的沉重聲音，「幽咽泉流」是像泉水在冰下嗚咽的低沉聲音，兩者都屬低沉。(A)錯，攏、撚、抹、挑是指法，但「切切」是形容聲音輕細，「滑」是形容鶯聲流利，都不是技法。(B)錯，霓裳、綠腰是曲名，「間關」是鳥叫的狀聲詞。(C)錯，大小珍珠落在玉盤上，是清脆圓潤、急促錯落的聲音，不是緩慢婉轉。", "skill": "音樂描寫題把句子分成「動作（指法）」「曲名」「聲音比喻」三類，再檢查選項有沒有把不同類的詞混在一起。"}], "difficulty": "中", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-16", "exam": "tc102", "nums": [16], "form": "單題", "img": "img/tc102-16.png", "source": "結婚喜帖（應用文）", "author": "", "genre": "其他", "types": ["文化常識", "字詞解釋"], "passage": "謹詹於中華民國一０二年國曆五月廿五日農曆四月十六日（星期六）為長孫長男志明、次女春嬌舉行結婚典禮，敬備喜筵恭請 闔第光臨　李有德、陳家寶、王善良、莊智慧鞠躬　恕邀", "translation": "我們謹選定民國一○二年國曆五月二十五日（農曆四月十六日，星期六），為長孫兼長男志明與次女春嬌舉行婚禮，準備了喜宴，誠心邀請您全家光臨。（男女雙方家長）李有德、陳家寶、王善良、莊智慧敬上。恕不一一親自登門邀請。", "keywords": [{"w": "詹", "m": "選定（日期）"}, {"w": "闔第光臨", "m": "請全家一起光臨"}, {"w": "頂格", "m": "抬頭另起一行頂端書寫，表示尊敬"}, {"w": "恕邀", "m": "請原諒不能親自邀請"}, {"w": "鞠躬", "m": "具名者表示敬意的結尾語"}], "questions": [{"n": 16, "qtype": "單選", "stem": "關於圖(一)的柬帖內文，下列敘述何者正確？", "options": {"A": "謹「詹」於：邀請", "B": "「闔第光臨」頂格書寫表敬意", "C": "「恕」邀：熱烈貌", "D": "具名邀請者皆男方家長"}, "answer": "B", "explain": "(B)正確，「闔第光臨」指的是受邀的對方全家，寫在最頂端（頂格）是對客人表示尊敬，就像現在公文提到長官時要抬頭。(A)錯，「謹詹於」的「詹」是選定日期，不是邀請；邀請是後面的「恭請」。(C)錯，「恕邀」是「請原諒我們無法親自登門邀請」，帶有歉意，不是熱烈。(D)錯，喜帖寫的是「長孫長男志明」和「次女春嬌」，可見具名者包含男方的李家與女方家長，是雙方家長共同邀請。", "skill": "柬帖題記三個關鍵：「詹」是擇日、「恕邀」是致歉、提到對方的字要抬頭或頂格；再看新人身分寫法判斷具名者是哪一方。"}], "difficulty": "中", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-18", "exam": "tc102", "nums": [18], "form": "單題", "img": "img/tc102-18.png", "source": "《世說新語‧賢媛》", "author": "劉義慶", "genre": "筆記小品", "types": ["人物情感", "文意推論"], "passage": "許因謂曰：「婦有四德，卿有其幾？」婦曰：「新婦所乏唯容爾。然士有百行，君有幾？」許云：「皆備。」婦曰：「夫百行以德為首，君好色不好德，何謂皆備？」允有慚色，遂相敬重。", "translation": "許允就對妻子說：「婦女有四種美德，妳有幾種？」妻子說：「我缺的只有容貌而已。不過讀書人有各種好品行，您有幾種？」許允說：「全都具備。」妻子說：「各種品行中以德行為首，您喜好美色而不重德行，怎麼能說全都具備呢？」許允露出慚愧的神色，從此兩人互相敬重。", "keywords": [{"w": "四德", "m": "婦德、婦言、婦容、婦功"}, {"w": "卿", "m": "你，夫妻間親暱的稱呼"}, {"w": "新婦", "m": "媳婦，妻子自稱"}, {"w": "百行", "m": "各種品行"}, {"w": "慚色", "m": "慚愧的臉色"}], "questions": [{"n": 18, "qtype": "單選", "stem": "「許(允)因謂曰：『婦有四德，卿有其幾？』(阮)婦曰：『新婦所乏唯容爾。然士有百行，君有幾？』許云：『皆備。』婦曰：『夫百行以德為首，君好色不好德，何謂皆備？』(許)允有慚色，遂相敬重。」(劉義慶《世說新語》)文中許允終有慚色，其理虧所在是：", "options": {"A": "疾言厲色", "B": "言行不一", "C": "前倨後恭", "D": "貪多務得"}, "answer": "B", "explain": "許允自稱「百行皆備」，可是他嫌妻子醜，正好暴露自己「好色不好德」，嘴上說德行齊全，行為卻重外貌不重品德，說的和做的不一樣，所以理虧，(B)言行不一正確。(A)疾言厲色是說話急躁、臉色嚴厲，文中他只是發問，沒有這種態度，而且這不是他慚愧的理由。(C)前倨後恭是先傲慢後恭敬，雖然後來「相敬重」，但他理虧的「原因」不是態度轉變。(D)貪多務得是貪求越多越好，與文意無關。", "skill": "問「理虧在哪」，就找對方抓到的矛盾點：把當事人「說的話」和「做的事」並排比對。"}], "difficulty": "易", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-24", "exam": "tc102", "nums": [24, 25, 26], "form": "題組", "img": "img/tc102-24.png", "source": "沈壽《雪宦繡譜》", "author": "沈壽", "genre": "說理議論", "types": ["文意推論", "字詞解釋", "主旨寓意"], "passage": "色有定也，色之用無定。針法有定也，針法之用無定。有定故常，無定故不可有常，微有常弗精，微無常弗妙，以有常求無常在勤，以無常運有常在悟。昔之繡花卉無陰陽，繡山水亦無陰陽，常有一枝之花而數異其色。一段之山，一本之樹，而歧出其色者，藉堆垛為燦爛焉耳，固不可以繡有筆法之畫，與天然之景物（山水花卉皆是），余憾焉。故不敢不循畫理，不敢不師真形，雖謂自余始，不敢辭也。言乎色，若余繡《耶穌像》，稿本油畫；繡《義大利皇后像》，稿本鉛畫，皆本於攝影。影因光異，光因色異，執一色以貌之而不肖，潛心默會，乃合二三色穿於一針，肖焉。旋悟雖七色可合而和也，分析之雖百數十色亦可合而和也，故曰：「色之用無定也。」", "translation": "絲線的顏色是固定的，但顏色的運用沒有定規；針法是固定的，針法的運用也沒有定規。有定規所以有常法，沒有定規所以不能死守常法。沒有常法就不精確，沒有變化就不巧妙；從常法中追求變化靠勤練，用變化來運用常法靠領悟。過去繡花草沒有明暗，繡山水也沒有明暗，常常一枝花用了好幾種不同顏色；一座山、一棵樹，卻分出好幾種顏色，只是靠堆疊顏色來顯得燦爛罷了，本來就沒辦法繡出有筆法的畫，以及天然的景物（山水花草都是），我對此感到遺憾。所以我不敢不遵循繪畫的道理，不敢不效法真實的形貌，即使說這是從我開始的，我也不敢推辭。說到顏色，像我繡〈耶穌像〉，底稿是油畫；繡〈義大利皇后像〉，底稿是鉛筆畫，都是根據攝影的道理。影像因光線而不同，光線因顏色而不同，只拿一種顏色去描繪就不像，我專心體會，於是把兩三種顏色的線穿在同一根針上，就像了。接著我領悟到，即使是七種顏色也能調合；拆開來，就算上百種顏色也能調合。所以說：「顏色的運用沒有定規。」", "keywords": [{"w": "微", "m": "沒有、若非"}, {"w": "弗", "m": "不"}, {"w": "陰陽", "m": "明暗、光影"}, {"w": "堆垛", "m": "把顏色堆疊在一起"}, {"w": "師", "m": "效法"}, {"w": "真形", "m": "真實的形貌"}, {"w": "肖", "m": "相像"}], "questions": [{"n": 24, "qtype": "單選", "stem": "閱讀本文，下列何者不是作者改良傳統刺繡的看法？", "options": {"A": "求真形可本攝影之理", "B": "循畫理改進刺繡針法", "C": "應多取材天然景物作繡", "D": "求精須有常，求妙要無常"}, "answer": "C", "explain": "(C)不是作者的看法，所以是答案。文中提到「天然之景物」，是批評舊繡法「不可以繡」天然景物，作者遺憾的是技術做不到，並沒有主張「應該多拿天然景物當題材」。(A)是，她繡人像「皆本於攝影」，從光影找出真實樣貌。(B)是，「不敢不循畫理，不敢不師真形」。(D)是，「微有常弗精，微無常弗妙」，有規矩才精確、能變化才巧妙。", "skill": "「不是作者看法」題，小心選項借用原文字詞卻改變方向：原文是「做不到」，選項變成「應該做」。"}, {"n": 25, "qtype": "單選", "stem": "「昔之繡花卉無陰陽，繡山水亦無陰陽」句中的「陰陽」是指：", "options": {"A": "遠近", "B": "高低", "C": "正反", "D": "明暗"}, "answer": "D", "explain": "後文說她繡像時「本於攝影」，發現「影因光異，光因色異」，所以要用幾種顏色才繡得像；可見舊繡法缺少的是光影變化，「陰陽」指明暗，(D)正確。(A)遠近是透視。(B)高低是位置。(C)正反是方向。這三者文中都沒有討論。", "skill": "抽象詞（陰陽）要回文中找具體說明，作者後面談「光」「影」，答案就在光影上。"}, {"n": 26, "qtype": "單選", "stem": "下列何者無法表現「色之用無定」的繡理？", "options": {"A": "無定不可有常，以無常運有常在悟", "B": "不敢不循畫理，不敢不師真形", "C": "歧出其色者，藉堆垛為燦爛", "D": "潛心默會，合二三色穿於一針"}, "answer": "C", "explain": "「色之用無定」是說顏色要依光影靈活調配。(C)無法表現，所以是答案：這是作者批評的舊繡法，一座山、一棵樹胡亂分出很多顏色，只靠堆疊顏色來顯得熱鬧，並不是依真實光影來用色。(A)可以，說明運用沒有定法，要靠領悟來變化。(B)可以，遵循畫理、效法真形，正是她靈活用色的出發點。(D)可以，把兩三種顏色穿在同一針上，就是她實踐「色之用無定」的具體方法。", "skill": "留意作者「批評的舊做法」和「提倡的新做法」：題目問理念時，舊做法通常是陷阱。"}], "difficulty": "難", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-27", "exam": "tc102", "nums": [27, 28, 29], "form": "題組", "img": "img/tc102-27.png", "source": "青城子《亦復如是》", "author": "青城子", "genre": "筆記小品", "types": ["文意推論", "主旨寓意"], "passage": "墨魚即為烏賊魚，骨名海螵蛸。腹中有墨可以書字，但逾年則迹滅，惟存空紙爾。俗謂是海若白事小吏也。近海皆有之，每游行輒吸波噀墨，令水溷黑自衛，以防人害。漁人即于有墨處網取，百不失一。魚知以墨自衛可謂智矣。不謂漁人則因彼之智以成己之智，智出彼上，而彼以智敗。是可為不善用智者戒。", "translation": "墨魚就是烏賊，牠的骨頭叫做海螵蛸。牠肚子裡有墨，可以用來寫字，但過了一年字跡就消失，只剩一張白紙。民間說牠是向海神稟報事情的小官。靠近海的地方都有牠，每次游動就吸水噴墨，讓水變得混濁漆黑來保護自己，防止被人捕捉。漁夫卻偏偏就在有墨的地方撒網，百發百中。墨魚懂得用墨保護自己，可算聰明了；沒想到漁夫利用牠的聰明成就自己的聰明，智慧更高一籌，墨魚反而因為自己的聰明而失敗。這可以作為不善於運用聰明的人的警惕。", "keywords": [{"w": "迹滅", "m": "字跡消失"}, {"w": "海若", "m": "海神"}, {"w": "白事", "m": "稟告事情"}, {"w": "噀", "m": "噴"}, {"w": "溷", "m": "混濁"}, {"w": "不謂", "m": "沒想到"}], "questions": [{"n": 27, "qtype": "單選", "stem": "本文對墨魚的敘述，下列何者錯誤？", "options": {"A": "吐墨溷黑留下行跡", "B": "噴出墨汁用以攻敵", "C": "其墨書寫字跡易褪", "D": "吸波噀墨得以遁形"}, "answer": "B", "explain": "(B)錯誤，所以是答案。文中說墨魚噴墨是「自衛，以防人害」，是防守躲藏，不是攻擊敵人。(A)正確，墨把水染黑，反而讓漁夫知道牠在哪裡，「即于有墨處網取」。(C)正確，墨寫的字「逾年則迹滅」。(D)正確，吸水噴墨讓水變黑，想藉此隱藏身形。", "skill": "找「目的」的字眼（自衛、以防）來判斷攻或守，選項換掉目的就是錯誤選項。"}, {"n": 28, "qtype": "單選", "stem": "對於墨魚自衛之智，下列敘述何者較恰當？", "options": {"A": "拆東牆補西牆", "B": "聰明反被聰明誤", "C": "長痛不如短痛", "D": "得了便宜又賣乖"}, "answer": "B", "explain": "墨魚自以為噴墨就能保命，沒想到墨汁正好替漁夫指出位置，「彼以智敗」，正是聰明反被聰明誤，(B)正確。(A)拆東牆補西牆是挖這裡補那裡、只顧眼前。(C)長痛不如短痛是勸人早點下決斷。(D)得了便宜又賣乖是占了好處還裝委屈，墨魚並沒有占到便宜。", "skill": "寓言題找「轉折」：本來的優點（智）變成失敗原因（以智敗），就是「反被誤」類成語。"}, {"n": 29, "qtype": "單選", "stem": "漁人捕捉墨魚，運用何種策略？（選項為四幅漁夫圖，分別標示：(A)釜底抽薪　(B)瞞天過海　(C)威脅利誘　(D)因敵制宜）", "options": {"A": "釜底抽薪", "B": "瞞天過海", "C": "威脅利誘", "D": "因敵制宜"}, "answer": "D", "explain": "漁夫「因彼之智以成己之智」，看準墨魚一定會噴墨，就順著這個習性在有墨處撒網，是依照對手的特性來決定對策，(D)因敵制宜正確。就像業務員先摸清客戶習慣再設計方案。(A)釜底抽薪是從根本斷絕問題來源，漁夫沒有去除墨魚的墨。(B)瞞天過海是用偽裝欺騙對手，漁夫沒有偽裝。(C)威脅利誘是用恐嚇和好處逼人就範，不適用於捕魚。", "skill": "策略題找出主角「依據什麼」行動：依據對方的特點下手，就是因敵制宜、因勢利導這類答案。"}], "difficulty": "易", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc102-33", "exam": "tc102", "nums": [33, 34, 35], "form": "題組", "img": "img/tc102-33.png", "source": "李翱〈鳳喪其助〉", "author": "李翱", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "龍與蛇皆食于鳳。龍智而神，其德無方。鳳知其可與皆為靈也，禮而親之。蛇毒而險，所忌必傷，且惡其得于鳳也，不惟嚙龍，雖遇麟、龜，固將噬而亡之。鳳知蛇不得其欲則將協豺犬而來吠嗥也，賦之食，加于龍。以龍之神浮于食也，將使飽焉，終畏蛇而不能。麟與龜瞠而謳曰：「鳳兮鳳兮，何德之衰！往者不可諫，來者猶可追。已而已而！」既而麟傷于毒，伏于窟；龜屏氣潛于殼。蛇偵龍之寐也，以毒攻其喉而龍走。鳳喪其助，于是下翼而不敢靈也。", "translation": "龍和蛇都靠鳳供養。龍聰明而神奇，德行廣大沒有局限；鳳知道可以和牠一起成為靈物，就以禮相待、親近牠。蛇狠毒陰險，牠忌恨的對象一定要傷害，又嫉妒龍受到鳳的重視，不只咬龍，就算遇到麒麟、神龜，也要咬死牠們。鳳知道蛇如果得不到想要的，就會聯合豺狼野狗來吠叫鬧事，於是分給蛇的食物比給龍的還多。龍的神力本來超過所吃的食物，鳳想讓龍吃飽，最後卻因為怕蛇而做不到。麒麟和神龜瞪著眼唱道：「鳳啊鳳啊，你的德行為何這麼衰微！過去的已經不能挽回，未來的還來得及補救。算了吧，算了吧！」不久麒麟被毒傷，躲進洞穴；神龜屏住氣息縮進殼裡。蛇偷看到龍睡著了，用毒攻擊牠的喉嚨，龍就逃走了。鳳失去了輔佐，從此垂下翅膀，再也不敢顯現靈異。", "keywords": [{"w": "食于鳳", "m": "由鳳供養"}, {"w": "其德無方", "m": "德行廣大，不拘一方"}, {"w": "惡", "m": "厭惡、嫉妒"}, {"w": "協", "m": "聯合"}, {"w": "浮", "m": "超過"}, {"w": "偵", "m": "窺伺、偷看"}, {"w": "下翼", "m": "垂下翅膀，比喻失去威勢"}], "questions": [{"n": 33, "qtype": "單選", "stem": "有關文中動物的描述，下列何者正確？", "options": {"A": "龍為群首領導無方", "B": "鳳為輔治賢良之才", "C": "麟龜與蛇結黨為惡", "D": "豺犬嗆聲是為蛇助陣"}, "answer": "D", "explain": "(D)正確，鳳擔心蛇得不到好處就會「協豺犬而來吠嗥」，豺犬是蛇找來助勢、叫囂的幫手。(A)錯，「其德無方」是德行廣大，不是「領導無方」；而且帶頭供養大家的是鳳，龍不是首領。(B)錯，鳳是供養群獸、做決定的主事者，像君主；輔佐的賢才是龍。(C)錯，麟、龜被蛇咬傷、嚇得躲起來，是受害者，沒有和蛇結黨。", "skill": "寓言先替每個角色貼上「現實身分」：鳳＝君主、龍＝賢臣、蛇＝奸臣、豺犬＝爪牙、麟龜＝旁觀的忠良。"}, {"n": 34, "qtype": "單選", "stem": "依文中所示，鳳喪其助的原因：", "options": {"A": "縱欲肆志", "B": "利令智昏", "C": "姑息養奸", "D": "暴虐猜疑"}, "answer": "C", "explain": "鳳明知蛇狠毒，卻因為怕牠鬧事，反而多給牠食物，對龍卻沒照顧好，結果蛇越來越囂張，龍被逼走，這是一味忍讓、縱容壞人，(C)姑息養奸正確。(A)縱欲肆志是放縱自己的慾望，鳳不是為了享樂。(B)利令智昏是貪圖利益而糊塗，鳳是害怕而不是貪利。(D)暴虐猜疑是殘暴又多疑，鳳正好是太軟弱。", "skill": "問「原因」時，找主角做錯的那個關鍵決定（「賦之食，加于龍」），再挑能概括那個決定的成語。"}, {"n": 35, "qtype": "單選", "stem": "關於本文寓意，下列何者正確？", "options": {"A": "賢才紛然輩出，拯濟國難", "B": "劣幣驅逐良幣，奸惡當道", "C": "正邪相互內鬥，動搖國本", "D": "文武各盡其才，中興邦國"}, "answer": "B", "explain": "結局是龍被蛇逼走、麟龜躲藏，只剩蛇得勢，鳳也失去威望，正是壞的把好的趕走、小人當道，(B)正確。在職場上也常見：主管一味遷就愛鬧事的人，認真的人才反而離開。(A)賢才不是輩出，而是被逼走。(C)不是雙方互鬥，而是蛇單方面加害，龍並沒有反擊。(D)結局是鳳「不敢靈」，國勢衰落，不是中興。", "skill": "寓意題看結局：誰留下、誰離開，就能判斷作者要批評什麼。"}], "difficulty": "中", "label": "102統測", "year": 102, "kind": "統測"}, {"id": "tc103-01", "exam": "tc103", "nums": [1], "form": "單題", "img": "img/tc103-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "諮諏善道／渡大海，入荒陬；傴僂提攜／嘔啞嘲哳難為聽；跫音不響／秋蟬兒噪罷寒蛩兒叫；形容枯槁／阿縞之衣，錦繡之飾", "translation": "「諮諏善道」：詢問治國的好方法（諸葛亮〈出師表〉）。「渡大海，入荒陬」：渡過大海，進入荒遠的角落（連橫〈臺灣通史序〉）。「傴僂提攜」：彎腰駝背的老人和被牽著的小孩（歐陽脩〈醉翁亭記〉）。「嘔啞嘲哳難為聽」：聲音雜亂難聽（白居易〈琵琶行〉）。「秋蟬兒噪罷寒蛩兒叫」：秋蟬叫完換蟋蟀叫（元曲）。「形容枯槁」：面容憔悴（屈原〈漁父〉）。「阿縞之衣」：東阿出產的白絹做的衣服（李斯〈諫逐客書〉）。", "keywords": [{"w": "諏", "m": "ㄗㄡ，詢問"}, {"w": "陬", "m": "ㄗㄡ，角落"}, {"w": "傴", "m": "ㄩˇ，彎腰駝背"}, {"w": "嘔", "m": "ㄡ，嘔啞是雜亂的聲音"}, {"w": "跫、蛩", "m": "皆讀ㄑㄩㄥˊ"}, {"w": "槁、縞", "m": "皆讀ㄍㄠˇ"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列各組「」內的字，何者讀音不同？", "options": {"A": "諮「諏」善道／渡大海，入荒「陬」", "B": "「傴」僂提攜／「嘔」啞嘲哳難為聽", "C": "「跫」音不響／秋蟬兒噪罷寒「蛩」兒叫", "D": "形容枯「槁」／阿「縞」之衣，錦繡之飾"}, "answer": "B", "explain": "(B)讀音不同，所以是答案。「傴」讀ㄩˇ，「傴僂」是彎腰駝背；「嘔」在「嘔啞」裡讀ㄡ，形容雜亂的聲音。(A)「諏」「陬」都讀ㄗㄡ。(C)「跫」「蛩」都讀ㄑㄩㄥˊ。(D)「槁」「縞」都讀ㄍㄠˇ。", "skill": "形聲字的聲旁只能當提示：同聲旁字通常讀音相近，但「區」旁的傴、嘔、驅、歐就有好幾種讀法，要逐字記。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-03", "exam": "tc103", "nums": [3], "form": "單題", "img": "img/tc103-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "文化常識"], "passage": "三人行，必有我師焉；四維不張，國乃滅亡；五帝三王之所以無敵；六藝經傳，皆通習之", "translation": "「三人行，必有我師焉」：幾個人走在一起，其中一定有值得我學習的人（《論語》）。「四維不張，國乃滅亡」：禮義廉恥四種綱紀不能伸張，國家就會滅亡（《管子》）。「五帝三王之所以無敵」：五帝三王之所以天下無敵（李斯〈諫逐客書〉）。「六藝經傳，皆通習之」：六經的經文和注解，全都學通了（韓愈〈師說〉）。", "keywords": [{"w": "虛指", "m": "數字不是確實的數量，而是表示多或少"}, {"w": "四維", "m": "禮、義、廉、恥"}, {"w": "五帝三王", "m": "上古五位帝王與夏禹、商湯、周文王武王"}, {"w": "六藝", "m": "此指六經"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列文句「」內的數字，何者可理解為「虛指」？", "options": {"A": "「三」人行，必有我師焉", "B": "「四」維不張，國乃滅亡", "C": "「五」帝三王之所以無敵", "D": "「六」藝經傳，皆通習之"}, "answer": "A", "explain": "(A)正確。「三人行」不一定剛好三個人，而是泛指「幾個人在一起」，三在這裡表示多數，是虛指。(B)「四維」確實是禮、義、廉、恥四項，是實指。(C)「五帝」指上古五位帝王，有確定的人選，是實指。(D)「六藝」指六部經典，數目確定，是實指。", "skill": "判斷虛實：如果能說出「是哪幾個」，就是實指；說不出來、只是表示「多」，就是虛指。三、九、百、千最常當虛指。"}], "difficulty": "易", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-04", "exam": "tc103", "nums": [4], "form": "單題", "img": "img/tc103-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "寄蜉蝣於天地；男女衣著，悉如外人；遷客騷人，多會於此；引氣不齊，巧拙有素", "translation": "「寄蜉蝣於天地」：像蜉蝣一樣短暫寄身在天地之間（蘇軾〈赤壁賦〉）。「男女衣著，悉如外人」：男男女女的穿著，全都像外面的人（陶淵明〈桃花源記〉）。「遷客騷人，多會於此」：被貶的官員和詩人，大多聚集在這裡（范仲淹〈岳陽樓記〉）。「引氣不齊，巧拙有素」：運氣的方式各不相同，技巧好壞是天生本來就有的（曹丕〈典論論文〉）。", "keywords": [{"w": "寄", "m": "寄託、暫時依附"}, {"w": "悉", "m": "全、都"}, {"w": "騷人", "m": "詩人、文人"}, {"w": "素", "m": "本來、平素"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列各組「」內的詞，何者意義相同？", "options": {"A": "「寄」蜉蝣於天地／到台北以後，學校宿舍成為我的「寄」身之處", "B": "男女衣著，「悉」如外人／同學們得「悉」此事，都感到十分訝異", "C": "遷客「騷」人，多會於此／公司即將裁員的消息引起一陣「騷」動", "D": "引氣不齊，巧拙有「素」／領國家俸祿的公務員豈能尸位「素」餐"}, "answer": "A", "explain": "(A)正確，兩個「寄」都是「暫時依附、託身」：人像蜉蝣一樣暫時寄身天地；宿舍是我暫時落腳的地方。(B)前者「悉」是「全、都」；後者「得悉」是「知道」。(C)前者「騷人」指詩人（源自屈原〈離騷〉）；後者「騷動」是擾亂不安。(D)前者「有素」是本來就有；後者「素餐」是白吃飯、不做事。", "skill": "文白對照的字義題，先把白話詞句換成同義詞（得悉＝得知、騷動＝擾動），再回頭比對文言句。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-11", "exam": "tc103", "nums": [11], "form": "單題", "img": "img/tc103-11.png", "source": "《京都風俗志》", "author": "讓廉", "genre": "筆記小品", "types": ["文意推論", "文化常識"], "passage": "凡通衢委巷，燈光星布珠懸，皎如白晝，喧闐徹旦。人家鋪肆，筵樂歌唱，市食則蜜食、糖果、花生、瓜子諸品果蓏。王孫貴客，仕女兒童，傾城出遊，謂之「逛燈」，車馬塞途，幾無寸隙。", "translation": "不管是大街還是小巷，燈光像星星散布、珍珠懸掛，明亮得像白天，熱鬧喧嘩直到天亮。住家和商店擺宴奏樂唱歌，市場賣的吃食有蜜餞、糖果、花生、瓜子各種果品。王孫貴客、男男女女、大人小孩，全城的人都出門遊玩，叫做「逛燈」，車馬塞滿道路，幾乎沒有一點空隙。", "keywords": [{"w": "通衢委巷", "m": "四通八達的大街與彎曲的小巷"}, {"w": "喧闐", "m": "喧鬧、熱鬧"}, {"w": "徹旦", "m": "直到天亮"}, {"w": "果蓏", "m": "樹上的果實與地上的瓜果，泛指果品"}, {"w": "傾城", "m": "全城的人"}], "questions": [{"n": 11, "qtype": "單選", "stem": "閱讀下文，選出符合所述情景的選項：", "options": {"A": "無分晝夜，終日點燈", "B": "男女雜遝，市井喧囂", "C": "廟會酬神，歌舞盛饌", "D": "老少出城，郊外賞燈"}, "answer": "B", "explain": "文中「仕女兒童，傾城出遊」「喧闐徹旦」「車馬塞途」，男女老少擠滿街市，熱鬧喧嘩，(B)男女雜遝、市井喧囂正確。(A)錯，「皎如白晝」是說夜裡燈火亮得像白天，不是白天也點燈；「徹旦」是整夜到天亮。(C)錯，文中有宴樂歌唱，但沒有提到廟會酬神。(D)錯，燈是掛在「通衢委巷」城內大小街巷，「傾城出遊」是全城的人出來玩，不是出城到郊外。", "skill": "情景題逐字核對地點、時間、活動三要素，選項多出原文沒有的（廟會、郊外）就刪掉。"}], "difficulty": "易", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-12", "exam": "tc103", "nums": [12], "form": "單題", "img": "img/tc103-12.png", "source": "李東陽〈記女醫〉", "author": "李東陽", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "京師有女醫，主婦女孩稚之疾。其為人不識文字，不辨方脈，不能名藥物，不習於炮煉烹煮之用。以金購太醫求婦女孩稚之劑，教之曰：「某丸某散。某者丸之，某者散之。」載而歸。人有召者，攜所購以往，脈其指，灸其面，探藥囊中與之。雖誤投以他藥，弗辨也。", "translation": "京城有個女醫生，專看婦女和小孩的病。她不識字，不懂藥方和脈象，叫不出藥名，也不會炮製煎煮藥材。她花錢向太醫買治婦女小孩的藥，太醫教她說：「這是某丸、那是某散；這種做成丸，那種磨成粉。」她就把藥載回家。有人請她看病，她帶著買來的藥前往，按按病人的手指（假裝把脈），在臉上灸一灸，然後從藥袋裡隨手掏藥給病人。就算拿錯了藥，她也分辨不出來。", "keywords": [{"w": "主", "m": "主治、專管"}, {"w": "方脈", "m": "藥方與脈象"}, {"w": "炮煉", "m": "炮製藥材"}, {"w": "劑", "m": "藥劑"}, {"w": "脈", "m": "把脈（名詞當動詞）"}, {"w": "投", "m": "給藥"}, {"w": "弗辨", "m": "分辨不出來"}], "questions": [{"n": 12, "qtype": "單選", "stem": "閱讀下文，選出符合女醫作為的選項：", "options": {"A": "不通醫理，臆斷處方", "B": "敏於藥性，無師自通", "C": "拜師求劑，精進醫術", "D": "偽造名藥，行騙詐財"}, "answer": "A", "explain": "她「不辨方脈，不能名藥物」，完全不懂醫理；看病時只是隨手從袋裡拿藥，「雖誤投以他藥，弗辨也」，是憑猜測亂給藥，(A)正確。(B)錯，她連藥名都叫不出來，談不上懂藥性。(C)錯，她是花錢向太醫買藥，不是拜師學醫，也沒有精進。(D)錯，她的藥是向太醫買的真藥，不是偽造；文中重點在她無知亂用，而不是刻意詐財。", "skill": "人物作為題用「四個不」（不識、不辨、不能、不習）先定調，再看選項是貶是褒，方向相反的直接刪。"}], "difficulty": "易", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-14", "exam": "tc103", "nums": [14], "form": "單題", "img": "img/tc103-14.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "沛公旦日從百餘騎來見項王；何曾日食萬錢，至孫以驕溢傾家；吾嘗終日而思矣，不如須臾之所學也；施及孝文王、莊襄王，享國日淺，國家無事", "translation": "「沛公旦日從百餘騎來見項王」：沛公第二天一早帶著一百多個騎兵來見項王（〈鴻門宴〉）。「何曾日食萬錢」：何曾每天吃飯要花一萬錢，到了孫子輩就因為驕奢而敗光家產（司馬光〈訓儉示康〉）。「吾嘗終日而思矣」：我曾經整天苦思，卻比不上片刻學習的收穫（荀子〈勸學〉）。「享國日淺」：（孝文王、莊襄王）在位的時日很短，國家沒有發生大事（賈誼〈過秦論〉）。", "keywords": [{"w": "旦日", "m": "明天、第二天"}, {"w": "日食", "m": "每天吃"}, {"w": "終日", "m": "整天"}, {"w": "日淺", "m": "時日短淺"}], "questions": [{"n": 14, "qtype": "單選", "stem": "「日新月異」、「日積月累」中的「日」，用來形容「新」、「積」的逐漸發展，可解釋為「一天一天的」。下列文句中的「日」，何者用法相同？", "options": {"A": "沛公旦「日」從百餘騎來見項王", "B": "何曾「日」食萬錢，至孫以驕溢傾家", "C": "吾嘗終「日」而思矣，不如須臾之所學也", "D": "施及孝文王、莊襄王，享國「日」淺，國家無事"}, "answer": "D", "explain": "題幹的「日」放在「新」「積」前面修飾它，表示一天一天地變化累積。(D)用法相同，所以是答案：「享國日淺」的「日」放在形容詞「淺」前面，表示在位的時日短，結構同樣是「日＋描述變化或程度的詞」。(A)「旦日」是名詞「明天」。(B)「日食萬錢」是「每天」，強調每一天都花這麼多，是固定頻率，不是逐漸變化。(C)「終日」是名詞「整天」。", "skill": "「日」放在動詞或形容詞前，先分辨是「每天（固定重複）」還是「一天天（逐漸改變）」；名詞用法（明天、整天）最容易先刪。"}], "difficulty": "難", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-16", "exam": "tc103", "nums": [16], "form": "單題", "img": "img/tc103-16.png", "source": "方苞〈左忠毅公軼事〉", "author": "方苞", "genre": "史傳人物", "types": ["句意理解", "虛詞句式"], "passage": "及左公下廠獄，史朝夕窺獄門外。逆閹防伺甚嚴，雖家僕不得近。久之，聞左公被炮烙，旦夕且死。持五十金，涕泣謀於禁卒，卒感焉。一日，使史公更敝衣草屨，背筐，手長鑱，為除不潔者。引入，微指左公處。", "translation": "等到左光斗被關進東廠的監獄，史可法從早到晚在監獄門外守候窺探。宦官的防備監視非常嚴密，連左家的僕人都不能靠近。過了很久，史可法聽說左公受了炮烙酷刑，早晚就要死了，就拿著五十兩銀子，哭著和看守的獄卒商量，獄卒被他感動。有一天，獄卒讓史可法換上破衣服和草鞋，背著竹筐，手拿長鏟，裝成打掃清潔的人。獄卒帶他進去，偷偷指出左公所在的位置。", "keywords": [{"w": "廠獄", "m": "明代東廠的監獄"}, {"w": "逆閹", "m": "指宦官魏忠賢一黨"}, {"w": "旦夕且死", "m": "很快就要死了"}, {"w": "禁卒", "m": "看守監獄的士兵"}, {"w": "更", "m": "換"}, {"w": "鑱", "m": "鏟土的工具"}, {"w": "微指", "m": "暗中指點"}], "questions": [{"n": 16, "qtype": "單選", "stem": "下列畫底線的四個句子，何者省略的「主語」是「史公(史可法)」？（①聞左公被炮烙　②持五十金　③使史公更敝衣草屨　④引入）", "options": {"A": "①②", "B": "①④", "C": "②③", "D": "③④"}, "answer": "A", "explain": "①「聞左公被炮烙」：是史可法在獄外守候時聽說的，主語是史公。②「持五十金，涕泣謀於禁卒」：拿錢哭著去求獄卒的是史公。③「使史公更敝衣草屨」：句中史公是被叫去換衣服的對象，下令的是獄卒，主語是禁卒。④「引入，微指左公處」：帶人進去、指出位置的是熟悉監獄的獄卒，主語也是禁卒。所以是①②，(A)正確；(B)(C)(D)都把獄卒的動作算到史公頭上。", "skill": "找省略主語時，看「誰有能力做這件事」：能帶人進牢房、指點位置的一定是獄卒；句中已出現的人名（使史公）通常是受詞而不是主語。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-18", "exam": "tc103", "nums": [18], "form": "單題", "img": "img/tc103-18.png", "source": "文集命名（文學常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "杜工部集；王右丞集；柳河東集；辛稼軒集；范文正公集", "translation": "杜甫曾任檢校工部員外郎，所以稱「杜工部」；王維官至尚書右丞，稱「王右丞」；柳宗元是河東人，稱「柳河東」；辛棄疾號稼軒；范仲淹死後諡號「文正」。", "keywords": [{"w": "工部", "m": "杜甫的官職（檢校工部員外郎）"}, {"w": "右丞", "m": "王維的官職（尚書右丞）"}, {"w": "河東", "m": "柳宗元的郡望、籍貫"}, {"w": "稼軒", "m": "辛棄疾的號"}, {"w": "文正", "m": "范仲淹的諡號"}], "questions": [{"n": 18, "qtype": "單選", "stem": "古人文集之名，有以作者姓名、字、號、諡號為名，也有以出生地、居官地、書齋、官爵等為名。下列文集的命名方式，何者與「杜工部集」(杜甫)相同？", "options": {"A": "王右丞集(王維)", "B": "柳河東集(柳宗元)", "C": "辛稼軒集(辛棄疾)", "D": "范文正公集(范仲淹)"}, "answer": "A", "explain": "「杜工部」是以杜甫的官職命名。(A)王維做過尚書右丞，「王右丞」也是官職，相同，正確。(B)「河東」是柳宗元的籍貫（郡望），屬於以地命名。(C)「稼軒」是辛棄疾的號。(D)「文正」是范仲淹死後朝廷給的諡號。", "skill": "文集名的後兩字先分類：官名（工部、右丞）、地名（河東、臨川）、號（稼軒、東坡）、諡號（文正、文忠），同類就是答案。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-19", "exam": "tc103", "nums": [19], "form": "單題", "img": "img/tc103-19.png", "source": "古典韻文常識（文學常識）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "文賦", "m": "宋代的賦，句法散文化，如〈赤壁賦〉"}, {"w": "絕句、律詩", "m": "依句數分：絕句四句、律詩八句"}, {"w": "小令、中調、長調", "m": "依字數分"}, {"w": "劇曲、散曲", "m": "劇曲有科（動作）有白（對白），散曲只有唱詞"}], "questions": [{"n": 19, "qtype": "單選", "stem": "下列是一段關於古典韻文的敘述，其中畫底線處何者正確？「賦」是①先秦時期的重要文學，到宋代則常見②散文化的特色。「詩」大致有古體詩、近體詩之分，近體詩③依對仗的有無，分為絕句、律詩。「詞」一名詩餘，④依內容風格分為小令、中調、長調。「曲」一名詞餘，可分為劇曲、散曲，⑤劇曲搬演故事，⑥散曲有科無白。", "options": {"A": "①③", "B": "②⑤", "C": "②④⑤", "D": "③⑤⑥"}, "answer": "B", "explain": "②正確：宋代的「文賦」句式像散文，如蘇軾〈赤壁賦〉。⑤正確：劇曲（雜劇、傳奇）用來演出故事。①錯：賦雖然起源於先秦，但真正興盛、成為代表文學的是漢代，所以叫「漢賦」。③錯：絕句、律詩是依「句數」分，四句是絕句，八句是律詩，不是看對仗。④錯：小令、中調、長調是依「字數」分。⑥錯：散曲只有唱詞，沒有科（動作）也沒有白（對白）；有科有白的是劇曲。所以只有②⑤，(B)正確。", "skill": "文體常識記「分類依據」：詩看句數、詞看字數、曲看有沒有科白，題目常把依據偷換。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-21", "exam": "tc103", "nums": [21, 22, 23], "form": "題組", "img": "img/tc103-21.png", "source": "張錯〈十八弦〉（引蘇璟〈春草堂琴譜〉、冷仙〈冷仙琴聲十六法〉）", "author": "張錯", "genre": "說理議論", "types": ["比較閱讀", "文意推論", "句意理解"], "passage": "彈琴要辨派，而後不誤於所從。高人逸士，自有性情，則其琴古淡而近於拙，疏脫不拘，不隨時好，此山林派也。江湖遊客，以音動人，則其琴纖靡而合於俗，以至粥奇謬古，轉以自喜，此江湖派也。若夫文人學士，適志弦歌，用律嚴而取音正，則其琴和平肆好，得風雅之遺，可以備廟廊之用，此儒派也。（蘇璟〈春草堂琴譜〉）\n琴聲只有二途，非從古，則從時，茲雖古樂久淹，而彷彿其意，則自和澹中來，故下指不落時調，便有羲皇氣象，寬大純樸，落落弦中，不事小巧，宛如深山邃谷，老木寒泉，風聲簌簌，頓令人起道心，是以名曰「古音」。（冷仙〈冷仙琴聲十六法〉）", "translation": "蘇璟說：彈琴要先分辨派別，才不會跟錯了學。隱居的高人自有性情，他們的琴聲古樸淡雅、近乎笨拙，灑脫不受拘束，不追隨流行，這是山林派。走江湖的人用音樂打動人，琴聲柔靡、迎合大眾口味，甚至標新立異、違背古法，還沾沾自喜，這是江湖派。至於讀書人用琴歌抒發心志，講究音律、取音端正，琴聲平和美好，保有《詩經》風雅的遺風，可以在朝廷典禮上演奏，這是儒派。\n冷仙說：琴聲只有兩條路，不是遵循古法，就是追隨時尚。現在古樂雖然早已失傳，但要體會它的意境，就要從平和淡泊中得來；所以下指不落入流行曲調，就有上古伏羲時代的氣象，寬厚純樸，在琴弦間舒展自在，不賣弄小技巧，就像深山幽谷、老樹寒泉、風聲颯颯，立刻讓人生出求道之心，所以叫做「古音」。", "keywords": [{"w": "辨派", "m": "分辨流派"}, {"w": "時好", "m": "當時流行的喜好"}, {"w": "纖靡", "m": "柔弱浮華"}, {"w": "粥奇謬古", "m": "賣弄新奇、違背古法（粥通鬻，賣）"}, {"w": "肆好", "m": "非常美好"}, {"w": "淹", "m": "湮沒、失傳"}, {"w": "和澹", "m": "平和淡泊"}, {"w": "羲皇氣象", "m": "上古伏羲時代淳樸的氣象"}], "questions": [{"n": 21, "qtype": "單選", "stem": "依據上文，蘇璟〈春草堂琴譜〉所說的三派，何者接近〈冷仙琴聲十六法〉所說的「古音」？", "options": {"A": "江湖派、儒派", "B": "山林派、儒派", "C": "山林派、江湖派", "D": "山林派、江湖派、儒派"}, "answer": "B", "explain": "冷仙的「古音」特色是「和澹」「不落時調」「寬大純樸」「不事小巧」。山林派「古淡」「不隨時好」，和「和澹」「不落時調」相合；儒派「和平肆好，得風雅之遺」，和「和澹」「古」相合。江湖派「纖靡而合於俗」「粥奇謬古」，迎合流行又違背古法，正是古音的反面。所以是山林派、儒派，(B)正確；含江湖派的(A)(C)(D)都錯。", "skill": "比較兩段文言時，各抽出關鍵形容詞列成表（古淡／纖靡／和平 vs. 和澹、不落時調），用「相合」或「相反」連線。"}, {"n": 22, "qtype": "單選", "stem": "依據上文，下列敘述何者正確？", "options": {"A": "作者認為，藉由歌文可逐步揣摩音曲的內涵", "B": "蘇璟認為，彈琴須先辨派，方能習得雅俗共賞的琴藝", "C": "冷仙認為，彈琴指法趨仿時調，可逐漸養成和澹氣度", "D": "蘇璟和冷仙都認為，琴音之「古」均為氣質胸懷的外顯"}, "answer": "D", "explain": "(D)正確：作者說這是「內在氣質與外在表現相關的看法」，蘇璟說高人逸士「自有性情」所以琴聲古淡，冷仙說古音從「和澹」的胸懷而來，兩人都認為琴音是內在氣質的表現。(A)錯，作者說「音曲才是內容，歌文只是進一步的形式表達」，要揣摩的是音曲本身，不是靠歌文。(B)錯，蘇璟說辨派是為了「不誤於所從」，而且他看不起合俗的江湖派，並沒有追求雅俗共賞。(C)錯，冷仙主張「下指不落時調」，正好相反。", "skill": "「誰認為什麼」的題目，把選項主詞對回該人物那段原文找證據，最常見的陷阱是把「不」拿掉或換成相反詞。"}, {"n": 23, "qtype": "單選", "stem": "上文第三段畫底線處，其意義與下列何者相通？（畫底線處：因為有情，而才有聲，這樣的情發這樣的聲，那般的情發那般的聲）", "options": {"A": "雖世殊事異，所以興懷，其致一也", "B": "操千曲而後曉聲，觀千劍而後識器", "C": "在心為志，發言為詩，情動於中而形於言", "D": "古之作者，莫不寄身於翰墨，見意於篇籍"}, "answer": "C", "explain": "畫線處說：先有內在的情，才發出聲音，什麼樣的情就發出什麼樣的聲。(C)〈詩大序〉說心中的志向說出來就成為詩，情感在內心萌動就表現在言語上，同樣是「內在情感→外在表現」，正確。(A)王羲之〈蘭亭集序〉說時代不同，但引發感慨的原因相同，講的是古今情感相通。(B)劉勰《文心雕龍》說彈過上千首曲子才懂音樂，強調多練習才能鑑賞。(D)曹丕〈典論論文〉說古代作家把生命寄託在文章裡，談的是文章不朽。", "skill": "文意相通題先把底線句濃縮成一個公式（情→聲），再找同樣公式的選項（情→言）。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-30", "exam": "tc103", "nums": [30, 31, 32], "form": "題組", "img": "img/tc103-30.png", "source": "馮夢龍《智囊》", "author": "馮夢龍", "genre": "筆記小品", "types": ["字詞解釋", "文意推論", "人物情感"], "passage": "海虞嚴相公（嚴訥，明朝大臣）營大宅於城中，度其已就，獨民房一楹錯入，未得方圓。其人鬻酒腐，而房其世傳也。司工者請厚價乞之，必不可，憤而訴公。公曰：「無庸，先營三面可也。」工既興，公命每日所需酒腐，皆取辦此家，且先資其值。其人夫婦拮据，日不暇給，又募人為助。已而，鳩工愈眾，獲利愈豐，所積米豆，充牣屋中，缸仗俱增數倍，屋隘不足以容之，又感公之德，自愧其初之抗也，遂書券以獻。公以他房之相近者易焉，房稍寬，其人大悅，不日遷去。", "translation": "常熟的嚴相公在城裡蓋大宅院，規劃得差不多了，只有一間民房夾在中間，讓宅院不方正。屋主是賣酒和豆腐的，房子是祖傳的。負責工程的人願意出高價向他買，他堅決不肯，工頭很生氣，就向嚴公告狀。嚴公說：「不必了，先蓋其他三面就好。」動工以後，嚴公吩咐工地每天要用的酒和豆腐，全都向這家買，而且先付錢。這對夫婦忙得手忙腳亂、應接不暇，又雇人來幫忙。後來，工人越聚越多，他們賺得越來越多，存下的米和豆子堆滿屋子，缸和器具都增加了好幾倍，屋子狹小放不下；他們又感念嚴公的恩德，對當初的抗拒感到慚愧，就寫了契約把房子獻給嚴公。嚴公拿附近另一間房子跟他交換，那間房子比較寬敞，屋主非常高興，沒幾天就搬走了。", "keywords": [{"w": "營", "m": "建造"}, {"w": "楹", "m": "量詞，一間房屋"}, {"w": "方圓", "m": "方正完整的形狀"}, {"w": "鬻", "m": "賣"}, {"w": "無庸", "m": "不必"}, {"w": "資其值", "m": "支付貨款"}, {"w": "拮据", "m": "忙碌操勞"}, {"w": "鳩", "m": "聚集"}, {"w": "充牣", "m": "充滿"}, {"w": "券", "m": "契約、房契"}], "questions": [{"n": 30, "qtype": "單選", "stem": "下列文句「」內的解釋，何者正確？", "options": {"A": "未得「方圓」：金錢補償", "B": "其人「鬻」酒腐：貯藏", "C": "且先「資其值」：賒欠款項", "D": "「鳩」工愈眾：聚集"}, "answer": "D", "explain": "(D)正確，「鳩」本是鳥名，借作「聚集」，「鳩工愈眾」是聚集的工人越來越多。(A)錯，「方圓」指宅院形狀方正完整，因為民房插在中間所以「未得方圓」，跟錢無關。(B)錯，「鬻」是賣，他是賣酒和豆腐的小販。(C)錯，「先資其值」是先付錢給他，正好和賒欠相反。", "skill": "字義題用前後文驗證：「先資其值」後面接「夫婦拮据（忙不過來）」，表示生意變好，就知道是先付款而不是賒帳。"}, {"n": 31, "qtype": "單選", "stem": "依據上文，民房夫婦「不日遷去」的原因為何？", "options": {"A": "嚴相公終於願意出高價購買其舊屋", "B": "因生意變好而有足夠資金買下新屋", "C": "有機會得以附近大屋取代原有小屋", "D": "經嚴相公介紹而能以低價購得大屋"}, "answer": "C", "explain": "夫婦生意興隆，貨多到「屋隘不足以容之」，又感激嚴公而獻出房契；嚴公「以他房之相近者易焉，房稍寬」，用附近較寬的房子跟他交換，所以他們高興地搬走，(C)正確。(A)錯，是夫婦主動獻屋，嚴公是以房換房，並非出高價買。(B)錯，新屋不是他們自己花錢買的。(D)錯，不是介紹低價購買，而是直接交換。", "skill": "問原因時抓結果前一句（公以他房之相近者易焉），「易」是交換，選項寫「買」的都不對。"}, {"n": 32, "qtype": "單選", "stem": "依據上文，下列何者符合嚴相公處理此次事件的作法？", "options": {"A": "勢取不得，以智取之", "B": "依法辦理，無從商榷", "C": "任人需索，委曲求全", "D": "威逼利誘，予取予求"}, "answer": "A", "explain": "高價收購失敗後，嚴公不強逼，而是讓工地向這家買東西，使他們生意興旺、房子不夠用，又心存感激，最後自願獻屋；用智慧而不是權勢達成目的，(A)正確。就像高明的談判者先替對方創造好處，對方自然願意合作。(B)錯，嚴公沒有走法律途徑。(C)錯，對方沒有漫天要價，嚴公也不是忍氣吞聲，而是主動布局。(D)錯，嚴公沒有威脅，給的是實際的好處，也沒有強取。", "skill": "評價人物手段時，先看他「沒做什麼」（沒有逼迫）和「做了什麼」（創造雙贏），兩點都吻合的選項才對。"}], "difficulty": "易", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-33", "exam": "tc103", "nums": [33, 34, 35], "form": "題組", "img": "img/tc103-33.png", "source": "《北齊書‧高長恭傳》（改寫）", "author": "李百藥", "genre": "史傳人物", "types": ["文意推論", "人物情感", "虛詞句式"], "passage": "蘭陵武王長恭，文襄（高澄）第四子也，貌柔心壯，音容兼美。芒山之捷，後主謂長恭曰：「入陣太深，失利悔無所及。」對曰：「家事親切，不覺遂然。」帝嫌其稱家事，遂忌之。及在定陽，其屬尉相願謂曰：「王既受朝寄，何得如此貪殘？」長恭未答。相願曰：「豈不由芒山大捷，恐以威武見忌，欲自穢乎？」長恭曰：「然。」相願曰：「朝廷若忌王，於此犯便當行罰，求福反以速禍。」長恭泣下，前膝請以安身術。相願曰：「王前既有勳，今復告捷，威聲太重，宜屬疾在家，勿預事。」長恭然其言，未能退。及江淮寇擾，恐復為將，歎曰：「我去年面腫，今何不發！」自是有疾不療。武平（後主年號）四年五月，帝使徐之範飲以毒藥。長恭謂妃鄭氏曰：「我忠以事上，何辜於天，而遭鴆也！」妃曰：「何不求見天顏？」長恭曰：「天顏何由可見！」遂飲藥薨。", "translation": "蘭陵武王高長恭，是文襄帝高澄的第四個兒子，外貌柔美而內心剛強，聲音和容貌都很出眾。芒山大捷之後，後主對長恭說：「你衝進敵陣太深，萬一失利，後悔就來不及了。」長恭回答：「這是自家的事，心裡著急，不知不覺就衝進去了。」後主不高興他把國事說成「家事」，從此猜忌他。後來長恭鎮守定陽，他的部屬尉相願對他說：「大王既然受朝廷重託，怎麼能這樣貪財殘暴？」長恭沒回答。相願說：「莫非是因為芒山大捷，怕威名太盛被猜忌，所以故意敗壞自己的名聲？」長恭說：「是的。」相願說：「朝廷如果猜忌大王，正好可以藉這些罪名處罰你，想求福反而加速招來禍患。」長恭流下眼淚，跪著向前請教保全自己的方法。相願說：「大王以前已有功勳，如今又打勝仗，聲威太大，應該託病在家，不要參與政事。」長恭認同他的話，卻沒能退下來。等到江淮一帶有敵人侵擾，長恭怕又要被派去當將領，嘆息說：「我去年臉腫，現在怎麼不再發作呢！」從此有病也不醫治。武平四年五月，後主派徐之範拿毒酒給他喝。長恭對王妃鄭氏說：「我忠心侍奉皇上，對上天有什麼罪過，竟要被毒死！」王妃說：「為什麼不去求見皇上？」長恭說：「皇上哪能見得到！」於是喝下毒藥而死。", "keywords": [{"w": "家事親切", "m": "是自家的事，關係切身"}, {"w": "忌", "m": "猜忌"}, {"w": "朝寄", "m": "朝廷的託付"}, {"w": "自穢", "m": "故意敗壞自己的名聲"}, {"w": "速禍", "m": "招致禍患更快到來"}, {"w": "屬疾", "m": "託病"}, {"w": "預", "m": "參與"}, {"w": "鴆", "m": "毒酒"}], "questions": [{"n": 33, "qtype": "單選", "stem": "依據上文，北齊後主對蘭陵王心生不滿，是因他認為蘭陵王：", "options": {"A": "愛美惜命，殺敵未盡全力", "B": "急於立功，不顧家族安危", "C": "盡忠養望，儼如皇室棟樑", "D": "深入敵陣，致使後主受困"}, "answer": "C", "explain": "關鍵句「帝嫌其稱家事，遂忌之」。長恭把國家打仗說成「家事」，表示他以高家子孫自居、把國家當自家來扛；再加上戰功顯赫、威名日盛，後主覺得他忠心建立聲望，儼然成了皇室支柱，威脅到自己，(C)正確。(A)錯，他是「入陣太深」，非常拚命。(B)錯，後主擔心的是他的威望，而不是他害家族受累。(D)錯，文中沒有後主被困的記載，後主只是說他太深入。", "skill": "找「因為什麼而忌」，抓住緊接在「遂忌之」前面的原因（稱家事），再想它對君主意味著什麼。"}, {"n": 34, "qtype": "單選", "stem": "依據上文，相願給蘭陵王的建議為何？", "options": {"A": "託病退居，不理政事", "B": "縱欲斂財，自毀名譽", "C": "有疾不醫，但求速死", "D": "服食密藥，詐死保命"}, "answer": "A", "explain": "相願說「宜屬疾在家，勿預事」：應該假稱生病待在家裡，不要參與政事，(A)正確。(B)錯，貪財自污是長恭自己的做法，相願反而指出這樣「求福反以速禍」。(C)錯，「有疾不療」是長恭後來為了避免出征自己決定的，不是相願的建議，也不是為了求死。(D)錯，文中沒有詐死的建議，毒藥是後主賜的。", "skill": "「某人的建議」只看那個人說的話，別把主角後來自己做的事算進去。"}, {"n": 35, "qtype": "單選", "stem": "「帝使徐之範飲以毒藥」句中的「飲以毒藥」，「飲」意謂「使人喝下」，「以毒藥」補充說明使人喝下之物。下列文句「」內，何者使用相同的構句方式？", "options": {"A": "夫在殷憂，必「竭誠以待下」", "B": "左右以君賤之也，「食以草具」", "C": "若亡鄭而有益於君，「敢以煩執事」", "D": "如有不由此者，在勢者去，「眾以為殃」"}, "answer": "B", "explain": "題幹結構是「動詞（使人做）＋以＋東西」：飲以毒藥＝拿毒藥給他喝。(B)「食以草具」＝拿粗劣的飯菜給他吃（〈馮諼客孟嘗君〉），「食」是使人吃，「以草具」補充吃的東西，結構相同，正確。(A)「竭誠以待下」是「竭誠」＋「以」（來）＋「待下」，以是連接兩個動作，意思是用盡誠心來對待部屬。(C)「敢以煩執事」是「以（此事）去麻煩您的手下」，以後面省略了受詞。(D)「眾以為殃」是「眾人以（之）為殃」，大家認為他是禍害。", "skill": "看「以」字的位置：「動詞＋以＋名詞」多半是「拿某物給人／用某物來做」的補語結構；「以＋為」是「認為」。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc103-36", "exam": "tc103", "nums": [36, 37, 38], "form": "題組", "img": "img/tc103-36.png", "source": "柳宗元〈始得西山宴遊記〉；袁宏道〈晚遊六橋待月記〉", "author": "柳宗元、袁宏道", "genre": "山水遊記", "types": ["比較閱讀", "寫作手法", "詩詞賞析", "主旨寓意"], "passage": "其高下之勢，岈然洼然，若垤若穴。尺寸千里，攢蹙累積，莫得遯隱。縈青繚白，外與天際，四望如一。然後知是山之特立，不與培塿為類。悠悠乎與灝氣俱，而莫得其涯！洋洋乎與造物者遊，而不知其所窮！引觴滿酌，頹然就醉，不知日之入。蒼然暮色，自遠而至，至無所見，而猶不欲歸。心凝形釋，與萬化冥合。然後知吾嚮之未始遊，遊於是乎始，故為之文以志。（柳宗元〈始得西山宴遊記〉）\n由斷橋至蘇隄一帶，綠煙紅霧，彌漫二十餘里。歌吹為風，粉汗為雨，羅紈之盛，多於隄畔之草，豔冶極矣。然杭人遊湖，止午、未、申三時，其實湖光染翠之工，山嵐設色之妙，皆在朝日始出，夕舂未下，始極其濃媚。月景尤不可言，花態柳情，山容水意，別是一種趣味。此樂留與山僧遊客受用，安可為俗士道哉！（袁宏道〈晚遊六橋待月記〉）", "translation": "柳文：從山頂往下看，地勢高高低低，有的隆起、有的凹陷，像蟻丘、像洞穴。千里遠的景物縮成尺寸大小，聚集堆疊在眼前，沒有一樣能藏得住。青山白水互相環繞，遠處和天空相接，四面望去都一樣。這才知道西山特別高聳，不和小土丘同類。心胸悠遠，好像和天地元氣融為一體，找不到邊際；廣大無邊，好像和造物者同遊，不知道盡頭在哪。我舉杯斟滿酒，喝得醉倒，連太陽下山都不知道。蒼茫的暮色從遠處漫過來，直到什麼都看不見了，還不想回家。心神凝定、形體解放，和萬物默默融合。這才知道我以前根本不算真正的遊覽，真正的遊覽從這次才開始，所以寫下這篇文章來記錄。\n袁文：從斷橋到蘇堤一帶，綠柳如煙、紅花似霧，綿延二十多里。歌聲樂聲像風一樣飄送，仕女的香汗像雨一樣多，穿著綾羅綢緞的遊人比堤邊的草還多，真是豔麗到了極點。可是杭州人遊西湖，只在中午到下午這三個時辰；其實湖水染上翠綠的工夫、山間霧氣上色的巧妙，都在太陽剛出來、夕陽還沒落下時，才顯得最濃豔嫵媚。月下的景色更是說不出的美，花的姿態、柳的情韻、山的容貌、水的意趣，另有一種趣味。這種樂趣只留給山中僧人和懂得欣賞的遊客享受，怎能說給庸俗的人聽呢！", "keywords": [{"w": "岈然洼然", "m": "山谷深邃、地勢低窪的樣子"}, {"w": "垤", "m": "蟻丘、小土堆"}, {"w": "攢蹙累積", "m": "聚集收縮、層層堆疊"}, {"w": "培塿", "m": "小土丘"}, {"w": "灝氣", "m": "天地間的大氣"}, {"w": "心凝形釋", "m": "精神專注，形體放鬆"}, {"w": "冥合", "m": "默默契合"}, {"w": "夕舂", "m": "夕陽"}, {"w": "俗士", "m": "庸俗的人"}], "questions": [{"n": 36, "qtype": "單選", "stem": "下列關於柳、袁二文寫景的敘述，何者正確？", "options": {"A": "柳文的「縈青繚白」形容山嵐；袁文的「綠煙紅霧」形容湖水", "B": "柳文的西山樣貌帶有個人遭遇的投射；袁文的西湖風姿多為景色直觀的感受", "C": "柳、袁二文皆敘述夜景之動人，故前者於日落後「猶不欲歸」，後者謂月色「別是一種趣味」", "D": "柳文以「尺寸千里」的角度敘寫沿途美景；袁文以「彌漫二十餘里」的視野歷數環湖名勝"}, "answer": "B", "explain": "(B)正確。柳宗元被貶永州，寫西山「特立，不與培塿為類」，借高聳不凡的山比喻自己的人格，是把個人遭遇投射到景物上；袁宏道寫西湖的花柳、湖光山色、遊人，多是眼前所見的直接感受。(A)錯，「縈青繚白」是青山白水互相環繞；「綠煙紅霧」是綠柳紅花遠看如煙似霧，不是湖水。(C)錯，柳文是在暮色中陶醉，「至無所見」並沒有描寫夜景之美；袁文只說月景「不可言」，其實沒有具體描寫夜景。(D)錯，「尺寸千里」是站在山頂俯瞰，千里遠景縮成尺寸，不是沿途美景；袁文「二十餘里」寫花柳綿延，沒有一一列舉名勝。", "skill": "寫景比較題先替兩篇各下一個標籤（柳：借景抒懷；袁：直寫景色），再逐一核對選項中引號詞語的本意。"}, {"n": 37, "qtype": "單選", "stem": "柳宗元、袁宏道於遊歷中各有體會。下列敘述，何者正確？", "options": {"A": "柳宗元發現「遊」始於登臨名嶽；袁宏道感慨自己實為俗士", "B": "柳宗元發現「遊」始於登臨名嶽；袁宏道暗詡自己並非俗士", "C": "柳宗元發現「遊」始於心靈感悟；袁宏道感慨自己實為俗士", "D": "柳宗元發現「遊」始於心靈感悟；袁宏道暗詡自己並非俗士"}, "answer": "D", "explain": "柳宗元在「心凝形釋，與萬化冥合」之後，才說「然後知吾嚮之未始遊，遊於是乎始」，真正的遊是從心靈與自然合一的感悟開始，不是因為登上名山（西山本來也不是名嶽）。袁宏道說這種樂趣「留與山僧遊客受用，安可為俗士道哉」，言下之意自己懂得欣賞，不是俗士，是暗中自誇。所以(D)正確；(A)(B)的「登臨名嶽」錯，(A)(C)的「感慨自己實為俗士」也錯。", "skill": "兩兩組合的選項，先判斷前半刪掉兩個，再判斷後半，四選一很快就能定案。"}, {"n": 38, "qtype": "單選", "stem": "某出版社編輯若想依據柳、袁二文的內容，各以一句古典詩大致形容其特色，則下列何者是最恰當的安排？", "options": {"A": "獨立蒼茫自詠詩——柳宗元〈始得西山宴遊記〉；正是江南好風景——袁宏道〈晚遊六橋待月記〉", "B": "獨立蒼茫自詠詩——柳宗元〈始得西山宴遊記〉；萬里歸心對月明——袁宏道〈晚遊六橋待月記〉", "C": "四顧山光接水光——柳宗元〈始得西山宴遊記〉；正是江南好風景——袁宏道〈晚遊六橋待月記〉", "D": "四顧山光接水光——柳宗元〈始得西山宴遊記〉；萬里歸心對月明——袁宏道〈晚遊六橋待月記〉"}, "answer": "A", "explain": "柳文寫自己獨自登上西山、在蒼茫暮色中物我合一，又以「特立」的山自況，「獨立蒼茫自詠詩」（杜甫〈樂遊園歌〉）最貼切。袁文寫杭州西湖的花柳湖光，「正是江南好風景」（杜甫〈江南逢李龜年〉）正好形容。所以(A)正確。「四顧山光接水光」（黃庭堅〈鄂州南樓書事〉）偏重寫山水相接的景色，少了柳文孤高自許的心境；「萬里歸心對月明」（盧綸〈晚次鄂州〉）是思鄉之情，袁文雖提到月景，卻沒有思鄉，所以(B)(C)(D)都不恰當。", "skill": "以詩句配文章，要同時對上「景」和「情」：只對上景色的詩句，常常是陷阱。"}], "difficulty": "中", "label": "103統測", "year": 103, "kind": "統測"}, {"id": "tc104-01", "exam": "tc104", "nums": [1], "form": "單題", "img": "img/tc104-01.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "本題比較四組文言句中「」內字的讀音，不需整段翻譯。(A)自從我成了被貶謫的罪人。(B)陶朱公、猗頓那樣的富有；（陳涉）從軍伍之中崛起。／窮困時就被飢寒所威脅。(C)不停地雕刻，金石也能刻穿。／在會稽山陰的蘭亭聚會，舉行修禊的祭禮。(D)桃花隨流水深遠地流去。／門人點燈進來，只見道士獨自坐著，客人已經不見蹤影了。", "keywords": [{"w": "僇", "m": "音ㄌㄨˋ，通「戮」，受刑辱的罪人"}, {"w": "躡", "m": "音ㄋㄧㄝˋ，踏；躡足行伍指置身軍隊之中"}, {"w": "懾", "m": "音ㄓㄜˊ，恐懼、受威脅"}, {"w": "禊", "m": "音ㄒㄧˋ，古代在水邊祭祀以除災求福的禮俗"}, {"w": "窅然", "m": "窅音ㄧㄠˇ，深遠的樣子"}, {"w": "杳", "m": "音ㄧㄠˇ，不見蹤影"}], "questions": [{"n": 1, "qtype": "單選", "stem": "下列各組「」內的字，何者讀音相同？", "options": {"A": "自余為「僇」人／人臣之「謬」思亂者，乃螳臂之拒走輪耳", "B": "陶朱、猗頓之富，「躡」足行伍之間／貧賤則「懾」於飢寒", "C": "「鍥」而不舍，金石可鏤／會于會稽山陰之蘭亭，脩「禊」事也", "D": "桃花流水「窅」然去／門人燃燭來，則道士獨坐，而客「杳」矣"}, "answer": "D", "explain": "(D)正確：「窅」與「杳」都讀ㄧㄠˇ，一個指深遠，一個指不見蹤影，意思也相近。(A)「僇」讀ㄌㄨˋ（通「戮」），「謬」讀ㄇㄧㄡˋ，聲母韻母都不同。(B)「躡」讀ㄋㄧㄝˋ，「懾」讀ㄓㄜˊ，兩字都有「聶」卻不同音。(C)「鍥」讀ㄑㄧㄝˋ，「禊」讀ㄒㄧˋ，都有「契」字旁卻不同音。", "skill": "形聲字的聲旁只是線索，不保證同音；遇到「同聲旁」的組合要特別小心，反而是字形不同的組合可能同音。"}], "difficulty": "中", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-03", "exam": "tc104", "nums": [3], "form": "單題", "img": "img/tc104-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "(A)傍晚天色昏暗，老虎吼叫、猿猴哀啼。／太陽迫近西山，氣息微弱。(B)學了又時常溫習，不也很喜悅嗎？／郢地人寫的信被燕國人亂解釋。(C)會面次數多而禮節殷勤，禮物輕薄而情意深厚。／聽說生死有一定的規律，難以逃脫命定的氣數。(D)曾經見過滄海的人，難以再把別處的水當作水。／藉此觸動他的心志、堅忍他的性情，增加他原本所不具備的能力。", "keywords": [{"w": "薄", "m": "迫近"}, {"w": "說", "m": "音ㄩㄝˋ通「悅」；或音ㄕㄨㄛ，解說"}, {"w": "數", "m": "音ㄕㄨㄛˋ，屢次；或音ㄕㄨˋ，氣數、命運"}, {"w": "曾", "m": "曾經；或通「增」，增加"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列各組文句中，「」內詞義相同的選項為何？", "options": {"A": "「薄」暮冥冥，虎嘯猿啼／日「薄」西山，氣息奄奄", "B": "學而時習之，不亦「說」乎／郢書燕「說」，猶存其名", "C": "會「數」而禮勤，物薄而情厚／伏聞生死有常，難逃定「數」", "D": "「曾」經滄海難為水，除卻巫山不是雲／所以動心忍性，「曾」益其所不能"}, "answer": "A", "explain": "(A)正確：兩個「薄」都是「迫近」，「薄暮」是接近傍晚，「日薄西山」是太陽快落到西山。(B)前者「說」通「悅」，喜悅；後者是「解說、解釋」。(C)前者「數」讀ㄕㄨㄛˋ，屢次、次數多；後者讀ㄕㄨˋ，指命運、氣數。(D)前者「曾」是曾經；後者「曾」通「增」，增加。", "skill": "一字多義題，先把字放回各句試換成白話詞（迫近、喜悅、屢次、增加），兩邊換得通的同一個詞才算相同。"}], "difficulty": "中", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-04", "exam": "tc104", "nums": [4], "form": "單題", "img": "img/tc104-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "弟走從軍阿姨死，暮去朝來顏色故。（白居易〈琵琶行〉）／自是指物作詩立就，其文理皆有可觀者。（王安石〈傷仲永〉）／不聞人從日邊來，居然可知。（《世說新語》）／今觀其文章，寬厚宏博，充乎天地之間。（蘇轍〈上樞密韓太尉書〉）", "translation": "(A)弟弟去從軍、阿姨死了，日子一天天過去，容貌也衰老了。(B)從此指定事物要他作詩，立刻就能完成，文采和道理都有值得欣賞的地方。(C)沒聽說有人從太陽那邊來，顯然可以知道（太陽比較遠）。(D)現在看他（歐陽脩）的文章，寬厚宏大而廣博，充滿在天地之間。", "keywords": [{"w": "顏色", "m": "古：容貌"}, {"w": "可觀", "m": "古：值得觀賞"}, {"w": "居然", "m": "古：顯然、明明白白"}, {"w": "文章", "m": "古今皆可指文辭作品"}], "questions": [{"n": 4, "qtype": "單選", "stem": "詞義會因年代而產生變化，請選出下列文句「」內，詞義古今相同的選項：", "options": {"A": "弟走從軍阿姨死，暮去朝來「顏色」故／這件衣服的「顏色」非常特別", "B": "自是指物作詩立就，其文理皆有「可觀」者／這個工程所需經費非常「可觀」", "C": "不聞人從日邊來，「居然」可知／男生於母親節感性說愛，母親「居然」不領情", "D": "今觀其「文章」，寬厚宏博，充乎天地之間／寫「文章」可以累積知識，培養思考能力"}, "answer": "D", "explain": "(D)正確：兩個「文章」都指寫成的文辭作品，古今意思一樣。(A)古句「顏色」指容貌（琵琶女容顏老去），今句指色彩。(B)古句「可觀」是值得欣賞，今句是數量很大。(C)古句「居然」是顯然、明白可知，今句是「竟然」，表示出乎意料。", "skill": "古今詞義題，把古句的詞換成現代意思念一遍，念起來怪怪的就是詞義變了；念得通的那組才是古今相同。"}], "difficulty": "中", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-09", "exam": "tc104", "nums": [9], "form": "單題", "img": "img/tc104-09.png", "source": "《史記‧項羽本紀》", "author": "司馬遷", "genre": "史傳人物", "types": ["文意推論"], "passage": "項王曰：「壯士！能復飲乎？」樊噲曰：「……懷王與諸將約曰：『先破秦入咸陽者王之。』今沛公先破秦入咸陽，毫毛不敢有所近，封閉宮室，還軍霸上，以待大王來。故遣將守關者，備他盜出入與非常也。勞苦而功高如此，未有封侯之賞，而聽細說，欲誅有功之人，此亡秦之續耳，竊為大王不取也。」項王未有以應，曰：「坐！」", "translation": "項王說：「壯士！還能再喝嗎？」樊噲說：「……懷王和諸將約定：『先攻破秦國進入咸陽的人就封他為王。』現在沛公先破秦入咸陽，連一根毫毛都不敢碰，封閉宮室，退軍駐紮在霸上，等待大王到來。之所以派將領守住函谷關，是防備其他盜賊進出和意外變故。這樣勞苦功高，沒得到封侯的賞賜，大王反而聽信小人的讒言，想殺有功的人，這是走上滅亡秦朝的老路罷了，我私下認為大王不該這麼做。」項王無話可答，只說：「坐！」", "keywords": [{"w": "王之", "m": "封他為王"}, {"w": "非常", "m": "意外的變故"}, {"w": "細說", "m": "小人的讒言"}, {"w": "續", "m": "延續、後繼者"}, {"w": "竊", "m": "私下，謙詞"}], "questions": [{"n": 9, "qtype": "單選", "stem": "閱讀下文，選出不是樊噲所持論點的選項：", "options": {"A": "沛公遵守先前誓約，沒有稱王意圖", "B": "沛公還軍等待項王，並無踰越之舉", "C": "沛公勢力不若項王，不敢輕舉妄動", "D": "沛公破秦入關有功，反遭謠言所害"}, "answer": "C", "explain": "樊噲整段話是在替沛公「表功、喊冤」。(C)不是他的論點：他從頭到尾沒提雙方兵力強弱，更不會說沛公「不敢」是因為打不過——那等於自曝弱點。(A)是：毫毛不敢有所近、封閉宮室，表示沒有據地稱王的意圖。(B)是：「還軍霸上，以待大王來」。(D)是：「勞苦而功高如此」卻「聽細說，欲誅有功之人」。", "skill": "找「不是某人論點」，先抓說話者立場（替沛公辯護），再把每個選項對回原文找證據；原文沒寫、又違背立場的就是答案。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-10", "exam": "tc104", "nums": [10], "form": "單題", "img": "img/tc104-10.png", "source": "《左傳‧僖公三十年》（燭之武退秦師）", "author": "左丘明", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "佚之狐言於鄭伯曰：「國危矣！若使燭之武見秦君，師必退。」公從之。辭曰：「臣之壯也，猶不如人；今老矣！無能為也已。」公曰：「吾不能早用子，今急而求子，是寡人之過也。然鄭亡，子亦有不利焉！」許之。", "translation": "佚之狐對鄭文公說：「國家危險了！如果派燭之武去見秦君，秦軍一定會撤退。」鄭文公聽從了。燭之武推辭說：「我年輕時，尚且比不上別人；現在老了，沒辦法有作為了。」鄭文公說：「我沒能早點重用您，現在情況危急才來求您，這是我的過錯。但是鄭國若滅亡，對您也有不利啊！」燭之武就答應了。", "keywords": [{"w": "辭", "m": "推辭"}, {"w": "壯", "m": "壯年"}, {"w": "許之", "m": "答應了這件事"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下文，依文意選出錯誤的選項：", "options": {"A": "鄭伯採納佚之狐的建議，請燭之武去見秦君", "B": "燭之武起初以年老為藉口，婉拒鄭伯的請求", "C": "鄭伯從亡國的角度，向燭之武剖析利害關係", "D": "佚之狐最後答應鄭伯的請求，前去遊說秦君"}, "answer": "D", "explain": "(D)錯誤：最後「許之」的是燭之武，去見秦君的也是燭之武；佚之狐只是推薦人。(A)正確：「公從之」。(B)正確：「今老矣！無能為也已」是婉拒的說法。(C)正確：「然鄭亡，子亦有不利焉」，用國亡對你也不好來說服。", "skill": "文言常省略主語，讀到「許之」「辭曰」這類動詞，先問「是誰做的」，把主語補回去就不會張冠李戴。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-12", "exam": "tc104", "nums": [12], "form": "單題", "img": "img/tc104-12.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文意推論", "典故出處"], "passage": "老驥伏櫪，志在千里／烈士暮年，壯心不已（曹操〈龜雖壽〉）／年壽有盡，榮樂止身（化用曹丕〈典論論文〉「年壽有時而盡，榮樂止乎其身」）／松柏後凋，正氣長存（化用《論語‧子罕》「歲寒，然後知松柏之後彫也」）", "translation": "(A)老了的千里馬伏在馬槽邊，心志仍在奔馳千里。(B)有志之士到了晚年，雄心壯志也不停息。(C)壽命有終結的時候，榮華享樂只限於自身。(D)松柏在嚴寒中最後凋零，象徵正氣長存。", "keywords": [{"w": "驥", "m": "千里馬"}, {"w": "櫪", "m": "馬槽"}, {"w": "烈士", "m": "有志節、有抱負的人"}, {"w": "後凋", "m": "最後才凋零，比喻堅貞"}], "questions": [{"n": 12, "qtype": "單選", "stem": "閱讀下文，推斷下列何者不符合文中「老兵精神」的意涵？（文略：老兵退伍後仍以老兵自居，以犧牲奮鬥、奉獻創造、堅毅卓絕投入人生另一個戰場。）", "options": {"A": "老驥伏櫪，志在千里", "B": "烈士暮年，壯心不已", "C": "年壽有盡，榮樂止身", "D": "松柏後凋，正氣長存"}, "answer": "C", "explain": "文中「老兵精神」是：年紀大了仍不放棄、犧牲奉獻、堅毅不屈。(C)不符合：它講的是人生有限、榮華只屬於自己一身，口氣偏向感嘆生命短暫，看不到奮鬥奉獻的精神。(A)(B)出自曹操〈龜雖壽〉，老了仍有遠大志向，正合「已非年輕力壯卻仍以老兵自居」。(D)松柏耐寒、正氣長存，對應「堅毅卓絕」與「浩然的老兵精神」。", "skill": "先用自己的話替關鍵詞下定義（老兵精神＝老而不屈、奉獻），再逐一檢查選項有沒有這個「精神」，方向相反的就是答案。"}], "difficulty": "中", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-13", "exam": "tc104", "nums": [13], "form": "單題", "img": "img/tc104-13.png", "source": "《太平御覽》", "author": "李昉等編", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "平原陶邱氏取渤海墨台氏女，女色甚美，才甚令，復相敬，已生一男而歸。母丁氏年老，進見女婿。女婿既歸而遣婦，婦臨去請罪，夫曰：「曩見夫人，年德已衰，非昔日比，亦恐新婦老後，必復如此，是以遣，實無他故。」", "translation": "平原郡的陶邱氏娶了渤海郡墨台家的女兒，妻子容貌很美，才德也很好，夫妻又互相敬重，已經生了一個兒子後回娘家。她的母親丁氏年紀老了，出來見女婿。女婿回家後就把妻子休了，妻子臨走前問自己犯了什麼錯，丈夫說：「前些日子見到岳母，年紀和容貌都已經衰老，不能跟從前相比，我也怕你老了以後一定也會變成這樣，所以休了你，真的沒有其他原因。」", "keywords": [{"w": "取", "m": "通「娶」"}, {"w": "令", "m": "美好"}, {"w": "歸", "m": "回娘家"}, {"w": "遣", "m": "休棄"}, {"w": "曩", "m": "從前、先前"}, {"w": "夫人", "m": "此指岳母"}, {"w": "新婦", "m": "對妻子的稱呼"}], "questions": [{"n": 13, "qtype": "單選", "stem": "閱讀下文，推斷文中平原陶邱氏休妻的理由，下列選項何者正確？", "options": {"A": "向岳母表達妻子炫耀才貌雙全族人不屑", "B": "向岳母抱怨妻子產後容貌衰老遭到斥責", "C": "由岳母只生一子認定妻子無法多子多孫", "D": "由岳母容貌推論妻子日後一定又老又醜"}, "answer": "D", "explain": "丈夫自己講得很明白：「曩見夫人，年德已衰……亦恐新婦老後，必復如此」，看到岳母老了，就推論妻子以後也會這樣，所以休妻。(D)正確。(A)文中沒提妻子炫耀或族人不屑，反而說「復相敬」。(B)沒有向岳母抱怨，妻子現在也還「色甚美」。(C)理由和生幾個孩子無關。", "skill": "問「理由」時，直接找人物自己說的「是以……」「故……」那一句，原因就寫在前面。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-14", "exam": "tc104", "nums": [14], "form": "單題", "img": "img/tc104-14.png", "source": "《說苑‧建本》", "author": "劉向", "genre": "說理議論", "types": ["主旨寓意", "寫作手法"], "passage": "晉平公問於師曠曰：「吾年七十欲學，恐已暮矣。」師曠曰：「何不炳燭乎？」平公曰：「安有為人臣而戲其君乎？」師曠曰：「盲臣安敢戲其君乎？臣聞之，少而好學，如日出之陽；壯而好學，如日中之光；老而好學，如炳燭之明。炳燭之明，孰與昧行乎？」平公曰：「善哉！」", "translation": "晉平公問師曠：「我七十歲了想學習，恐怕太晚了。」師曠說：「為什麼不點起蠟燭呢？」平公說：「哪有做臣子的戲弄國君的呢？」師曠說：「瞎眼的臣子怎麼敢戲弄國君？我聽說，少年時好學，像初升太陽的光；壯年時好學，像正午的陽光；老年時好學，像點燃蠟燭的光亮。點著蠟燭的光亮，和在黑暗中摸索行走比起來，哪一個好呢？」平公說：「說得好啊！」", "keywords": [{"w": "暮", "m": "晚，雙關天色已晚與年紀已老"}, {"w": "炳燭", "m": "點燃蠟燭"}, {"w": "孰與", "m": "和……比起來哪一個"}, {"w": "昧行", "m": "在黑暗中行走"}], "questions": [{"n": 14, "qtype": "單選", "stem": "閱讀下文，師曠以燭火向晉平公說明學習的道理，下列選項何者正確？", "options": {"A": "老年學習，方法明確，經驗豐富，勝過少壯時期", "B": "老年學習，起步雖晚，效果雖小，但也勝過不學", "C": "少年學習，成就最大，有如日正當中，發揚光大", "D": "壯年學習，效果最好，有如初昇朝陽，蓬勃向上"}, "answer": "B", "explain": "師曠用三種光比喻：少年像朝陽、壯年像正午、老年像燭光。燭光雖然比不上太陽，但「孰與昧行乎」——總比摸黑走路好。(B)正確。(A)燭光明明比太陽弱，不是勝過少壯。(C)少年是「日出之陽」，日正當中是壯年。(D)壯年是「日中之光」，初昇朝陽是少年，兩者對調了。", "skill": "比喻題先列「本體＝喻體」對照表（少＝朝陽、壯＝正午、老＝燭光），選項一對照就知道誰配錯。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-17", "exam": "tc104", "nums": [17], "form": "單題", "img": "img/tc104-17.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "然則何時而樂耶？其必曰：先天下之憂而憂，後天下之樂而樂乎！噫！微斯人，吾誰與歸？（范仲淹〈岳陽樓記〉）", "translation": "題幹：那麼什麼時候才快樂呢？他們一定會說：在天下人憂慮之前先憂慮，在天下人快樂之後才快樂吧！唉！如果沒有這種人，我和誰同道呢？(A)如果沒有管仲，我們恐怕都要披散頭髮、衣襟向左開（淪為夷狄）了。(B)天下的事，常常從極細微處發生，最後成為大禍。(C)有一天風雪嚴寒，（左公）帶著幾名騎兵出門，隱藏身分出行，進入古寺。(D)我看夏商周三代以後，世道衰落，人們拋棄禮義、捨棄廉恥。", "keywords": [{"w": "微", "m": "如果沒有（假設否定）"}, {"w": "微行", "m": "隱藏身分出行"}, {"w": "道微", "m": "道德衰微"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列文句中的「微」，何者與「然則何時而樂耶？其必曰：先天下之憂而憂，後天下之樂而樂乎！噫！微斯人，吾誰與歸」的「微」字義相同？", "options": {"A": "「微」管仲，吾其被髮左衽矣", "B": "天下之事，常發於至「微」，而终為大患", "C": "一日，風雪嚴寒，從數騎出，「微」行，入古寺", "D": "吾觀三代以下，世衰道「微」，棄禮義，捐廉恥"}, "answer": "A", "explain": "題幹「微斯人」是「如果沒有這種人」。(A)正確：「微管仲」＝如果沒有管仲（《論語‧憲問》），也是假設否定。(B)「至微」是極細小的地方。(C)「微行」是隱藏身分、便服出行（方苞〈左忠毅公軼事〉）。(D)「道微」是道德衰微（顧炎武〈廉恥〉）。", "skill": "「微＋人名／代詞」放在句首、後面接一個可怕或無奈的結果，幾乎都是「如果沒有」的意思。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-18", "exam": "tc104", "nums": [18], "form": "單題", "img": "img/tc104-18.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "本題考古籍內容性質，無文言引文。", "keywords": [{"w": "左傳", "m": "解釋《春秋》的編年史，記春秋時代"}, {"w": "戰國策", "m": "記戰國時代謀士遊說的國別史"}], "questions": [{"n": 18, "qtype": "單選", "stem": "書店為了促銷古籍，往往在書名前加上標題。下列古籍的標題，何者與書的內容性質不符合？", "options": {"A": "滿紙荒唐辛酸淚：紅樓夢", "B": "先民生活的謳歌：詩經", "C": "魏晉人物寫真集：世說新語", "D": "戰國群雄爭霸錄：左傳"}, "answer": "D", "explain": "(D)不符合：《左傳》記的是春秋時代的歷史（配合《春秋》編年），不是戰國；寫戰國群雄、謀士縱橫的是《戰國策》。(A)符合：曹雪芹自題《紅樓夢》「滿紙荒唐言，一把辛酸淚」。(B)符合：《詩經》多寫周代百姓生活與情感。(C)符合：《世說新語》記魏晉名士言行軼事，像人物素描集。", "skill": "文化常識題先抓「時代」：春秋→《左傳》、戰國→《戰國策》、魏晉→《世說新語》，時代對錯常是陷阱。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-19", "exam": "tc104", "nums": [19], "form": "單題", "img": "img/tc104-19.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "本題考經史子集四部分類常識，無文言引文。", "keywords": [{"w": "斷代史", "m": "只記一個朝代的史書，以《漢書》為祖"}, {"w": "昭明文選", "m": "南朝梁昭明太子蕭統編，現存最早的詩文總集"}], "questions": [{"n": 19, "qtype": "單選", "stem": "閱讀下文，其中劃底線處依序應填入的內容，正確的選項為何？經、史、子、集是傳統的中國書籍分類法。經部中的＿＿有〈大學〉、〈中庸〉兩篇，後由南宋朱熹取出與《論語》、《孟子》組成「四書」。史部中的＿＿是斷代史之祖，屬於紀傳體的著作。子部中的＿＿又稱《道德經》，是道家學派的著作。集部中的＿＿由蕭統與文人共編，是最早的詩文總集。", "options": {"A": "《詩經》、《國語》、《莊子》、《世說新語》", "B": "《禮記》、《漢書》、《老子》、《昭明文選》", "C": "《尚書》、《通鑑》、《列子》、《樂府詩集》", "D": "《春秋》、《史記》、《管子》、《文心雕龍》"}, "answer": "B", "explain": "(B)全對：〈大學〉〈中庸〉原是《禮記》的篇章；斷代史之祖是班固《漢書》；《道德經》就是《老子》；蕭統編《昭明文選》。(A)《國語》是國別史，《莊子》不叫《道德經》，《世說新語》是小說。(C)《資治通鑑》是編年通史，《列子》非《道德經》，《樂府詩集》是宋代郭茂倩所編。(D)《史記》是紀傳體通史之祖，《管子》屬法家，《文心雕龍》是文學評論。", "skill": "四格填空只要先確定最有把握的一格（例如《道德經》＝《老子》），就能一次刪掉三個選項。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-26", "exam": "tc104", "nums": [26], "form": "單題", "img": "img/tc104-26.png", "source": "白居易詩句（綜合）", "author": "白居易", "genre": "古典詩詞曲", "types": ["文意推論", "詩詞賞析"], "passage": "(A)面黑眼昏頭雪白，老應無可更增加。(B)目昏思寢即安眠，足軟妨行便坐禪。(C)眼澀夜先臥，頭慵朝未梳。有時扶杖出，盡日閉門居。(D)兩目今先暗，中年似老翁。看朱漸成碧，羞日不禁風。", "translation": "(A)臉色黝黑、眼睛昏花、頭髮雪白，老到大概沒什麼可再增加的了。(B)眼睛昏花想睡就安心睡覺，腳軟不方便走路就坐禪。(C)眼睛乾澀，晚上早早就躺下；頭昏沉懶散，早上連頭也不梳。有時拄著拐杖出門，整天關著門待在家。(D)兩眼現在先昏暗了，才中年就像個老頭。看紅色漸漸變成綠色，怕見陽光、經不起風吹。", "keywords": [{"w": "眼澀", "m": "眼睛乾澀不適"}, {"w": "頭慵", "m": "頭昏沉、懶散無力"}, {"w": "看朱成碧", "m": "把紅色看成綠色，視覺錯亂"}], "questions": [{"n": 26, "qtype": "單選", "stem": "依上文，下列白居易詩句，何者最有助於作者研判白居易患有青光眼？（上文為譚健鍬〈歷史課本沒寫出的隱情〉：作者認為玻璃體病變不足以解釋白居易全部病狀，因為他還有眼痛，間有眼澀和頭暈的現象；眼痛合併眼昏，可用急性閉角型青光眼解釋。）", "options": {"A": "面黑眼昏頭雪白，老應無可更增加", "B": "目昏思寢即安眠，足軟妨行便坐禪", "C": "眼澀夜先臥，頭慵朝未梳。有時扶杖出，盡日閉門居", "D": "兩目今先暗，中年似老翁。看朱漸成碧，羞日不禁風"}, "answer": "C", "explain": "文章的推理是：眼昏、飛蚊症用玻璃體病變就能解釋，但白居易「還有眼痛，間有眼澀和頭暈」，這些症狀才讓作者想到青光眼。(C)同時寫到「眼澀」與「頭慵」（頭昏沉），正是作者用來研判青光眼的關鍵症狀。(A)只有「眼昏」加上臉黑、白髮，是一般老化，白內障、玻璃體病變也會眼昏。(B)「目昏」「足軟」也只是衰老、視力差，無法區別病因。(D)「兩目先暗」是視力下降；「看朱成碧」雖然容易聯想到青光眼的青碧色視覺，但文中說那是青光眼命名的由來，並不是作者研判的依據，且前文已指出單憑眼昏無法確定病因，所以不是「最有助於」研判的詩句。", "skill": "「最有助於研判」要回到作者的推理鏈：哪個症狀是「其他病解釋不了、只有這個病能解釋」的，那句詩就是答案。"}], "difficulty": "難", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-30", "exam": "tc104", "nums": [30, 31, 32], "form": "題組", "img": "img/tc104-30.png", "source": "〈小港渡者〉", "author": "周容", "genre": "寓言故事", "types": ["文意推論", "主旨寓意", "人物情感"], "passage": "庚寅冬，予自小港欲入蛟川城，命小奚以木簡束書從。時西日沈山，晚煙縈樹，望城二里許。因問渡者尚可得南門開否？渡者熟視小奚，應曰：「徐行之，尚開也；速進則闔。」予慍為戲。趨行及半，小奚仆，束斷書崩，啼未即起。理書就束而前，門已牡下矣。予爽然，思渡者言近道。天下之以躁急自敗，窮暮而無所歸宿者，其猶是也夫！其猶是也夫！", "translation": "庚寅年冬天，我從小港要進蛟川城，叫書僮用木板捆著書跟著我。當時夕陽西沉，傍晚的煙霧繚繞著樹木，望見城牆大約還有二里遠。於是問渡船的人：還趕得上南門開著嗎？渡者仔細看了看書僮，回答說：「慢慢走，城門還開著；走得快，城門就關了。」我很生氣，以為他在開玩笑。快步走到一半，書僮跌倒，捆書的繩子斷了、書散落一地，他哭著沒能馬上爬起來。等整理好書重新捆好再往前走，城門已經上鎖了。我茫然若失，想到渡者的話很接近道理。天下那些因為急躁而自取失敗、到天黑都沒有地方安身的人，大概就像這樣吧！大概就像這樣吧！", "keywords": [{"w": "小奚", "m": "書僮"}, {"w": "熟視", "m": "仔細地看"}, {"w": "闔", "m": "關閉"}, {"w": "慍", "m": "生氣"}, {"w": "仆", "m": "跌倒"}, {"w": "牡下", "m": "上鎖"}, {"w": "爽然", "m": "茫然若失的樣子"}, {"w": "近道", "m": "接近道理"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依上文，下列何者是渡者判斷作者能否及時入城的依據？", "options": {"A": "書僮的狀況", "B": "時間的影響", "C": "距離的條件", "D": "天候的因素"}, "answer": "A", "explain": "關鍵在「渡者熟視小奚」，他仔細看了書僮背的那一大捆書，才說「徐行之，尚開也；速進則闔」——知道走太快書會散掉。(A)正確。(B)(C)時間和距離是作者自己在擔心的，渡者的判斷重點不在這裡。(D)文中沒提天候影響。", "skill": "答「判斷依據」要找人物說話前「做了什麼動作、看了什麼」，那個觀察對象就是依據。"}, {"n": 31, "qtype": "單選", "stem": "依上文，文末兩次的「其猶是也夫！其猶是也夫」，表達了作者何種呼告語氣？", "options": {"A": "埋怨的語氣", "B": "沈痛的語氣", "C": "請求的語氣", "D": "感悟的語氣"}, "answer": "D", "explain": "作者先「慍為戲」，吃了苦頭後「爽然，思渡者言近道」，從一件小事領悟到人生道理，再推到天下急躁的人，連說兩次是在強調自己的醒悟。(D)正確。(A)他沒有怪罪書僮或渡者。(B)語氣是恍然大悟，談不上悲痛。(C)沒有向誰提出請求。", "skill": "判斷語氣看情緒轉折：前面「慍」、後面「爽然」，從生氣到明白，就是「感悟」。"}, {"n": 32, "qtype": "單選", "stem": "依上文，作者透過此次經驗所得到的體會，下列選項何者錯誤？", "options": {"A": "性急圖快，欲速則不達", "B": "以小見大，察言並觀色", "C": "智者慮遠，見微以知著", "D": "力排異議，擇善而固執"}, "answer": "D", "explain": "(D)錯誤：作者的教訓剛好相反——他當初不聽渡者的「異議」，固執己見才吃虧，所以體會不會是「力排異議」。(A)正確：急著趕路反而進不了城。(B)正確：渡者由書僮的樣子（小處）推知結果，作者也體會到要細心觀察。(C)正確：渡者看到書捆不牢這個小徵兆，就預見結果。", "skill": "「體會」題先想故事教訓的方向，再找和教訓方向相反的選項；這篇的教訓是「別急、要聽勸」。"}], "difficulty": "易", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-33", "exam": "tc104", "nums": [33, 34, 35], "form": "題組", "img": "img/tc104-33.png", "source": "〈蜃說〉", "author": "林景熙", "genre": "筆記小品", "types": ["文意推論", "寫作手法", "句意理解"], "passage": "嘗讀《漢天文志》，載「海旁蜃氣象樓臺」，初未之信。庚寅季春，予避寇海濱。一日飯午，家僮走報怪事，曰：「海中忽起數山，皆昔未嘗有！父老觀以為甚異。」余駭而出。會穎川主人走使邀余，既至，相攜登聚遠樓東望。第見滄溟浩渺中，矗如奇峰，聯如疊巘，列如崪岫，隱見不常。移時，城郭、堂榭，驟變欻起，如眾大之區，數十萬家，魚鱗相比。中有浮圖老子之宮，三門嵯峨，鐘鼓樓翼其左右，檐牙歷歷，極公輸巧不能過。又移時，或立如人，或站如獸，或列若旌旗之飾、甕盎之器，詭異萬千。日近晡，冉冉漫滅。向之有者安在？而海自若也。《筆談》紀登州海市事，往往類此，予因是始信。", "translation": "我曾讀《漢書‧天文志》，記載「海邊的蜃氣會形成樓臺的樣子」，起初並不相信。庚寅年春末，我到海邊躲避盜寇。有一天中午吃飯時，家僮跑來報告怪事，說：「海中忽然冒出好幾座山，都是從前沒有的！老人家看了都覺得非常奇怪。」我吃驚地跑出去。正好穎川主人派人來邀我，到了之後，一起登上聚遠樓向東望。只見大海遼闊無邊之中，有的高聳像奇峰，有的相連像重疊的山嶺，有的並列像險峻的峰巒，忽隱忽現，變化不定。過了一會兒，城郭、廳堂亭榭，突然變化出現，像大都市一樣，有幾十萬戶人家，像魚鱗般緊密排列。其中有佛寺道觀，三座大門高聳，鐘樓鼓樓像翅膀般排在左右，屋檐翹角清清楚楚，就算魯班的巧藝也比不上。又過一會兒，有的站立像人，有的蹲著像野獸，有的排列像旗幟的裝飾、甕盆等器物，奇異的景象千變萬化。太陽快到申時，景象慢慢消散。剛才的景物在哪裡呢？而大海還是原來的樣子。《夢溪筆談》記載登州海市蜃樓的事，往往和這個類似，我因此才相信。", "keywords": [{"w": "蜃", "m": "傳說中能吐氣成樓臺的大蛤，此指海市蜃樓"}, {"w": "走", "m": "跑"}, {"w": "第", "m": "只"}, {"w": "滄溟", "m": "大海"}, {"w": "巘", "m": "山峰"}, {"w": "欻", "m": "忽然"}, {"w": "浮圖老子之宮", "m": "佛寺和道觀"}, {"w": "公輸", "m": "公輸般（魯班），巧匠"}, {"w": "晡", "m": "申時，下午三到五點"}, {"w": "自若", "m": "和原來一樣"}], "questions": [{"n": 33, "qtype": "單選", "stem": "依上文，下列選項中的景象，何者沒有出現在蜃景中？", "options": {"A": "櫛比鱗次的高樓", "B": "翼可蔽天的鵬鳥", "C": "建築精巧的寺廟", "D": "直立高聳的群山"}, "answer": "B", "explain": "(B)沒有出現：文中動物只有「站如獸」，沒有大鳥；「翼其左右」的「翼」是形容鐘鼓樓像兩翼排在兩邊，不是鳥。(A)有：「數十萬家，魚鱗相比」。(C)有：「浮圖老子之宮……極公輸巧不能過」。(D)有：「矗如奇峰，聯如疊巘」。", "skill": "找「沒出現」的景象，把原文的景物清單列出來逐一打勾；小心「翼」這種動詞化的字被拿來當誘答。"}, {"n": 34, "qtype": "單選", "stem": "依上文，下列選項中的敘述，何者錯誤？", "options": {"A": "文中蜃景出現的時段，是從上午到中午", "B": "當蜃景慢慢消失後，海上景色一如往常", "C": "面對蜃景的現象，作者的心態是從不信到相信", "D": "作者接受穎川主人的邀請，同在高樓上看蜃景"}, "answer": "A", "explain": "(A)錯誤：家僮在「飯午」（中午吃飯時）來報，景象到「日近晡」（下午三到五點）才消失，所以是從中午到傍晚，不是上午到中午。(B)正確：「冉冉漫滅……而海自若也」。(C)正確：「初未之信」到「予因是始信」。(D)正確：「穎川主人走使邀余……相攜登聚遠樓東望」。", "skill": "時間題要記古代時辰：日中＝中午，晡＝下午三到五點；把文中的時間詞抓出來排順序就能判斷。"}, {"n": 35, "qtype": "單選", "stem": "依上文，下列選項中作者描述蜃景用語的說明，何者正確？", "options": {"A": "「隱見不常」、「驟變欻起」，描寫了蜃景變化的飄忽不定", "B": "「矗如」、「聯如」、「立如」、「站如」，呈現了蜃景的千篇一律", "C": "「家僮走報」、「父老觀以為甚異」，強調了人們看見蜃景的不以為異", "D": "「移時」、「又移時」，指出作者為了要有更好的觀賞視野而不時移動位置"}, "answer": "A", "explain": "(A)正確：「隱見不常」是忽隱忽現，「驟變欻起」是突然變出，都寫變化難測。(B)用不同的「如」字比喻正是要寫景象多變，結論是「詭異萬千」，不是千篇一律。(C)家僮跑著來報、父老「以為甚異」，是大家都覺得非常奇怪，與「不以為異」相反。(D)「移時」是「過了一段時間」，表示時間推移，不是移動位置。", "skill": "「移時」「須臾」「俄而」都是時間詞，別被字面的「移」騙成移動；遇到相反詞（甚異／不以為異）要回原文核對。"}], "difficulty": "中", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc104-36", "exam": "tc104", "nums": [36, 37, 38], "form": "題組", "img": "img/tc104-36.png", "source": "陶淵明〈桃花源記〉、權德輿〈桃源篇〉", "author": "陶淵明、權德輿", "genre": "山水遊記", "types": ["比較閱讀", "句意理解", "寫作手法"], "passage": "【甲】初極狹，纔通人；復行數十步，豁然開朗。土地平曠，屋舍儼然。有良田、美池、桑、竹之屬，阡陌交通，雞犬相聞。其中往來種作，男女衣著，悉如外人；黃髮垂髫，並怡然自樂。見漁人，乃大驚，問所從來，具答之。便要還家，設酒、殺雞、作食。村中聞有此人，咸來問訊。自云：「先世避秦時亂，率妻子、邑人來此絕境，不復出焉，遂與外人間隔。」問今是何世？乃不知有漢，無論魏、晉！此人一一為具言所聞，皆嘆惋。餘人各復延至其家，皆出酒食。停數日，辭去。此中人語云：「不足為外人道也。」（節自陶淵明〈桃花源記〉）\n【乙】一路鮮雲雜彩霞，漁舟遠遠逐桃花。漸入空濛迷鳥道，寧知掩映有人家。龐眉秀骨爭迎客，鑿井耕田人世隔。不知漢代有衣冠，猶說秦家變阡陌。石髓雲英甘且香，仙翁留飯出青囊。相逢自是松喬侶，良會應殊劉阮郎。（節自權德輿〈桃源篇〉）", "translation": "【甲】洞口起初非常狹窄，只能通過一個人；再走幾十步，忽然變得開闊明亮。土地平坦寬廣，房屋整整齊齊。有肥沃的田地、美麗的池塘，還有桑樹竹子之類，田間小路交錯相通，到處聽得到雞鳴狗叫。在其中來往耕作的人，男女的穿著都和外面的人一樣；老人和小孩都快樂自在。他們看見漁人，非常吃驚，問他從哪裡來，漁人詳細回答。就邀請他到家裡，擺酒、殺雞、做飯款待。村裡人聽說有這個人，都來打聽消息。他們說：「祖先為了躲避秦朝的戰亂，帶著妻兒和同鄉來到這與世隔絕的地方，就不再出去，於是和外界隔絕了。」問現在是什麼朝代，竟然不知道有漢朝，更不用說魏、晉了！漁人把所聽到的一一詳細告訴他們，大家都感嘆惋惜。其他人也各自請他到家裡，都拿出酒飯招待。住了幾天，漁人告辭離開。這裡的人叮嚀說：「不必對外面的人說啊。」\n【乙】一路上鮮豔的雲朵夾雜著彩霞，漁船遠遠地追逐著桃花。漸漸進入迷濛的險峻山路，哪裡知道在掩映之中竟然有人家。眉毛花白、骨相清秀的老人爭著來迎接客人，在這裡鑿井耕田，與人世隔絕。他們不知道漢代的衣冠文物，還在談論秦朝改變田制的事。石髓和雲英又甜又香，仙翁從青色袋子中拿出來留客吃飯。相逢的自然是赤松子、王子喬這樣的仙人，這次美好的聚會應該和劉晨、阮肇的奇遇不同。", "keywords": [{"w": "儼然", "m": "整齊的樣子"}, {"w": "阡陌交通", "m": "田間小路交錯相通"}, {"w": "黃髮垂髫", "m": "老人和小孩"}, {"w": "要", "m": "通「邀」，邀請"}, {"w": "無論", "m": "更不必說"}, {"w": "龐眉", "m": "眉毛花白，指老人"}, {"w": "鳥道", "m": "狹隘險絕的山路"}, {"w": "石髓雲英", "m": "仙家服食的石乳與雲母，指仙人食物"}, {"w": "松喬侶", "m": "仙人赤松子、王子喬一類的同伴"}], "questions": [{"n": 36, "qtype": "單選", "stem": "下列關於〈桃花源記〉和〈桃源篇〉的文句解釋，何者正確？", "options": {"A": "〈桃花源記〉的「阡陌交通」，意近於〈桃源篇〉的「鑿井耕田」", "B": "〈桃花源記〉的「黃髮垂髫」，意同於〈桃源篇〉的「龐眉秀骨」", "C": "〈桃花源記〉的「便要還家」，意近於〈桃源篇〉的「寧知掩映有人家」", "D": "〈桃花源記〉的「設酒、殺雞、作食」，意同於〈桃源篇〉的「石髓雲英甘且香」"}, "answer": "A", "explain": "(A)正確：「阡陌交通」寫田間小路縱橫，「鑿井耕田」寫挖井種田，都在描寫村民的農耕生活，意思相近。(B)「黃髮垂髫」是老人加小孩，「龐眉秀骨」只寫老人，範圍不同。(C)「便要還家」是邀漁人回家，「寧知掩映有人家」是驚訝發現有人居住，意思不同。(D)「設酒殺雞」是一般農家菜，「石髓雲英」是仙家食物，性質不同。", "skill": "比較兩文詞句時，先各自翻成白話，再看「範圍」與「性質」是否一致；凡、仙不同、老少不同都是陷阱。"}, {"n": 37, "qtype": "單選", "stem": "下列關於〈桃花源記〉和〈桃源篇〉的比較，何者錯誤？", "options": {"A": "〈桃花源記〉和〈桃源篇〉皆謂桃花源為與世隔絕之境", "B": "〈桃源篇〉認為居桃花源中者為神仙，〈桃花源記〉無此想法", "C": "〈桃花源記〉將故事背景設在晉代，〈桃源篇〉將故事背景改為漢代", "D": "〈桃源篇〉未述及〈桃花源記〉「此中人語云：不足為外人道也」的情節"}, "answer": "C", "explain": "(C)錯誤：〈桃源篇〉說「不知漢代有衣冠」，意思是桃源人不知道有漢朝，並不是把故事改到漢代，這和〈桃花源記〉「乃不知有漢，無論魏晉」相同。(A)正確：甲「與外人間隔」，乙「人世隔」。(B)正確：乙有「仙翁」「松喬侶」，把村民寫成仙人；甲的村民穿著「悉如外人」，是凡人。(D)正確：節錄的〈桃源篇〉沒寫到叮嚀「不足為外人道」。", "skill": "「不知漢代」是桃源人的認知，不是故事時代；讀詩時要分清「誰的觀點」。"}, {"n": 38, "qtype": "單選", "stem": "〈桃源篇〉較〈桃花源記〉多出「一路鮮雲雜彩霞」、「漸入空濛迷鳥道」的描寫，添加這樣的描寫，最可能具有下列何種作用？", "options": {"A": "烘托桃花源為渺遠絕美的仙家異境", "B": "說明桃花源「土地平曠，屋舍儼然」", "C": "強調桃花源中之人為避秦亂、冒險入山的艱辛", "D": "為漁人入桃花源後「大驚」、「嘆惋」預設反襯伏筆"}, "answer": "A", "explain": "彩雲彩霞、迷濛險絕的山路，營造出又美又遙遠、難以抵達的氣氛，配合後文「仙翁」「松喬侶」，把桃源寫成仙境。(A)正確。(B)這兩句寫的是入口沿途，不是村內平坦整齊的景象。(C)寫的是漁人一路所見，不是祖先避秦入山的艱辛。(D)「大驚」「嘆惋」是〈桃花源記〉中村民的反應，〈桃源篇〉沒有這些情節，談不上伏筆。", "skill": "問「添加描寫的作用」，先看描寫的氛圍（美、遠、迷濛），再找與全篇主題（仙境）呼應的選項。"}], "difficulty": "中", "label": "104統測", "year": 104, "kind": "統測"}, {"id": "tc105-02", "exam": "tc105", "nums": [2], "form": "單題", "img": "img/tc105-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "引觴滿酌，頹然就醉，不知日之入。（柳宗元〈始得西山宴遊記〉）／望之蔚然而深秀者，琅琊也。（歐陽脩〈醉翁亭記〉）／土地平曠，屋舍儼然，有良田、美池、桑、竹之屬。（陶淵明〈桃花源記〉）／則有去國懷鄉，憂讒畏譏，滿目蕭然，感極而悲者矣。（范仲淹〈岳陽樓記〉）", "translation": "(A)拿起酒杯斟滿酒，醉倒了，不知道太陽已經下山。(B)遠望那草木茂盛、幽深秀麗的地方，就是琅琊山。(C)土地平坦寬廣，房屋整整齊齊，有肥沃的田地、美麗的池塘和桑樹竹子之類。(D)就會有離開國都、懷念家鄉，擔心讒言、害怕譏諷，滿眼蕭條冷落，感慨到極點而悲傷的心情。", "keywords": [{"w": "頹然", "m": "倒下、委靡不振的樣子"}, {"w": "蔚然", "m": "草木茂盛的樣子"}, {"w": "儼然", "m": "古：整齊的樣子；今：好像、很像"}, {"w": "蕭然", "m": "蕭條冷落的樣子"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列各組「」內的詞，何者意義不同？", "options": {"A": "引觴滿酌，「頹然」就醉，不知日之入／在空曠的客廳裡，盛公獨自「頹然」靠在太師椅上", "B": "望之「蔚然」而深秀者，琅琊也／黃山樹木中最有特色的要算松樹了，奇美挺秀，「蔚然」可觀", "C": "土地平曠，屋舍「儼然」，有良田、美池、桑、竹之屬／她愛照鏡子，左轉右轉，「儼然」是個公主", "D": "則有去國懷鄉，憂讒畏譏，滿目「蕭然」，感極而悲者矣／雲志嫌這顏色不起眼，連九莉也覺得環堵「蕭然」"}, "answer": "C", "explain": "(C)意義不同：〈桃花源記〉「屋舍儼然」是房屋整齊；後句「儼然是個公主」是「好像、宛如」。(A)兩個「頹然」都是身體倒下、委靡無力的樣子。(B)兩個「蔚然」都是草木茂盛的樣子。(D)兩個「蕭然」都是蕭條冷落、空蕩的樣子（「環堵蕭然」是屋內空空蕩蕩）。", "skill": "「○然」形容詞要看後面接什麼：接名詞判斷句（是個公主）多半是「好像」，描寫景物則是狀態詞。"}], "difficulty": "易", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-06", "exam": "tc105", "nums": [6], "form": "單題", "img": "img/tc105-06.png", "source": "《呂氏春秋‧貴當》", "author": "呂不韋門客", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "荊有善相人者，所言無遺策，聞於國，莊王見而問焉。對曰：「臣非能相人也，能觀人之友也。」", "translation": "楚國有個擅長看相的人，他說的話從來沒有失誤，名聲傳遍全國，楚莊王召見他並詢問其中的道理。他回答說：「我不是會看人的面相，而是會觀察一個人所交的朋友。」", "keywords": [{"w": "荊", "m": "楚國"}, {"w": "相人", "m": "看相、判斷人的好壞"}, {"w": "無遺策", "m": "沒有失算"}, {"w": "聞於國", "m": "名聲傳遍全國"}], "questions": [{"n": 6, "qtype": "單選", "stem": "依據下文，「善相人者」所以能提出研判，係因掌握人際互動的何種特質？", "options": {"A": "人云亦云", "B": "物以類聚", "C": "樹大招風", "D": "趨利避害"}, "answer": "B", "explain": "看相的人說穿了是「觀人之友」：看一個人交什麼朋友，就能判斷他是什麼樣的人，因為人會和同類的人聚在一起。(B)物以類聚正確。(A)人云亦云是沒主見、跟著別人說。(C)樹大招風是名大易招忌。(D)趨利避害是追求利益、避開禍害，都和「看朋友知其人」無關。", "skill": "短文寓言，關鍵句往往在最後的回答；把「觀人之友」換成一個成語，就是答案。職場上也一樣：看一個人常和誰合作，大概能猜到他的工作風格。"}], "difficulty": "易", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-10", "exam": "tc105", "nums": [10], "form": "單題", "img": "img/tc105-10.png", "source": "《菜根譚》", "author": "洪應明", "genre": "經典語錄", "types": ["文意推論", "比較閱讀"], "passage": "(A)處林泉之下，須要懷廊廟的經綸。(B)談山林之樂者，未必真得山林之趣。(C)草際煙光，水心雲影，閒中觀去，見乾坤最上文章。(D)濟世經邦，要段雲水的趣味，若一有貪著，便墮危機。", "translation": "(A)隱居在山林泉石之間，仍要懷抱治理國家的才能。(B)整天談論山林樂趣的人，未必真正得到山林的趣味。(C)草叢邊的煙霧光影、水中央的雲朵倒影，在悠閒中觀賞，就能看見天地間最美好的文章。(D)治理國家、救助世人，要有一份行雲流水般的灑脫趣味；一旦有了貪戀執著，就會陷入危險。", "keywords": [{"w": "林泉", "m": "山林泉石，指隱居之處"}, {"w": "廊廟", "m": "朝廷"}, {"w": "經綸", "m": "治理國家的才能"}, {"w": "乾坤", "m": "天地"}, {"w": "貪著", "m": "貪戀執著"}], "questions": [{"n": 10, "qtype": "單選", "stem": "閱讀下文，推斷何者最接近作者的想法？（文略：鍾理和〈我的書齋〉：我的書齋既無屋頂又無牆壁，它就在空曠偉大的天地中，與浩然之氣相往來，與自然成一整體。）", "options": {"A": "處林泉之下，須要懷廊廟的經綸", "B": "談山林之樂者，未必真得山林之趣", "C": "草際煙光，水心雲影，閒中觀去，見乾坤最上文章", "D": "濟世經邦，要段雲水的趣味，若一有貪著，便墮危機"}, "answer": "C", "explain": "鍾理和把大自然當書齋，山川雲煙「盡收眼底」，在天地中讀到最好的東西。(C)正確：在自然景物中悠閒觀賞，就能讀到「乾坤最上文章」，和「以天地為書齋」最接近。(A)講隱居仍要有治國抱負，作者沒談政治。(B)批評口說山林之樂的人，與作者真心享受自然的態度不合。(D)講從政要有灑脫心境，主題不同。", "skill": "文白對讀先用一句話抓白話文主旨（大自然就是我的書齋），再把文言選項翻成白話比對，主題相同才算接近。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-11", "exam": "tc105", "nums": [11], "form": "單題", "img": "img/tc105-11.png", "source": "出處待查（祝壽詩）", "author": "", "genre": "其他", "types": ["文化常識", "詩詞賞析"], "passage": "春風萱國綺筵開，笑指麻姑晉酒杯。仁壽鏡光鸞自舞，滄桑籌數鶴添來。", "translation": "春風吹拂母親的居所，華美的宴席已經擺開，笑著指向麻姑仙女，請她來敬酒。仁德長壽的光輝照在鏡中，鸞鳥自在起舞；經歷滄海桑田，仙鶴不斷為她添上壽籌。", "keywords": [{"w": "萱", "m": "萱草，代指母親"}, {"w": "麻姑", "m": "傳說中的女仙，常用於女性祝壽"}, {"w": "晉", "m": "進、獻上"}, {"w": "鶴添籌", "m": "海屋添籌，祝人長壽"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下圖二人受邀出席一場宴會，依祝賀詩的內容，□□□□內的題辭應是：（圖中祝賀詩：「春風萱國綺筵開，笑指麻姑晉酒杯。仁壽鏡光鸞自舞，滄桑籌數鶴添來。」）", "options": {"A": "慈竹長青", "B": "鸞鳳和鳴", "C": "跨鶴仙鄉", "D": "里仁為美"}, "answer": "A", "explain": "詩中「萱」代表母親，「麻姑」是女壽常用典故，「鶴添籌」祝長壽，所以這是替女性長輩祝壽的宴會。(A)慈竹長青是女壽題辭，正確。(B)鸞鳳和鳴用於結婚。(C)跨鶴仙鄉是哀輓男性喪事。(D)里仁為美用於遷居（喬遷）。", "skill": "題辭題先從詩中抓「場合線索」（萱、麻姑＝女性；籌、鶴＝長壽），再刪掉婚、喪、遷居等不同場合的題辭。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-12", "exam": "tc105", "nums": [12], "form": "單題", "img": "img/tc105-12.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "1.是謂大同 2.兼愛交利 3.舉一反三 4.人有四端 5.逍遙無為 6.白露為霜", "translation": "本題考菜名所用詞語的原始出處：是謂大同（《禮記‧禮運》）、兼愛交利（《墨子》）、舉一反三（化自《論語‧述而》「舉一隅不以三隅反」）、人有四端（《孟子‧公孫丑上》）、逍遙無為（《莊子》）、白露為霜（《詩經‧秦風‧蒹葭》）。", "keywords": [{"w": "經部", "m": "儒家經典，如《詩經》《禮記》《論語》《孟子》"}, {"w": "子部", "m": "諸子百家，如《墨子》《莊子》"}], "questions": [{"n": 12, "qtype": "單選", "stem": "古代典籍可分為「經、史、子、集」四部。下圖菜單的四字創意菜名，何者的原始出處來自「經」部典籍？（菜單：1.是謂大同 2.兼愛交利 3.舉一反三 4.人有四端 5.逍遙無為 6.白露為霜）", "options": {"A": "1、2、3、6", "B": "1、3、4、6", "C": "2、3、4、5", "D": "3、4、5、6"}, "answer": "B", "explain": "經部收儒家經典。1「是謂大同」出自《禮記》，3「舉一反三」來自《論語》，4「人有四端」出自《孟子》，6「白露為霜」出自《詩經》，四者都是經部，(B)正確。2「兼愛交利」是《墨子》、5「逍遙無為」是《莊子》，屬子部。", "skill": "經部記「儒家十三經」：《詩》《書》《禮》《易》《春秋》加《論語》《孟子》等；墨家、道家著作都歸子部，先刪含2、5的選項。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-13", "exam": "tc105", "nums": [13, 14], "form": "題組", "img": "img/tc105-13.png", "source": "《論語‧公冶長》、《論語‧述而》", "author": "孔子弟子及再傳弟子", "genre": "經典語錄", "types": ["句意理解", "人物情感", "文意推論"], "passage": "甲、顏淵、季路侍。子曰：「盍各言爾志？」子路曰：「願車馬、衣輕裘，與朋友共。敝之而無憾。」顏淵曰：「願無伐善，無施勞。」子路曰：「願聞子之志。」子曰：「老者安之，朋友信之，少者懷之。」（《論語‧公冶長》）\n乙、子謂顏淵曰：「用之則行，舍之則藏，唯我與爾有是夫！」子路曰：「子行三軍，則誰與？」子曰：「暴虎馮河，死而無悔者，吾不與也。必也臨事而懼，好謀而成者也。」（《論語‧述而》）", "translation": "甲、顏淵、子路陪在孔子身旁。孔子說：「何不各自說說你們的志向？」子路說：「我願把車馬、衣服、皮袍和朋友共用，用壞了也沒有遺憾。」顏淵說：「我願不誇耀自己的長處，不張揚自己的功勞。」子路說：「希望聽聽老師的志向。」孔子說：「讓老人安養，讓朋友信任，讓年輕人得到關懷。」\n乙、孔子對顏淵說：「被任用就出來做事，不被任用就隱藏起來，只有我和你能做到吧！」子路說：「老師如果統率三軍，要和誰一起呢？」孔子說：「空手打老虎、徒步過河，死了也不後悔的人，我不和他共事。一定要是遇事謹慎戒懼、善於謀劃而能成功的人。」", "keywords": [{"w": "盍", "m": "何不"}, {"w": "敝", "m": "用壞"}, {"w": "伐善", "m": "誇耀自己的長處"}, {"w": "施勞", "m": "張揚自己的功勞"}, {"w": "舍", "m": "捨棄、不用"}, {"w": "與", "m": "偕同、一起"}, {"w": "暴虎馮河", "m": "空手搏虎、徒步渡河，比喻有勇無謀"}], "questions": [{"n": 13, "qtype": "單選", "stem": "依據上文，下列何者含有「亟欲爭勝」的意味？", "options": {"A": "盍各言爾志", "B": "願聞子之志", "C": "唯我與爾有是夫", "D": "子行三軍，則誰與"}, "answer": "D", "explain": "孔子剛稱讚顏淵「唯我與爾有是夫」，子路馬上問「如果帶兵打仗，您要找誰？」——他自認勇武，想讓老師說出「當然找你」，有急著和顏淵比高下的意味。(D)正確。(A)是孔子請學生說志向，沒有爭勝。(B)子路單純請教老師的志向。(C)是孔子稱讚顏淵，不是爭勝。", "skill": "人物語氣題要看「說話的時機」：緊接在別人被稱讚之後的問題，常隱含不服氣或想表現。"}, {"n": 14, "qtype": "單選", "stem": "要通過「《論語》競技場」關卡，小華須挑出一組文句，且文句的意思能和甲、乙兩段文字中的某處句意相符。若他想順利過關，應挑出：", "options": {"A": "不求完美，不爭功勞", "B": "待時而動，能屈能伸", "C": "少宜戒鬥，老宜無悔", "D": "鍥而不捨，有志竟成"}, "answer": "B", "explain": "(B)正確：「用之則行，舍之則藏」就是有機會就出來做事、沒機會就退隱，等待時機、能屈能伸。(A)「無伐善，無施勞」是不誇耀長處與功勞，不是「不求完美」，前半句不符。(C)甲乙兩段都沒提「戒鬥」，「死而無悔」是孔子不贊同的態度，不是「老宜無悔」。(D)鍥而不捨強調堅持到底，文中沒有對應的句子。", "skill": "「兩句都要對」的選項，要逐字檢查前後兩半，只要一半對不上原文就淘汰。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-15", "exam": "tc105", "nums": [15, 16], "form": "題組", "img": "img/tc105-15.png", "source": "〈蘭亭集序〉", "author": "王羲之", "genre": "書信序跋", "types": ["虛詞句式", "字詞解釋"], "passage": "每覽昔人興感之由，若合一契，未嘗不臨文嗟悼，不能喻之於懷。固知一死生為虛誕，齊彭殤為妄作。", "translation": "每次看到古人發生感慨的原因，和我的感受好像符契一樣相合，沒有一次不是對著文章嘆息哀傷，心裡卻說不清楚為什麼。這才確實知道，把生和死看成一樣是荒誕的，把長壽和短命看成相同是胡說的。", "keywords": [{"w": "若合一契", "m": "像符契一樣相合"}, {"w": "喻", "m": "明白、了解"}, {"w": "一死生", "m": "把死與生看成一樣"}, {"w": "齊彭殤", "m": "把長壽的彭祖與短命夭折的人看成相同"}], "questions": [{"n": 15, "qtype": "單選", "stem": "「未嘗不臨文嗟悼」使用兩個否定詞（未嘗、不）來表達必然、肯定之意。下列文句，何者沒有使用此種表意方式？", "options": {"A": "故凡文化之國，未有不重其史者也", "B": "目不能兩視而明，耳不能兩聽而聰", "C": "蓋不廉則無所不取，不恥則無所不為", "D": "凡百元首，承天景命，莫不殷憂而道著"}, "answer": "B", "explain": "雙重否定＝肯定。(B)沒有：「目不能兩視而明」只有一個否定，意思是眼睛不能同時看兩樣東西還看得清楚，是單純否定。(A)「未有不重其史」＝一定重視歷史（連橫〈臺灣通史序〉）。(C)「無所不取」＝什麼都拿，「無所不為」＝什麼都做（顧炎武〈廉恥〉）。(D)「莫不殷憂」＝沒有不深深憂慮的（魏徵〈諫太宗十思疏〉）。", "skill": "數否定詞：未、不、無、莫、非，同一個意思單位裡出現兩個就是雙重否定；只有一個就是單純否定。"}, {"n": 16, "qtype": "單選", "stem": "「一死生」和「齊彭殤」意謂「視死和生為一，視長壽和短命相齊」，「一」和「齊」均活用為動詞，相當於白話文「把……當成……」之意。下列文句「」內，何者也有相同的用法？", "options": {"A": "漁樵於江渚之上，「侶」魚蝦而友麋鹿", "B": "蓋君子審己以「度」人，故能免於斯累", "C": "君家所寡有者以義耳！竊以為君「市」義", "D": "史公「治」兵，往來桐城，必躬造左公第"}, "answer": "A", "explain": "題幹是「意動用法」：把某物當成某種東西。(A)正確：「侶魚蝦」＝把魚蝦當成伴侶（蘇軾〈赤壁賦〉），名詞「侶」活用為「把……當成伴侶」。(B)「度」本來就是動詞，衡量（曹丕〈典論論文〉）。(C)「市」名詞轉動詞，意思是「買」，但不是「把……當成……」（《戰國策》馮諼客孟嘗君）。(D)「治」本來就是動詞，整治、操練（方苞〈左忠毅公軼事〉）。", "skill": "判斷意動：試著把句子翻成「把○當成△」，翻得通才是；只是名詞變動詞（市＝買）不算意動。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-17", "exam": "tc105", "nums": [17, 18], "form": "題組", "img": "img/tc105-17.png", "source": "〈朝天曲〉之一、之六", "author": "薛昂夫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "典故出處", "文意推論"], "passage": "甲、沛公，大風，也得文章用。卻教猛士歎良弓，多了遊雲夢。駕馭英雄，能擒能縱，無人出彀中。後宮，外宗，險把炎劉并。（薛昂夫〈朝天曲〉之一）\n乙、假王，氣昂，跨下羞都忘。提牌不過一中郎，漂母曾相餉。蒯徹名言，將軍將強，良弓不早藏。未央，法場，險似壇臺上。（薛昂夫〈朝天曲〉之六）", "translation": "甲、沛公（劉邦）寫〈大風歌〉，也算用得上文章。卻讓功臣（韓信）發出「飛鳥盡，良弓藏」的感嘆，藉口巡遊雲夢擒拿他，實在多此一舉。他駕馭英雄，能抓能放，沒有人逃得出他的掌控。但死後后宮呂后、外戚宗族，差點把劉家天下吞併。\n乙、假王（韓信）意氣昂揚，連受胯下之辱的羞恥都忘了。當初在項羽手下只是個持戟的郎中，還靠漂母送飯過活。蒯徹說的名言：將軍功高勢強，（不如自立），他卻沒有早點像良弓一樣收藏起來（急流勇退）。最後在未央宮被處死，那裡成了法場，就像當年拜將的壇臺一樣。", "keywords": [{"w": "沛公", "m": "漢高祖劉邦"}, {"w": "大風", "m": "劉邦所作〈大風歌〉"}, {"w": "歎良弓", "m": "用「狡兔死，走狗烹；飛鳥盡，良弓藏」之典"}, {"w": "遊雲夢", "m": "劉邦偽遊雲夢以擒韓信"}, {"w": "彀中", "m": "箭的射程範圍，比喻掌控之中"}, {"w": "炎劉", "m": "漢朝劉氏（漢以火德王）"}, {"w": "假王", "m": "韓信曾請封「假齊王」"}, {"w": "漂母", "m": "在水邊洗衣的老婦，曾送飯給韓信"}, {"w": "未央", "m": "未央宮，韓信被呂后誅殺之處"}, {"w": "壇臺", "m": "劉邦築壇拜韓信為大將之處"}], "questions": [{"n": 17, "qtype": "單選", "stem": "下列關於曲中詞句的解釋，何者正確？", "options": {"A": "「也得文章用」意謂沛公注重文章濟世；「跨下羞都忘」意謂假王忘卻名利", "B": "「無人出彀中」意謂沛公才能平庸；「提牌不過一中郎」意謂假王志向遠大", "C": "「卻教猛士歎良弓」意謂沛公讓功臣有兔死狗烹之慨；「良弓不早藏」意謂假王未能急流勇退", "D": "「後宮，外宗，險把炎劉并」意謂沛公死於外戚之手；「未央，法場，險似壇臺上」意謂假王死於項羽之手"}, "answer": "C", "explain": "(C)正確：「歎良弓」用「飛鳥盡，良弓藏」的典故，指劉邦讓功臣有兔死狗烹的感嘆；「良弓不早藏」是說韓信沒有及早退隱。(A)「也得文章用」是說劉邦也能寫〈大風歌〉；「跨下羞都忘」是韓信得志後忘了當年胯下之辱，不是忘卻名利。(B)「無人出彀中」是說英雄都在他掌握中，表示劉邦很有手腕；「提牌不過一中郎」是說韓信早年地位低微。(D)劉邦不是死於外戚之手，是死後呂后外戚差點篡奪漢室；韓信是被呂后殺於未央宮，不是死於項羽之手。", "skill": "詠史曲先把人物對號入座（沛公＝劉邦、假王＝韓信），再用熟悉的史事（兔死狗烹、胯下之辱、蕭何月下追韓信）去檢查解釋。"}, {"n": 18, "qtype": "單選", "stem": "若撰寫《從歷史看職場生存之道》一書時，欲以假王與沛公的故事為素材，則就二人的互動關係而言，下列何者是最恰當的篇名？", "options": {"A": "假王出身好，上司急結交", "B": "從來不當明星的假王哲學", "C": "跟假王學八面玲瓏的手腕", "D": "小心！別像假王功高震主"}, "answer": "D", "explain": "韓信功勞太大、又不懂收斂，讓劉邦忌憚，最後被殺——典型的「功高震主」，換成職場就是能力強卻不懂分寸，反而讓主管不安。(D)正確。(A)韓信出身低微（靠漂母接濟）。(B)韓信「氣昂」，很愛出鋒頭。(C)韓信正是不夠圓融才招禍。", "skill": "「互動關係」題要同時看兩個人：上位者的猜忌＋下位者的不收斂，合起來就是「功高震主」。"}], "difficulty": "難", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-19", "exam": "tc105", "nums": [19, 20], "form": "題組", "img": "img/tc105-19.png", "source": "王維〈夏日過青龍寺謁操禪師〉、李白〈望廬山瀑布〉其一、杜甫〈遣興〉", "author": "王維、李白、杜甫", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "甲、龍鍾一老翁，徐步謁禪宮。欲問義心義，遙知空病空。山河天眼裡，世界法身中。莫怪銷炎熱，能生大地風。\n乙、掛流三百丈，噴壑數十里。欻如飛電來，隱若白虹起。初驚河漢落，半灑雲天裡。仰觀勢轉雄，壯哉造化功。海風吹不斷，江月照還空。\n丙、蓬生非無根，漂蕩隨高風。天寒落萬里，不復歸本叢。客子念故宅，三年門巷空。悵望但烽火，戎車滿關東。生涯能幾何，常在羈旅中。", "translation": "甲、一個衰老的老翁，慢慢走去拜謁禪寺。想請教佛法的義理，遠遠就知道連「空」的執著也要放下。山河都在佛的天眼之中，整個世界都在法身之內。別奇怪這裡能消除炎熱，因為它能生出大地的清風。\n乙、瀑布從三百丈高處垂掛而下，水花噴灑山谷幾十里。忽然像閃電飛來，隱約像白虹升起。起初驚訝是銀河落下，一半灑在雲天裡。抬頭看，氣勢越來越雄壯，大自然的造化真是偉大。海風吹也吹不斷，江上月光照著，又顯得空靈。\n丙、蓬草不是沒有根，卻隨著大風飄蕩。天寒時落到萬里之外，再也回不到原本的草叢。在外漂泊的人想念老家，三年來家門巷弄空無一人。惆悵望去只見烽火，戰車布滿關東。人生能有多長，卻常常在旅途中漂泊。", "keywords": [{"w": "龍鍾", "m": "衰老、行動不便的樣子"}, {"w": "禪宮", "m": "佛寺"}, {"w": "空病空", "m": "佛家語，連「空」的執著也要破除"}, {"w": "欻", "m": "忽然"}, {"w": "河漢", "m": "銀河"}, {"w": "本叢", "m": "原生的草叢"}, {"w": "羈旅", "m": "寄居作客、漂泊在外"}], "questions": [{"n": 19, "qtype": "單選", "stem": "依據詩的內容與情境，三詩＿＿內最適合填入的句子依序為何？", "options": {"A": "遙知空病空／江月照還空／三年門巷空", "B": "遙知空病空／三年門巷空／江月照還空", "C": "江月照還空／三年門巷空／遙知空病空", "D": "江月照還空／遙知空病空／三年門巷空"}, "answer": "A", "explain": "甲寫拜謁禪寺問佛法，接佛理句「遙知空病空」最合。乙寫瀑布，海風、江月是自然景物，「海風吹不斷，江月照還空」對仗工整。丙寫漂泊思鄉，「客子念故宅，三年門巷空」寫家園荒涼。(A)正確，其他選項把三句的情境放錯位置。", "skill": "詩句填空先找每首詩的「主題詞」（禪宮、瀑布、故宅），再看候選句裡有沒有同一類的字（空病、江月、門巷）。"}, {"n": 20, "qtype": "單選", "stem": "若三詩各自反映作者的生活經歷與寫作風格，則它們最有可能是唐代何人的作品？", "options": {"A": "甲：王維；乙：李白；丙：杜甫", "B": "甲：王維；乙：杜甫；丙：李白", "C": "甲：李白；乙：王維；丙：杜甫", "D": "甲：李白；乙：杜甫；丙：王維"}, "answer": "A", "explain": "甲滿是佛理用語（禪宮、法身、天眼），符合「詩佛」王維。乙寫瀑布用誇張想像（河漢落、白虹起），氣勢豪放，是「詩仙」李白的風格。丙寫戰亂烽火、羈旅漂泊、思念故鄉，是經歷安史之亂、被稱為「詩聖」的杜甫。(A)正確。", "skill": "唐代三大詩人記關鍵字：王維＝禪、山水；李白＝誇張、豪放、仙；杜甫＝戰亂、民生、漂泊。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-26", "exam": "tc105", "nums": [26], "form": "單題", "img": "img/tc105-26.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "(A)安能以身之察察，受物之汶汶者乎！寧赴湘流，葬於江魚之腹中。（〈漁父〉）(B)夫晉，何厭之有？既東封鄭，又欲肆其西封，若不闕秦，將焉取之？（《左傳》燭之武退秦師）(C)必秦國之所生然後可，則是夜光之璧，不飾朝廷，犀象之器，不為玩好。（李斯〈諫逐客書〉）(D)若有作姦犯科，及為忠善者，宜付有司，論其刑賞，以昭陛下平明之治。（諸葛亮〈出師表〉）", "translation": "(A)怎能讓自己清白的身體，去承受外物的汙濁呢！我寧可跳進湘江，葬身在江魚的肚子裡。(B)晉國哪有滿足的時候？既然已經向東把鄭國當作邊界，又想擴張西邊的疆界，如果不侵損秦國，要從哪裡取得土地呢？(C)一定要秦國出產的東西才可以用，那麼夜光璧就不會裝飾朝廷，犀角象牙做的器物也不會成為玩賞之物。(D)如果有做壞事犯法，以及盡忠行善的人，應該交給主管官員，評定他們的刑罰和獎賞，來彰顯陛下公正清明的治理。", "keywords": [{"w": "察察", "m": "潔白、清白"}, {"w": "汶汶", "m": "汙濁"}, {"w": "厭", "m": "通「饜」，滿足"}, {"w": "封", "m": "作為疆界"}, {"w": "闕", "m": "侵損、削減"}, {"w": "有司", "m": "主管官員"}], "questions": [{"n": 26, "qtype": "單選", "stem": "下列何者說的話，意在引導對方用「賽局理論」進行思考？（上文：賽局理論的基本思維是，當對方的做法可能影響自己的利益，必須把對方的做法納入決策考量。）", "options": {"A": "屈原對漁父說：「安能以身之察察，受物之汶汶者乎！寧赴湘流，葬於江魚之腹中。」", "B": "燭之武對秦伯說：「夫晉，何厭之有？既東封鄭，又欲肆其西封，若不闕秦，將焉取之？」", "C": "李斯對秦王說：「必秦國之所生然後可，則是夜光之璧，不飾朝廷，犀象之器，不為玩好。」", "D": "諸葛亮對後主說：「若有作姦犯科，及為忠善者，宜付有司，論其刑賞，以昭陛下平明之治。」"}, "answer": "B", "explain": "賽局理論的重點是「把對手下一步會怎麼做納入考量」。(B)正確：燭之武提醒秦穆公，晉國貪得無厭，滅了鄭之後下一個就輪到秦，要秦想想晉的動向會如何影響自己——正是引導對方站在競爭者的角度推估策略。(A)屈原表明自己寧死不同流合汙，是個人志節，沒有分析對手。(C)李斯用反證說明只用秦國東西不合理，勸秦王別逐客，是論證邏輯，不是推估對手策略。(D)諸葛亮勸後主賞罰公平，是治國原則。", "skill": "把抽象理論換成一句白話（想想對手會怎麼做），再看哪個說話者真的在叫聽者「預測第三方的行動」。就像做生意要先想競爭對手會不會跟著降價。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-30", "exam": "tc105", "nums": [30, 31, 32], "form": "題組", "img": "img/tc105-30.png", "source": "《昨非庵日纂》", "author": "鄭瑄", "genre": "筆記小品", "types": ["文意推論", "人物情感", "字詞解釋"], "passage": "蘇東坡卜居陽羨，士人邵民瞻為公買一宅，緡五百，公傾囊僅能償之。卜吉將入居，夜與邵步月至村落，聞一嫗哭甚哀。公與邵推扉入問故，嫗言：「吾有居，傳百年，子不肖，舉以售人。數世舊居，一旦訣別，所以泣也。」坡愴然問所在，即公以五百緡易者，因再三慰撫曰：「此居乃吾所售，不必深悲，當以還嫗。」即令取屋券對嫗焚之，呼其子迎母還，不索其直。公遂還毘陵，不復買宅。", "translation": "蘇東坡選擇在陽羨定居，讀書人邵民瞻替他買了一間房子，價錢五百緡，蘇東坡把所有積蓄都拿出來才剛好付清。選好吉日準備搬進去，晚上和邵民瞻在月光下散步到村落，聽到一位老婦人哭得很悲傷。蘇東坡和邵民瞻推門進去問原因，老婦人說：「我有一間房子，傳了一百年，兒子不成材，把它賣給別人了。好幾代住的老房子，一下子就要訣別，所以哭泣。」東坡悲傷地問房子在哪裡，正是他用五百緡買下的那間，於是一再安慰她說：「這間房子是我買的，你不必太傷心，我會把它還給你。」立刻叫人拿來房契當著老婦人的面燒掉，叫她兒子接母親回去住，沒有要回買房的錢。東坡於是回到毘陵，不再買房子。", "keywords": [{"w": "卜居", "m": "選擇居住的地方"}, {"w": "緡", "m": "成串的錢，一緡一千文"}, {"w": "償", "m": "付清"}, {"w": "卜吉", "m": "選擇吉日"}, {"w": "步月", "m": "在月下散步"}, {"w": "嫗", "m": "老婦人"}, {"w": "不肖", "m": "不成材"}, {"w": "舉", "m": "全部、整個"}, {"w": "售", "m": "賣；文中「此居乃吾所售」為買"}, {"w": "易", "m": "交換，此指買"}, {"w": "直", "m": "通「值」，價錢"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依據上文，下列敘述何者正確？", "options": {"A": "邵民瞻出資為蘇東坡買住宅", "B": "老嫗瞞著兒子變賣祖宅牟利", "C": "老嫗因祖宅售人而徙居村落", "D": "蘇東坡同意老嫗購回其祖宅"}, "answer": "C", "explain": "(C)正確：祖宅被兒子賣掉，老婦人只好住到村落裡，夜裡在那兒哭。(A)邵民瞻只是幫忙買，錢是蘇東坡「傾囊」付的。(B)是「子不肖，舉以售人」，賣房的是兒子，不是老婦人。(D)蘇東坡是燒掉房契、「不索其直」，免費歸還，不是讓她買回去。", "skill": "「誰做了什麼」的題目，最容易在主語和出錢的人上設陷阱；把每個動作的主詞圈出來再比對。"}, {"n": 31, "qtype": "單選", "stem": "下列「」內關於蘇東坡形象的解說，何者正確？", "options": {"A": "「卜吉」將入居：意謂蘇東坡常為地方祈福", "B": "公「傾囊」僅能償之：意謂蘇東坡寬裕慷慨", "C": "夜與邵「步月」至村落：意謂蘇東坡步履悠閒", "D": "因「再三」慰撫曰：意謂蘇東坡內心多所顧忌"}, "answer": "C", "explain": "(C)正確：「步月」是在月下散步，可見他從容悠閒。(A)「卜吉」是選擇吉日搬家，不是替地方祈福。(B)「傾囊僅能償之」是掏空錢包才剛好付清，說明他並不富裕。(D)「再三慰撫」是一再安慰，表現他體貼仁厚，不是有所顧忌。", "skill": "「形象解說」題先把詞義翻對，再判斷它能不能推出那個形象；詞義錯了，形象一定錯。"}, {"n": 32, "qtype": "單選", "stem": "下列各組「」內的詞，何者意義最接近？", "options": {"A": "舉以「售」人／此居乃吾所「售」", "B": "呼其子迎母「還」／公遂「還」毘陵", "C": "舉「以」售人／即公「以」五百緡易者", "D": "「即」公以五百緡易者／「即」令取屋券對嫗焚之"}, "answer": "B", "explain": "(B)正確：兩個「還」都是「回去、返回」——迎母親回家、東坡回毘陵。(A)前者「售」是賣出；後者「此居乃吾所售」是蘇東坡說房子是他買的，「售」為買進，意思相反。(C)前者「以」後省略了「之」，是「把（房子）」；後者「以五百緡」是「用」。(D)前者「即」是「就是」；後者是「立即」。", "skill": "同字比較要代入主語想一想：同樣是「售」，說話者是賣方還是買方，意思就完全不同。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-33", "exam": "tc105", "nums": [33, 34, 35], "form": "題組", "img": "img/tc105-33.png", "source": "《閱微草堂筆記》", "author": "紀昀", "genre": "筆記小品", "types": ["文意推論", "主旨寓意", "人物情感"], "passage": "滄洲劉士玉孝廉，有書室，為狐所據。白晝與人對語，擲瓦石擊人，但不睹其形耳。知州平原董思任，良吏也。聞其事，自往驅之。方盛陳人妖異路之理，忽簷際朗言曰：「公為官，頗愛民，亦不取錢，故我不敢擊公。然公愛民乃好名，不取錢乃畏後患耳，故我亦不避公。公休矣，毋多言取困。」董狼狽而歸，咄咄不怡者數日。劉一僕婦，甚粗蠢，獨不畏狐，狐亦不擊之。或於對語時，舉以問狐。狐曰：「彼雖下役，乃真孝婦也。鬼神見之猶歛避，況我曹乎？」劉乃令僕婦居此室，狐是日即去。", "translation": "滄州的舉人劉士玉，有一間書房被狐精佔據。狐精白天和人對話，丟瓦片石頭打人，只是看不見牠的樣子。平原人董思任當知州，是個好官。聽說這件事，親自前往驅趕。他正大談人和妖各走各路的道理，忽然屋簷邊有清楚的聲音說：「您做官很愛護百姓，也不收錢，所以我不敢打您。但您愛民是為了好名聲，不收錢是怕日後惹禍罷了，所以我也不躲避您。您算了吧，別多說話自討沒趣。」董思任狼狽地回去，好幾天都悶悶不樂。劉家有一個僕婦，非常粗笨，卻偏偏不怕狐精，狐精也不打她。有人在和狐精對話時，拿這件事問牠。狐精說：「她雖然是下人，卻是真正孝順的婦人。鬼神見了她都要收斂迴避，何況我們呢？」劉士玉就讓這僕婦住進書室，狐精當天就離開了。", "keywords": [{"w": "孝廉", "m": "明清時對舉人的稱呼"}, {"w": "據", "m": "佔據"}, {"w": "睹", "m": "看見"}, {"w": "盛陳", "m": "大力陳述"}, {"w": "人妖異路", "m": "人與妖各走各的路"}, {"w": "取困", "m": "自討沒趣"}, {"w": "咄咄不怡", "m": "嘆氣而不愉快"}, {"w": "歛避", "m": "收斂迴避"}, {"w": "我曹", "m": "我們"}], "questions": [{"n": 33, "qtype": "單選", "stem": "下列關於故事中狐仙的敘述，何者正確？", "options": {"A": "化為人形以瓦石傷人", "B": "對人進行選擇性襲擊", "C": "藉劉家僕婦求見良吏", "D": "嘲弄劉家僕婦後離去"}, "answer": "B", "explain": "(B)正確：狐仙會擲瓦石打人，但「不敢擊」董思任、「亦不擊」僕婦，看人決定打不打。(A)文中說「不睹其形」，牠沒有現出人形。(C)董思任是自己去驅狐的，和僕婦無關。(D)狐仙敬重僕婦是「真孝婦」，是因為她住進來才離開，不是嘲弄她。", "skill": "注意否定句「不睹其形」「不敢擊」「亦不擊」，這些小小的「不」字往往就是判斷的關鍵。"}, {"n": 34, "qtype": "單選", "stem": "依據上文，董思任「咄咄不怡」的原因為何？", "options": {"A": "狐仙揚言揭穿他不廉不義", "B": "遭狐仙惡作劇而被迫辭官", "C": "害怕報應而不敢強驅狐仙", "D": "無力驅逐狐仙又受其譏評"}, "answer": "D", "explain": "董思任去驅狐，狐不但沒走，還說他愛民是為了名、不收錢是怕後患，點破他動機不純，叫他少說話。所以他是驅狐失敗又被批評，(D)正確。(A)狐仙承認他「頗愛民，亦不取錢」，沒說他不廉不義，批評的是動機。(B)文中沒有辭官。(C)他是被說得無話可說才回去，不是怕報應。", "skill": "人物情緒的原因要回到情緒出現「前一刻」發生的事：被一番話說中心事、事情又沒辦成。"}, {"n": 35, "qtype": "單選", "stem": "依據上文，狐仙避畏哪一種人？", "options": {"A": "德性端醇者", "B": "膽識過人者", "C": "寒微愚拙者", "D": "潔己奉公者"}, "answer": "A", "explain": "狐仙說僕婦「乃真孝婦也，鬼神見之猶歛避」，牠怕的是品德真誠純厚的人。(A)正確。(B)僕婦不怕狐，是因為德行而非膽量。(C)「粗蠢」「下役」只是她的身分外貌，不是狐仙怕她的原因。(D)「潔己奉公」是董思任那類清官，狐仙偏偏不避他，因為他的善行出於名利考量。", "skill": "本文對比：外表好官卻動機不純 vs. 外表粗笨卻真心孝順；寓意在「真」字，答案要抓內在德行。"}], "difficulty": "中", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc105-36", "exam": "tc105", "nums": [36, 37, 38], "form": "題組", "img": "img/tc105-36.png", "source": "韓愈〈師說〉、呂溫〈與族兄皋請學春秋書〉", "author": "韓愈、呂溫", "genre": "說理議論", "types": ["比較閱讀", "寫作手法", "主旨寓意"], "passage": "【甲】愛其子，擇師而教之，於其身也則恥師焉，惑矣！彼童子之師，授之書而習其句讀者也，非吾所謂傳其道、解其惑者也。句讀之不知，惑之不解，或師焉，或不焉，小學而大遺，吾未見其明也。巫、醫、樂師、百工之人，不恥相師；士大夫之族，曰師、曰弟子云者，則群聚而笑之。問之，則曰：「彼與彼年相若也，道相似也。」位卑則足羞，官盛則近諛。嗚呼！師道之不復可知矣。（韓愈〈師說〉）\n【乙】夫學者，豈徒受章句而已，蓋必求所以化人，日日新，又日新，以至乎終身。夫教者，豈徒博文字而已，蓋必本之以忠孝，申之以禮義，敦之以信讓，激之以廉恥，過則匡之，失則更之，如切如磋，如琢如磨，以至乎無瑕。故兩漢多名臣，諫諍之風，同乎三代，蓋由其身受師保之教誨，朋友之箴誡，既知己之損益，不忍觀人之成敗也。魏晉之後，其風大壞，學者皆以不師為天縱，獨學為生知，……以諷誦章句為精，以穿鑿文字為奧，至於聖賢之微旨，教化之大本，人倫之紀律，王道之根源，則蕩然莫知所措矣。其先進者，亦以教授為鄙，公卿大夫，恥為人師，至使鄉校之老人，呼以先生，則勃然動色。痛乎風俗之移人也如是！是以今之君子，事君者不諫諍，與人交者無切磋，蓋由其身不受師保之教誨，朋友之箴規，既不知己之損益，惡肯顧人之成敗乎？（〔唐〕呂溫〈與族兄皋請學春秋書〉）", "translation": "【甲】愛自己的孩子，就選擇老師教他，但對自己卻以拜師為恥，真是糊塗啊！那些孩子的老師，是教他們讀書、學習斷句的，不是我所說的傳授道理、解答疑惑的老師。不懂斷句、不能解惑，前者去請教老師，後者卻不請教，學了小的反而遺漏大的，我看不出他們的明智。巫醫、樂師和各種工匠，不以互相學習為恥；士大夫這類人，只要有人稱老師、稱弟子，就聚在一起嘲笑。問他們原因，就說：「他和他年紀差不多，學問也差不多。」以地位低的人為師就覺得羞恥，以官位高的人為師就近乎諂媚。唉！從師的風氣不能恢復，由此可知了。\n【乙】求學的人，難道只是學習斷句章法而已？一定要追求能讓自己變化氣質的道理，天天進步，直到終身。教學的人，難道只是讓學生多識文字而已？一定要以忠孝為根本，用禮義來推廣，用誠信謙讓來敦厚，用廉恥來激勵，有過錯就糾正，有缺失就改正，像切磋琢磨玉石一樣，直到沒有瑕疵。所以兩漢有很多名臣，敢於直言勸諫的風氣和夏商周三代相同，這是因為他們自己受過師長的教誨、朋友的規勸，知道自己的得失，也就不忍心坐看別人的成敗。魏晉以後，這種風氣大壞，求學的人都把不拜師當作天生聰明，把自學當作生而知之……把背誦章句當作精通，把穿鑿附會文字當作深奧，至於聖賢的精深意旨、教化的根本、人倫的規範、王道的根源，就完全不知道如何處理了。那些前輩也以教書為鄙賤，公卿大夫以當別人老師為恥，甚至鄉里學校的老人被稱為「先生」，都會變臉生氣。風俗改變人心竟到這種地步，真令人痛心！所以現在的君子，侍奉君王不敢直諫，與人交往不互相切磋，就是因為自己沒有受過師長的教誨、朋友的規勸，既然不知道自己的得失，哪裡肯關心別人的成敗呢？", "keywords": [{"w": "句讀", "m": "文句的斷句"}, {"w": "小學而大遺", "m": "學了小的（句讀）卻遺漏了大的（解惑）"}, {"w": "諛", "m": "諂媚"}, {"w": "章句", "m": "分章斷句、解釋字句之學"}, {"w": "匡", "m": "糾正"}, {"w": "箴誡", "m": "規勸告誡"}, {"w": "天縱", "m": "天生的聰明"}, {"w": "勃然動色", "m": "突然變臉生氣"}, {"w": "惡", "m": "音ㄨ，哪裡、怎麼"}], "questions": [{"n": 36, "qtype": "單選", "stem": "甲文所敘述的情形，何者可於乙文得到最明顯的印證？", "options": {"A": "小學而大遺", "B": "群聚而笑之", "C": "位卑則足羞", "D": "官盛則近諛"}, "answer": "A", "explain": "(A)正確：甲文批評人們只學斷句（小）而不解大惑（大）；乙文說魏晉以後「以諷誦章句為精，以穿鑿文字為奧，至於聖賢之微旨……則蕩然莫知所措」，正是只顧章句小事、遺漏聖賢大道。(B)乙文沒寫士大夫聚在一起嘲笑從師的人。(C)(D)乙文沒有談拜地位高低不同的人為師會羞恥或諂媚。", "skill": "兩文互證題，先把甲文的觀點換成白話（只學小技、忽略大道），再到乙文找意思相同但字面不同的句子。"}, {"n": 37, "qtype": "單選", "stem": "下列敘述，何者符合甲、乙二文的觀點？", "options": {"A": "唐代普遍不重師道，實承襲兩漢魏晉之風", "B": "唐代士大夫不屑與百工為伍，故拒為其師", "C": "士大夫自認天縱英明，視章句為淺薄之學", "D": "士大夫恥於相師，遂使彼此失去反省能力"}, "answer": "D", "explain": "(D)正確：甲文說士大夫「恥學於師」；乙文說公卿大夫「恥為人師」，因此「不受師保之教誨……既不知己之損益」，失去反省改過的能力。(A)乙文說兩漢重師道、名臣輩出，壞風氣是魏晉之後才開始，不是承襲兩漢。(B)甲文是說百工互相學習、士大夫反而不肯從師，沒說士大夫拒絕當百工的老師。(C)乙文說他們「以諷誦章句為精」，是把章句看得太重，不是看輕。", "skill": "「符合二文」要兩篇都找得到依據；遇到時代（兩漢／魏晉）和褒貶方向的敘述，最容易被偷換。"}, {"n": 38, "qtype": "單選", "stem": "下列關於甲、乙二文運用對比寫作技巧的敘述，何者錯誤？", "options": {"A": "甲文：以「為子擇師的意願」與「自己從師的意願」對比", "B": "甲文：以「士大夫的態度」與「技藝工人的態度」對比", "C": "乙文：以「公卿大夫的態度」與「鄉校老人的態度」對比", "D": "乙文：以「兩漢的風氣」與「魏晉以後的風氣」對比"}, "answer": "C", "explain": "(C)錯誤：公卿大夫「恥為人師」，鄉校老人被稱先生也「勃然動色」，兩者態度相同，都以當老師為恥，是「連鄉校老人都這樣」的層遞強調，不是對比。(A)正確：愛子擇師vs.自己恥師。(B)正確：百工「不恥相師」vs.士大夫「群聚而笑之」。(D)正確：兩漢多名臣、諫諍之風盛vs.魏晉之後其風大壞。", "skill": "判斷是否「對比」，就問兩者態度是相反還是相同；相同就只是舉例或層遞。"}], "difficulty": "難", "label": "105統測", "year": 105, "kind": "統測"}, {"id": "tc106-02", "exam": "tc106", "nums": [2], "form": "單題", "img": "img/tc106-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "庭中始為籬，已為牆，凡再變矣。（歸有光〈項脊軒志〉）", "translation": "題幹：庭院中起初用籬笆隔開，後來改成牆，總共變了兩次。(A)在早晨太陽剛升起、傍晚太陽還沒落下時，（西湖景色）才最濃豔嫵媚。(B)千呼萬喚，（琵琶女）才走出來，還抱著琵琶遮住半邊臉。(C)楠樹剛開始生長時，已經具備完整的樹形，年代久了就變得堅硬，始終不再長大。(D)今年九月二十八日，因為坐在法華寺西亭，望見西山，才指著覺得它奇特。", "keywords": [{"w": "始", "m": "起初、剛開始；或作副詞「才」"}, {"w": "已", "m": "後來、不久"}, {"w": "再", "m": "兩次"}, {"w": "指異之", "m": "指著西山，覺得它奇特"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列文句中的「始」，何者與「庭中始為籬，已為牆，凡再變矣」的「始」意義相同？", "options": {"A": "朝日始出，夕春未下，「始」極其濃媚", "B": "千呼萬喚「始」出來，猶抱琵琶半遮面", "C": "楠之「始」生，已具全體，歲久則堅，終不加大", "D": "今年九月二十八日，因坐法華西亭，望西山，「始」指異之"}, "answer": "C", "explain": "題幹「始為籬，已為牆」是「起初……後來……」，「始」＝起初、開始的時候。(C)正確：「楠之始生」＝楠樹剛開始生長時，後面也接「已具全體」，用法一樣。(A)「始極其濃媚」＝這時候「才」最濃豔（袁宏道〈晚遊六橋待月記〉）。(B)「千呼萬喚始出來」＝喊了很多次「才」出來（白居易〈琵琶行〉）。(D)「始指異之」＝這時「才」發現西山奇特（柳宗元〈始得西山宴遊記〉）。", "skill": "「始」放在動作前、前面有條件或時間（千呼萬喚、坐法華西亭）時，多半是「才」；和「已」「後」呼應時則是「起初」。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-10", "exam": "tc106", "nums": [10], "form": "單題", "img": "img/tc106-10.png", "source": "《孔子家語‧好生》", "author": "", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "虞、芮二國爭田而訟，連年不決。乃相謂曰：「西伯，仁人也。盍往質之？」入其境，則耕者讓畔，行者讓路；入其邑，男女異路，斑白不提挈；入其朝，士讓為大夫，大夫讓為卿。虞、芮之君曰：「嘻！吾儕小人也，不可以履君子之庭。」遂自相與而退，咸以所爭之田為閑田矣。", "translation": "虞國和芮國為了爭奪田地而打官司，好幾年都解決不了。於是彼此商量說：「西伯（周文王）是仁德的人，何不去請他評斷？」進入周國境內，看到種田的人互相讓出田界，走路的人互相讓路；進入城邑，男女分道而行，頭髮斑白的老人不必自己提東西；進入朝廷，士人讓位給別人當大夫，大夫讓位給別人當卿。虞、芮兩國的國君說：「唉！我們真是小人啊，不配踏進君子的朝廷。」於是一起退回去，都把所爭的田地當作閒置的田地（不再爭了）。", "keywords": [{"w": "訟", "m": "打官司、爭訟"}, {"w": "西伯", "m": "周文王"}, {"w": "盍", "m": "何不"}, {"w": "質", "m": "評斷是非"}, {"w": "畔", "m": "田界"}, {"w": "斑白", "m": "頭髮花白的老人"}, {"w": "提挈", "m": "提拿東西"}, {"w": "吾儕", "m": "我們"}, {"w": "履", "m": "踩、踏入"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下列成語，何者最符合畫底線處虞、芮之君的表現？（畫底線處：虞、芮之君曰：「嘻！吾儕小人也，不可以履君子之庭。」）", "options": {"A": "不自量力", "B": "妄自菲薄", "C": "畫地自限", "D": "反躬自責"}, "answer": "D", "explain": "兩位國君看到周國人人互讓，慚愧地說自己是「小人」，於是不再爭田——這是回頭檢討自己的過錯。(D)反躬自責正確。(A)不自量力是高估自己能力去做做不到的事。(B)妄自菲薄是無故看輕自己，但他們是真的做錯而反省，並非過度自卑。(C)畫地自限是自己設限不肯進步，文意不合。", "skill": "成語對應題先說清楚人物「為什麼這樣說」：是看到別人的好而慚愧，就是自我反省；不是單純自卑。"}], "difficulty": "易", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-11", "exam": "tc106", "nums": [11], "form": "單題", "img": "img/tc106-11.png", "source": "鄭燮〈竹石〉、〈出紙一竿〉", "author": "鄭燮", "genre": "古典詩詞曲", "types": ["詩詞賞析", "主旨寓意"], "passage": "甲、咬定青山不放鬆，立根原在破岩中。千磨萬擊還堅勁，任爾東南西北風。（鄭燮〈竹石〉）\n乙、畫工何事好離奇？一竿掀天去不知。若使循循牆下立，拂雲擎日待何時。（鄭燮〈出紙一竿〉）", "translation": "甲、竹子緊緊咬住青山不放鬆，它的根原本就扎在破裂的岩石之中。經過千萬次磨難打擊仍然堅韌挺拔，任憑你從東南西北哪個方向吹來的風。\n乙、畫工為什麼喜歡畫得這麼奇特？一根竹竿直衝天際，不知要伸到哪裡去。如果讓它規規矩矩地站在牆下，要等到什麼時候才能拂動雲彩、托起太陽呢？", "keywords": [{"w": "咬定", "m": "緊緊抓住"}, {"w": "堅勁", "m": "堅韌有力"}, {"w": "掀天", "m": "衝向天際"}, {"w": "循循", "m": "規規矩矩、按部就班的樣子"}, {"w": "擎", "m": "托舉"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下列甲、乙兩首題畫詩，表達出何種處世哲理？", "options": {"A": "甲：追根究柢；乙：循序漸進", "B": "甲：追根究柢；乙：勇於突破", "C": "甲：堅毅不撓；乙：循序漸進", "D": "甲：堅毅不撓；乙：勇於突破"}, "answer": "D", "explain": "甲詩寫竹子扎根在岩縫中，「千磨萬擊還堅勁」，象徵堅毅不屈服；「立根」是扎根，不是「追根究柢」（追問根源）。乙詩說竹子若「循循牆下立」就永遠無法「拂雲擎日」，鼓勵突破框架、衝出牆外，所以是勇於突破，不是循序漸進。(D)正確。", "skill": "題畫詩看物象背後的「人」：竹子被風打不倒＝堅毅；竹子衝出畫框＝突破。小心字面陷阱，如「根」不等於「追根究柢」、「循循」恰好是詩人反對的。"}], "difficulty": "易", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-13", "exam": "tc106", "nums": [13], "form": "單題", "img": "img/tc106-13.png", "source": "綜合（對聯）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "甲、一炬東風推公瑾，千年理學尚濂溪\n乙、中堂樂賞右軍墨，西苑常吟摩詰詩\n丙、慷慨千金酬一飯，從容一表冠八家", "translation": "甲、赤壁一把借東風的大火，大家推崇周瑜（字公瑾）；千年來的理學，推尊周敦頤（號濂溪）。乙、廳堂裡喜歡欣賞王羲之（曾任右軍將軍）的書法，西園中常吟詠王維（字摩詰）的詩。丙、慷慨地用千金報答一頓飯之恩的是韓信；從容寫成〈論佛骨表〉、位居唐宋八大家之首的是韓愈。", "keywords": [{"w": "公瑾", "m": "周瑜的字"}, {"w": "濂溪", "m": "周敦頤的號"}, {"w": "右軍", "m": "王羲之，曾任右軍將軍"}, {"w": "摩詰", "m": "王維的字"}, {"w": "千金酬一飯", "m": "韓信報答漂母一飯之恩"}, {"w": "冠八家", "m": "韓愈居唐宋八大家之首"}], "questions": [{"n": 13, "qtype": "單選", "stem": "甲、乙、丙三聯各敘一姓氏，每聯的前後句分述該姓氏名人各一位，則這三個姓氏依序應是：", "options": {"A": "朱／李／蘇", "B": "朱／王／韓", "C": "周／李／蘇", "D": "周／王／韓"}, "answer": "D", "explain": "甲：公瑾＝周瑜，濂溪＝周敦頤，都姓周。乙：右軍＝王羲之，摩詰＝王維，都姓王。丙：千金報一飯＝韓信，一表冠八家＝韓愈（〈諫迎佛骨表〉、唐宋八大家之首），都姓韓。(D)正確。理學雖讓人想到朱熹，但「濂溪」是周敦頤；「摩詰」容易誤想成李白，其實是王維。", "skill": "人名對聯題，熟記古人的字、號、官銜（公瑾、濂溪、右軍、摩詰）就能秒解；先解最確定的一聯刪選項。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-14", "exam": "tc106", "nums": [14], "form": "單題", "img": "img/tc106-14.png", "source": "出處待查（清人論詩詞之別）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "文化常識"], "passage": "詩：男兒所在即為家，百鎰黃金一朵花。借問春風何處好？綠楊深巷馬頭斜。\n詞：試問於誰分最多，便隨人意轉橫波，縷金衣上小雙鵝。醉後愛稱嬌姐姐，夜來留得好哥哥，不知情事久長麼？\n詩貴莊而詞不嫌□。詩貴□□而詞不嫌□□。", "translation": "詩：男子漢走到哪裡，哪裡就是家；百鎰黃金也只換得一朵花般的歡樂。請問春風哪裡最好？就在綠楊掩映的深巷，馬頭斜斜停住的地方。\n詞：試問她對誰的情意最多，眼波就隨人的心意流轉，金線繡的衣裳上有一對小鵝。喝醉後愛叫「嬌姐姐」，夜裡留住了「好哥哥」，不知道這份感情能不能長久呢？\n論述：詩以莊重為貴，詞卻不嫌輕佻；詩以含蓄為貴，詞卻不嫌直接流露。", "keywords": [{"w": "鎰", "m": "古代重量單位，二十兩（一說二十四兩）"}, {"w": "橫波", "m": "流轉的眼波"}, {"w": "佻", "m": "輕佻、不莊重"}, {"w": "含蓄", "m": "意思藏而不露"}, {"w": "流露", "m": "情感直接表現出來"}], "questions": [{"n": 14, "qtype": "單選", "stem": "參考右圖的一詩一詞，推斷某位古人在談論「詩詞有別」時，□內的想法依序應是：（圖中：詩貴莊而詞不嫌□。詩貴□□而詞不嫌□□。）", "options": {"A": "佻／含蓄／流露", "B": "佻／齊言／參差", "C": "雅／含蓄／流露", "D": "雅／齊言／參差"}, "answer": "A", "explain": "第一句和「莊」相對的應是輕佻的「佻」；圖中的詞寫「嬌姐姐」「好哥哥」，口吻輕佻俏皮，正是「不嫌佻」。若填「雅」，雅和莊同義，無法形成「詩如此、詞卻不嫌如此」的對比，所以刪(C)(D)。第二句：詩寫尋歡只說「綠楊深巷馬頭斜」，點到為止，是含蓄；詞直接寫情人間的稱呼與「不知情事久長麼」，是流露。(A)正確。(B)「齊言／參差」講的是句式長短（詩多齊言、詞多長短句），但這首詞七字句整齊，與圖例不符，且題目要比較的是表達風格。", "skill": "「A貴X而B不嫌Y」的句型，X和Y必定是相反的一對（莊／佻、含蓄／流露），先用反義詞配對就能刪掉一半選項。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-15", "exam": "tc106", "nums": [15, 16], "form": "題組", "img": "img/tc106-15.png", "source": "《戰國策‧齊策四》（馮諼客孟嘗君）", "author": "劉向編", "genre": "史傳人物", "types": ["虛詞句式", "文意推論"], "passage": "孟嘗君予車五十乘，金五百斤，西遊於梁，謂惠王曰：「齊放其大臣孟嘗君於諸侯，諸侯先迎之者，富而兵強。」於是梁王虛上位，以故相為上將軍，遣使者黃金千斤，車百乘，往聘孟嘗君。馮諼先驅，誡孟嘗君曰：「千金，重幣也；百乘，顯使也。齊其聞之矣！」", "translation": "孟嘗君給（馮諼）五十輛車、五百斤金，讓他向西到梁國遊說，馮諼對梁惠王說：「齊國把大臣孟嘗君放逐到諸侯間，哪個諸侯先迎接他，就能國富兵強。」於是梁王空出宰相的位子，把原來的宰相調任為上將軍，派使者帶著黃金千斤、車子一百輛，去聘請孟嘗君。馮諼先趕回去，告誡孟嘗君說：「千斤黃金是很貴重的聘禮，一百輛車是很顯赫的使節。齊國應該聽說了吧！」", "keywords": [{"w": "乘", "m": "音ㄕㄥˋ，一車四馬為一乘"}, {"w": "放", "m": "放逐、罷免"}, {"w": "虛上位", "m": "空出宰相的位子"}, {"w": "故相", "m": "原來的宰相"}, {"w": "聘", "m": "以禮物延請"}, {"w": "幣", "m": "禮物"}, {"w": "顯使", "m": "顯赫的使節"}, {"w": "其", "m": "表推測，大概、應該"}], "questions": [{"n": 15, "qtype": "單選", "stem": "「諸侯先迎之者，富而兵強」，前後句的語意關係可以是「只要……，就……」。下列文句，何者使用相同的表意方式？", "options": {"A": "鍥而不舍，金石可鏤", "B": "家有敝帚，享之千金", "C": "篳路藍縷，以啟山林", "D": "顏色憔悴，形容枯槁"}, "answer": "A", "explain": "題幹是條件句：只要先迎接孟嘗君，就能國富兵強。(A)正確：只要不停地刻，就算金石也能刻穿（《荀子‧勸學》）。(B)意思是自家的破掃帚，也當成價值千金來珍惜，是「雖然……卻……」的轉折，不是條件。(C)駕著柴車、穿著破衣去開闢山林，前句是方式、後句是目的（連橫〈臺灣通史序〉）。(D)臉色憔悴、形體枯瘦，前後並列（〈漁父〉）。", "skill": "判斷句間關係，就把關聯詞直接套進去讀：「只要鍥而不舍，就金石可鏤」讀得通，就是條件句。"}, {"n": 16, "qtype": "單選", "stem": "「齊其聞之矣」意謂馮諼想讓齊王明白什麼事？", "options": {"A": "孟嘗君跳槽恐有後患", "B": "孟嘗君果然見利忘義", "C": "孟嘗君重視豪奢享受", "D": "孟嘗君志在返國奪位"}, "answer": "A", "explain": "馮諼故意讓梁國用重金、大陣仗聘請孟嘗君，消息一定傳到齊國。齊王會擔心：孟嘗君這樣的人才若被梁國挖走，梁國「富而兵強」，對齊國將是大患。這就逼齊王趕快把孟嘗君請回來。(A)正確。(B)(C)馮諼要孟嘗君先別答應，正是要顯示他並非見利就走、也不是貪圖享受。(D)孟嘗君只是想恢復相位，不是篡奪王位。", "skill": "縱橫家的話常是「說給第三者聽」；想想消息傳到誰耳中、對方會擔心什麼，就懂策略的用意。就像人才被對手公司高薪挖角的消息，最緊張的是原公司老闆。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-17", "exam": "tc106", "nums": [17, 18], "form": "題組", "img": "img/tc106-17.png", "source": "〈聚芳園記〉", "author": "翟灝", "genre": "說理議論", "types": ["文意推論", "虛詞句式", "主旨寓意"], "passage": "友人見而謂之曰：四時之花，君能兼之；四季之樂，君能享之；此地不可以不名也。謂之「聚芳園」，可乎？然君究何修而得此樂也？夫人惟不滯於境之內者，斯可超於象之外。嘗見夫權門貴客，日坐錦堂，玩好滿前，氍毹鋪地，以視君之茅舍柴扉，紙窗竹屋，不啻霄壤也；猶自營營於紛華靡麗之場，而戚戚於蘭麝帷帳之內，寤寐不釋，飲食不寧，究不知何時而樂也！", "translation": "朋友看了之後對他說：四季的花，你都能擁有；四季的樂趣，你都能享受；這地方不能不取個名字。叫它「聚芳園」，可以嗎？可是你究竟修養了什麼才得到這種快樂呢？人只有不被外在環境困住，才能超脫於物象之外。我曾看過那些權貴人家，每天坐在華麗的廳堂，珍奇玩物擺滿眼前，毛毯鋪滿地面，和你的茅草屋、柴門、紙窗、竹屋相比，簡直是天壤之別；可是他們仍然在繁華奢靡的場合中忙碌奔走，在香氣瀰漫的帷帳中憂愁不安，睡覺醒著都放不下心，吃飯也不安穩，終究不知道什麼時候才能快樂啊！", "keywords": [{"w": "修", "m": "修養"}, {"w": "滯", "m": "拘泥、被困住"}, {"w": "象", "m": "外在物象"}, {"w": "玩好", "m": "供玩賞的珍奇器物"}, {"w": "氍毹", "m": "毛織的地毯"}, {"w": "不啻霄壤", "m": "不只是天和地那樣的差別"}, {"w": "營營", "m": "忙碌追求的樣子"}, {"w": "戚戚", "m": "憂愁的樣子"}, {"w": "寤寐", "m": "醒著和睡著"}], "questions": [{"n": 17, "qtype": "單選", "stem": "依據上文，友人認為作者能享庭園之樂，主要原因在於：", "options": {"A": "怡然自得，不役於物", "B": "花開四季，群賢畢至", "C": "簞食瓢飲，有志於學", "D": "遠離紅塵，遺世獨立"}, "answer": "A", "explain": "友人的答案就在「夫人惟不滯於境之內者，斯可超於象之外」：不被外物環境困住，心才自由快樂；再用權貴人家有錢卻不快樂來對比。(A)不被外物役使、自在快樂，正確。(B)花開四季只是園子的景物，不是快樂的根本原因；文中也沒有群賢聚會。(C)簞食瓢飲、有志於學是顏回安貧樂道，文中沒談求學。(D)作者並非與世隔絕，重點是心境不受外物拘束。", "skill": "問「主要原因」，找文中帶有「惟……者，斯……」「所以」這類推論句，那就是作者的核心論點。"}, {"n": 18, "qtype": "單選", "stem": "文中「猶自營營於紛華靡麗之場」，主語「權門貴客」因數句之前已出現，故省去不提。下列畫底線的文句，何者使用相同的表意方式？", "options": {"A": "項王、項伯東嚮坐；亞父南嚮坐，亞父者，范增也", "B": "工之僑以歸，謀諸漆工，作斷紋焉；又謀諸篆工，作古窾焉", "C": "貨惡其棄於地也，不必藏於己；力惡其不出於身也，不必為己", "D": "觥籌交錯，起坐而諠譁者，眾賓懽也；蒼顏白髮，頹然乎其間者，太守醉也"}, "answer": "B", "explain": "題幹是「承前省略主語」：前面已提過的人，後句不再重複。(B)正確：「又謀諸篆工，作古窾焉」的主語是前面出現過的「工之僑」，承前省略（劉基〈工之僑獻琴〉）。(A)畫線句「亞父南嚮坐，亞父者，范增也」主語「亞父」直接寫出來了（〈鴻門宴〉）。(C)畫線句講的是一般人的心態，前一句「貨惡其棄於地也」也沒有特定主語，是泛指，不是承前文某人而省略（《禮記‧禮運》）。(D)畫線句主語「太守」明白寫在句末（〈醉翁亭記〉）。", "skill": "找承前省略：先問畫線句「誰在做」，再看這個「誰」是不是前面剛出現過的特定人物；主語寫出來或泛指大眾的都不算。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-20", "exam": "tc106", "nums": [20], "form": "單題", "img": "img/tc106-20.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "(A)數罟不入洿池，魚鱉不可勝食也。（《孟子‧梁惠王上》）(B)夫膻臭之欲不止，殺害之機不已。(C)竭誠則胡越為一體，傲物則骨肉為行路。（魏徵〈諫太宗十思疏〉）(D)求福莫過齋戒佈施，求壽莫過不殺放生。", "translation": "(A)細密的漁網不放進池塘捕撈，魚鱉就吃不完了。(B)想吃腥羶肉食的欲望不停止，殺害生命的事就不會停止。(C)竭盡真誠待人，那麼胡人和越人這樣疏遠的人也能團結成一體；傲慢待人，那麼親骨肉也會成為陌路人。(D)求福沒有比吃素守戒、布施更好的，求長壽沒有比不殺生、放生更好的。", "keywords": [{"w": "數罟", "m": "細密的漁網"}, {"w": "洿池", "m": "池塘"}, {"w": "膻臭之欲", "m": "想吃腥羶肉食的欲望"}, {"w": "機", "m": "事端、念頭"}, {"w": "傲物", "m": "傲慢待人"}, {"w": "行路", "m": "路人"}], "questions": [{"n": 20, "qtype": "單選", "stem": "右圖倡導「不食魚翅，拒絕買賣」以挽救鯊魚，主要是基於何種理由？（圖中資料：每年死於鯊魚攻擊者僅10人；割鰭後鯊魚不能游泳、呼吸；魚翅汞含量高；鯊魚懷胎期長、產子數少，100年來1/3的種類瀕臨滅絕。）", "options": {"A": "數罟不入洿池，魚鱉不可勝食也", "B": "夫膻臭之欲不止，殺害之機不已", "C": "竭誠則胡越為一體，傲物則骨肉為行路", "D": "求福莫過齋戒佈施，求壽莫過不殺放生"}, "answer": "B", "explain": "「不食、拒買」的邏輯是：只要人還想吃魚翅，就會有人去割鰭獵殺鯊魚；從源頭斷絕口腹之欲，殺戮才會停止。(B)「口腹之欲不止，殺害就不停」正好說明這個理由。(A)是說不用細網、讓魚有時間繁殖，屬於「節制捕撈方法」，可以繼續吃，與「拒絕食用」的訴求不同。(C)講待人要真誠，與保育無關。(D)講齋戒放生可以求福求壽，是為自己祈福的宗教理由，圖中沒有這種訴求。", "skill": "先看標語的「行動」（不吃、不買＝斷需求），再找文言句中講「欲望導致殺害」的選項；想想「沒有買賣就沒有殺害」這句保育口號。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-29", "exam": "tc106", "nums": [29], "form": "單題", "img": "img/tc106-29.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "文意推論"], "passage": "(A)擊甕叩缶，彈箏搏髀。（李斯〈諫逐客書〉）(B)伯牙鼓琴而六馬仰秣。（《荀子‧勸學》）(C)拂琴開素匣，何事獨顰眉。(D)後來知是調箏手，窈窕傍聽曾誤否。", "translation": "(A)敲打陶甕瓦缶、彈箏、拍大腿打拍子。(B)伯牙彈琴，連正在吃草料的馬都抬起頭來聽。(C)拂拭琴弦、打開白色的琴匣，為什麼獨自皺著眉頭？(D)後來才知道她是彈箏的高手，那美好的女子在旁邊聽，曾經聽出誰彈錯了嗎？", "keywords": [{"w": "缶", "m": "瓦製的盛器，可敲擊打拍子"}, {"w": "搏髀", "m": "拍打大腿"}, {"w": "鼓", "m": "敲擊；鼓琴＝彈琴"}, {"w": "仰秣", "m": "抬頭停止吃草料"}, {"w": "顰眉", "m": "皺眉"}], "questions": [{"n": 29, "qtype": "單選", "stem": "下列文句「」內的詞，何者最適合做為文中畫底線處的引證？（上文許進雄《古事雜談》：弦樂器發明之初可能多以敲擊方式演奏，故即使後來有所變革，＿舊有技法還是保留在行文敘寫中＿。）", "options": {"A": "擊甕叩缶，「彈箏」搏髀", "B": "伯牙「鼓琴」而六馬仰秣", "C": "「拂琴」開素匣，何事獨顰眉", "D": "後來知是「調箏」手，窈窕傍聽曾誤否"}, "answer": "B", "explain": "文章說弦樂器最早可能用「敲」的，所以後來文字裡還留著敲擊的說法。(B)「鼓琴」的「鼓」本義是敲擊，琴明明是撥彈的，古人卻說「鼓琴」，正好證明敲擊的舊說法保留在文字中，正確。(A)「彈箏」是撥彈，屬於現有的演奏方式。(C)「拂琴」是拂拭或輕撥琴弦。(D)「調箏」是調音或彈奏，都看不出敲擊的痕跡。", "skill": "「語詞保留舊習俗」的題目，找字面意思和現在做法不一樣的詞（彈琴卻說「鼓」），那就是歷史留下的化石。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-30", "exam": "tc106", "nums": [30, 31, 32], "form": "題組", "img": "img/tc106-30.png", "source": "《池北偶談》", "author": "王士禎", "genre": "筆記小品", "types": ["文意推論", "字詞解釋", "人物情感"], "passage": "明嘉靖中，一樵人朝行，失足墮虎穴，見兩虎子臥穴內，深數丈，不得出，徬徨待死。日將晡，虎來，銜一生麋，飼其子既，復以餕予樵，樵懼甚，自度必不免。迨昧爽，虎躍去，暮歸飼子，復以餕與樵。如是月餘，漸與虎狎。一日，虎負子出，樵夫號曰：「大王救我！」須臾，虎復入，俛首就樵，樵遂騎而騰上，置叢箐中。樵復跪告曰：「蒙大王活我，今相失，懼不免他患，幸導我通衢，死不忘報。」虎又引之前至大道旁。樵泣拜曰：「蒙大王厚恩無以報，歸當畜一豚，縣西郭外郵亭下，以候大王，某日日中當至，無忘也。」虎頷之。至日，虎先期至，不見樵，遂入郭，居民噪逐，生致之，告縣。樵聞之，奔詣縣廳，抱虎痛哭曰：「大王以赴約來耶？」虎點頭。樵曰：「我為大王請命，不得，願以死從大王。」語罷，虎淚下如雨。觀者數千人，莫不歎息。知縣，萊陽人某也，急趣釋之，驅至亭下，投以豚，大嚼，顧樵再三而去。", "translation": "明朝嘉靖年間，有個樵夫早上出門，失足掉進老虎的洞穴，看見兩隻小老虎躺在洞裡，洞深好幾丈，爬不出去，只能徬徨地等死。太陽快下山時，母老虎回來，叼著一隻活鹿，餵完小老虎後，又把吃剩的給樵夫，樵夫非常害怕，自己估計一定活不了。等到天快亮，老虎跳出去，傍晚回來餵小老虎，又把剩的給樵夫。像這樣過了一個多月，樵夫漸漸和老虎親近起來。有一天，老虎背著小老虎出洞，樵夫大喊：「大王救我！」不久，老虎又進來，低頭靠近樵夫，樵夫就騎上虎背跳了上去，老虎把他放在竹叢中。樵夫又跪下說：「承蒙大王救我一命，現在要分開了，怕免不了遇到其他禍患，希望您帶我到大路上，我到死也不忘報答。」老虎又帶他往前走到大路旁。樵夫哭著拜謝說：「承蒙大王大恩，無以為報，回去後我會養一頭豬，掛在縣城西邊城外的驛亭下，等候大王，某天中午您一定要來，不要忘了。」老虎點頭答應。到了那天，老虎提早來了，沒看見樵夫，就進了城，居民大聲叫喊追趕，活捉了牠，報告縣官。樵夫聽說了，跑到縣衙，抱著老虎痛哭說：「大王是因為赴約才來的嗎？」老虎點點頭。樵夫說：「我替大王求情，如果不成，我願意陪大王一起死。」說完，老虎眼淚像下雨一樣。圍觀的有幾千人，沒有不嘆息的。知縣是萊陽人某某，趕緊下令放了老虎，把牠趕到驛亭下，丟給牠豬，老虎大口吃完，回頭看了樵夫好幾次才離開。", "keywords": [{"w": "樵人", "m": "砍柴的人"}, {"w": "晡", "m": "申時，傍晚"}, {"w": "麋", "m": "鹿的一種"}, {"w": "既", "m": "完畢"}, {"w": "餕", "m": "剩餘的食物"}, {"w": "自度", "m": "自己估計"}, {"w": "昧爽", "m": "天將亮時"}, {"w": "狎", "m": "親近"}, {"w": "箐", "m": "竹林、草叢"}, {"w": "通衢", "m": "四通八達的大路"}, {"w": "縣", "m": "通「懸」，懸掛"}, {"w": "郭", "m": "外城"}, {"w": "頷之", "m": "點頭答應"}, {"w": "生致之", "m": "活捉牠"}, {"w": "趣", "m": "通「促」，趕快"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依據上文，下列敘述何者正確？", "options": {"A": "樵夫因逐虎而墮虎穴", "B": "樵夫畜豬俟老虎索食", "C": "老虎報樵夫飼子之恩", "D": "老虎欲救樵夫而遭擒"}, "answer": "B", "explain": "(B)正確：樵夫說「歸當畜一豚，縣西郭外郵亭下，以候大王」，養豬等老虎來吃。(A)樵夫是早上走路「失足」掉下去的，不是追老虎。(C)是老虎救了樵夫、拿食物餵他，樵夫沒有餵小老虎。(D)老虎是來赴約吃豬，沒見到樵夫才進城被捉，不是為了救樵夫。", "skill": "故事題要分清「誰對誰有恩」：恩人是老虎，報恩的是樵夫，方向弄反就會選錯。"}, {"n": 31, "qtype": "單選", "stem": "依據上文，老虎「入郭」的原因為何？", "options": {"A": "為報樵夫恩情", "B": "獵取城中牲畜", "C": "錯失約定之日", "D": "欲尋樵夫履約"}, "answer": "D", "explain": "「至日，虎先期至，不見樵，遂入郭」：老虎在約定的日子提早到，沒看到樵夫，才進城找他。後來樵夫問「大王以赴約來耶？」老虎也點頭。(D)正確。(A)報恩的是樵夫，不是老虎。(B)文中沒有獵取牲畜。(C)老虎是「先期至」，提早到，並沒有錯過日期。", "skill": "動作原因通常緊貼在動作前面：「不見樵，遂入郭」——因為沒看到人，所以進城找人。"}, {"n": 32, "qtype": "單選", "stem": "依據上文，下列「」內的解釋，何者正確？", "options": {"A": "樵懼甚，「自度必不免」：暗想終將餓死虎穴", "B": "樵遂騎而騰上，「置叢箐中」：躲避在草叢裡", "C": "今相失，「懼不免他患」：恐迷途山中或遭噬", "D": "「急趣釋之」，驅至亭下：識趣的將老虎放生"}, "answer": "C", "explain": "(C)正確：分開後怕遇到其他禍患，如迷路或被其他野獸吃掉，所以請老虎帶他到大路。(A)老虎還拿食物給他吃，他怕的是被老虎吃掉，不是餓死。(B)「置叢箐中」是老虎把他放在竹叢裡，不是樵夫躲起來。(D)「趣」通「促」，「急趣釋之」是趕緊下令放了老虎，不是「識趣」。", "skill": "「趣」常通「促」（催促、趕快），別用現代「有趣、識趣」去理解；解釋題先查通同字。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-33", "exam": "tc106", "nums": [33, 34, 35], "form": "題組", "img": "img/tc106-33.png", "source": "《澠水燕談錄》", "author": "王闢之", "genre": "筆記小品", "types": ["文意推論", "字詞解釋", "主旨寓意"], "passage": "江南一縣郊外古寺，地僻山險，邑人罕至，僧徒久苦不足。一日，有僧遊方至其寺，告於主僧，且將與之謀所以驚人耳目者。寺有五百羅漢，擇一貌類己，衣其衣，頂其笠，策其杖，入縣削髮。誤為刀傷其頂，解衣帶，白藥傅之，留杖為質，約至寺，將遺千錢。削者如期而往，方入寺，閽者毆之曰：「羅漢亡杖已半年，乃爾盜耶！」削者述所以得杖貌，相與見主僧，更異之。共開羅漢堂，門鎖生澀，塵凝坐榻，如久不開者。視亡杖羅漢，衣笠皆所見者，頂有傷處，血漬藥傅如昔。前有一千皆古錢，貫且朽。因共歎異之。傳聞遠近，施者日至，寺因大盛。", "translation": "江南某縣郊外有座古寺，地方偏僻、山路險峻，城裡的人很少來，寺裡的僧人長期苦於生活不足。有一天，一位四處雲遊的和尚來到這座寺，告訴住持，要和他一起策劃讓人們驚奇的事。寺裡有五百尊羅漢，雲遊僧挑了一尊相貌像自己的，穿上羅漢的衣服，戴上羅漢的斗笠，拄著羅漢的禪杖，進城剃頭。（剃頭師傅）不小心用刀割傷他的頭頂，他解開衣帶，拿出白色藥粉敷上，把禪杖留下當抵押，約剃頭師傅到寺裡來，答應給他一千錢。剃頭師傅按時前往，剛進寺門，守門人就打他說：「羅漢的禪杖丟了半年了，原來是你偷的！」剃頭師傅說明自己得到禪杖的經過和那人的相貌，大家一起去見住持，住持（假裝）更加驚奇。一起打開羅漢堂，門鎖都生鏽卡住了，座榻積滿灰塵，像很久沒有開過。看那尊丟了禪杖的羅漢，衣服斗笠都和剃頭師傅看見的一樣，頭頂有傷口，血跡和敷的藥都還在。羅漢前面放著一千錢，都是古錢，串錢的繩子也腐朽了。大家於是一起驚嘆這件奇事。消息遠近傳開，來布施的人天天都有，這座寺從此大為興盛。", "keywords": [{"w": "邑人", "m": "城裡的人"}, {"w": "遊方", "m": "僧人四處雲遊"}, {"w": "所以驚人耳目者", "m": "用來使人驚奇的方法"}, {"w": "衣其衣", "m": "穿上羅漢的衣服（前「衣」作動詞）"}, {"w": "策", "m": "拄著"}, {"w": "傅", "m": "通「敷」，塗抹"}, {"w": "質", "m": "抵押品"}, {"w": "遺", "m": "音ㄨㄟˋ，贈送、給"}, {"w": "閽者", "m": "守門人"}, {"w": "亡", "m": "遺失"}, {"w": "貫", "m": "串錢的繩子"}], "questions": [{"n": 33, "qtype": "單選", "stem": "依據上文，削者前往古寺的目的為何？", "options": {"A": "收取剃頭費用", "B": "藉機勒索主僧", "C": "暗中歸還竊物", "D": "打探寺中虛實"}, "answer": "A", "explain": "雲遊僧剃完頭「留杖為質，約至寺，將遺千錢」，剃頭師傅「如期而往」就是去拿約好的錢。(A)正確。(B)他是依約收款，不是勒索。(C)禪杖是對方留下的抵押品，不是他偷的。(D)他不知道寺裡的安排，沒有打探的意圖。", "skill": "人物行動目的，往前找「約定」「承諾」：有人答應給錢、留下抵押，去的目的當然就是收錢。"}, {"n": 34, "qtype": "單選", "stem": "依據上文，「寺因大盛」的原因為何？", "options": {"A": "迎遊方之僧為住持", "B": "寺中羅漢出現神蹟", "C": "羅漢堂內藏有珍寶", "D": "懸壺濟世藥方靈驗"}, "answer": "B", "explain": "雲遊僧設計了一場「羅漢下山剃頭」的戲：羅漢頭頂有傷、身前有千錢古錢，大家以為羅漢顯靈，「傳聞遠近，施者日至」。(B)正確。(A)文中沒說雲遊僧當上住持。(C)一千古錢不是什麼珍寶，也不是興盛原因。(D)白藥只是用來做假傷口的道具，不是行醫。", "skill": "「因」字前面的整件事就是原因：「傳聞遠近，施者日至」——大家傳的是什麼？就是羅漢顯靈的神蹟。就像今天的「行銷話題」，一則奇聞就能帶來人潮。"}, {"n": 35, "qtype": "單選", "stem": "依據上文，下列「」內的解釋，何者正確？", "options": {"A": "且將與之謀「所以驚人耳目者」：令人稱奇之事", "B": "「誤為刀傷其頂」，解衣帶：斗笠被刀子割毀", "C": "「羅漢亡杖」已半年：羅漢攜帶禪杖走失", "D": "頂有傷處，「血漬藥傅如昔」：藥效持久"}, "answer": "A", "explain": "(A)正確：「所以驚人耳目者」＝用來讓人驚奇的事。(B)「頂」是頭頂，刀割傷的是頭皮，後面才會敷藥，不是斗笠。(C)「亡杖」是禪杖遺失，不是羅漢走失。(D)「血漬藥傅如昔」是血跡和敷藥的痕跡和剃頭師傅看到的一樣，用來證明就是同一位，不是說藥效持久。", "skill": "「所以＋動詞＋者」＝「用來……的方法／事」，這是常考句式，看到就直接套。"}], "difficulty": "中", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc106-36", "exam": "tc106", "nums": [36, 37, 38], "form": "題組", "img": "img/tc106-36.png", "source": "蘇軾〈赤壁賦〉；李一冰《蘇東坡新傳》", "author": "蘇軾", "genre": "說理議論", "types": ["比較閱讀", "主旨寓意", "文意推論"], "passage": "【甲】蘇子曰：客亦知夫水與月乎？逝者如斯，而未嘗往也；盈虛者如彼，而卒莫消長也。蓋將自其變者而觀之，則天地曾不能以一瞬；自其不變者而觀之，則物與我皆無盡也，而又何羨乎？（蘇軾〈赤壁賦〉）", "translation": "【甲】蘇子說：你也知道那江水和月亮嗎？流逝的江水像這樣不停地流，卻從來沒有真正流走；時圓時缺的月亮像那樣變化，最終卻沒有增減。如果從變化的角度來看，天地萬物連一眨眼的時間都不能保持不變；如果從不變的角度來看，萬物和我都是無窮無盡的，又何必羨慕什麼呢？\n【乙】為白話文，說明蘇軾在黃州領悟永恆觀點，並引《莊子》「藏天下於天下」解釋「自其不變者而觀之」。", "keywords": [{"w": "逝者如斯", "m": "流逝的像這江水一樣"}, {"w": "盈虛者", "m": "時圓時缺的月亮"}, {"w": "卒", "m": "最終"}, {"w": "消長", "m": "減少與增加"}, {"w": "曾不能以一瞬", "m": "連一眨眼的時間都不能（保持不變）"}, {"w": "藏天下於天下", "m": "把天下藏在天下之中，無所謂失去"}], "questions": [{"n": 36, "qtype": "單選", "stem": "下列關於甲、乙二文的敘述，何者正確？", "options": {"A": "甲文是乙文的創作基礎，甲文所顯現的儒、道衝突為乙文闡發的重點", "B": "甲文的蘇子是蘇軾的化身，乙文中的蘇軾融合了史實與李一冰的闡釋", "C": "甲文用蘇子與客對話來敘寫，乙文則用蘇軾閱讀《莊子》來開展故事", "D": "甲文強調蘇子深陷人生無常的傷悲，乙文則凸顯蘇軾超越生死的智慧"}, "answer": "B", "explain": "(B)正確：〈赤壁賦〉中的「蘇子」就是蘇軾自己；乙文是傳記，寫蘇軾黃州三年的經歷（史實），再加上作者李一冰引《莊子》的詮釋。(A)甲文談的是變與不變的哲理，沒有儒道衝突，乙文重點也不在此。(C)乙文是作者自己引《莊子》來解釋，不是寫蘇軾讀《莊子》的故事。(D)甲文這段蘇子正是在開解客人、超脫無常的傷悲，不是深陷其中。", "skill": "甲乙對讀先分清「誰在說話」：甲是蘇軾自己的作品，乙是後人替他寫的傳記與解讀。"}, {"n": 37, "qtype": "單選", "stem": "乙文認為：莊子「藏天下於天下」可做為甲文「自其不變者而觀之」的註解，應是基於：", "options": {"A": "蘇軾從「不變」體悟了「萬物與我為一」，其哲理與莊子贊同的「以不藏為藏」相近", "B": "蘇軾從「不變」體悟了「萬物與我為一」，其哲理與莊子贊同的「用行而舍藏」相近", "C": "蘇軾從「不變」體悟了「世事終有定數」，其哲理與莊子贊同的「以不藏為藏」相近", "D": "蘇軾從「不變」體悟了「世事終有定數」，其哲理與莊子贊同的「用行而舍藏」相近"}, "answer": "A", "explain": "甲文「物與我皆無盡」，就是把自己和萬物看成一體的「萬物與我為一」，不是「世事有定數」的宿命觀，先刪(C)(D)。莊子說藏船藏山都可能被偷走，只有「藏天下於天下」——不刻意藏、與天地合一——才不會失落，這就是「以不藏為藏」。「用行舍藏」是《論語》孔子講出仕與退隱，和莊子無關，刪(B)。(A)正確。", "skill": "兩段式選項各自檢查：前半看甲文、後半看乙文，兩半都對才選；也要辨認「用行舍藏」是儒家（論語）用語。"}, {"n": 38, "qtype": "單選", "stem": "乙文所說的「失落」，主要是由什麼原因所造成？", "options": {"A": "心有拘執", "B": "天下無道", "C": "藏才隱智", "D": "物我無盡"}, "answer": "A", "explain": "人之所以會「失落」，是因為想把東西牢牢藏起來、據為己有，心裡有所執著；只要能「藏天下於天下」，不執著於佔有，就沒有失落可言。(A)正確。(B)失落與政治清明與否無關。(C)「藏才隱智」是隱藏才能，與藏船藏山的比喻不同。(D)「物我無盡」正是避免失落的境界，不是原因。", "skill": "寓言比喻題先翻成生活語言：越想緊緊抓住，越怕失去；「失落」的根源就是執著。"}], "difficulty": "難", "label": "106統測", "year": 106, "kind": "統測"}, {"id": "tc107-04", "exam": "tc107", "nums": [4], "form": "單題", "img": "img/tc107-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "可望而不可即", "translation": "「可望而不可即」：看得到卻無法靠近。這裡的「即」是「靠近、接近」。", "keywords": [{"w": "即", "m": "靠近；就是；立刻；便"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列文句中的「即」，何者與「可望而不可即」的「即」意義最接近？", "options": {"A": "余攬衣「即」穴旁視之，聞怒雷震蕩地底，而驚濤與沸鼎聲間之", "B": "翡冷翠稱為文藝復興搖籃之地，「即」因這個地方人文薈萃，人才輩出", "C": "及郡下，詣太守，說如此。太守「即」遣人隨其往，尋向所誌，遂迷不復得路", "D": "像放那東洋煙火，一個彈子上天，隨化作千百道五色火光，縱橫散亂。這一聲飛起，「即」有無限聲音，俱來並發"}, "answer": "A", "explain": "先確定題目的「即」：可望而不可即＝看得見卻走不到，「即」是動詞「靠近」。(A)正確：郁永河〈北投硫穴記〉「攬衣即穴旁視之」＝撩起衣服走近洞穴旁邊去看，「即」是靠近。(B)錯：「即因」＝就是因為，「即」是判斷用的「就是」。(C)錯：〈桃花源記〉「太守即遣人隨其往」＝太守立刻派人跟去，「即」是「立刻」。(D)錯：劉鶚〈明湖居聽書〉「這一聲飛起，即有無限聲音」＝這一聲一起，便有無數聲音，「即」是「便、就」。", "skill": "看「即」後面接的是地點還是動作：接地點（穴旁）多是「靠近」，接動作（遣人、有）多是「立刻、便」。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-05", "exam": "tc107", "nums": [5], "form": "單題", "img": "img/tc107-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文化常識", "句意理解"], "passage": "", "translation": "", "keywords": [{"w": "執事", "m": "辦事的人；書信或對話中不直接稱對方，而稱其手下辦事人員，以表敬意"}, {"w": "姑", "m": "姑且、暫且"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列畫底線的措詞口吻，何者向言談的對方表示恭敬之意？", "options": {"A": "(將士)或勸以少休，公曰：「吾上恐負朝廷，下恐愧吾師也。」", "B": "樊噲曰：「今日之事何如？」良(張良)曰：「甚急！今者項莊拔劍舞，其意常在沛公也。」", "C": "(燭之武)見秦伯，曰：「秦、晉圍鄭，鄭既知亡矣。若亡鄭而有益於君，敢以煩執事。」", "D": "馮諼誡孟嘗君曰：「願請先王之祭器，立宗廟於薛。」廟成，還報孟嘗君曰：「三窟已就，君姑高枕為樂矣！」"}, "answer": "C", "explain": "找「說話者故意放低自己、抬高對方」的用語。(C)正確：燭之武對秦穆公說「敢以煩執事」，意思是「冒昧拿這件事來麻煩您的辦事人員」；「敢」是謙詞（冒昧），不直接說麻煩秦伯本人而說「執事」，是很恭敬的說法，就像今天寫信給長官說「敬請 鈞座」一樣客氣。(A)錯：〈左忠毅公軼事〉史可法說「上怕辜負朝廷，下怕對不起老師」，是表明自己的心志，不是對將士表示恭敬。(B)錯：〈鴻門宴〉張良回答樊噲「情況很危急」，是報告緊急軍情，沒有敬意用語。(D)錯：〈馮諼客孟嘗君〉馮諼說「三窟已就，君姑高枕為樂矣」，是自信地告訴孟嘗君可以放心，口吻是安慰、邀功，不是特別表示恭敬。", "skill": "遇到「敬意」題，先抓謙詞（敢、竊、愚、不才）與敬稱（執事、足下、陛下）這類標記詞。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-10", "exam": "tc107", "nums": [10], "form": "單題", "img": "img/tc107-10.png", "source": "柳宗元〈鞭賈〉", "author": "柳宗元", "genre": "寓言故事", "types": ["文意推論", "主旨寓意"], "passage": "市之鬻鞭者，人問之，其賈宜五十，必曰五萬。復之以五十，則伏而笑；以五百，則小怒；五千，則大怒；必以五萬而後可。有富者子，適市買鞭，出五萬，持以誇余。", "translation": "市場上有個賣鞭子的人，別人問價，那鞭子大約值五十錢，他一定開價五萬。還價五十，他就彎腰大笑；還價五百，他有點生氣；還價五千，他大發脾氣；一定要五萬才肯賣。有個富家子弟到市場買鞭，付了五萬錢，拿著它來向我炫耀。", "keywords": [{"w": "鬻", "m": "賣"}, {"w": "賈", "m": "同「價」，價錢"}, {"w": "復", "m": "回應、還價"}, {"w": "伏", "m": "俯身、彎腰"}, {"w": "適", "m": "前往"}, {"w": "誇", "m": "炫耀"}], "questions": [{"n": 10, "qtype": "單選", "stem": "依據下文，下列敘述何者正確？", "options": {"A": "商人因富者子出價極高，遂忍痛割愛", "B": "商人因富者子出價反覆，乃出言嘲諷", "C": "富者子不慎損毀貨品，情願照價賠償", "D": "富者子不識貨品價值，仍出高價購買"}, "answer": "D", "explain": "大意：一條只值五十錢的鞭子，商人硬要賣五萬，富家子竟真的花五萬買下，還拿來炫耀。(D)正確：富家子付了「五萬」，正是不識貨、被當冤大頭。(A)錯：商人本來就堅持「必以五萬而後可」，賣出是得償所願，不是忍痛割愛。(B)錯：「伏而笑、小怒、大怒」是針對一般還價的人，富家子沒有反覆出價，直接出五萬。(C)錯：文中沒有損毀貨品的情節，富家子是買了之後「持以誇余」。", "skill": "寓言題先抓數字或關鍵動作的對照（值五十、賣五萬），諷刺點通常就在落差裡。"}], "difficulty": "易", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-11", "exam": "tc107", "nums": [11], "form": "單題", "img": "img/tc107-11.png", "source": "《論語》、《左傳》（文字雲）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "", "translation": "", "keywords": [{"w": "君子", "m": "《論語》最常談論的理想人格"}, {"w": "晉、楚、鄭、公", "m": "《左傳》記春秋列國之事，常見國名與「公」"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下列甲、乙兩朵文字雲由兩本經典製成，書中使用次數越多的字，字體越大，則這兩本經典依序應是：", "options": {"A": "論語／左傳", "B": "論語／荀子", "C": "孟子／左傳", "D": "孟子／荀子"}, "answer": "A", "explain": "看最大的字：甲最大的是「君子」「子」，旁邊有「仁」「顏淵」「子路」「子貢」「曾子」「問」——孔子和弟子問答，正是《論語》。乙最大的是「晉」「鄭」「楚」「齊」「公」「師」「伐」「盟」——諸侯國名與戰爭、會盟用語，正是記載春秋列國歷史的《左傳》。所以是(A)論語／左傳。(B)(D)錯：《荀子》是議論文，高頻字不會是一堆國名與「伐、盟」。(C)(D)錯：甲出現子路、子貢、顏淵、曾子等孔門弟子，是《論語》，若是《孟子》會出現「梁惠王、齊宣王、王」等字。", "skill": "文字雲題抓最大的幾個字＋專有名詞：人名是孔門弟子→論語；國名＋伐、盟→史書（左傳）。"}], "difficulty": "易", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-15", "exam": "tc107", "nums": [15, 16], "form": "題組", "img": "img/tc107-15.png", "source": "鄭愁予〈編秋草〉；溫庭筠〈商山早行〉", "author": "鄭愁予；溫庭筠", "genre": "古典詩詞曲", "types": ["比較閱讀", "詩詞賞析"], "passage": "晨起動征鐸，客行悲故鄉。雞聲茅店月，人跡板橋霜。槲葉落山路，枳花明驛牆。因思杜陵夢，鳧雁滿回塘。", "translation": "清晨起來，車馬的鈴鐺已經響起，出門在外的旅人想念故鄉而悲傷。雞啼時，茅草搭的旅店上還掛著月亮；木板橋上的白霜，已印上早行人的腳印。槲樹葉落滿山路，枳樹的白花照亮了驛站的牆。於是想起昨夜夢見的杜陵家鄉，野鴨和大雁正擠滿曲折的池塘。（甲詩為現代詩：旅人像編草鞋一樣編織晨昏、趕路，雁群也在寒暑之間奔波。）", "keywords": [{"w": "征鐸", "m": "遠行車馬上掛的鈴鐺"}, {"w": "客行", "m": "旅人出門在外"}, {"w": "槲", "m": "落葉喬木名"}, {"w": "枳", "m": "一種有刺的灌木，春天開白花"}, {"w": "驛", "m": "驛站，供旅客、公差換馬休息處"}, {"w": "杜陵", "m": "地名，在長安附近，詩人故鄉所在"}, {"w": "鳧", "m": "野鴨"}, {"w": "回塘", "m": "曲折的池塘"}], "questions": [{"n": 15, "qtype": "單選", "stem": "甲、乙二詩共同述及的內容為何？", "options": {"A": "江山如故", "B": "旅途奔波", "C": "世態炎涼", "D": "黃粱一夢"}, "answer": "B", "explain": "甲詩說「製一雙趕路的鞋子」「那穿著晨與夜的，趕路的雁來了」；乙詩一開頭「晨起動征鐸，客行悲故鄉」，又寫茅店、板橋、山路、驛牆，全是趕路的景象。兩首都在寫旅途奔波，選(B)。(A)錯：兩首都沒有感嘆山河依舊。(C)錯：沒有寫人情冷暖。(D)錯：乙詩雖提到「杜陵夢」，是夢見故鄉，不是「人生如夢、富貴虛幻」的黃粱一夢。", "skill": "比較兩首詩的共同點，先各圈出重複出現的場景詞（趕路、晨、驛、雁），交集就是答案。"}, {"n": 16, "qtype": "單選", "stem": "下列關於甲、乙詩句的解釋，何者最符合詩意？", "options": {"A": "甲詩「多是寒了的，與暑了的追迫」意謂回憶冰消瓦解", "B": "乙詩「雞聲茅店月，人跡板橋霜」暗指旅人清晨趕路", "C": "甲詩的「葉襬」和乙詩的「落葉」皆比喻腸枯思竭", "D": "甲、乙二詩的「雁」，詩人皆以之自比籠中之鳥"}, "answer": "B", "explain": "(B)正確：雞才啼、月還在、霜上已有腳印——天還沒亮旅人就上路了，用景物暗示早行。(A)錯：甲詩說雁的記憶多是被寒暑追趕，寫的是一路奔波的辛苦，不是回憶消失。(C)錯：「葉襬」是芒草可用來編鞋的部分，「槲葉落山路」是沿途景色，都不是比喻才思枯竭。(D)錯：雁是候鳥，正好象徵遷徙、奔波；乙詩的「鳧雁滿回塘」是夢中故鄉的悠閒景象，兩者都不是被困住的籠中鳥。", "skill": "詩句只有名詞並列時（雞聲、茅店、月），把它們連成一個畫面，再問「這是一天中的什麼時候、人在做什麼」。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-17", "exam": "tc107", "nums": [17, 18], "form": "題組", "img": "img/tc107-17.png", "source": "甲：祝允明《前聞記》；乙：郎瑛《七修類稿》", "author": "祝允明；郎瑛", "genre": "筆記小品", "types": ["文意推論", "文化常識", "比較閱讀"], "passage": "甲、太祖皇帝一日閱遠方驛夫，見一小兒在其中，問之，兒對曰：「臣父當此役，近日死，臣代役耳。」上曰：「你幾歲？」兒對曰：「七歲。」上曰：「能作對麼？」兒對曰：「能。」上曰：「七歲孩兒當馬驛」，即應聲云：「＿＿＿＿」。上大喜，蠲其役。\n乙、太祖嘗微行，遇一監生，同飲於酒家，奈坐已滿，回觀惟有土神之几，太祖遂移神於地曰：「且讓我。」因對飲，問生曰：「何處人？」生曰：「重慶。」帝因出對曰：「千里為重，重水重山重慶府」，生對：「一人成大，大邦大國大明君」。帝甚喜，散後，酒主復移土神上坐。是夜夢神曰：「皇帝命我不可上坐。」方疑之，則聞朝廷召昨日飲酒監生與官矣，然後知太祖焉。故今天下土地多坐於下。", "translation": "甲：明太祖有一天檢閱遠地驛站的役夫，看見一個小孩在裡面，就問他。小孩回答：「我父親負責這項差役，最近死了，我來代替服役。」皇上問：「你幾歲？」答：「七歲。」皇上說：「會對對子嗎？」答：「會。」皇上出上聯「七歲孩兒當馬驛」，小孩立刻對出下聯。皇上非常高興，免除了他的差役。\n乙：太祖曾經微服出巡，遇到一個監生，一起到酒館喝酒，可是座位都滿了，回頭一看只有土地神的桌案，太祖就把神像移到地上說：「暫且讓給我。」兩人對飲，太祖問監生：「哪裡人？」答：「重慶。」太祖便出上聯「千里為重，重水重山重慶府」，監生對「一人成大，大邦大國大明君」。太祖很高興。散席後，酒館主人把土地神移回上座，當夜夢見神說：「皇帝命令我不可以坐上面。」店主正疑惑，就聽說朝廷召見昨天喝酒的監生並授予官職，這才知道那人是太祖。所以如今天下的土地神像大多放在下面。", "keywords": [{"w": "閱", "m": "檢閱、視察"}, {"w": "驛夫", "m": "驛站中服勞役的人"}, {"w": "役", "m": "差役、勞役"}, {"w": "蠲", "m": "免除"}, {"w": "微行", "m": "帝王換便服出巡"}, {"w": "監生", "m": "國子監的學生"}, {"w": "几", "m": "小桌案"}, {"w": "與官", "m": "授予官職"}], "questions": [{"n": 17, "qtype": "單選", "stem": "依據對聯原則與故事情境，甲文 ＿＿ 內小兒所對的下聯應是：", "options": {"A": "萬年天子坐龍庭", "B": "萬里長征人未還", "C": "萬頃江田一鷺飛", "D": "萬古惟留楚客悲"}, "answer": "A", "explain": "對聯要詞性相對、意思呼應。上聯「七歲孩兒當馬驛」：數字＋人物＋動詞＋處所，說的是小孩自己。(A)「萬年／天子／坐／龍庭」逐字相對：七歲對萬年、孩兒對天子、當對坐、馬驛對龍庭，又祝頌眼前的皇帝，難怪「上大喜」。(B)「萬里長征人未還」是王昌齡〈出塞〉，寫征人不歸，對皇帝說這句不吉利，也與情境不合。(C)「萬頃江田一鷺飛」是寫景，與「孩兒當馬驛」的人事不相關，也無法讓皇帝大喜。(D)「萬古惟留楚客悲」是悲涼懷古句，同樣不合當下要討皇帝歡心的情境。", "skill": "對聯填空：先逐詞對位（數字對數字、人對人、地點對地點），再看哪個合乎說話對象與情境。"}, {"n": 18, "qtype": "單選", "stem": "依據上文，下列敘述何者錯誤？", "options": {"A": "甲文小兒與乙文監生在應答時，均不知太祖的真實身分", "B": "甲、乙二文的太祖，均因欣賞能對出佳聯者而施予恩典", "C": "乙文的對聯巧妙運用合字(千＋里＝重，一＋人＝大)開展句意", "D": "乙文的土神敬畏皇帝，故託夢給酒家主人，表示不敢復坐於原處"}, "answer": "A", "explain": "(A)錯誤（本題答案）：甲文小兒一開口就自稱「臣」，又稱對方「上」問他，可見他知道眼前是皇帝；只有乙文監生是事後「然後知太祖焉」。(B)正確：甲文「蠲其役」，乙文「召監生與官」，都是因為對聯對得好而給恩典。(C)正確：「千里為重」是把「重」拆成「千＋里」，「一人成大」把「大」拆成「一＋人」，是拆字（合字）對。(D)正確：土神夢中說「皇帝命我不可上坐」，所以不敢再坐上座。", "skill": "判斷人物是否知道對方身分，就看他用什麼稱呼：自稱「臣」，就是知道對方是君。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-19", "exam": "tc107", "nums": [19, 20], "form": "題組", "img": "img/tc107-19.png", "source": "《孟子‧告子上》", "author": "孟子", "genre": "經典語錄", "types": ["主旨寓意", "虛詞句式"], "passage": "弈秋，通國之善弈者也。使弈秋誨二人弈，其一人專心致志，惟弈秋之為聽；一人雖聽之，一心以為有鴻鵠將至，思援弓繳而射之，雖與之俱學，弗若之矣。為是其智弗若與？曰：非然也。", "translation": "弈秋是全國最會下棋的人。讓弈秋教兩個人下棋，其中一人專心一意，只聽弈秋講解；另一人雖然也在聽，心裡卻一直想著有天鵝要飛來，想拿弓箭去射牠。雖然兩人一起學，後者卻比不上前者。是因為他的聰明比不上嗎？我說：不是這樣的。", "keywords": [{"w": "弈", "m": "下棋"}, {"w": "通國", "m": "全國"}, {"w": "誨", "m": "教導"}, {"w": "惟弈秋之為聽", "m": "只聽弈秋的，賓語「弈秋」提前"}, {"w": "鴻鵠", "m": "天鵝"}, {"w": "援", "m": "拿、拉"}, {"w": "繳", "m": "繫在箭上的生絲繩"}, {"w": "弗若", "m": "比不上"}], "questions": [{"n": 19, "qtype": "單選", "stem": "下列文句，何者最接近上文的主旨？", "options": {"A": "常人貴遠賤近，向聲背實", "B": "聞道有先後，術業有專攻", "C": "目不能兩視而明，耳不能兩聽而聰", "D": "安能以皓皓之白，而蒙世俗之塵埃乎"}, "answer": "C", "explain": "主旨：兩人資質差不多，差別在「專心」與「分心」。(C)正確：《荀子‧勸學》「眼睛不能同時看兩樣東西而看得清楚，耳朵不能同時聽兩種聲音而聽得明白」，就是說做事要專一。就像上班時一邊開會一邊滑手機，兩邊都做不好。(A)錯：曹丕〈典論論文〉批評人重視遠的、輕視近的，崇尚虛名、背離實際，與專心無關。(B)錯：韓愈〈師說〉講各人懂道理有早晚、專業各有分工，不是講專心。(D)錯：〈漁父〉屈原表示不願讓清白受世俗汙染，講的是堅持節操。", "skill": "主旨題先用一句話說出故事的對比（專心vs分心），再找講同一件事的選項。"}, {"n": 20, "qtype": "單選", "stem": "「惟弈秋之為聽」意謂「惟聽弈秋」，但書寫時將「弈秋」移到動詞「聽」的前面。下列畫底線的文句，何者也有相同的表意方式？", "options": {"A": "百年老屋，塵泥滲漉，雨澤下注", "B": "近世寇萊公豪侈冠一時，然以功業大，人莫之非", "C": "傾壺而醉，醉則更相枕以臥，臥而夢，意有所極，夢亦同趣", "D": "暮春之初，會於會稽山陰之蘭亭，修禊事也，群賢畢至，少長咸集"}, "answer": "B", "explain": "要找「賓語跑到動詞前面」的句子。(B)正確：司馬光〈訓儉示康〉「人莫之非」＝人莫非之（沒有人責怪他），否定句中代詞「之」提前到動詞「非」前面，和「惟弈秋之為聽」一樣是賓語前置。(A)錯：歸有光〈項脊軒志〉「雨澤下注」＝雨水往下灌，主詞＋動詞，正常語序。(C)錯：柳宗元〈始得西山宴遊記〉「夢亦同趣」＝夢也跟著到那裡，正常語序。(D)錯：王羲之〈蘭亭集序〉「少長咸集」＝年少年長的都聚集，主詞在前，正常語序。", "skill": "否定句（莫、不、未）＋代詞（之、我）＋動詞，代詞常是被提前的賓語；把它移回動詞後面讀讀看就知道。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-26", "exam": "tc107", "nums": [26], "form": "單題", "img": "img/tc107-26.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解"], "passage": "為農者，必儲糞朽以糞之，則地力常新壯，而收穫不減", "translation": "種田的人一定要儲存糞便和腐爛的草葉來給田地施肥，這樣土地的肥力就能常保新鮮旺盛，收成也不會減少。", "keywords": [{"w": "糞朽", "m": "糞便與腐爛的草木"}, {"w": "糞之", "m": "給土地施肥（「糞」作動詞）"}, {"w": "地力", "m": "土地的肥力"}], "questions": [{"n": 26, "qtype": "單選", "stem": "下列文句，何者顯現古人對資源循環利用的重視？", "options": {"A": "善畜養者，必有愛重之心；有愛重之心，必無慢易之意", "B": "為農者，必儲糞朽以糞之，則地力常新壯，而收穫不減", "C": "泰山不讓土壤，故能成其大；河海不擇細流，故能就其深", "D": "惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色，取之無禁，用之不竭"}, "answer": "B", "explain": "「循環利用」＝把用過、丟掉的東西變回資源。(B)正確：把糞便、腐草這些「廢物」做成肥料還給土地，讓地力常新、收成不減，就是今天說的循環經濟——像台積電把廢硫酸變成工業原料一樣。(A)錯：講飼養牲畜要愛護、不可輕忽，是對待的態度，沒有回收再用。(C)錯：李斯〈諫逐客書〉以泰山、河海不拒細小來比喻要廣納人才。(D)錯：蘇軾〈赤壁賦〉說清風明月取用不盡，是讚美大自然無窮，不是把廢物再利用。", "skill": "抓題目關鍵詞的定義（循環＝廢物→再變資源），再看哪個選項同時有「廢」與「再用」兩個環節。"}], "difficulty": "易", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-30", "exam": "tc107", "nums": [30, 31, 32], "form": "題組", "img": "img/tc107-30.png", "source": "張岱〈菊海〉；袁宏道〈晚遊六橋待月記〉", "author": "張岱；袁宏道", "genre": "筆記小品", "types": ["文意推論", "寫作手法", "比較閱讀"], "passage": "兗州張氏期余看菊，去城五里，余至其園，盡其所為園者而折旋之，又盡其所不盡為園者而周旋之，絕不見一菊，異之。移時，主人導至一蒼莽空地，有葦廠三間，肅余入，遍觀之，不敢以菊言，真菊海也。廠三面，砌壇三層，以菊之高下高下之。花大如瓷甌，無不球，無不甲，無不金銀荷花瓣，色鮮艷，異凡本，而翠葉層層，無一葉早脫者。此是天道，是土力，是人工，缺一不可焉。\n（袁宏道）余時為桃花所戀，竟不忍去湖上。由斷橋至蘇堤一帶，綠煙紅霧，彌漫二十餘里。歌吹為風，粉汗為雨，羅紈之盛，多於堤畔之草，艷冶極矣。", "translation": "兗州的張家約我去賞菊，地點離城五里。我到了他的園子，把整座園子都繞遍了，又把園子以外的地方也繞了一圈，卻連一朵菊花都沒看到，覺得很奇怪。過了一會兒，主人帶我到一片荒草空地，那裡有三間蘆葦搭的棚子，恭敬地請我進去。我四處觀看，簡直不能只用「菊花」來形容，真是菊花的海洋。棚子三面都砌了三層花壇，依照菊花的高矮擺放高低。花朵大得像瓷碗，沒有一朵不是圓球狀、不是層層如甲片、不是金銀荷花瓣的品種，顏色鮮豔，與一般品種不同；而且翠綠的葉子層層疊疊，沒有一片提早掉落。這是天時、地力、人工三者缺一不可的成果。\n（袁文）我那時被桃花迷住，竟捨不得離開西湖。從斷橋到蘇堤一帶，綠色的柳煙、紅色的花霧，綿延二十多里。遊人的歌聲樂聲像風一樣，女子臉上帶脂粉的汗水像雨一樣，穿綾羅綢緞的遊人之多，比堤邊的草還多，真是豔麗到了極點。", "keywords": [{"w": "期", "m": "約定"}, {"w": "折旋、周旋", "m": "來回繞行"}, {"w": "異之", "m": "覺得奇怪"}, {"w": "移時", "m": "過了一會兒"}, {"w": "蒼莽", "m": "草木茂密而荒野"}, {"w": "葦廠", "m": "蘆葦搭的棚子"}, {"w": "肅", "m": "恭敬地引導"}, {"w": "以菊之高下高下之", "m": "依菊株高矮來安排高低位置"}, {"w": "甌", "m": "碗"}, {"w": "凡本", "m": "一般品種"}, {"w": "羅紈", "m": "華美的絲織衣服，代指遊人"}, {"w": "艷冶", "m": "豔麗"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依據上文，關於張府賞菊處所的敘述，何者正確？", "options": {"A": "佔地廣達五里，包含葦廠三間", "B": "入園之後幾經打探，始見葦廠", "C": "葦廠有圍牆三層，牆以石磚砌成", "D": "配合壇分三層，菊株按高低擺放"}, "answer": "D", "explain": "(D)正確：「砌壇三層，以菊之高下高下之」＝花壇分三層，按菊花高矮擺放。(A)錯：「去城五里」是離城五里，不是佔地五里。(B)錯：作者是自己繞完整座園子找不到菊花，後來「主人導至」才看到，不是到處打聽。(C)錯：砌的是「壇」（花台）三層，不是圍牆三層，也沒說用石磚。", "skill": "數字題特別小心「主詞」：五里是距離還是面積、三層是壇還是牆，回原文對位就不會被騙。"}, {"n": 31, "qtype": "單選", "stem": "依據上文，作者至張府賞菊時初覺「異之」，主要是因為：", "options": {"A": "吾廬籬下菊，秋來未著花", "B": "東籬有佳菊，恨無知音賞", "C": "遍尋不知蹤，覓時何處覓", "D": "行到水窮處，但聞人語響"}, "answer": "C", "explain": "「異之」的原因在前一句：繞遍園內園外「絕不見一菊」——說好來賞菊，卻到處找不到菊花，所以奇怪。(C)「到處找都不知道在哪裡」最貼切。(A)錯：不是菊花還沒開，而是根本沒看到。(B)錯：文中沒有「沒人欣賞」的遺憾。(D)錯：「只聽到人聲」與看不到菊花無關，文中也沒有水窮之處。", "skill": "問「為什麼覺得怎樣」，答案多半就在那個感受詞的前一句。"}, {"n": 32, "qtype": "單選", "stem": "上文與下面方框袁宏道〈晚遊六橋待月記〉都敘寫了「花海」。關於兩文畫底線處的解讀，何者錯誤？", "options": {"A": "張文：描述菊花的形貌色彩", "B": "袁文：呈現遊人的綺麗風情", "C": "張文：展示近距觀賞的畫面", "D": "袁文：運用擬物為人的手法"}, "answer": "D", "explain": "張文畫線處是「花大如瓷甌……無一葉早脫者」，袁文畫線處是「歌吹為風，粉汗為雨，羅紈之盛，多於堤畔之草」。(D)錯誤（本題答案）：袁文是把人的歌聲比作風、汗水比作雨、遊人多過草，是把「人事」比成「自然物」，再加上誇飾，並不是把物當成人來寫的擬人手法。(A)正確：花的大小、形狀、顏色、葉子都寫到了。(B)正確：寫遊人的歌樂、脂粉、華服，呈現熱鬧豔麗的遊人風情。(C)正確：能看清花瓣形態、葉子有沒有掉，是走近細看的畫面。", "skill": "判斷擬人：要有「物」做出「人才會有的動作或情感」；若是把人比成物（汗→雨），方向相反，不是擬人。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-33", "exam": "tc107", "nums": [33, 34, 35], "form": "題組", "img": "img/tc107-33.png", "source": "劉向《說苑‧政理》", "author": "劉向", "genre": "史傳人物", "types": ["文意推論", "比較閱讀", "主旨寓意"], "passage": "（甲圖）宓子賤為單父宰。陽晝：「有釣道二焉，請以送子。」宓子賤：「釣道奈何？」陽晝：「迎而吸之者，陽橋也，其為魚，薄而不美。若食若不食者，魴也，其為魚，博而厚味。」宓子賤：「善。」（未至單父，冠蓋迎之者交接於道）宓子賤：「陽橋者至矣。」（心想）請耆老尊賢者共治單父。\n【乙】宓子賤治單父，彈鳴琴，身不下堂而單父治。巫馬期亦治單父，以星出，以星入，日夜不處，以身親之，而單父亦治。巫馬期問其故於宓子賤，宓子賤曰：「我之謂任人，子之謂任力。任力者固勞，任人者固佚。」", "translation": "（甲圖）宓子賤要去當單父的縣長。陽晝說：「我有兩種釣魚的道理，送給你。」宓子賤問：「什麼道理？」陽晝說：「一放下餌就迎上來吞的，是陽橋魚，這種魚肉薄、味道不好。好像要吃又好像不吃的，是魴魚，這種魚肉厚、味道鮮美。」宓子賤說：「好。」還沒到單父，坐著華車、戴著官帽來迎接的人一路不斷，宓子賤說：「陽橋魚來了。」於是他去請地方上年高德劭、受人尊敬的賢者一起治理單父。\n【乙】宓子賤治理單父，每天彈琴，人不必走下廳堂，單父就治理得很好。巫馬期也治理過單父，天沒亮（星星還在）就出門，天黑（星星出來）才回家，日夜不休息，什麼事都親自處理，單父也治理得很好。巫馬期問宓子賤原因，宓子賤說：「我這叫做任用人才，你那叫做使用自己的力氣。用自己力氣的人當然勞累，任用人才的人當然安逸。」", "keywords": [{"w": "宰", "m": "地方長官"}, {"w": "單父", "m": "地名，音ㄕㄢˋ ㄈㄨˇ"}, {"w": "陽橋", "m": "一種見餌就搶吃的魚，比喻趨炎附勢的人"}, {"w": "魴", "m": "魚名，謹慎不輕易上鉤，比喻難得的賢才"}, {"w": "冠蓋", "m": "官帽與車蓋，代指官員權貴"}, {"w": "耆老", "m": "年高德劭的長者"}, {"w": "不處", "m": "不休息"}, {"w": "任人", "m": "任用人才"}, {"w": "任力", "m": "親自出力"}, {"w": "佚", "m": "同「逸」，安逸"}], "questions": [{"n": 33, "qtype": "單選", "stem": "依據甲圖、乙文，下列敘述何者正確？", "options": {"A": "宓子賤因治理單父頗有窒礙，遂向陽晝請益", "B": "宓子賤得陽晝建議，先往陽橋學習釣魚之道", "C": "巫馬期樂於以自身的經驗，傳授宓子賤治理訣竅", "D": "就發生時間而言，乙文的對話應晚於甲圖的對話"}, "answer": "D", "explain": "(D)正確：甲圖是宓子賤上任前（「未至單父」）向陽晝討教；乙文是他已經把單父治理好、巫馬期來問原因，所以乙文較晚。(A)錯：他是上任前就聽了建議，不是治理遇到困難才請教，而且是陽晝主動說「請以送子」。(B)錯：「陽橋」是一種魚名，不是地方，他也沒去學釣魚。(C)錯：是巫馬期向宓子賤請教「問其故於宓子賤」，方向相反。", "skill": "圖文題先排時間軸：圖的格子順序＋文中「未至」「既治」等時間詞，就能判斷先後。"}, {"n": 34, "qtype": "單選", "stem": "乙文所述宓子賤的「任人」，最可能是甲圖的何者？", "options": {"A": "陽晝", "B": "陽橋", "C": "冠蓋迎之者", "D": "耆老尊賢者"}, "answer": "D", "explain": "「任人」是任用賢能的人替自己做事。甲圖最後一格，宓子賤想「請耆老尊賢者共治單父」，這些人就是他任用的人才，選(D)。(A)錯：陽晝只是提供建議的人，沒有去單父一起治理。(B)(C)錯：陽橋魚比喻一見好處就湊上來的人，「冠蓋迎之者」正是宓子賤說的「陽橋者至矣」，是他要提防、不重用的對象。就像職場上主管不該只提拔最會巴結的人。", "skill": "比喻題先把喻體對應到真實人物：陽橋＝搶著巴結的人，魴＝難請的賢才，答案就是後者在現實中的對應。"}, {"n": 35, "qtype": "單選", "stem": "下列文句，何者最接近宓子賤治理單父的方式？", "options": {"A": "居廟堂之高，則憂其民；處江湖之遠，則憂其君", "B": "不懈於內，忘身於外，夙夜憂勤，報之於陛下，恐託付不效", "C": "不以謫為患，自放山水之間，蓬戶甕牖無所不快，窮耳目之勝以自適", "D": "簡能而任之，擇善而從之，文武爭馳，君臣無事，可以盡豫遊之樂，可以養松喬之壽"}, "answer": "D", "explain": "宓子賤的方法：找賢才來做事（任人），自己彈琴就能把地方治好（任人者固佚）。(D)正確：魏徵〈諫太宗十思疏〉「選拔有才能的人任用他，選擇好的意見聽從它，文臣武將都爭著效力，君臣無事，可以盡情遊樂、養生長壽」，正是任人而逸。(A)錯：范仲淹〈岳陽樓記〉講無論在朝在野都憂國憂民，重點是憂心，不是任人。(B)錯：〈出師表〉文意相關句講臣子日夜勤勞、怕辜負託付，比較像巫馬期的「任力」。(C)錯：蘇轍〈黃州快哉亭記〉講被貶也能自得其樂，與治理方法無關。", "skill": "把文中的核心概念換成一組關鍵字（任人、佚），再找同時出現「用人」和「輕鬆」的選項。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc107-36", "exam": "tc107", "nums": [36, 37, 38], "form": "題組", "img": "img/tc107-36.png", "source": "甲：《禮記‧禮運》；乙：改寫自陳祖為《儒家致善主義——現代的政治哲學重構》", "author": "戴聖（編）；陳祖為", "genre": "經典語錄", "types": ["文意推論", "比較閱讀", "主旨寓意"], "passage": "今大道既隱，天下為家，各親其親，各子其子，貨力為己。大人世及以為禮，城郭溝池以為固，禮義以為紀。以正君臣，以篤父子，以睦兄弟，以和夫婦，以設制度，以立田里，以賢勇知，以功為己。故謀用是作，而兵由此起。禹、湯、文、武、成王、周公，由此其選也。此六君子者，未有不謹於禮者也。以著其義，以考其信，著有過，刑仁講讓，示民有常。如有不由此者，在勢者去，眾以為殃。是謂小康。", "translation": "如今大道已經隱沒，天下成為一家一姓所私有，人們各自只親愛自己的父母，只疼愛自己的子女，財物和力氣都為自己。天子諸侯父子兄弟相傳成為禮制，修築城牆和護城河作為防守，用禮義作為綱紀：用來端正君臣關係，使父子感情深厚，使兄弟和睦，使夫婦和諧，用來建立制度，劃分田地住宅，尊重勇敢和有智慧的人，把功勞歸於自己。因此陰謀詭計由此而生，戰爭也由此而起。禹、湯、文王、武王、成王、周公，就是在這種情況下選出的傑出人物。這六位君子沒有一個不謹守禮制的：用禮來彰顯道義，考察誠信，揭露過錯，以仁愛為典範、講求禮讓，讓百姓知道有常規可循。如果有不遵守的，即使有權勢的也會被罷黜，百姓視他為禍害。這就叫做小康。（乙文為白話，說明大同以無私關愛為基礎，小康則以禮維持秩序，並部分實現大同理想。）", "keywords": [{"w": "天下為家", "m": "天下歸一家一姓所有"}, {"w": "世及", "m": "父子相傳為世，兄弟相傳為及"}, {"w": "紀", "m": "綱紀、準則"}, {"w": "篤", "m": "使深厚"}, {"w": "知", "m": "同「智」"}, {"w": "謀用是作", "m": "陰謀因此產生"}, {"w": "由此其選", "m": "因此而被選出的傑出者"}, {"w": "刑仁講讓", "m": "以仁為典範，講求禮讓"}, {"w": "在勢者去", "m": "有權位者也要被罷免"}, {"w": "殃", "m": "禍害"}], "questions": [{"n": 36, "qtype": "單選", "stem": "下列「大同」與「小康」的關係，何者符合乙文的看法？", "options": {"A": "由小康進至大同，是社會演變的必然歷程", "B": "從大同淪為小康，人性的美好已蕩然無存", "C": "小康固不及大同，仍維持安分有序的型態", "D": "大同與小康皆優，均以嚴謹外在制度為本"}, "answer": "C", "explain": "乙文說：大同靠無私關愛，小康時這種精神「減弱了」，但小康靠「禮」維持秩序，「部分實現了」大同理想。(C)正確：小康比不上大同，但仍有禮制使社會安分有序。(A)錯：乙文明說「小康並非通往大同的過渡階段」。(B)錯：乙文說無私精神只是「減弱」，小康仍「保有大同精神」，不是蕩然無存。(D)錯：大同「沒有禮或法——即使存在也無須執行」，不是以外在制度為本。", "skill": "比較兩概念的關係題，到文中找「並非」「但」「不過」等轉折詞，作者真正的看法多在轉折後面。"}, {"n": 37, "qtype": "單選", "stem": "依據甲文，乙文 ＿＿ 內關於「小康」的描述，何者不適合填入？", "options": {"A": "行事強調家人與他人親疏有別", "B": "以禮制儀則引導各種人際關係", "C": "視城郭為彼此隔閡而亟欲拆除", "D": "為維護利益而出現權術與爭鬥"}, "answer": "C", "explain": "空格要描述「無私關愛減弱」後小康社會的樣子，答案須和甲文相符。(C)不適合（本題答案）：甲文是「城郭溝池以為固」——小康社會把城牆護城河當成保護，正是要築起它，不是想拆掉。(A)適合：「各親其親，各子其子」，只親愛自己的家人，有親疏之別。(B)適合：「禮義以為紀，以正君臣，以篤父子……」，用禮規範人際關係。(D)適合：「貨力為己」「謀用是作，而兵由此起」，為私利而出現計謀和戰爭。", "skill": "「不適合」題逐一回原文找證據，找不到證據、甚至和原文相反的那一項就是答案。"}, {"n": 38, "qtype": "單選", "stem": "乙文認為，「大同」的展現來自儒家的一個預設，亦即甲文的「大道」。下列《論語》文句，何者最能說明這個預設？", "options": {"A": "君子泰而不驕", "B": "克己復禮為仁", "C": "名不正則言不順", "D": "博施於民而能濟眾"}, "answer": "D", "explain": "乙文說大同的預設是「無私的關愛精神：不只照顧家人，也照顧家庭外的人」。(D)正確：「廣泛地施恩給百姓，又能救助大眾」，正是把關愛推廣到所有人。(A)錯：講君子安詳舒泰而不驕傲，是個人修養。(B)錯：「克制自己、回歸禮」是以禮約束，比較接近小康「以禮為紀」，而乙文說大同不需要禮。(C)錯：講名分要正，偏重制度秩序，也屬小康一路。", "skill": "先把題目要的概念（無私關愛、照顧所有人）換成白話，再找意思最貼近的選項，不要被熟悉的名句吸引。"}], "difficulty": "中", "label": "107統測", "year": 107, "kind": "統測"}, {"id": "tc108-03", "exam": "tc108", "nums": [3], "form": "單題", "img": "img/tc108-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "赴湯蹈火，在所不辭", "translation": "就算跳進滾水、踩進烈火，也絕不推辭。這裡的「辭」是「推辭、拒絕」。", "keywords": [{"w": "辭", "m": "推辭、拒絕；言辭、文辭；告別"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列文句中的「辭」，何者與「赴湯蹈火，在所不辭」的「辭」意思不同？", "options": {"A": "臣死且不避，卮酒安足「辭」", "B": "於學無所遺，於「辭」無所假", "C": "梁使三反，孟嘗君固「辭」不往也", "D": "莫「辭」更坐彈一曲，為君翻作琵琶行"}, "answer": "B", "explain": "題目的「辭」是動詞「推辭」。(B)不同（本題答案）：「在學問上沒有遺漏，在文辭上不必借用別人」，「辭」和「學」對舉，是名詞「言辭、文辭」。(A)〈鴻門宴〉樊噲說「我死都不怕，一杯酒哪裡值得推辭」，是推辭。(C)〈馮諼客孟嘗君〉梁國使者來回三次，孟嘗君堅決推辭不去，是推辭。(D)白居易〈琵琶行〉「別推辭，再坐下彈一曲」，是推辭。", "skill": "看「辭」前後：前面有安、固、莫等副詞且後面沒接名詞，多為動詞「推辭」；和「學」「文」對舉時多為名詞「言辭」。"}], "difficulty": "易", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-08", "exam": "tc108", "nums": [8], "form": "單題", "img": "img/tc108-08.png", "source": "《論語》（選項）；逯耀東《且做神州袖手人》（題幹）", "author": "孔子及其弟子", "genre": "經典語錄", "types": ["文意推論", "句意理解"], "passage": "用之則行，舍之則藏", "translation": "被任用就出來施展抱負，不被任用就退隱藏身。", "keywords": [{"w": "用", "m": "任用"}, {"w": "舍", "m": "捨棄、不任用"}, {"w": "藏", "m": "退隱"}, {"w": "兼善", "m": "兼善天下，出仕救世"}, {"w": "獨善", "m": "獨善其身，退而修身"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下列選項，何者說明下文「在儒家價值體系中早有明確的分劃」？", "options": {"A": "用之則行，舍之則藏", "B": "君子喻於義，小人喻於利", "C": "見賢思齊焉，見不賢而內自省也", "D": "政者，正也。子帥以正，孰敢不正"}, "answer": "A", "explain": "下文說知識分子的「分劃」是「兼善或獨善」：要嘛進入政治一展抱負，要嘛遠離政治。(A)正確：《論語‧述而》「被任用就出來做事，不被任用就退隱」，一進一退，正好對應兼善與獨善。(B)錯：講君子懂得道義、小人只懂利益，是品格區分，不是出仕與退隱。(C)錯：講見到賢人要學習、見到不賢的人要反省，是自我修養。(D)錯：講為政者要先端正自己，才能帶領別人，是為政之道，沒有「退隱」這一面。", "skill": "題目給兩個對立選項（兼善／獨善）時，答案通常也是一組兩兩相對的句子（行／藏）。"}], "difficulty": "易", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-09", "exam": "tc108", "nums": [9], "form": "單題", "img": "img/tc108-09.png", "source": "方苞〈又書貨殖傳後〉", "author": "方苞", "genre": "說理議論", "types": ["文意推論", "句意理解"], "passage": "「義」即《易》之所謂「言有物」也，「法」即《易》之所謂「言有序」也。義以為經，而法緯之，然後為「成體之文」。", "translation": "「義」就是《易經》所說的「言之有物」（文章有內容），「法」就是《易經》所說的「言之有序」（文章有條理）。以內容為直線（經），以條理為橫線（緯），經緯交織，才成為完整的好文章。", "keywords": [{"w": "義", "m": "文章的內容、思想"}, {"w": "法", "m": "文章的寫作方法、結構"}, {"w": "言有物", "m": "說話寫文章有實在內容"}, {"w": "言有序", "m": "說話寫文章有條理次序"}, {"w": "經、緯", "m": "織布的直線與橫線，比喻兩者交織配合"}], "questions": [{"n": 9, "qtype": "單選", "stem": "若以「→」代表由因到果的關係，符合下文脈絡的示意圖為何？", "options": {"A": "（言有物、言有序）→成體之文", "B": "法→義→成體之文", "C": "法→言有物、義→言有序，兩者→成體之文", "D": "義→法、言有物→言有序，兩者→成體之文"}, "answer": "A", "explain": "先整理對應：義＝言有物（內容），法＝言有序（條理）；兩者像經線和緯線一樣交織，才「然後為成體之文」。所以是「言有物」與「言有序」一起導向「成體之文」，選(A)。(B)錯：把法和義排成先後因果，但文中兩者是並列交織，不是「法造成義」。(C)錯：把法配給言有物、義配給言有序，對應弄反了，而且「即」是「就是」，不是因果。(D)錯：「義→法」「言有物→言有序」都變成前因後果，與經緯並列的意思不合。", "skill": "「即」＝等於，不是因果箭頭；「經…緯…然後為…」才是「兩者合起來→結果」。畫圖題先標出哪些是等號、哪些是箭頭。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-10", "exam": "tc108", "nums": [10], "form": "單題", "img": "img/tc108-10.png", "source": "論蘇軾詞之詩二首（出處待查）", "author": "出處待查", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論"], "passage": "甲、雪堂繞枕大江東，入夢蛟龍氣未平。千載才流學豪放，心頭莊釋筆風霆。\n乙、捋青擣麨俗偏好，曲港圓荷儷亦工。莫道先生疏格律，行雲流水見高風。", "translation": "甲：蘇軾在黃州雪堂枕邊繞著「大江東去」的氣勢，夢中的蛟龍仍騰躍不平。千年來的才子都學他的豪放，他心中有莊子與佛家的思想，筆下如風雷一般。\n乙：「捋青擣麨」這類寫農村生活的通俗詞句他偏愛，「曲港圓荷」這類對偶工巧的句子也寫得很好。別說東坡先生不講究格律，他行雲流水的文字正見高尚風格。", "keywords": [{"w": "雪堂", "m": "蘇軾貶黃州時所築的居所"}, {"w": "大江東", "m": "指〈念奴嬌‧赤壁懷古〉「大江東去」"}, {"w": "莊釋", "m": "莊子（道家）與釋迦（佛家）"}, {"w": "風霆", "m": "風雷，形容筆力雄健"}, {"w": "捋青擣麨", "m": "摘取青麥、炒熟磨粉做乾糧，出自蘇軾農村詞"}, {"w": "儷", "m": "對偶"}, {"w": "疏格律", "m": "不講究音律規範"}], "questions": [{"n": 10, "qtype": "單選", "stem": "依據甲、乙兩首談論蘇軾詞的詩作，下列何者不符合論者對蘇軾詞的看法？", "options": {"A": "流露佛道思想", "B": "淺俗工麗兼具", "C": "多寫山水隱逸", "D": "開啟豪放詞風"}, "answer": "C", "explain": "逐項回詩中找證據。(C)不符合（本題答案）：兩首詩都沒有提到蘇詞多寫山水或隱居。(A)符合：甲詩「心頭莊釋」，莊子是道家、釋是佛家。(B)符合：乙詩「捋青擣麨俗偏好」是通俗，「曲港圓荷儷亦工」是對偶工麗。(D)符合：甲詩「千載才流學豪放」，後世才子都學他的豪放風格。", "skill": "「不符合」題就是找證據：能在原文指出對應詞的都刪掉，剩下找不到出處的就是答案。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-11", "exam": "tc108", "nums": [11], "form": "單題", "img": "img/tc108-11.png", "source": "綜合（題詠對聯）", "author": "", "genre": "其他", "types": ["文化常識", "典故出處"], "passage": "甲、困貶永州書八記　乙、道濟天下三朝相　丙、文留世間一醉翁　丁、忍看江雪坐孤翁", "translation": "甲：被貶到永州時寫下〈永州八記〉。乙：以道救濟天下，做了三朝宰相。丙：文章流傳世間的一位醉翁。丁：怎忍心看著江雪中獨坐的孤舟老翁。", "keywords": [{"w": "永州八記", "m": "柳宗元貶永州時所作八篇山水遊記"}, {"w": "江雪", "m": "柳宗元〈江雪〉「孤舟蓑笠翁，獨釣寒江雪」"}, {"w": "醉翁", "m": "歐陽脩自號醉翁，有〈醉翁亭記〉"}, {"w": "三朝相", "m": "歐陽脩歷仕仁宗、英宗、神宗三朝，官至參知政事"}], "questions": [{"n": 11, "qtype": "單選", "stem": "甲、乙、丙、丁分屬兩副題詠古代名人的對聯，依據「上下聯依序組合」與「人物事蹟」，下列組合何者正確？", "options": {"A": "詠柳宗元聯：甲＋丙；詠歐陽脩聯：乙＋丁", "B": "詠柳宗元聯：甲＋丁；詠歐陽脩聯：乙＋丙", "C": "詠柳宗元聯：乙＋丙；詠歐陽脩聯：甲＋丁", "D": "詠柳宗元聯：丁＋甲；詠歐陽脩聯：丙＋乙"}, "answer": "B", "explain": "先分人物：「永州八記」「江雪孤翁」都是柳宗元（甲、丁）；「醉翁」「三朝相」是歐陽脩（乙、丙）。再分上下聯：上聯末字仄聲、下聯末字平聲。甲「記」是仄聲、丁「翁」是平聲，所以柳聯是甲＋丁；乙「相」是仄聲、丙「翁」是平聲，所以歐聯是乙＋丙，選(B)。(A)把丙（醉翁）給了柳宗元、丁（江雪）給了歐陽脩，人物錯。(C)兩組人物全錯。(D)人物對了，但上下聯順序顛倒：丁、丙末字平聲應放下聯。", "skill": "對聯題兩步驟：先用典故分人物，再用「上仄下平」（看最後一字）排順序。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-14", "exam": "tc108", "nums": [14, 15], "form": "題組", "img": "img/tc108-14.png", "source": "歐陽脩《新五代史‧周臣傳》", "author": "歐陽脩", "genre": "說理議論", "types": ["主旨寓意", "寫作手法"], "passage": "治國譬之於奕，知其用而置得其處者勝，不知其用而置非其處者敗。敗者臨棋注目，終日而勞心；使善奕者視焉，為之易置其處則勝矣。勝者所用，敗者之棋也；興國所用，亡國之臣也。", "translation": "治理國家可以比喻成下棋：知道每顆棋子的作用、把它放在適當位置的人就會贏，不知道棋子的作用、放錯位置的人就會輸。輸的人盯著棋盤，整天費盡心思；如果讓會下棋的人來看，替他把棋子換個位置，就能贏了。贏家所用的，其實就是輸家的那些棋子；使國家興盛的人所任用的，也就是使國家滅亡的那些臣子。", "keywords": [{"w": "譬", "m": "比喻"}, {"w": "奕", "m": "同「弈」，下棋"}, {"w": "置得其處", "m": "放在適當的位置"}, {"w": "臨棋注目", "m": "對著棋盤專注凝視"}, {"w": "易置", "m": "更換位置"}], "questions": [{"n": 14, "qtype": "單選", "stem": "上文「治國譬之於奕」，旨在提醒執政者應：", "options": {"A": "心無二用", "B": "知人善任", "C": "恩威並用", "D": "樂天知命"}, "answer": "B", "explain": "下棋要「知其用而置得其處」——知道棋子的作用並放對位置；治國就是了解臣子的才能並放在對的職位。同一批人，用對了國家興、用錯了國家亡。(B)知人善任正確。就像同一支球隊換了懂排兵布陣的教練，戰績就完全不同。(A)錯：文中沒講專心。(C)錯：沒講賞罰。(D)錯：沒講安於天命。", "skill": "比喻題把喻體換回本體：棋子＝臣子、放對位置＝任用得當，答案就出來了。"}, {"n": 15, "qtype": "單選", "stem": "上文結尾：「勝者所用，敗者之棋也；興國所用，亡國之臣也」，前半以棋局為比喻，用來說明後半的政治之道。下列文句，何者也是以〔〕為比喻，用來說明【】的道理？", "options": {"A": "〔逝者如斯，而未嘗往也〕；【盈虛者如彼，而卒莫消長也】", "B": "〔懼滿溢，則思江海而下百川〕；【樂盤游，則思三驅以為度】", "C": "〔滄浪之水清兮，可以濯吾纓〕；【滄浪之水濁兮，可以濯吾足】", "D": "〔不臨深谿，不知地之厚也〕；【不聞先王之遺言，不知學問之大也】"}, "answer": "D", "explain": "要找「前半是比喻、後半是要說的道理」。(D)正確：《荀子‧勸學》不站到深谷邊，不知道地有多厚（比喻）；不聽古代聖王留下的言論，不知道學問有多廣大（道理）。(A)錯：蘇軾〈赤壁賦〉前半講水、後半講月，兩句都是自然景象並列，不是一喻一理。(B)錯：魏徵〈諫太宗十思疏〉兩句都是直接勸諫君王的道理（怕驕滿就想江海居下、喜歡打獵就想三驅之禮），是並列的勸告。(C)錯：〈漁父〉歌兩句都是水的比喻，並列對照，後半不是道理本身。", "skill": "檢查兩半句的性質：一半是具體事物、一半是抽象道理，才是「以前喻後」；兩半都具體或都抽象，就是並列。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-16", "exam": "tc108", "nums": [16, 17], "form": "題組", "img": "img/tc108-16.png", "source": "甲：《史記‧管晏列傳》；乙：《莊子‧徐無鬼》", "author": "司馬遷；莊子", "genre": "史傳人物", "types": ["句意理解", "文意推論", "比較閱讀"], "passage": "【甲】管仲夷吾者，潁上人也。少時常與鮑叔牙游，鮑叔知其賢。管仲貧困，常欺鮑叔，鮑叔終善遇之，不以為言。已而鮑叔事齊公子小白，管仲事公子糾。及小白立為桓公，公子糾死，管仲囚焉。鮑叔遂進管仲。\n【乙】管仲有病，桓公問之，曰：「仲父之病病矣，可不諱云，至於大病，則寡人惡乎屬國而可？」管仲曰：「公誰欲與？」公曰：「鮑叔牙。」曰：「不可。其為人絜廉善士也，其於不己若者不比之，又一聞人之過，終身不忘。使之治國，上且鉤乎君，下且逆乎民。其得罪於君也，將弗久矣。」", "translation": "【甲】管仲名夷吾，是潁上人。年輕時常和鮑叔牙往來，鮑叔知道他有才能。管仲家貧，常占鮑叔的便宜，鮑叔始終善待他，不拿這些事說嘴。後來鮑叔侍奉齊國公子小白，管仲侍奉公子糾。等到小白即位為齊桓公，公子糾被殺，管仲被囚禁。鮑叔就向桓公推薦管仲。\n【乙】管仲生病，桓公去探望，說：「仲父的病很重了，不必避諱地說，萬一病危，我要把國家託付給誰才好？」管仲說：「您想交給誰？」桓公說：「鮑叔牙。」管仲說：「不行。他為人清廉正直，是個好人，但是對不如自己的人不願親近，又一聽說別人的過錯，一輩子都忘不了。讓他治理國家，對上會違逆國君，對下會違逆百姓。他得罪國君，恐怕要不了多久。」", "keywords": [{"w": "游", "m": "交往"}, {"w": "欺", "m": "占便宜"}, {"w": "不以為言", "m": "不拿這件事說話"}, {"w": "進", "m": "推薦"}, {"w": "病病", "m": "病得很重"}, {"w": "不諱", "m": "不避諱，指死亡"}, {"w": "惡乎", "m": "於何、向誰"}, {"w": "屬", "m": "託付"}, {"w": "絜廉", "m": "清白廉潔"}, {"w": "不己若者", "m": "不如自己的人"}, {"w": "比", "m": "親近"}, {"w": "鉤", "m": "違逆"}], "questions": [{"n": 16, "qtype": "單選", "stem": "依據乙文，管仲不推薦鮑叔牙，是因他認為鮑叔牙：", "options": {"A": "不喜歡能力比自己差的，又對別人犯錯十分介意", "B": "不喜歡能力比自己差的，又對自己犯錯十分介意", "C": "不喜歡能力比自己好的，又對別人犯錯十分介意", "D": "不喜歡能力比自己好的，又對自己犯錯十分介意"}, "answer": "A", "explain": "關鍵兩句：「其於不己若者不比之」——「不己若」是「不若己」（賓語前置），不如自己的人，他不親近；「一聞人之過，終身不忘」——聽到「別人」的過錯一輩子記著。兩點合起來就是(A)。(B)(D)錯：是「人之過」，別人的錯，不是自己的錯。(C)(D)錯：是看不起比自己差的人，不是嫉妒比自己好的人。像職場上要求很高、眼裡揉不得沙子的主管，人很正直，卻不適合帶整個團隊。", "skill": "遇到「不己若」「莫之知」這種否定句代詞前置，先還原成「不若己」「莫知之」再翻譯。"}, {"n": 17, "qtype": "單選", "stem": "依據甲、乙二文，能否支持下列①、②兩項推論？①齊桓公頗器重鮑叔牙，故聽其言用管仲，也想選他繼管仲為相。②鮑叔牙與管仲昔日有好交情，但同朝為官後，兩人便漸行漸遠。", "options": {"A": "①能支持；②能支持", "B": "①能支持；②不能支持", "C": "①不能支持；②能支持", "D": "①不能支持；②不能支持"}, "answer": "B", "explain": "①能支持：甲文「鮑叔遂進管仲」，桓公聽了推薦而用管仲；乙文桓公問接班人時第一個就說「鮑叔牙」，可見他器重鮑叔。②不能支持：管仲不推薦鮑叔，是因為鮑叔個性不適合治國，而且說得很中肯，反而像是保護老友不得罪國君；兩文都沒有寫兩人關係變差。所以是①√②X，選(B)。(A)錯在②。(C)(D)錯在①。", "skill": "推論題要找「文中證據」：有事件直接撐得起的才算支持；只是自己腦補的人際變化不算。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-24", "exam": "tc108", "nums": [24, 25, 26], "form": "題組", "img": "img/tc108-24.png", "source": "甲：連橫〈臺灣通史序〉；乙：連橫《雅堂文集》", "author": "連橫", "genre": "書信序跋", "types": ["文意推論", "比較閱讀", "寫作手法"], "passage": "【甲】舊志誤謬，文采不彰，其所記載，僅隸有清一朝，荷人、鄭氏之事，闕而弗錄，竟以島夷、海寇視之。烏乎！此非舊史氏之罪歟？且府志重修於乾隆二十九年，臺、鳳、彰、淡諸志，雖有續修，侷促一隅，無關全局，而書又已舊。苟欲以二三陳編而知臺灣大勢，是猶以管窺天，以蠡測海，其被囿也亦巨矣。\n【乙】《閩海紀要》為清代禁書，而鄭氏之信史也，故余喜而刊之。某君讀後語人曰：「此書所載，多與臺灣府志不同，雅堂校刊時，何不改之？」余曰：「此書之價值正與臺灣府志不同。夫府志為清代官書，其載鄭氏辭多誣蔑，而此為私人著作，據事直書，藏之名山，傳之其人，此其所以可寶也。」余謂讀史當多讀野史，考證異同，辨析是非，方不為官書所囿。", "translation": "【甲】舊的方志錯誤很多，文辭也不好，記載的內容只屬於清朝一代，荷蘭人、鄭氏的事蹟都缺漏不記，竟然把他們當成島上蠻夷、海上盜寇看待。唉！這難道不是過去修史者的罪過嗎？而且府志在乾隆二十九年重修後，臺灣、鳳山、彰化、淡水各縣廳志雖然有續修，卻只侷限一個地方，與全局無關，而且書也已經老舊。如果想憑兩三本舊書了解臺灣整體情勢，就像從竹管看天、用瓢量海，被限制的範圍也太大了。\n【乙】《閩海紀要》是清代的禁書，卻是記載鄭氏的可信史書，所以我很高興地把它刊印出來。有人讀後對別人說：「這書記載的多和臺灣府志不同，雅堂校印時為什麼不改正？」我說：「這本書的價值正在於和臺灣府志不同。府志是清朝官府編修的書，記載鄭氏的文字多是誣衊，而這是私人著作，依照事實直接記錄，藏在名山，傳給懂得的人，這就是它珍貴的地方。」我認為讀史應該多讀野史，考證異同、分辨是非，才不會被官修史書所侷限。", "keywords": [{"w": "舊志", "m": "舊有的地方志"}, {"w": "隸", "m": "屬於"}, {"w": "闕而弗錄", "m": "缺漏不記載"}, {"w": "島夷、海寇", "m": "島上的蠻夷、海上的盜寇，對荷、鄭的貶稱"}, {"w": "侷促一隅", "m": "侷限在一個角落"}, {"w": "陳編", "m": "舊書"}, {"w": "以管窺天，以蠡測海", "m": "從竹管看天、用瓢測海，比喻見識狹窄"}, {"w": "囿", "m": "限制"}, {"w": "信史", "m": "記載可信的史書"}, {"w": "誣蔑", "m": "捏造事實毀謗"}, {"w": "據事直書", "m": "根據事實如實記載"}], "questions": [{"n": 24, "qtype": "單選", "stem": "作為《臺灣通史》的「作者自序」，甲文的寫作策略為何？", "options": {"A": "指出臺灣雖有歷朝「斷代史」卻無「通史」", "B": "檢討臺灣舊史書散佚的原因，呼籲保存歷史", "C": "回顧歷來的臺灣史書典範，希望能繼承傳統", "D": "以臺灣向來缺乏優質史書，凸顯該書的必要"}, "answer": "D", "explain": "甲文一路在批評舊志：錯誤多、文采差、只記清朝、把荷鄭當海寇、內容老舊又侷限一隅——言下之意「所以需要我這本《臺灣通史》」。(D)正確。就像新產品發表會先指出舊產品的缺點，再推出自己的解決方案。(A)錯：文中說舊志「僅隸有清一朝」，沒有說有「歷朝」斷代史。(B)錯：批評的是內容錯誤、缺漏，不是書籍散佚失傳。(C)錯：對舊志全是批評，沒有當成典範要繼承。", "skill": "序文策略題：看作者花篇幅在「讚美前人」還是「批評前人」，批評前人多半是為了凸顯自己書的價值。"}, {"n": 25, "qtype": "單選", "stem": "依據甲、乙二文，何者符合作者的看法？", "options": {"A": "《閩海紀要》因扭曲鄭成功，遭官方查禁", "B": "清代臺灣僅府志數度續修，縣志皆未更新", "C": "清代臺灣官史固然立場偏頗，仍有其價值", "D": "凡官方正史皆不可信，唯有野史方為信史"}, "answer": "C", "explain": "(C)正確：連橫批評府志「載鄭氏辭多誣蔑」（立場偏頗），但他主張「考證異同，辨析是非」——要拿官書和野史互相比對，可見官書仍有參考價值，他也是用舊志的不足來寫新書。(A)錯：《閩海紀要》是「鄭氏之信史」，記載可信，被禁是因為不合清朝立場，不是扭曲鄭成功。(B)錯：甲文說「臺、鳳、彰、淡諸志，雖有續修」，縣志也有續修。(D)錯：說法太絕對，作者只說讀史要「多讀野史」並比對，不是全盤否定官史。", "skill": "選項出現「凡、皆、唯、僅」這類絕對字眼要特別警覺，多半是過度推論。"}, {"n": 26, "qtype": "單選", "stem": "若撰述者背景必然影響史書敘寫的措辭、口吻，下列文句與「可能撰述者」的配對，何者最不適宜？", "options": {"A": "五月庚辰，明招討大將軍延平王晉封潮王國姓成功殂於東都──《閩海紀要》作者", "B": "我皇上好生如天，以普天之下皆吾赤子，奚忍獨遺？二十一年，特命靖海將軍施公率師討平，郡縣其地──《臺灣府志》纂修者", "C": "五十一年，林爽文之亂，縣內衙署被毀。五十三年，林逆平，遂移駐鹿仔港焉──《彰化縣志》纂修者", "D": "偽藩鄭克塽遣小船前來接引入港，偽侯劉國軒、偽伯馮錫範率領各文武官員到軍前迎接──《臺灣通史》連橫"}, "answer": "D", "explain": "從稱呼看立場。(D)最不適宜（本題答案）：稱鄭克塽為「偽藩」、劉國軒為「偽侯」，是清朝官府否定明鄭的口吻；連橫推崇鄭氏、批評舊志把鄭氏當海寇，不會這樣稱呼。(A)適宜：稱鄭成功「延平王」「潮王」、用「殂」，尊重鄭氏，符合「鄭氏之信史」。(B)適宜：「我皇上好生如天」歌頌清帝，正是清代官修府志口吻。(C)適宜：稱林爽文為「林逆」，是清代官修縣志立場。", "skill": "立場判讀看「稱謂」：偽、逆、寇是貶稱，王、殂、皇上是尊稱，對照撰述者的立場就能配對。"}], "difficulty": "難", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-27", "exam": "tc108", "nums": [27, 28, 29], "form": "題組", "img": "img/tc108-27.png", "source": "甲：諸葛亮〈出師表〉；乙：改寫自朱大渭、梁滿倉《一代軍師諸葛亮》", "author": "諸葛亮；朱大渭、梁滿倉", "genre": "書信序跋", "types": ["文意推論", "比較閱讀", "文化常識"], "passage": "【甲】先帝知臣謹慎，故臨崩寄臣以大事也。受命以來，夙夜憂勤，恐託付不效，以傷先帝之明。故五月渡瀘，深入不毛。今南方已定，兵甲已足，當獎率三軍，北定中原，庶竭駑鈍，攘除姦凶，興復漢室，還於舊都，此臣所以報先帝而忠陛下之職分也。至於斟酌損益，進盡忠言，則攸之、褘、允之任也。願陛下託臣以討賊興復之效；不效，則治臣之罪，以告先帝之靈。若無興德之言，則責攸之、褘、允等之慢，以彰其咎。\n（乙文所引諸葛亮致孫權信）曹賊篡逆，蔓延及今，皆思巢滅，未遂同盟。亮受昭烈皇帝寄託之重，敢不竭力盡忠。今大兵已會於祁山，狂寇將亡於渭水，伏望執事以同盟之義，命將北征，共靖中原，同匡漢室。", "translation": "【甲】先帝知道我做事謹慎，所以臨終前把國家大事託付給我。接受遺命以來，我日夜憂慮勤勞，怕託付的事做不好，損害先帝知人之明。所以五月渡過瀘水，深入不毛之地。如今南方已經平定，兵器盔甲也已充足，應當激勵率領三軍，北上平定中原，希望竭盡我平庸的才能，剷除奸惡的敵人，復興漢室，回到舊都，這是我報答先帝、效忠陛下的本分。至於衡量政事的得失、進獻忠言，那是郭攸之、費褘、董允的責任。希望陛下把討伐曹賊、復興漢室的任務交給我；如果沒有成效，就治我的罪，來稟告先帝在天之靈。如果沒有發揚聖德的建言，就責罰郭攸之、費褘、董允等人的怠慢，來公開他們的過失。\n（信）曹賊篡位叛逆，一直延續到今天，大家都想把他們連窩剷除，只是還沒能結成同盟。我承受昭烈皇帝的重大託付，怎敢不盡力盡忠。現在大軍已經在祁山會合，狂妄的敵寇即將在渭水滅亡，懇切希望您本著同盟的情義，派將北征，一起平定中原，共同匡扶漢室。", "keywords": [{"w": "崩", "m": "帝王去世"}, {"w": "夙夜", "m": "早晚"}, {"w": "不效", "m": "沒有成效"}, {"w": "瀘", "m": "瀘水"}, {"w": "不毛", "m": "不長草木的荒地"}, {"w": "庶", "m": "希望"}, {"w": "駑鈍", "m": "劣馬與鈍刀，比喻才能平庸（謙詞）"}, {"w": "攘除", "m": "排除"}, {"w": "斟酌損益", "m": "衡量事情的利弊得失"}, {"w": "慢", "m": "怠慢"}, {"w": "咎", "m": "過失"}, {"w": "執事", "m": "對對方的敬稱，不直稱其人而稱其辦事者"}, {"w": "昭烈皇帝", "m": "劉備死後的諡號"}], "questions": [{"n": 27, "qtype": "單選", "stem": "依據甲、乙二文，「五月渡瀘」的主要目的為何？", "options": {"A": "打探曹丕逝後魏國敵情", "B": "引進水源改良貧瘠土地", "C": "運用焦土政策滅絕南中", "D": "取南中資源為北伐後盾"}, "answer": "D", "explain": "甲文「五月渡瀘，深入不毛。今南方已定……當獎率三軍，北定中原」；乙文說「思惟北伐，先宜入南」，平定南中後可「出其金銀、丹漆、耕牛、戰馬給軍國之用」，還把南中勁卒編成「飛軍」。可見南征是為北伐準備後方資源，選(D)。像企業要打新市場，先穩住後方的供應鏈。(A)錯：渡瀘是南征，不是去偵察北方的魏國。(B)錯：文中沒有改良土地的事。(C)錯：乙文強調避免「激起民族仇恨」，與焦土滅絕相反。", "skill": "問「目的」時，把事件放進前後文的因果鏈：前面做了什麼→後面要達成什麼，答案就在箭頭後面。"}, {"n": 28, "qtype": "單選", "stem": "比較甲文與乙文「諸葛亮約孫權出兵的信」，下列敘述何者正確？", "options": {"A": "二者均對蜀、吳長期未能結盟深表惋惜", "B": "二者均提及不負寄託的使命感與匡復漢室的目標", "C": "信寫於劉備在位時，故稱劉備「昭烈皇帝」而非「先帝」", "D": "甲文的「駑鈍」表示謙抑；信中的「執事」則有要對方讓步之意"}, "answer": "B", "explain": "(B)正確：〈出師表〉「恐託付不效」「興復漢室」，信中「亮受昭烈皇帝寄託之重，敢不竭力盡忠」「同匡漢室」，兩者都有受託的使命感與復興漢室的目標。(A)錯：「未遂同盟」只出現在信中，〈出師表〉沒提吳國。(C)錯：「昭烈」是劉備死後的諡號，信寫於建興五年、劉備已死；對外國君主稱諡號，對自家皇帝稱「先帝」，是場合不同。(D)錯：「執事」是不敢直呼對方、改稱其辦事人員的敬稱，表示尊敬，不是要對方讓步。", "skill": "看到帝王稱號要先分清「生前／死後」：諡號（昭烈、文、武）一定是死後才有的。"}, {"n": 29, "qtype": "單選", "stem": "乙文「＿＿」內，最適合填入的甲文文句為何？", "options": {"A": "當獎率三軍，北定中原", "B": "先帝知臣謹慎，故臨崩寄臣以大事也", "C": "若無興德之言，則責攸之、褘、允等之慢", "D": "願陛下託臣以討賊興復之效；不效，則治臣之罪"}, "answer": "C", "explain": "空格前說諸葛亮擔心「劉禪平庸，剛培養的人才未曾獨挑大樑」，所以「妥善安排人事」；空格後說「期望劉禪能因律臣以賢而勵己親賢」——要用賢臣督促劉禪。(C)正確：要求郭攸之、費褘、董允盡責進言，否則就追究他們，正是安排人事、以賢臣規範朝政。(A)錯：講北伐目標，不是安排後方人事。(B)錯：講先帝託付的由來，與人事安排無關。(D)錯：講的是諸葛亮自己的責任，不是安排賢臣。", "skill": "填空題看空格前後兩端的關鍵詞（安排人事、律臣以賢），選項必須同時接得上前因與後果。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-30", "exam": "tc108", "nums": [30, 31, 32], "form": "題組", "img": "img/tc108-30.png", "source": "劉基《郁離子》", "author": "劉基", "genre": "寓言故事", "types": ["句意理解", "文意推論", "主旨寓意"], "passage": "蜀賈三人，皆賣藥於市。其一人專取良；計入以為出，不虛價，亦不過取贏；一人良不良皆取焉，其價之賤貴，惟買者之欲，而隨以其良不良應之；一人不取良，惟其多，賣則賤其價，請益則益之不較，於是爭趨之，其門之限，月一易，歲餘而大富。其兼取者趨稍緩，再期亦富。其專取良者，肆日中如宵，旦食而昏不足。", "translation": "蜀地有三個商人，都在市場上賣藥。第一個只進好藥，按進貨成本來定售價，不亂開價，也不賺太多；第二個好藥壞藥都進，價錢高低隨顧客想要的，再依價錢給好藥或壞藥；第三個不進好藥，只求量多，賣得很便宜，顧客要求多給一點就多給，不計較，於是大家搶著到他店裡買，他家的門檻一個月就要換一次，一年多就發了大財。好壞兼賣的那位，顧客稍微少一點，兩年後也富了。只賣好藥的那位，店裡大白天也像夜晚一樣冷清，早上吃了晚上就沒得吃。", "keywords": [{"w": "賈", "m": "商人"}, {"w": "良", "m": "好的藥材"}, {"w": "計入以為出", "m": "根據進貨成本決定售價"}, {"w": "虛價", "m": "虛報價格"}, {"w": "取贏", "m": "賺取利潤"}, {"w": "請益", "m": "要求多給一些"}, {"w": "較", "m": "計較"}, {"w": "限", "m": "門檻"}, {"w": "再期", "m": "兩年"}, {"w": "肆", "m": "店鋪"}, {"w": "旦食而昏不足", "m": "早餐有得吃，晚餐就不夠了，形容窮困"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依據上文，「惟買者之欲，而隨以其良不良應之」的意思為何？", "options": {"A": "讓買家隨意挑選，再依據買家的態度好壞決定價格", "B": "由買家隨意喊價，再隨機拿出優劣不一的產品敷衍", "C": "看買家願意花多少錢，再提供合乎價格條件的產品", "D": "請買家說明產品需求，再看自己能不能接這項訂單"}, "answer": "C", "explain": "這句前面是「其價之賤貴」——價錢的高低由顧客決定（惟買者之欲），然後依價錢「以其良不良應之」：出高價給好藥，出低價給差藥。(C)「看買家願意花多少，再給相應等級的產品」正確，就像餐廳有平價套餐也有高價套餐，一分錢一分貨。(A)錯：不是看態度好壞。(B)錯：不是「隨機」敷衍，而是依價錢對應良窳。(D)錯：沒有挑訂單的意思。", "skill": "翻譯長句先找它修飾的主語（其價之賤貴），再把「惟…之欲」「以…應之」逐段還原。"}, {"n": 31, "qtype": "單選", "stem": "依據上文，最符合第三個賣藥者的敘述為何？", "options": {"A": "耐心回答消費者的各種疑問", "B": "掌握群眾愛買便宜貨的心理", "C": "高價販售劣質商品牟取暴利", "D": "大量進貨壓低上等藥材成本"}, "answer": "B", "explain": "第三人「不取良，惟其多，賣則賤其價，請益則益之不較」——不賣好藥、量多價低，多要就多給，結果「爭趨之」「大富」，正是抓住大家愛便宜的心理，選(B)。(A)錯：文中沒寫他回答問題。(C)錯：他是「賤其價」低價賣，不是高價。(D)錯：他「不取良」，根本不進上等藥材。", "skill": "人物題把文中動作逐一對應選項的「價格、品質、手段」三要素，錯一個就刪。"}, {"n": 32, "qtype": "單選", "stem": "小資現階段想買間低價的房子，屋況較差沒關係，未來存夠了錢，再換購優質好屋。若上文三個賣藥者的銷售型態，依序即是甲、乙、丙三個房仲公司的銷售型態，下列建議，何者最不適合小資？", "options": {"A": "現階段可從乙、丙兩公司找物件", "B": "無論現階段或未來，都可從乙公司找物件", "C": "現階段應從甲公司找物件，未來可從乙公司找物件", "D": "現階段應從丙公司找物件，未來可從甲公司找物件"}, "answer": "C", "explain": "先對應：甲＝只賣好貨、價格實在（好但不便宜）；乙＝好壞都有，依預算給貨；丙＝只有便宜差貨。小資現在要「低價、屋況差沒關係」→乙、丙；未來要「優質好屋」→甲、乙。(C)最不適合（本題答案）：現在去只賣優質物件的甲找低價房，不合需求。(A)適合：乙、丙都有便宜物件。(B)適合：乙依預算提供，現在買便宜的、將來買好的都行。(D)適合：現在找丙便宜，未來找甲優質。", "skill": "生活應用題先做「對照表」：每一方提供什麼、需求方各階段要什麼，再逐項打勾。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-35", "exam": "tc108", "nums": [35], "form": "單題", "img": "img/tc108-35.png", "source": "蘇軾〈飲湖上初晴後雨〉、張岱〈湖心亭看雪〉（題幹引文）", "author": "蘇軾；張岱", "genre": "古典詩詞曲", "types": ["典故出處", "文化常識"], "passage": "①水光瀲灩晴方好，山色空濛雨亦奇。欲把西湖比西子，淡妝濃抹總相宜。\n②崇禎五年十二月，余住西湖。大雪三日，湖中人鳥聲俱絕。是日更定矣，余拏一小舟，擁毳衣爐火，獨往湖心亭看雪。", "translation": "①晴天時湖水波光閃動，正是美好；雨天時山色朦朧，也很奇妙。如果把西湖比作美女西施，不論淡妝或濃妝都很合適。\n②崇禎五年十二月，我住在西湖。大雪下了三天，湖上人聲鳥聲全都消失。這天初更時分，我划著一艘小船，裹著皮衣、帶著火爐，獨自前往湖心亭看雪。", "keywords": [{"w": "瀲灩", "m": "水波閃動的樣子"}, {"w": "空濛", "m": "迷茫朦朧"}, {"w": "西子", "m": "西施"}, {"w": "更定", "m": "初更時分，晚上八點左右"}, {"w": "拏", "m": "划（船）"}, {"w": "毳衣", "m": "皮毛做的衣服"}], "questions": [{"n": 35, "qtype": "單選", "stem": "上文提到：「景點是被塑造出來的，透過詩文不斷建構美感」。下列蘇軾與張岱的詩文，最可能與哪一篇文章共同建構景點美感？", "options": {"A": "王羲之〈蘭亭集序〉", "B": "柳宗元〈始得西山宴遊記〉", "C": "范仲淹〈岳陽樓記〉", "D": "袁宏道〈晚遊六橋待月記〉"}, "answer": "D", "explain": "兩段引文都寫「西湖」：蘇軾把西湖比西子，張岱在西湖湖心亭看雪。要找同樣寫西湖的文章。(D)正確：袁宏道〈晚遊六橋待月記〉寫西湖的斷橋、蘇堤、六橋。(A)錯：〈蘭亭集序〉寫會稽山陰的蘭亭。(B)錯：〈始得西山宴遊記〉寫永州西山。(C)錯：〈岳陽樓記〉寫湖南洞庭湖畔的岳陽樓。", "skill": "國學常識題：記住名篇對應的「地點」，看到西湖就想到蘇軾、張岱、袁宏道。"}], "difficulty": "易", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc108-36", "exam": "tc108", "nums": [36, 37, 38], "form": "題組", "img": "img/tc108-36.png", "source": "袁中道《遊居柿錄》", "author": "袁中道", "genre": "筆記小品", "types": ["文意推論", "主旨寓意", "人物情感"], "passage": "凡遊不能刻期，以江上多惡風也。是日，風日清和，遂同客往。過龔遴甫書舍，呼與同去。時吳生長統，從新安至，亦偕焉。登舟順流而下，頃之抵洲上。予立舟頭語曰：「此舟極有靈驗，往年初春遊此，得佳石者，一年百事皆如意。」於是舟人及稚子輩，皆踴躍而上，至洲覓石，各求奇者。凡得一枚，即以呈予。予大詫曰：「佳！汝今年必有好事。」其人喜，復往覓，以次呈予，為殿最，仍還之，而取其尤者。已而復謂之曰：「此中小石，止堪澄水，無大用，須得可用者。」復命尋求得數石，皆可作筆格，或可作鎮紙，或可作硯山者。大抵凡僮僕之巧慧者，必得佳石；其餘稍癡，所得者多頑陋無足取。舟人輩不知妍媸，各負數大石堪作砧者登舟。予大笑。", "translation": "凡是出遊都不能預先約定日期，因為江上常有大風。這天風和日麗，我就和客人一起去。經過龔遴甫的書房，叫他一起去。當時吳長統從新安來，也同行。上了船順流而下，不久到了沙洲。我站在船頭說：「這裡非常靈驗，以前初春來這裡玩，撿到好石頭的人，一整年事事如意。」於是船夫和小孩們都興奮地跳上岸，到沙洲找石頭，各自找奇特的。每撿到一塊，就拿來給我看。我故意大大驚嘆說：「好！你今年一定有好事。」那人很高興，又去找，依次拿來給我，我替他們評定高下，把石頭還給他們，而留下其中最好的。後來又對他們說：「這裡的小石頭只能用來沉澱淨水，沒什麼大用，要找能用的。」又叫他們去找，找到幾塊，都可以做筆架，或做鎮紙，或做硯山。大致上聰明靈巧的僮僕，一定找到好石頭；其他比較傻的，找到的多半粗劣不值得取。船夫們不懂美醜，各自背了幾塊可以當搗衣砧板的大石頭上船。我大笑。", "keywords": [{"w": "刻期", "m": "約定日期"}, {"w": "偕", "m": "一同"}, {"w": "詫", "m": "驚嘆"}, {"w": "殿最", "m": "評定優劣，殿為下等、最為上等"}, {"w": "尤者", "m": "特別好的"}, {"w": "止堪", "m": "只能"}, {"w": "筆格", "m": "筆架"}, {"w": "硯山", "m": "石製的山形硯台或筆架"}, {"w": "頑陋", "m": "粗劣"}, {"w": "妍媸", "m": "美與醜"}, {"w": "砧", "m": "搗衣、切物用的石板"}], "questions": [{"n": 36, "qtype": "單選", "stem": "請再次參閱前一題組的〈晚明古人瘋旅遊，竟還有炫耀文、套裝行程？〉，並研判袁中道這篇遊記所敘寫的經驗，符合前文指出的何種情況？", "options": {"A": "庶民以進香團為主要旅遊形式", "B": "士大夫想展現不同凡俗的品味", "C": "文人依據僮僕的見聞撰寫遊記", "D": "使用美觀畫舫與其他精緻工具"}, "answer": "B", "explain": "袁中道帶人去江洲找石頭，挑出可做筆格、鎮紙、硯山的雅石，又笑船夫「不知妍媸」只扛回當砧板的大石——文人懂得賞玩、凡夫只看實用，正是前文說士大夫要「展現不同凡俗的品味」，選(B)。(A)錯：這是文人與朋友出遊，不是進香團。(C)錯：作者親自出遊，僮僕只是幫忙撿石，遊記不是靠聽僮僕轉述杜撰。(D)錯：文中只說「登舟」，沒有強調畫舫或精緻器具。", "skill": "跨文本題：先把前文的幾個「情況」列成清單，再看這篇文章最突出的情節（雅石vs砧石）落在哪一項。"}, {"n": 37, "qtype": "單選", "stem": "下列關於這篇遊記「覓石」的敘述，何者正確？", "options": {"A": "作者認為虔誠祝禱必覓得佳石", "B": "眾人沿江搜羅並暗中私藏美石", "C": "眾人為求好運而棄小石取大石", "D": "作者因眾人協尋而得賞玩奇石"}, "answer": "D", "explain": "作者編了「此舟極有靈驗」的說法，引得大家熱心找石，再「取其尤者」並要他們找「可用者」，最後得到可做筆格、鎮紙、硯山的佳石——作者靠眾人幫忙而得到奇石，選(D)。就像主管用「抽獎」名義號召同事幫忙找資料，結果最好的成果都進了主管的報告。(A)錯：文中沒有祝禱，「靈驗」只是作者的說詞。(B)錯：大家撿到就「以呈予」，沒有私藏。(C)錯：要大家換找可用之石的是作者的要求，船夫背大石是因「不知妍媸」，不是為求好運。", "skill": "敘事題要分清楚「誰」做了什麼、為什麼：作者說的話不等於事實，可能是他的手段。"}, {"n": 38, "qtype": "單選", "stem": "這篇遊記以「作者大笑」結尾，意在寄託何種想法？", "options": {"A": "石有別趣，慧者方知", "B": "石無小大，必有所用", "C": "取石為砧，功虧一簣", "D": "點石成金，筆底生花"}, "answer": "A", "explain": "前一句說聰明的僮僕必得佳石，傻一點的撿到粗劣石頭，船夫「不知妍媸」扛回一堆可當砧板的大石——作者笑的是：石頭的雅趣，只有有慧眼的人才懂，選(A)。(B)錯：作者明說小石「無大用」，也看不上砧石，並不認為石頭都有用。(C)錯：船夫背回砧石，不是快成功卻失敗。(D)錯：「點石成金、筆底生花」講文才高妙，與賞石無關。", "skill": "結尾的「笑、嘆、泣」要回扣前一兩句的情節，看作者對誰、對什麼事產生這個反應。"}], "difficulty": "中", "label": "108統測", "year": 108, "kind": "統測"}, {"id": "tc109-02", "exam": "tc109", "nums": [2], "form": "單題", "img": "img/tc109-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "", "keywords": [{"w": "獨", "m": "老而無子；單獨"}, {"w": "小", "m": "小；輕視（意動）"}, {"w": "非", "m": "非議、責怪；不是"}, {"w": "自", "m": "從"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列各組文句「」內的詞，何者意義相同？", "options": {"A": "矜寡孤「獨」廢疾者皆有所養／右旁巨石間，一穴「獨」大", "B": "山有「小」口，彷彿若有光／傅毅之於班固，伯仲之間耳，而固「小」之", "C": "當時士大夫家皆然，人不相「非」也／棄禮義，捐廉恥，「非」一朝一夕之故", "D": "蓋將「自」其變者而觀之，則天地曾不能以一瞬／顧「自」海通以來，西力東漸"}, "answer": "D", "explain": "(D)相同：〈赤壁賦〉「從變的角度來看」與連橫〈臺灣通史序〉「從海上交通開放以來」，「自」都是介詞「從」。(A)不同：〈禮運大同〉「獨」是名詞，老而無子的人；後句「一個洞特別大」，「獨」是副詞「特別、唯獨」。(B)不同：〈桃花源記〉「山上有個小洞口」，「小」是形容詞；〈典論論文〉「而班固卻輕視他」，「小之」是「以之為小」，動詞「輕視」。(C)不同：〈訓儉示康〉「人們不互相責怪」，「非」是動詞「非議」；顧炎武〈廉恥〉「不是一朝一夕造成的」，「非」是否定詞「不是」。", "skill": "一字多義比較：先判斷詞性（名詞、形容詞、動詞、副詞、介詞），詞性不同意思一定不同。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-04", "exam": "tc109", "nums": [4], "form": "單題", "img": "img/tc109-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "貴人過而見之，易之以百金", "translation": "有地位的人經過看見它，用一百金把它換走。", "keywords": [{"w": "易", "m": "交換、換取"}, {"w": "以", "m": "用（介詞）"}], "questions": [{"n": 4, "qtype": "單選", "stem": "「貴人過而見之，易之以百金」，「易之以百金」相當於「以百金易之」，但造句時，將「以百金」移到「易之」的後面。下列文句畫底線處，何者也採用相同造句方式？", "options": {"A": "醉則更相枕以臥，意有所極，夢亦同趣", "B": "俛仰之間，已為陳跡，猶不能不以之興懷", "C": "願陛下託臣以討賊興復之效，不效，則治臣之罪", "D": "史噤不敢發聲，趨而出，後常流涕述其事以語人"}, "answer": "C", "explain": "要找「以＋東西」被放到動詞後面的介詞片語後置。(C)正確：〈出師表〉「託臣以討賊興復之效」＝「以討賊興復之效託臣」，把討賊興復的任務交給我，「以…」移到「託臣」後面。(A)錯：〈始得西山宴遊記〉「更相枕以臥」的「以」是連詞，＝互相枕著而睡，不是介詞片語。(B)錯：〈蘭亭集序〉「以之興懷」，「以之」本來就在動詞「興懷」前面，是正常語序。(D)錯：〈左忠毅公軼事〉「述其事以語人」＝講述這件事來告訴別人，「以」是連詞（表目的），不是被移後的介詞片語。", "skill": "把「以…」搬到動詞前面試試看：搬過去意思不變、句子通順，就是介詞片語後置；搬不動的多半是連詞「以」。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-07", "exam": "tc109", "nums": [7], "form": "單題", "img": "img/tc109-07.png", "source": "綜合（經史典籍）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "語錄體", "m": "記錄言談對話，如《論語》"}, {"w": "編年體", "m": "依年月先後記事，如《左傳》"}, {"w": "紀傳體", "m": "以人物傳記為中心，如《史記》"}, {"w": "國別體", "m": "分國記事，如《戰國策》《國語》"}], "questions": [{"n": 7, "qtype": "單選", "stem": "王同學將甲～己六部典籍，填入按「作者」、「經書子書」、「史書」分類的交叉查詢表，其中位置正確的典籍為何？（表：經書子書／語錄體：甲《論語》〔集體作者〕、乙《荀子》〔單一具名作者〕；經書子書／專題論述：丙《孟子》〔集體作者〕；史書／編年體：丁《戰國策》〔集體作者〕；史書／紀傳體：戊《左傳》〔集體作者〕、己《史記》〔單一具名作者〕）", "options": {"A": "甲己", "B": "乙丙戊", "C": "甲丙丁己", "D": "乙丁戊己"}, "answer": "A", "explain": "逐格檢查。甲《論語》：孔子弟子及再傳弟子集體編成，記錄對話，是語錄體、集體作者——正確。乙《荀子》：大多一篇論一個主題（如〈勸學〉〈天論〉），是專題論述，不是語錄體——錯。丙《孟子》：多記孟子與人對話，屬語錄體，而且一般認為是孟子與弟子萬章等人所作，不應放在專題論述——錯。丁《戰國策》：分國記事，是國別體，不是編年體——錯。戊《左傳》：依魯國年代記事，是編年體，不是紀傳體——錯。己《史記》：司馬遷所作、以人物本紀列傳為主，是單一具名作者的紀傳體——正確。所以答案(A)甲己。", "skill": "國學常識表格題：每部書記三件事——作者是誰、體例是什麼、篇章怎麼組成，逐格對照就不會漏。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-08", "exam": "tc109", "nums": [8], "form": "單題", "img": "img/tc109-08.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文意推論", "句意理解"], "passage": "舉一隅不以三隅反，則不復也", "translation": "（《論語‧述而》）舉出一個角給他看，他不能類推出其他三個角，我就不再教他了。", "keywords": [{"w": "隅", "m": "角落"}, {"w": "反", "m": "類推、推想"}, {"w": "復", "m": "再（教）"}], "questions": [{"n": 8, "qtype": "單選", "stem": "依據下文，「＿＿」內應填入的文句為何？（響尾蛇靠頰窩偵測紅外線捕獵，武器專家由此發明響尾蛇飛彈。所以古人說：「＿＿」，就是期許學習者能主動發現知識類推的創新力量。）", "options": {"A": "聞道有先後，術業有專攻", "B": "舉一隅不以三隅反，則不復也", "C": "凡有四端於我者，知皆擴而充之矣", "D": "物各從其類也，是故質的張而弓矢至焉"}, "answer": "B", "explain": "空格後點明要的是「主動發現知識、類推創新」——從蛇的紅外線感應，推到飛彈的熱定位。(B)正確：《論語》「舉一隅不以三隅反，則不復也」，強調學習要能舉一反三。(A)錯：韓愈〈師說〉講聞道早晚與專業分工。(C)錯：《孟子》講把仁義禮智四種善端擴充，是道德修養。(D)錯：《荀子‧勸學》說箭靶一張開，弓箭就射過來，比喻同類相招、禍福自取，不是類推創新。", "skill": "填名句看空格後的「解釋句」：作者通常會用白話把名句的意思再說一次，直接對應即可。"}], "difficulty": "易", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-09", "exam": "tc109", "nums": [9], "form": "單題", "img": "img/tc109-09.png", "source": "趙璘《因話錄》（試卷未標出處）", "author": "趙璘", "genre": "筆記小品", "types": ["文意推論", "主旨寓意"], "passage": "郭子儀之子郭曖嘗與昇平公主琴瑟不調，曖罵公主：「倚乃父為天子耶？我父嫌天子不作。」公主恚啼，奔車奏之。上曰：「汝不知，他父實嫌天子不作。使不嫌，社稷豈汝家有也？」因泣下，但命公主還。尚父郭子儀拘曖，自詣朝待罪。上召而慰之曰：「諺云：『不癡不聾，不作阿家阿翁。』小兒女子閨幃之言，大臣安用聽？」錫賚以遣之。尚父杖曖數十而已。", "translation": "郭子儀的兒子郭曖曾經和昇平公主夫妻不和，郭曖罵公主：「仗著你父親是天子嗎？我父親是嫌天子不肯當。」公主又氣又哭，坐車奔回宮中向皇上告狀。皇上說：「你不知道，他父親確實是嫌天子而不當。假使他不嫌，天下難道會是你家的嗎？」說著流下眼淚，只叫公主回去。郭子儀把郭曖綁起來，親自到朝廷請罪。皇上召見他、安慰他說：「俗話說：『不裝傻不裝聾，當不了公公婆婆。』小兒女在閨房裡的話，大臣何必當真？」賞賜財物讓他回去。郭子儀只打了郭曖幾十棍而已。", "keywords": [{"w": "琴瑟不調", "m": "夫妻不和"}, {"w": "倚", "m": "倚仗"}, {"w": "乃父", "m": "你的父親"}, {"w": "恚", "m": "憤怒"}, {"w": "奏", "m": "向皇帝報告"}, {"w": "社稷", "m": "國家"}, {"w": "拘", "m": "捆綁"}, {"w": "詣", "m": "前往"}, {"w": "待罪", "m": "等候治罪"}, {"w": "阿家阿翁", "m": "婆婆與公公，泛指長輩"}, {"w": "閨幃", "m": "閨房"}, {"w": "錫賚", "m": "賞賜"}], "questions": [{"n": 9, "qtype": "單選", "stem": "大唐《朱雀時報》要刊載一則皇室軼聞，暫擬下列①、②、③、④為可能的標題文句，則最能概括全文的標題文句組合應是：①駙馬仗勢謀篡　②天子促公主入宮還家　③駙馬莽言惹禍　④親家翁以高智慧化解", "options": {"A": "①＋②", "B": "①＋④", "C": "③＋②", "D": "③＋④"}, "answer": "D", "explain": "故事兩段：前段郭曖口不擇言說「我父嫌天子不作」，惹得公主哭著去告狀（③駙馬莽言惹禍）；後段皇上（郭家的親家翁）用「不癡不聾，不作阿家阿翁」化解，還安慰賞賜郭子儀（④親家翁以高智慧化解）。所以③＋④最能概括，選(D)。①錯：郭曖只是夫妻吵架說氣話，沒有要篡位的行動。②錯：公主是自己「奔車奏之」回宮，皇上反而「命公主還」叫她回夫家，不是皇上催她入宮。就像公司裡兩位主管的子女吵架，聰明的長輩會裝作沒聽到，不讓小事變大事。", "skill": "下標題題：把故事切成「起因」與「結果」兩段，各選一個最準確的標題；用詞太重（謀篡）的通常是陷阱。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-10", "exam": "tc109", "nums": [10], "form": "單題", "img": "img/tc109-10.png", "source": "周必大論張良；朱熹論張良、諸葛亮（《朱子語類》）", "author": "周必大；朱熹", "genre": "說理議論", "types": ["文意推論", "比較閱讀"], "passage": "（周必大）張良之於高祖，蓋天授也。運籌帷幄姑置未問，鴻門之會，微項伯以良故，背其主而翼蔽沛公，則沛公之肉不足以齒項莊之劍矣，尚敢望數百年血食哉？\n（朱熹）子房用智之過，有微近譎處，其小者如躡足之類，其大則扶漢以爲韓，而終身不以語人也。若武侯，即名義俱正，無所隱匿，其爲漢復讎之志，如青天白日，人人得而知之，有補於天下後世，非子房比也。", "translation": "（周必大）張良對漢高祖來說，大概是上天賜予的。在營帳中出謀劃策的功勞暫且不談，鴻門宴時，如果不是項伯因為張良的緣故，背叛自己的主人去掩護沛公，那麼沛公的肉還不夠項莊的劍砍，哪還能指望漢朝享受幾百年的祭祀呢？\n（朱熹）張良用智謀用得太過，有些地方近乎詭詐，小的像踩劉邦的腳暗示他之類，大的是幫助漢朝其實是為了替韓國報仇，卻一輩子不對人說。至於諸葛武侯，名分道義都很端正，沒有隱瞞，他為漢室復仇的志向，像青天白日一樣，人人都知道，對天下後世有幫助，不是張良能比的。", "keywords": [{"w": "天授", "m": "上天所賜"}, {"w": "運籌帷幄", "m": "在軍帳中籌畫策略"}, {"w": "微", "m": "如果沒有"}, {"w": "翼蔽", "m": "像鳥張翅一樣掩護"}, {"w": "齒", "m": "觸及、當作砍殺對象"}, {"w": "血食", "m": "享受祭祀，指國祚延續"}, {"w": "子房", "m": "張良的字"}, {"w": "譎", "m": "詭詐"}, {"w": "躡足", "m": "踩腳暗示，指張良踩劉邦的腳提醒他封韓信為齊王"}, {"w": "扶漢以為韓", "m": "輔佐漢朝其實是為了替韓國報仇"}, {"w": "武侯", "m": "諸葛亮，諡忠武侯"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下列張良與諸葛亮的對話，何者對他們所讀的文獻理解錯誤？", "options": {"A": "（張良）周必大認為，要不是我，劉邦可能死在鴻門宴了", "B": "（諸葛亮）而且若非項伯看在您的份上，怎肯出手幫劉邦呢", "C": "（張良）朱熹說，我智不及您，對漢朝的扶助也比不上韓信", "D": "（諸葛亮）感謝朱熹認同我表裡如一，不過他也了解您部分想法"}, "answer": "C", "explain": "(C)錯誤（本題答案）：朱熹說張良「用智之過」——是智謀用得太多、近乎詭詐，不是智不如諸葛亮；「扶漢以為韓」的「韓」是韓國（張良是韓國貴族後代，輔漢是為韓復仇），不是韓信。(A)正確：周必大說鴻門宴若沒有張良，沛公早死了。(B)正確：「微項伯以良故，背其主而翼蔽沛公」，項伯是因為張良才保護劉邦。(D)正確：朱熹說諸葛亮「名義俱正，無所隱匿」＝表裡如一；又點出張良「終身不以語人」的真正動機（為韓），等於說朱熹看穿了張良的部分心思。", "skill": "文言裡的單字人名、國名要小心：「韓」可能是國名也可能是人名，回到人物背景判斷。"}], "difficulty": "難", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-15", "exam": "tc109", "nums": [15, 16], "form": "題組", "img": "img/tc109-15.png", "source": "張岱《陶庵夢憶‧柳敬亭說書》", "author": "張岱", "genre": "筆記小品", "types": ["文意推論", "寫作手法"], "passage": "余聽其說〈景陽岡武松打虎〉白文，與本傳大異。其描寫刻畫，微入毫髮，然又找截乾淨，並不嘮叨。哱夬聲如巨鐘，說至筋節處，叱吒叫喊，洶洶崩屋。武松到店沽酒，店內無人，謈地一吼，店中空缸空甓，皆甕甕有聲。閒中著色，細微至此。主人必屏息靜坐，傾耳聽之。彼方掉舌，稍見下人呫嗶耳語，聽者欠伸有倦色，輒不言，故不得強。", "translation": "我聽他說〈景陽岡武松打虎〉的段子，和《水滸傳》原書很不一樣。他的描寫刻畫，細到毫髮，卻又剪裁得乾淨俐落，一點也不囉嗦。他的聲音像大鐘一樣響亮，說到緊要關頭，大聲吆喝叫喊，聲勢大得像房子要倒塌。說到武松到酒店買酒，店裡沒人，武松大吼一聲，店中的空缸空甕都嗡嗡作響。在閒筆處添加細節渲染，竟細緻到這種地步。主人一定要屏住氣息安靜坐好，側耳傾聽，他才肯說。他正在說的時候，只要看到底下有人低聲交談，或聽眾打呵欠、伸懶腰、露出疲倦的樣子，他就立刻不說了，所以不能勉強他。", "keywords": [{"w": "白文", "m": "說書時不唱只說的部分"}, {"w": "本傳", "m": "原書，指《水滸傳》"}, {"w": "找截", "m": "收束剪裁"}, {"w": "哱夬", "m": "聲音洪亮"}, {"w": "筋節處", "m": "緊要關鍵處"}, {"w": "謈", "m": "大喊"}, {"w": "甓", "m": "磚，此處指陶甕類器物"}, {"w": "閒中著色", "m": "在不重要處添加細節渲染"}, {"w": "掉舌", "m": "鼓動舌頭，指說書"}, {"w": "呫嗶", "m": "低聲說話"}, {"w": "欠伸", "m": "打呵欠、伸懶腰"}, {"w": "輒", "m": "就"}], "questions": [{"n": 15, "qtype": "單選", "stem": "依據上文，何者最符合說書人的「閒中著色」？", "options": {"A": "加入武松聲振酒缸的音效", "B": "加入武松毀屋砸店的動作", "C": "加入武松飲酒喝醉的情節", "D": "加入武松所在店家的道具"}, "answer": "A", "explain": "「閒中著色」緊接在「武松到店沽酒，店內無人，謈地一吼，店中空缸空甓，皆甕甕有聲」之後——買酒只是過場，說書人卻加了武松一吼、空缸嗡嗡響的聲音效果，選(A)。就像電影在平淡的過場畫面加入音效，讓觀眾更有臨場感。(B)錯：「洶洶崩屋」是形容說書人聲勢大，不是武松毀屋砸店。(C)錯：文中沒說武松喝醉。(D)錯：缸甓是用來表現聲音，不是另外加道具。", "skill": "遇到作者自己下的評語（閒中著色、細微至此），答案就在評語前一句的例子裡。"}, {"n": 16, "qtype": "單選", "stem": "若說書場合貼有觀眾注意事項，最符合上文所述的是：", "options": {"A": "請尊重演出者，表演進行中請勿干擾", "B": "若身體不適，請通知服務人員協助處理", "C": "本店不強收費用，若合您心意，請打賞鼓勵", "D": "請就聲音表現提供改善建議，我們定虛心接受"}, "answer": "A", "explain": "文末說：主人要屏息靜坐、傾耳而聽；只要有人低聲交談或打呵欠，柳敬亭就不說了，「故不得強」。可見他要求觀眾專心、不得干擾，選(A)。(B)錯：「欠伸有倦色」是指觀眾不專心，不是身體不適。(C)錯：文中沒提收費。(D)錯：他對聽眾要求嚴格，沒有要徵求建議。", "skill": "把文言情境轉成現代告示，先找人物最在意、會立刻反應的那件事。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-17", "exam": "tc109", "nums": [17, 18, 19], "form": "題組", "img": "img/tc109-17.png", "source": "周密《癸辛雜識》", "author": "周密", "genre": "筆記小品", "types": ["字詞解釋", "文意推論", "人物情感"], "passage": "華亭縣市中有小常賣鋪，適有一物，如小桶而無底，非竹，非木，非金，非石，既不知其名，亦不知何用。如此者凡數年，未有過而睨之者。一日，有海舶老商見之，駭愕，且有喜色，撫弄不已。叩其所直，其人亦駔黠，意必有所用，漫索五百緡。商嘻笑償以三百，即取錢付駔。因叩曰：「此物我實不識，今已成交得錢，決無悔理，幸以告我。」商曰：「此至寶也，其名曰海井。尋常航海必須載淡水自隨，今但以大器滿貯海水，置此井於水中，汲之皆甘泉也。平生聞其名於番賈，而未嘗遇，今幸得之，吾事濟矣。」", "translation": "華亭縣市場裡有家賣雜貨的小鋪子，正好有一件東西，像沒有底的小桶，不是竹子、不是木頭、不是金屬、不是石頭，既不知道它叫什麼，也不知道做什麼用。就這樣擺了好幾年，沒有路過的人看它一眼。有一天，一位搭海船的老商人看到它，非常驚訝，而且面露喜色，拿在手上把玩不停。老商人問它價錢，店主也是個狡猾的商販，心想這東西一定有用，就隨口開價五百緡。老商人笑嘻嘻地還價三百，店主立刻拿了錢交貨。店主接著問：「這東西我真的不認識，現在已經成交拿到錢，絕對不會反悔，希望您告訴我。」老商人說：「這是最珍貴的寶物，名叫海井。平常航海一定要帶淡水隨行，現在只要用大容器裝滿海水，把這海井放進水裡，汲出來的都是甘甜的淡水。我一輩子聽外國商人說過它的名字，卻從來沒遇到，如今幸運得到，我的事業成功了。」", "keywords": [{"w": "常賣鋪", "m": "賣雜貨的店"}, {"w": "適", "m": "正好"}, {"w": "睨", "m": "斜眼看"}, {"w": "海舶", "m": "航海的大船"}, {"w": "駭愕", "m": "驚訝"}, {"w": "叩", "m": "詢問"}, {"w": "直", "m": "同「值」，價錢"}, {"w": "駔", "m": "商販"}, {"w": "黠", "m": "狡猾"}, {"w": "漫索", "m": "隨口索價"}, {"w": "緡", "m": "成串的錢，一千文為一緡"}, {"w": "償", "m": "付錢、還價"}, {"w": "幸", "m": "希望（敬辭）；幸運"}, {"w": "番賈", "m": "外國商人"}, {"w": "濟", "m": "成功"}], "questions": [{"n": 17, "qtype": "單選", "stem": "依據上文，對於甲、乙的研判應是：甲、「叩其所直」和「因叩曰」省略的主語，都是老商　乙、「幸以告我」和「今幸得之」的「幸」，意義相同", "options": {"A": "甲、乙皆正確", "B": "甲、乙皆錯誤", "C": "甲正確，乙錯誤", "D": "甲錯誤，乙正確"}, "answer": "B", "explain": "甲錯：「叩其所直」是老商問價錢；但「因叩曰：此物我實不識，今已成交得錢」——說「成交得錢」的是收錢的店主，所以「因叩曰」的主語是店主。乙錯：「幸以告我」的「幸」是「希望、請」（客氣地請求），「今幸得之」的「幸」是「幸運地」，意思不同。兩者都錯，選(B)。", "skill": "找省略主語：看話裡的內容是誰的立場（得錢的是賣方、付錢的是買方），就知道是誰說的。"}, {"n": 18, "qtype": "單選", "stem": "依據上文，下列解說何者正確？", "options": {"A": "以「未有過而睨之者」的神態，形容鋪主趾高氣昂", "B": "以「撫弄不已」的動作，表現老商尋獲失物的喜悅", "C": "以「意必有所用」，暗示鋪主動了提高售價的念頭", "D": "以「吾事濟矣」，表達老商對番賈提供飲水的感謝"}, "answer": "C", "explain": "(C)正確：鋪主看到老商又驚又喜、把玩不放，心想這東西一定有用處，於是「漫索五百緡」漫天開價——「意必有所用」正是他想抬價的念頭。像二手店老闆看到客人眼睛發亮，馬上就想加價。(A)錯：「沒有路過的人看它一眼」，是說這東西乏人問津，不是鋪主驕傲。(B)錯：老商只是「聞其名而未嘗遇」，第一次遇到，不是找回遺失的東西。(D)錯：「吾事濟矣」是說有了海井，自己的航海事業可以成功，不是感謝番賈。", "skill": "人物心理題：把心理句（意必有所用）和緊接的行動（漫索五百緡）連起來看，動機就清楚了。"}, {"n": 19, "qtype": "單選", "stem": "某公司擬從上文發想品牌故事，行銷與「海井」功能相似的產品。在右圖文案標題下，最可能出現的文字是：（文案標題：海井，曾流落在宋代雜貨鋪的一角／沒人知道，它穿越自未來）", "options": {"A": "攜帶型海水淡化裝置，每小時可生成40公升飲用水", "B": "獨家四層奈米過濾技術，澈底淨化水中病菌與重金屬", "C": "除蛋白機能吸附魚缸多餘雜質，是海水魚玩家的好隊友", "D": "礦物質智慧篩選科技，能去除水垢，保留有益的鈣、鎂"}, "answer": "A", "explain": "海井的功能：放進海水裡，「汲之皆甘泉」——把海水變成可喝的淡水，而且是航海時隨身用。(A)「攜帶型海水淡化裝置」完全符合。(B)錯：淨化病菌重金屬是一般淨水，不是把海水變淡水。(C)錯：是清潔魚缸，與飲水無關。(D)錯：去水垢、保留礦物質是處理自來水，也不是海水淡化。", "skill": "文創應用題：先用一句話說出原文物品的「功能本質」（海水→淡水），再找功能相同的現代產品。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-20", "exam": "tc109", "nums": [20, 21, 22], "form": "題組", "img": "img/tc109-20.png", "source": "甲：張達修〈新聞雜誌為文明利器社會木鐸說〉；乙：改寫自鍾樹人譯〈如何消滅網路假新聞〉", "author": "張達修；鍾樹人（譯）", "genre": "說理議論", "types": ["比較閱讀", "文意推論", "主旨寓意"], "passage": "時至今日，乃有操觚之徒，假新聞雜誌為機關，不知其使命為何若，惟日以粉飾昇平、藻繪外觀為能事，甚有行為齷齪，舞文弄墨，藉新聞雜誌為護身符，以攻訐人身，招人物議，至今日目為御用新聞、爛槽雜誌者，噫！若是者，是不特隕墮新聞雜誌之權威，且以迷惑文明社會之視聽。", "translation": "到了今天，竟有一些舞文弄墨的人，借用報紙雜誌當作工具，不知道它的使命是什麼，只是每天以粉飾太平、美化表面為本事，甚至有人行為卑劣，玩弄文字，把報紙雜誌當作護身符，用來攻擊別人的私事，招惹眾人議論，以致今天被人看作「御用新聞」「爛槽雜誌」。唉！像這樣的人，不只是讓報紙雜誌的權威墜落，而且還迷惑了文明社會的視聽。（乙文為白話，談網路假新聞與社群「同溫層」問題。）", "keywords": [{"w": "操觚之徒", "m": "執筆寫作的人，此指文人、記者"}, {"w": "假", "m": "借用"}, {"w": "機關", "m": "工具、手段"}, {"w": "粉飾昇平", "m": "掩飾問題，假裝太平"}, {"w": "藻繪", "m": "修飾、美化"}, {"w": "齷齪", "m": "卑劣"}, {"w": "攻訐", "m": "攻擊、揭人隱私"}, {"w": "物議", "m": "眾人的批評"}, {"w": "目", "m": "看待"}, {"w": "御用新聞", "m": "為當權者服務的報紙"}, {"w": "不特", "m": "不只"}, {"w": "隕墮", "m": "墜落"}], "questions": [{"n": 20, "qtype": "單選", "stem": "依據甲、乙二文，過去的「御用新聞」與今日的「假新聞」，有何共通點？", "options": {"A": "都由媒體創辦人藉權威所捏造", "B": "都利用讀者無從選擇進行欺騙", "C": "都為達到目的而散播不實言論", "D": "都結合商業廣告使新聞綜藝化"}, "answer": "C", "explain": "甲文：御用新聞「粉飾昇平、藻繪外觀」「攻訐人身」，是為討好當權或打擊他人而寫不實內容；乙文：假新聞是「點閱誘餌，藉此獲得廣告利益」，甚至「成為政黨惡鬥工具」。兩者都是為了某種目的散播不實訊息，選(C)。(A)錯：乙文的假新聞可能是「一群青少年架設的網站」，不一定是媒體創辦人。(B)錯：乙文說社群上讀者是「自己選擇」看誰的貼文，不是無從選擇。(D)錯：甲文沒提商業廣告，兩文也都沒談「綜藝化」。", "skill": "找兩文共通點：先各寫一句「它們為什麼做、做了什麼」，再取交集，不要選只在一篇出現的細節。"}, {"n": 21, "qtype": "單選", "stem": "依據乙文，「臉書的問題則糟糕一千倍」所指為何？", "options": {"A": "臉書不提供像翻閱報紙般的檢索功能", "B": "臉書對防止假新聞流竄向來沒有作為", "C": "臉書使用者無法分辨幽默和諷刺之別", "D": "臉書使用者容易落入氣味相投的窠臼"}, "answer": "D", "explain": "這句之後解釋：在社群媒體上你決定看誰的貼文，「不是選擇閱讀主題，而是選擇看新聞的角度——你正在建造自己的同溫層」。也就是只看到和自己想法相同的人，選(D)。(A)錯：問題不在檢索功能，而在只看同溫層的觀點。(B)錯：文中說臉書已謝絕假新聞廣告、考慮加註標示，並非沒有作為。(C)錯：讀者把諷刺文當真是另一段提到的現象，不是「糟糕一千倍」所指。", "skill": "解釋某句話「所指為何」，就看它後面緊跟的「換句話說」「也就是」那一句。"}, {"n": 22, "qtype": "單選", "stem": "對於讀者因媒體受到欺矇，下列敘述，何者符合上文的看法？", "options": {"A": "甲文歸咎於「假機關」，乙文歸咎於「同溫層」", "B": "甲文認為，媒體應自律，勿成為特定人士的工具", "C": "乙文認為，假新聞防不勝防，應由社群媒體過濾", "D": "甲、乙二文皆認為，讀者提升素養可消滅假新聞"}, "answer": "B", "explain": "(B)正確：甲文批評操觚之徒「假新聞雜誌為機關」，淪為御用新聞，讓新聞失去權威，言下之意是媒體應守住使命、不當特定人的工具。(A)錯：甲文的「假新聞雜誌為機關」是「借用報刊當工具」，「假」是借用，不是有個叫「假機關」的東西；而且甲文歸咎的是寫手。(C)錯：乙文明說「讓社群決定」根本無法過濾假新聞。(D)錯：兩文都沒談讀者素養，甲文更沒說能「消滅」。", "skill": "文言的「假」常是「借用」，看到「假○○為△△」先翻成「借○○當△△」。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-23", "exam": "tc109", "nums": [23, 24, 25], "form": "題組", "img": "img/tc109-23.png", "source": "乙：蘇轍〈東坡先生墓誌銘〉；甲：改寫自韓毅〈宋代政府應對疫病的歷史借鑒〉", "author": "蘇轍；韓毅", "genre": "史傳人物", "types": ["文意推論", "比較閱讀", "字詞解釋"], "passage": "明年方春，即減價糶常平米，民遂免大旱之苦。公又多作饘粥、藥劑，遣吏挾醫，分坊治病，活者甚眾。公曰：「杭，水陸之會，因疫病死比他處常多。」乃裒羨緡得二千，復發私橐得黃金五十兩，以作病坊，稍蓄錢糧以待之。", "translation": "第二年剛到春天，蘇軾就降價出售常平倉的米，百姓因此免於大旱的苦難。他又大量製作稀粥和藥劑，派官吏帶著醫生，分區替人治病，救活的人很多。蘇軾說：「杭州是水路陸路交會的地方，因瘟疫死的人常比別處多。」於是聚集公家盈餘的款項得到兩千緡，又拿出自己私人的錢袋得到黃金五十兩，用來設立病坊，並稍微儲存一些錢糧來因應。（甲文為白話，敘述宋代政府防疫措施；丙為傳染病簡介表。）", "keywords": [{"w": "糶", "m": "出售穀物"}, {"w": "常平米", "m": "常平倉的米，政府平抑米價的儲糧"}, {"w": "饘粥", "m": "稀飯"}, {"w": "挾", "m": "帶著"}, {"w": "坊", "m": "城中的街區"}, {"w": "會", "m": "交會處"}, {"w": "裒", "m": "聚集"}, {"w": "羨緡", "m": "盈餘款項"}, {"w": "私橐", "m": "私人的錢袋"}, {"w": "病坊", "m": "收治病人的地方"}], "questions": [{"n": 23, "qtype": "單選", "stem": "依據甲文，關於宋代防治傳染病的敘述，何者錯誤？", "options": {"A": "逐漸意識到公共衛生與疫病相關", "B": "翰林院醫官和太醫局多參與救治", "C": "加強邊境檢查以免疫病危及軍隊", "D": "透過隔離降低患者交互感染機率"}, "answer": "C", "explain": "(C)錯誤（本題答案）：甲文只說戰爭使「軍隊和邊境的疫病次數超越前代」，沒有提到加強邊境檢查。(A)正確：真德秀見溝渠淤塞「蒸為癘疫」而下令清理，可見已知環境衛生與疫病有關。(B)正確：「政府通常令翰林院醫官、太醫局派人巡診賜藥」。(D)正確：設病坊、安濟坊，「以病人輕重而異室處之，以防漸染」，就是隔離。", "skill": "「何者錯誤」先刪掉能在文中找到證據的，剩下那個常是「文中有相關字眼但沒說那件事」的選項。"}, {"n": 24, "qtype": "單選", "stem": "依據甲、乙二文，關於蘇軾在杭州賑災抗疫的措施，何者正確？", "options": {"A": "讓受災戶減免應繳米糧", "B": "以御賜丹藥治療重症者", "C": "向兩千人募得救濟善款", "D": "自掏腰包補充病坊資金"}, "answer": "D", "explain": "(D)正確：乙文「復發私橐得黃金五十兩，以作病坊」，拿出自己的錢設立病坊。(A)錯：「減價糶常平米」是降價賣米給百姓，不是減免百姓該繳的米。(B)錯：他自己「多作饘粥、藥劑」，甲文說用「聖散子」藥方，沒有御賜丹藥。(C)錯：「裒羨緡得二千」是聚集公家盈餘款項兩千緡，不是向兩千人募款。", "skill": "文言數字後面要看單位：「得二千」承接的是「羨緡」（錢），不是人數。"}, {"n": 25, "qtype": "單選", "stem": "依據丙表，甲文蘇軾面臨的「因乾旱而發生大疫」，最可能是何種傳染病？", "options": {"A": "傷寒、結核病", "B": "百日咳、結核病", "C": "傷寒、桿菌性痢疾", "D": "桿菌性痢疾、退伍軍人病"}, "answer": "C", "explain": "乾旱→缺乏乾淨水源、環境衛生變差。丙表中「多發生於缺乏乾淨水源或環境衛生較差的地區」的是傷寒和桿菌性痢疾，選(C)。(A)(B)錯：結核病靠飛沫空氣傳染，常見於同住家人，與乾旱無直接關係；百日咳四季都可能發生、多為幼兒。(D)錯：退伍軍人病與水塔、冷熱水系統有關，且無人傳人，不會造成滿城大疫。", "skill": "圖表配對題：先把題目情境轉成條件（乾旱＝缺乾淨水），再到表中找完全符合的列。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-26", "exam": "tc109", "nums": [26, 27, 28, 29], "form": "題組", "img": "img/tc109-26.png", "source": "甲：《楚辭‧漁父》；乙：《南史‧隱逸傳》", "author": "屈原（傳）；李延壽", "genre": "史傳人物", "types": ["比較閱讀", "文意推論", "人物情感", "典故出處"], "passage": "【甲】屈原曰：「舉世皆濁我獨清，眾人皆醉我獨醒，是以見放。」漁父曰：「聖人不凝滯於物，而能與世推移。世人皆濁，何不淈其泥而揚其波？眾人皆醉，何不餔其糟而歠其釃？何故深思高舉，自令放為？」屈原曰：「吾聞之，新沐者必彈冠，新浴者必振衣。安能以身之察察，受物之汶汶者乎？寧赴湘流，葬於江魚之腹中，安能以皓皓之白，而蒙世俗之塵埃乎？」漁父莞爾而笑，鼓枻而去，乃歌曰：「滄浪之水清兮，可以濯吾纓；滄浪之水濁兮，可以濯吾足。」遂去，不復與言。\n【乙】太康孫緬為尋陽太守，落日逍遙渚際，見一輕舟，陵波隱顯。俄而漁父至，神韻蕭灑，垂綸長嘯，緬甚異之。乃問：「有魚賣乎？」漁父笑而答曰：「其釣非釣，寧賣魚者邪？」緬益怪焉。遂褰裳涉水，謂曰：「竊觀先生，有道者也，終朝鼓枻，良亦勞止。吾聞黃金白璧，重利也；駟馬高蓋，榮勢也。今方王道文明，守在海外，隱鱗之士，靡然向風。子胡不贊緝熙之美，何晦用其若是也？」漁父曰：「僕山海狂人，不達世務，未辨賤貧，無論榮貴。」乃歌曰：「竹竿籊籊，河水浟浟。相忘為樂，貪餌吞鉤。非夷非惠，聊以忘憂。」於是悠然鼓棹而去。", "translation": "【甲】屈原說：「整個世界都汙濁，只有我清白；眾人都醉了，只有我清醒，所以被放逐。」漁父說：「聖人不拘泥於外物，能隨著世道變化。世人都汙濁，你為什麼不攪起泥水、揚起波浪（跟著同流）？眾人都醉了，你為什麼不也吃酒糟、喝薄酒？為什麼要想得那麼深、行為那麼清高，讓自己被放逐呢？」屈原說：「我聽說，剛洗過頭的人一定彈去帽子上的灰塵，剛洗過澡的人一定抖去衣服上的塵土。怎能讓潔白的身體，去沾染汙濁的東西呢？我寧可跳進湘江，葬身魚腹，怎能讓潔白的品格，蒙上世俗的塵埃呢？」漁父微微一笑，划著槳離開，唱道：「滄浪的水清啊，可以洗我的帽帶；滄浪的水濁啊，可以洗我的腳。」就走了，不再和他說話。\n【乙】太康人孫緬當尋陽太守時，傍晚在水邊散步，看見一艘小船在波浪上時隱時現。不久漁父靠近，神態瀟灑，垂著釣線長聲吟嘯，孫緬覺得很奇特。就問：「有魚賣嗎？」漁父笑著回答：「我釣魚不是為了釣魚，難道是賣魚的人嗎？」孫緬更覺奇怪，就提起衣服涉水過去，說：「我私下看先生是有道之人，整天划船，實在也很辛勞。我聽說黃金白璧是厚利，駟馬高車是榮耀權勢。如今王道清明，國威遠及海外，隱居的賢士都紛紛歸附。先生為什麼不出來輔佐光明的盛世，為什麼要這樣隱藏自己的才能呢？」漁父說：「我是山林湖海的狂放之人，不懂世事，分不清貧賤，更不談榮華富貴。」於是唱道：「竹竿細長，河水悠悠。彼此相忘才是快樂，貪吃魚餌就會吞下魚鉤。我不像伯夷那樣清高，也不像柳下惠那樣隨和，姑且藉此忘卻憂愁。」便悠閒地划船離去。", "keywords": [{"w": "見放", "m": "被放逐"}, {"w": "凝滯", "m": "拘泥"}, {"w": "與世推移", "m": "隨世道變化而調整"}, {"w": "淈", "m": "攪亂"}, {"w": "餔其糟", "m": "吃酒糟"}, {"w": "歠其釃", "m": "喝薄酒"}, {"w": "察察", "m": "潔白的樣子"}, {"w": "汶汶", "m": "汙濁的樣子"}, {"w": "莞爾", "m": "微笑的樣子"}, {"w": "鼓枻", "m": "划槳"}, {"w": "纓", "m": "帽帶"}, {"w": "陵波", "m": "乘著波浪"}, {"w": "綸", "m": "釣線"}, {"w": "褰", "m": "提起"}, {"w": "良亦勞止", "m": "實在也很辛勞"}, {"w": "隱鱗之士", "m": "隱居的人"}, {"w": "靡然向風", "m": "紛紛歸附"}, {"w": "緝熙", "m": "光明"}, {"w": "晦用", "m": "隱藏才能不用"}, {"w": "籊籊", "m": "細長的樣子"}, {"w": "夷、惠", "m": "伯夷、柳下惠"}], "questions": [{"n": 26, "qtype": "單選", "stem": "依據上文，下列敘述何者正確？", "options": {"A": "甲文屈原藉「彈冠、振衣」彰顯自己不役於物", "B": "乙文孫緬藉「黃金、駟馬」彰顯自己不慕榮利", "C": "甲文漁父所稱的「聖人」深明安時處順的意義", "D": "乙文漁父所稱的「狂人」實為己達達人的代表"}, "answer": "C", "explain": "(C)正確：漁父說「聖人不凝滯於物，而能與世推移」——不固執、隨時勢調整，就是安時處順。(A)錯：「新沐者必彈冠，新浴者必振衣」比喻潔身自好、不願被汙染，重點是堅持清白，不是「不被外物役使」。(B)錯：孫緬提黃金駟馬，是用利祿勸漁父出仕，正好相反。(D)錯：「山海狂人，不達世務」是自稱不問世事的隱士，只求自己逍遙，不是幫助別人成功的「己達達人」。", "skill": "先確認是誰說的話、說給誰聽、想達到什麼目的，就不會把勸說的話誤當成說話者自己的志向。"}, {"n": 27, "qtype": "單選", "stem": "依據上文，對於甲、乙的研判應是：甲、甲文「何不淈其泥而揚其波」，提問者是希望對方不要鳴琴垂拱　乙、乙文「何晦用其若是也」，提問者是勸對方不要無能卻彈鋏而歌", "options": {"A": "甲、乙皆正確", "B": "甲、乙皆錯誤", "C": "甲正確，乙錯誤", "D": "甲錯誤，乙正確"}, "answer": "B", "explain": "甲錯：漁父是希望屈原隨波逐流、不要太清高；「鳴琴垂拱」是宓子賤彈琴而治、無為而治的典故，和這裡無關。乙錯：孫緬是覺得漁父「有道」卻隱藏才能，勸他出來做官；「彈鋏而歌」是馮諼在孟嘗君門下彈劍抱怨待遇，和「無能」也扯不上，孫緬更沒有說漁父無能。兩者都錯，選(B)。", "skill": "研判題遇到陌生典故（鳴琴垂拱、彈鋏而歌），先想典故本身的意思，再和原文情境比對是否相符。"}, {"n": 28, "qtype": "單選", "stem": "關於甲、乙二文「歌曰」的解說，何者錯誤？", "options": {"A": "甲文「歌曰」，是漁父在屈原激昂表態後給予的委婉勸說", "B": "乙文「歌曰」，是漁父在孫緬拒絕妥協後給予的委婉勸說", "C": "甲文「歌曰」以「濯纓濯足」，寓托與世推移的處世之道", "D": "乙文「歌曰」以「貪餌吞鉤」，暗示重利榮勢的致命之險"}, "answer": "B", "explain": "(B)錯誤（本題答案）：乙文是孫緬勸漁父出仕，漁父不接受，才唱歌回絕；拒絕妥協的是漁父，不是孫緬，歌也不是在勸孫緬，而是表明自己不願被名利釣上鉤。(A)正確：屈原說寧死也不蒙塵，漁父笑著唱歌，用歌委婉勸他。(C)正確：水清就洗帽帶，水濁就洗腳，比喻順應時勢。(D)正確：「貪餌吞鉤」比喻貪圖名利就會被名利害死。", "skill": "兩文對照時，先畫出各自的「勸說者→被勸者」，再檢查選項有沒有把角色對調。"}, {"n": 29, "qtype": "單選", "stem": "自《楚辭》後，「漁父」一直是文學藝術作品中的典型人物。右圖是宋代馬遠〈秋江漁隱圖〉的漁父，其抱槳獨眠舟中的神態，寓托此典型人物的特質。這項特質，最適合徵引上文哪一文句形容？", "options": {"A": "深思高舉", "B": "寧赴湘流", "C": "靡然向風", "D": "不達世務"}, "answer": "D", "explain": "畫中漁父抱著槳在船上獨自睡覺，一派悠閒、不問世事。(D)「不達世務」——乙文漁父自稱不懂世事，最貼切。(A)錯：「深思高舉」是漁父批評屈原想太多、太清高，屬於屈原的特質。(B)錯：「寧赴湘流」是屈原寧死不屈的決心。(C)錯：「靡然向風」是孫緬說隱士紛紛出來歸附朝廷，與漁父隱逸相反。", "skill": "圖像配文句：先用一個形容詞描述畫中人物（悠閒、超脫），再刪去其實是在形容別人的句子。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc109-30", "exam": "tc109", "nums": [30, 31, 32], "form": "題組", "img": "img/tc109-30.png", "source": "綜合（唐詩、宋詞；歐陽炯〈花間集序〉）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析", "文意推論", "文化常識"], "passage": "綺筵公子，繡幌佳人，遞葉葉之花箋，文抽麗錦；舉纖纖之玉指，拍按香檀。不無清絶之辭，用助嬌嬈之態。", "translation": "（歐陽炯〈花間集序〉）華美宴席上的貴公子，繡花帷幕裡的美人，一張張遞出精美的紙箋，寫下如錦緞般華麗的文詞；美人舉起纖細的手指，打著檀木拍板唱歌。其中不乏清新絕妙的詞句，用來增添歌女嬌柔的姿態。", "keywords": [{"w": "綺筵", "m": "華美的宴席"}, {"w": "繡幌", "m": "繡花的帷幕"}, {"w": "花箋", "m": "精美的信紙、詩箋"}, {"w": "香檀", "m": "檀木製的拍板"}, {"w": "嬌嬈", "m": "嬌柔美好"}, {"w": "傷春、悲秋", "m": "因春去、秋來而感傷"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依上表的初步統計，最能支持下列哪一項假設？（表：《唐詩三百首》311首中含季節感懷120首：傷春44、悲秋49、其他27；《宋詞三百首》300首中含季節感懷173首：傷春111、悲秋50、其他12）", "options": {"A": "相較於詩，詞更多用於表達傷春之情", "B": "詩詞作者的感傷，多因慨歎歲月流逝", "C": "唐代詩人的作品，多半含有季節感懷", "D": "詞的讀者多為女性，故作品多寫傷春"}, "answer": "A", "explain": "(A)正確：唐詩傷春44首，宋詞傷春111首，總數接近（311對300），詞的傷春作品明顯多很多。(B)錯：表格「年老」等寫作題材還沒統計（都是「--」），無法支持。(C)錯：唐詩311首中只有120首含季節感懷，不到一半；而且樣本只是《唐詩三百首》，不能代表全部唐代詩人。(D)錯：表格沒有讀者性別的資料。", "skill": "數據推論題只能用表格裡「已經有」的數字；表上沒有的資料（題材、讀者）一律不能當證據。"}, {"n": 31, "qtype": "單選", "stem": "下列詩詞，何者最可能在上表中歸入「其他」門？", "options": {"A": "國破山河在，城春草木深。感時花濺淚，恨別鳥驚心。烽火連三月，家書抵萬金。白頭搔更短，渾欲不勝簪", "B": "十年離亂後，長大一相逢。問姓驚初見，稱名憶舊容。別來滄海事，語罷暮天鐘。明日巴陵道，秋山又幾重", "C": "綠蕪牆繞青苔院。中庭日淡芭蕉卷。蝴蝶上階飛。烘簾自在垂。玉鉤雙語燕。寶甃楊花轉。幾處簸錢聲。綠窗春睡輕", "D": "波面銅花冷不收。玉人垂釣理纖鉤。月明池閣夜來秋。江燕話歸成曉別，水花紅減似春休。西風梧井葉先愁"}, "answer": "C", "explain": "註2說「其他」包含「情境是春、秋，但不是悲傷情懷」的作品。(C)正確：陳克〈菩薩蠻〉寫春日庭院，蝴蝶飛、燕子雙語、楊花轉、窗內人春睡正輕，一片悠閒，有春景卻沒有悲傷，歸「其他」。(A)錯：杜甫〈春望〉在春天感時恨別、花濺淚，是傷春（傷時）。(B)錯：李益〈喜見外弟又言別〉相逢又要分別，「秋山又幾重」帶著離愁，屬悲秋。(D)錯：「夜來秋」「西風梧井葉先愁」，直接寫秋愁，屬悲秋。", "skill": "分類題先讀清楚分類規則（註解），再為每個選項判斷兩件事：季節是什麼、情緒是不是悲傷。"}, {"n": 32, "qtype": "單選", "stem": "詞本是配樂歌唱，起初的情境常是「綺筵公子，繡幌佳人，遞葉葉之花箋，文抽麗錦；舉纖纖之玉指，拍按香檀。不無清絕之辭，用助嬌嬈之態」，寫進歌詞的題材，因此也被北宋早期的詞家沿用。依上述觀點，《宋詞三百首》所收北宋早期詞作，最可能以上表哪一類寫作題材居最多數？", "options": {"A": "年老", "B": "情思", "C": "離鄉", "D": "仕宦"}, "answer": "B", "explain": "引文描述早期詞的場合：貴公子在華宴上寫詞，美人拍板演唱，用來增添嬌柔姿態——內容自然多是男女情愛、相思，北宋早期詞家沿用這種題材，所以以「情思」最多，選(B)。就像今天的流行歌曲，最大宗還是情歌。(A)錯：宴席助興不會多寫衰老。(C)錯：離鄉是遊子題材，與綺筵佳人的情境不合。(D)錯：仕宦是官場題材，也不適合歌女在宴席上嬌柔演唱。", "skill": "從「創作場合」推「內容題材」：誰寫、給誰唱、在什麼地方唱，題材就跟著決定。"}], "difficulty": "中", "label": "109統測", "year": 109, "kind": "統測"}, {"id": "tc110-02", "exam": "tc110", "nums": [2], "form": "單題", "img": "img/tc110-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "無出其右", "translation": "「無出其右」：沒有人能超過他（古人以右為尊，「出其右」就是排在他上面、勝過他）。", "keywords": [{"w": "出", "m": "本題題幹中為「超過、勝過」"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列文句的「出」，何者與「無出其右」的「出」意義最接近？", "options": {"A": "日「出」而林霏開", "B": "長鋏歸來乎！「出」無車", "C": "匣而埋諸土，朞年「出」之", "D": "古之聖人，其「出」人也遠矣"}, "answer": "D", "explain": "先抓題幹：「無出其右」是沒有人能「超過」他，所以要找當「超過」講的「出」。(A)歐陽脩〈醉翁亭記〉「日出而林霏開」，太陽「升起、出現」，林間霧氣散開，不是超過。(B)《戰國策》馮諼彈劍唱「長鋏歸來乎！出無車」，意思是「外出」沒有車坐，不是超過。(C)〈工之僑獻琴〉把琴裝匣埋進土裡，一年後「取出、挖出來」，不是超過。(D)韓愈〈師說〉「古之聖人，其出人也遠矣」，古代聖人「超出」一般人很多，和「無出其右」的「出」同義，正確。", "skill": "一字多義題：先把題幹的字換成白話（出＝超過），再把每個選項代進去讀，讀得通的就是答案。"}], "difficulty": "易", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-03", "exam": "tc110", "nums": [3], "form": "單題", "img": "img/tc110-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "", "translation": "(A)今年春天的雪下得「很」大。(B)問他們從哪裡來，「全都、詳細地」回答了。(C)「每次」讀到古人有所感慨的原因。(D)左公看完，「立刻」脫下貂皮衣蓋在書生身上。", "keywords": [{"w": "具", "m": "全部、詳盡"}, {"w": "甚", "m": "很、非常"}, {"w": "每", "m": "每次"}, {"w": "即", "m": "立刻"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列文句「」內的副詞，何者意指範圍層面的完整？", "options": {"A": "今歲春雪「甚」盛", "B": "問所從來，「具」答之", "C": "「每」覽昔人興感之由", "D": "公閱畢，「即」解貂覆生"}, "answer": "B", "explain": "題目要找表示「範圍全部、完整」的副詞。(A)袁宏道〈晚遊六橋待月記〉「甚」＝很，表程度，不是範圍。(B)陶淵明〈桃花源記〉漁人被問從哪裡來，「具答之」＝全部、詳細地回答，表示範圍完整，正確。(C)王羲之〈蘭亭集序〉「每」＝每次，表頻率。(D)方苞〈左忠毅公軼事〉「即」＝立刻，表時間。", "skill": "副詞分類先分四大類：程度（甚、頗）、範圍（皆、具、悉、咸）、頻率（每、屢）、時間（即、遂、旋），對號入座就好。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-04", "exam": "tc110", "nums": [4], "form": "單題", "img": "img/tc110-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解"], "passage": "參政魯公為諫官，真宗遣使急召之，得於酒家，既入，問其所來，以實對。", "translation": "(D)魯宗道擔任諫官時，宋真宗派使者緊急召見他，使者在酒館找到他，他進宮後，真宗問他從哪裡來，他照實回答。", "keywords": [{"w": "說", "m": "通「悅」，高興"}, {"w": "戍", "m": "駐守"}, {"w": "瞋目", "m": "睜大眼睛怒視"}, {"w": "目眥", "m": "眼眶"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下列文句，何者不是從頭至尾皆以畫底線者為主語？（畫底線者：(A)秦伯 (B)屈原 (C)噲 (D)參政魯公）", "options": {"A": "秦伯說，與鄭人盟，使杞子、逢孫、楊孫戍之", "B": "屈原既放，遊於江潭，行吟澤畔，顏色憔悴，形容枯槁", "C": "噲遂入，披帷，西嚮立，瞋目視項王，頭髮上指，目眥盡裂", "D": "參政魯公為諫官，真宗遣使急召之，得於酒家，既入，問其所來，以實對"}, "answer": "D", "explain": "逐句問「這個動作是誰做的」。(A)〈燭之武退秦師〉：高興、和鄭國結盟、派杞子等人駐守，都是秦伯做的，主語一致。(B)〈漁父〉：被放逐、遊江潭、邊走邊吟、臉色憔悴、形體枯瘦，都說屈原，主語一致。(C)〈鴻門宴〉：進帳、掀開帷幕、向西站、瞪著項王、頭髮直豎、眼眶裂開，都在寫樊噲，主語一致。(D)「為諫官」是魯公，「遣使急召之」換成真宗，「得於酒家」是使者找到他，「問其所來」又是真宗，最後「以實對」才回到魯公，主語換來換去，所以答案是(D)。", "skill": "判斷主語就像點名：每個動詞前面補上「誰」，只要中途換人，就不是同一主語。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-05", "exam": "tc110", "nums": [5], "form": "單題", "img": "img/tc110-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "", "translation": "", "keywords": [{"w": "文賦", "m": "宋代賦體，句式較自由、近於散文"}, {"w": "登高題材", "m": "寫登山、登樓眺望而抒懷的作品"}], "questions": [{"n": 5, "qtype": "單選", "stem": "如右圖所示，①為三者的交集，②、③、④為兩兩的交集。下列古典名篇的敘述，何者最不適當？（三圓分別為：散文、登高題材、宋代文學；②＝散文∩登高題材，③＝散文∩宋代文學，④＝登高題材∩宋代文學）", "options": {"A": "蘇軾〈赤壁賦〉符合④", "B": "范仲淹〈岳陽樓記〉符合③", "C": "柳宗元〈始得西山宴遊記〉符合②", "D": "歐陽脩〈醉翁亭記〉符合①"}, "answer": "A", "explain": "先看懂圖：④是「登高題材」和「宋代文學」的交集（不含散文）。(A)〈赤壁賦〉是宋代作品沒錯，但內容寫月夜和客人「泛舟」赤壁之下，不是登高眺望，放在④最不適當，所以選(A)。(B)〈岳陽樓記〉是宋代散文；范仲淹是看著滕子京寄來的〈洞庭晚秋圖〉寫成的，並沒有親自登樓，重點在抒發「先天下之憂而憂」的懷抱，歸在③（宋代散文）說得通。(C)〈始得西山宴遊記〉是唐代散文，寫攀登西山、在山頂眺望，屬「散文＋登高」的②，正確。(D)〈醉翁亭記〉是宋代散文，寫在琅琊山中山行、遊賞、宴飲，可視為登山遊覽之作，放在①說得通。", "skill": "文氏圖題先把每一區「有哪幾個條件、缺哪個條件」寫出來，再逐篇檢查朝代、文體、題材三項。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-08", "exam": "tc110", "nums": [8], "form": "單題", "img": "img/tc110-08.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "寫作手法"], "passage": "其間旦暮聞何物？杜鵑啼血猿哀鳴。（白居易〈琵琶行〉）\n庶竭駑鈍，攘除姦凶。（諸葛亮〈出師表〉）\n奔車朽索，其可忽乎？（魏徵〈諫太宗十思疏〉）\n吾嘗跂而望矣，不如登高之博見也。（荀子〈勸學〉）", "translation": "這裡早晚聽到的是什麼？是杜鵑啼到吐血、猿猴哀傷的叫聲。\n希望能用盡我平庸的才能，掃除奸邪凶惡的敵人。\n用腐朽的繩子駕馭飛奔的馬車，怎麼能夠疏忽呢？\n我曾經踮起腳尖遠望，還不如登到高處看得廣。", "keywords": [{"w": "駑鈍", "m": "劣馬與鈍刀，比喻才能平庸（自謙）"}, {"w": "攘除", "m": "排除、消滅"}, {"w": "跂", "m": "踮起腳跟"}], "questions": [{"n": 8, "qtype": "單選", "stem": "課堂上，有四位同學結合課文談論下圖（漫畫：主人對皺眉的狗說「電視沒壞，怎麼能換大螢幕電視呢？」後來換了大螢幕，說「大螢幕帶來寬闊的視野」），其中何者對課文有所誤解？", "options": {"A": "狗不會因螢幕小而皺眉，是人把感受投射到狗身上。這就像〈琵琶行〉：「其間旦暮聞何物？杜鵑啼血猿哀鳴」，內心哀傷，所聞動物鳴聲也變得哀傷", "B": "人表面上告訴狗為何不換電視，其實是自我說服。這就像〈出師表〉：「庶竭駑鈍，攘除姦凶」，作者表面勸後主勿因資質魯鈍而怯於除奸，實為激勵自己", "C": "「怎麼能換大螢幕電視呢？」雖是問句，其實並非想徵詢答案。這就像〈諫太宗十思疏〉：「奔車朽索，其可忽乎？」是無疑而問，作者只是藉問句申明觀點", "D": "因換了螢幕而「視野變寬闊」，可聯想到借助資源能追求進階。這就像〈勸學〉：「吾嘗跂而望矣，不如登高之博見也」，懂得運用學習資源，才能提升自我"}, "answer": "B", "explain": "關鍵是讀懂四句課文。(A)白居易被貶江州，心裡哀傷，聽到杜鵑、猿猴的聲音也覺得淒厲，是把情緒投射到外物，說法正確。(B)〈出師表〉「庶竭駑鈍」的「駑鈍」是諸葛亮謙稱「自己」才能平庸，意思是「我願意用盡自己平庸的能力去消滅奸凶」，根本不是在勸後主別因資質差而害怕，這位同學誤解了，所以選(B)。(C)「其可忽乎」是激問，答案在反面（不可忽視），只是用問句加強語氣，說法正確。(D)〈勸學〉說踮腳不如登高，強調善於借助外物（善假於物），和借助資源提升自己相合，正確。", "skill": "引文判讀題：先把引文的「主詞是誰」「在說誰」確認清楚，很多陷阱就是把作者自謙的話說成在勸別人。"}], "difficulty": "易", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-11", "exam": "tc110", "nums": [11, 12], "form": "題組", "img": "img/tc110-11.png", "source": "佐倉孫三《臺風雜記》（改寫）", "author": "佐倉孫三", "genre": "筆記小品", "types": ["比較閱讀", "文意推論"], "passage": "臺地亦有產婆，家有妊婦則聘之。婆隔日來而診之，及分娩，洗兒護母，懇篤盡仁術。其謝金大抵自一圓至五、六圓，雖富豪者，不過二十餘金。唯貧家不能聘婆者，近鄰老婦有經歷者往而舉之，曰先生媽，年齒大抵三十歲以上，妙齡者殆稀。今也泰西產婆術大開，立學校，養生徒，不得卒業證書者不許之，是以妙齡產婆續續輩出，「婆」之一字殆不相適合。", "translation": "臺灣也有產婆，家裡有孕婦就聘請她。產婆隔一天來診察一次，到了生產時，替嬰兒洗澡、照護產婦，誠懇周到，盡心施行仁術。酬金大約從一圓到五、六圓，就算是富豪人家，也不過二十多圓。只有請不起產婆的窮人家，由鄰近有經驗的老婦人前去接生，稱為「先生媽」，年紀大多在三十歲以上，年輕的幾乎沒有。現在西洋的產婆技術大為流行，設立學校，培養學生，拿不到畢業證書的人不准執業，因此年輕的產婆接連出現，「婆」這個字幾乎已經不適合了。", "keywords": [{"w": "妊婦", "m": "孕婦"}, {"w": "懇篤", "m": "誠懇周到"}, {"w": "謝金", "m": "酬金"}, {"w": "舉之", "m": "替她接生"}, {"w": "殆", "m": "幾乎、大概"}, {"w": "泰西", "m": "西洋"}, {"w": "卒業", "m": "畢業"}, {"w": "續續輩出", "m": "接連大量出現"}], "questions": [{"n": 11, "qtype": "單選", "stem": "依據甲、乙二文，助產婦與先生媽的區別主要為何？", "options": {"A": "前者無誕子經驗，後者有", "B": "前者30歲以下，後者30歲以上", "C": "前者在學校受過助產教育，後者沒有", "D": "二者皆受過助產教育，但前者為日本籍，後者為臺籍"}, "answer": "C", "explain": "甲文說新式產婆要「立學校，養生徒，不得卒業證書者不許之」，乙文說先生媽「從未受過一定教育」，總督府還要辦講習訓練助產婦，所以差別在有沒有受過學校教育，(C)正確。(A)甲文只說先生媽是「有經歷」的老婦，沒說助產婦都沒生過孩子。(B)甲文說年輕產婆變多，但乙文招收的講習生是16到40歲，不能說都在30歲以下。(D)先生媽沒受過教育；而且總督府要訓練的是「本島人」女子，助產婦不一定是日本籍。", "skill": "比較兩種人的差別，要找兩文「同一個條件」上的對照（受教育／沒受教育），不要被只出現一次的細節帶走。"}, {"n": 12, "qtype": "單選", "stem": "下列何者符合甲、乙二文所述？", "options": {"A": "助產婦的服務對象，大多為日本移居臺灣的孕婦", "B": "受過教育的妙齡產婆無誕子經驗，接受度不及先生媽", "C": "產婆能提供孕婦產前至分娩的照護，費用由聘請者酌給", "D": "臺籍人士的助產婦講習以先生媽優先，唯年齡須低於40歲"}, "answer": "C", "explain": "(C)甲文「婆隔日來而診之，及分娩，洗兒護母」是產前到生產的照護；酬金「大抵自一圓至五、六圓，雖富豪者，不過二十餘金」，金額有彈性，由聘請人家斟酌給，正確。(A)乙文說日本助產婦因語言、風俗不同難以適應，才要訓練本島人，文中沒說服務對象多是日本孕婦。(B)兩文都沒提到接受度比較。(D)招募資格是學歷、年齡、品行、身體，沒有先生媽優先的規定。", "skill": "「何者符合」題，每個選項都要回原文找到對應句子，找不到的一律當「文中未提」。"}], "difficulty": "易", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-13", "exam": "tc110", "nums": [13, 14], "form": "題組", "img": "img/tc110-13.png", "source": "高阜〈與周減齋先生〉", "author": "高阜", "genre": "書信序跋", "types": ["文意推論", "人物情感"], "passage": "寒家敝垣上藤蘿，見者多賞其初夏展放時，新綠如染，葉葉鱗次，微風過去，作碧波千萬頃。而某更領略秋冬之際，霜深宇凈，落葉滿庭階，如在萬山深處，令人意思孤遠。因意此蘿為先君手植，至今三十餘載。先君見背已二十餘年，猶令某對之肅肅，不敢作凡近想。生我之教訓，固何時已乎！敢請先生為書「蘿棲」字，以寵其居，志不忘也。", "translation": "我家破舊牆上的藤蘿，看到的人大多欣賞它初夏盛開的樣子：新綠像染過一樣，葉片像魚鱗般層層排列，微風吹過，像千萬頃的綠色波浪。而我更能體會它在秋冬時節的美：霜重、天空清朗，落葉鋪滿庭院台階，彷彿身在萬山深處，讓人心思孤高遼遠。想到這株藤蘿是先父親手種的，到現在已經三十多年了。先父過世已經二十多年，它仍讓我面對它時肅然起敬，不敢有平庸淺近的念頭。父親給我的教誨，哪有停止的時候呢！冒昧請先生為我題寫「蘿棲」二字，讓我的住處增光，也表示我不忘先父。", "keywords": [{"w": "敝垣", "m": "破舊的牆"}, {"w": "鱗次", "m": "像魚鱗般依序排列"}, {"w": "宇凈", "m": "天空清朗"}, {"w": "先君", "m": "已過世的父親"}, {"w": "見背", "m": "長輩過世"}, {"w": "肅肅", "m": "恭敬的樣子"}, {"w": "凡近", "m": "平庸淺近"}, {"w": "寵", "m": "使……增光"}, {"w": "志", "m": "記住"}], "questions": [{"n": 13, "qtype": "單選", "stem": "關於上文的藤蘿，下列敘述何者正確？", "options": {"A": "歷家中人事代謝，仍生生不息", "B": "初夏蔓生池上，風來碧波萬頃", "C": "逢秋葉落，興發離群索居之情", "D": "父親悉心照料，藉以追念祖父"}, "answer": "A", "explain": "藤蘿是父親三十多年前種的，父親已過世二十多年，它還好好長著，見證家中人事變遷而生生不息，(A)正確。(B)藤蘿長在「敝垣上」（牆上），「碧波千萬頃」是把滿牆綠葉比喻成波浪，不是長在池上。(C)秋冬落葉讓作者「意思孤遠」，是心境高遠清靜，不是想離開人群獨居。(D)藤蘿是父親種的，作者藉它追念「父親」，文中沒提到祖父。", "skill": "看到「如、作」要想到比喻，別把比喻的東西（碧波）當成真的景物（池塘）。"}, {"n": 14, "qtype": "單選", "stem": "上文為求周減齋惠賜墨寶，採取何種言說策略？", "options": {"A": "向對方透露先父未竟遺願", "B": "請對方諒察綿長思親衷懷", "C": "邀對方同遊故居撫今追昔", "D": "讚對方筆力超凡難望項背"}, "answer": "B", "explain": "作者先寫藤蘿之美，再說它是先父手植、自己對它肅然起敬，最後說請題「蘿棲」是為了「志不忘也」，用長久思念父親的心意打動對方，(B)正確。(A)沒提到父親有什麼沒完成的心願。(C)沒有邀請對方來遊。(D)信中沒有稱讚對方的書法。", "skill": "請託信的重點常在最後一句「目的＋理由」，倒回去看理由用了什麼情感打動人。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-15", "exam": "tc110", "nums": [15, 16], "form": "題組", "img": "img/tc110-15.png", "source": "紀昀〈飛車劉八〉（《閱微草堂筆記》）", "author": "紀昀", "genre": "筆記小品", "types": ["主旨寓意", "文意推論"], "passage": "飛車劉八，從孫樹珊之御者也。其御車極鞭策之威，盡馳驅之力，遇同行者，必驀越其前而後已，故得此名。馬之強弱所不問，馬之饑飽所不問，馬之生死亦所不問也。歷數主，殺馬頗多。一日，御樹珊往群從家，以空車返。中路馬軼，為輪所軋，仆轍中，其傷頗輕，竟昏瞀不知人，舁歸則氣已絕矣。", "translation": "「飛車劉八」是我堂姪孫樹珊的車夫。他駕車時極盡鞭打的威勢，用盡奔馳的力氣，遇到同路的車，一定要超到前面才罷休，所以得到這個外號。馬強不強壯他不管，馬餓不餓他不管，馬會不會累死他也不管。替好幾個主人駕過車，害死的馬很多。有一天，他載樹珊到族中兄弟家，空車回來。半路上馬突然狂奔，他被車輪輾到，倒在車轍裡，傷勢其實很輕，竟然昏迷不省人事，抬回家時已經斷氣了。", "keywords": [{"w": "御者", "m": "駕車的人"}, {"w": "鞭策", "m": "用鞭子抽打"}, {"w": "驀越", "m": "超越"}, {"w": "軼", "m": "奔突、失控狂奔"}, {"w": "仆", "m": "跌倒"}, {"w": "昏瞀", "m": "昏迷"}, {"w": "舁", "m": "抬"}], "questions": [{"n": 15, "qtype": "單選", "stem": "依據上文，何者的待人思維最接近劉八？", "options": {"A": "對店員說「這碗麵裡有蟲！叫店長出來」的顧客", "B": "對選手說「盡全力就好！不必在乎名次」的教練", "C": "對員工說「拚第一！別計較公司給多少資源」的老闆", "D": "對魯蛇說「越害怕越要來！懂得輸才懂得贏」的贏家"}, "answer": "C", "explain": "劉八只要求馬拚命跑、一定要贏，卻完全不管馬的強弱、飢飽、生死，就像只要求成果、不顧對方條件的人。(C)老闆要員工拚第一，又叫他們別計較資源，正是這種思維，正確。(A)顧客是在客訴產品問題，不是逼對方拚命。(B)教練說不必在乎名次，跟劉八「必驀越其前」的求勝心相反。(D)贏家是鼓勵人面對失敗、勇敢嘗試，不是不顧對方死活的壓榨。", "skill": "人物類比題：先把文中人物的行為濃縮成一句「只要結果、不管代價」，再拿這句去比對選項。就像職場上只喊業績、不給資源的主管。"}, {"n": 16, "qtype": "單選", "stem": "上文藉劉八的下場，最可能想警惕讀者：", "options": {"A": "勿藉寇兵而齎盜糧", "B": "勿淈其泥而揚其波", "C": "榮辱之來，必象其德", "D": "人為刀俎，我為魚肉"}, "answer": "C", "explain": "劉八害死很多馬，最後自己因為馬失控被車輪輾到，傷不重卻莫名死去，有一種「自作自受」的報應意味。(C)《荀子‧勸學》「榮辱之來，必象其德」，榮耀或恥辱的到來，一定和自己的德行相應，正確。(A)李斯〈諫逐客書〉，比喻不要資助敵人，與本文無關。(B)化用〈漁父〉「何不淈其泥而揚其波」，指隨波逐流；加上「勿」是不要同流合汙，與本文無關。(D)〈鴻門宴〉，比喻自己處境危險、任人宰割，與本文無關。", "skill": "寓意題看「結局怎麼呼應前面的行為」，前因後果對得上，就是作者要說的道理。"}], "difficulty": "易", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-17", "exam": "tc110", "nums": [17, 18, 19], "form": "題組", "img": "img/tc110-17.png", "source": "顧炎武〈廉恥〉、劉肅《大唐新語》", "author": "顧炎武、劉肅", "genre": "說理議論", "types": ["比較閱讀", "虛詞句式", "寫作手法"], "passage": "【甲】頃讀《顏氏家訓》，有云：「齊朝一士夫，嘗謂吾曰：『我有一兒，年已十七，頗曉書疏，教其鮮卑語及彈琵琶，稍欲通解，以此伏事公卿，無不寵愛。』吾時俯而不答。異哉，此人之教子也！若由此業，自致卿相，亦不願汝曹為之！」嗟乎！之推不得已而仕①於亂世，猶為此言，尚有〈小宛〉詩人之意，彼閹然媚於世者，能無愧哉！\n【乙】張易之兄同休，嘗請公卿宴②於司禮寺，因請御史大夫楊再思曰：「公面似高麗，請作高麗舞。」再思欣然，帖紙旗巾子，反披紫袍，作高麗舞，略無慚色。再思又見易之弟昌宗以貌美被寵，因諛之曰：「人言六郎似蓮花，再思以為不然，只是蓮花似六郎耳。」有識咸笑之。後昌宗兄弟犯贓，則天命桓彥範、李承嘉勘當以取實。經數日，彥範等奏：「昌宗兄弟共有贓四千餘貫，法當解職。」昌宗奏：「臣有功於國家，所犯不至解免。」則天問諸宰臣曰：「昌宗③於國有功否？」再思時為內史，奏曰：「昌宗合煉神丹，聖躬服之有效，此實莫大之功。」乃赦之。天下名士，視再思如糞土也。", "translation": "【甲】最近讀《顏氏家訓》，書中說：「北齊有一位士大夫曾對我說：『我有個兒子，已經十七歲，很會寫書信公文，我教他鮮卑話和彈琵琶，也漸漸學會了，憑這些去服侍公卿，沒有人不寵愛他。』我當時低頭沒有回答。奇怪啊，這個人教兒子的方法！就算靠這種本事能當上卿相，我也不願你們這樣做！」唉！顏之推是不得已在亂世做官，還能說出這種話，仍保有〈小宛〉詩人「不辱父母」的用心；那些曲意討好世俗的人，能不感到慚愧嗎！\n【乙】張易之的哥哥張同休，曾在司禮寺宴請公卿，席間對御史大夫楊再思說：「您的臉像高麗人，請跳高麗舞。」楊再思很高興，把紙貼在頭巾上當旗子，反穿紫色官袍，跳起高麗舞，一點也不覺得羞愧。楊再思又見張易之的弟弟張昌宗因長得俊美而受寵，就奉承說：「大家說六郎像蓮花，我認為不對，應該說蓮花像六郎才是。」有見識的人都嘲笑他。後來張昌宗兄弟犯了貪汙罪，武則天命桓彥範、李承嘉審問查實。幾天後，桓彥範等人上奏：「張昌宗兄弟共貪汙四千多貫，依法應當免職。」張昌宗上奏：「臣對國家有功，所犯的罪不至於免職。」武則天問宰相們：「昌宗對國家有功嗎？」楊再思當時任內史，上奏說：「昌宗煉製神丹，皇上服用有效，這實在是最大的功勞。」武則天於是赦免了他。天下有名望的士人，都把楊再思看得像糞土一樣。", "keywords": [{"w": "頃", "m": "最近"}, {"w": "書疏", "m": "書信、奏章"}, {"w": "伏事", "m": "服侍"}, {"w": "汝曹", "m": "你們"}, {"w": "閹然", "m": "曲意逢迎的樣子"}, {"w": "諛", "m": "奉承"}, {"w": "犯贓", "m": "犯貪汙罪"}, {"w": "勘當", "m": "審問定罪"}, {"w": "聖躬", "m": "皇帝本人"}], "questions": [{"n": 17, "qtype": "單選", "stem": "甲、乙二文共同批評的對象是：", "options": {"A": "諂諛奉承者", "B": "教導失措者", "C": "舌粲蓮花者", "D": "賣主求榮者"}, "answer": "A", "explain": "甲文最後罵「閹然媚於世者」（曲意討好的人），乙文的楊再思跳高麗舞、說「蓮花似六郎」、把煉丹說成大功，全是拍馬屁，天下名士「視再思如糞土」。兩文共同批評的是諂媚奉承的人，(A)正確。(B)教子不當只出現在甲文引述的齊朝士夫，乙文沒有。(C)「舌粲蓮花」是口才好，楊再思說的雖是蓮花，但重點是奉承不是口才。(D)兩文都沒有出賣主上換取富貴的情節。", "skill": "「共同」題：先各自找出甲、乙批評的人，再取交集；只出現在一篇的都刪掉。"}, {"n": 18, "qtype": "單選", "stem": "關於甲、乙文中①、②、③三個「於」的用法與意義，正確的研判是：", "options": {"A": "①②相同", "B": "②③相同", "C": "①②③皆相同", "D": "①②③皆不同"}, "answer": "A", "explain": "①「仕於亂世」：在亂世做官，「於」＝在（時間）。②「宴於司禮寺」：在司禮寺宴請，「於」＝在（地點）。③「於國有功」：對國家有功，「於」＝對。①②都是「在」，③是「對」，所以(A)正確，(B)(C)(D)都錯。", "skill": "「於」最常見三義：在、對、比（被）。把「在」「對」「比」代進句子試讀，哪個通就是哪個。"}, {"n": 19, "qtype": "單選", "stem": "關於甲、乙二文的敘寫方式，最適當的解說是：", "options": {"A": "二文作者皆以親見的官員醜態，做為評論案例", "B": "甲文先摘引《顏氏家訓》文句，再譴責該書作者心態可議", "C": "乙文就楊再思與張易之的互動記錄三事，以呈現楊再思為人", "D": "乙文作者似未置評論，實藉「天下名士」的反應來表達自己的看法"}, "answer": "D", "explain": "(D)乙文從頭到尾只記事，最後一句「天下名士，視再思如糞土也」借別人的態度表達作者的評價，正確。(A)甲文是讀書時引用的例子，乙文是史料記載，都不是作者親眼看到。(B)甲文引《顏氏家訓》後是「肯定」顏之推仍有〈小宛〉詩人之意，批評的是媚世者，不是譴責顏之推。(C)乙文三件事中，高麗舞是應張同休要求，蓮花之諛和煉丹之功都和張昌宗有關，並非和張易之互動。", "skill": "判斷作者態度：注意結尾「旁人怎麼看」，這常是作者不明說、借他人之口表態的地方。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-20", "exam": "tc110", "nums": [20, 21, 22], "form": "題組", "img": "img/tc110-20.png", "source": "郁永河《裨海紀遊》、柯培元《噶瑪蘭志略‧山川志》、莊芳池〈湯圍溫泉〉", "author": "郁永河、柯培元、莊芳池", "genre": "山水遊記", "types": ["比較閱讀", "寫作手法", "文意推論"], "passage": "【甲】水潺潺巉石間，與石皆作藍靛色。導人謂此水源出硫穴下，是沸泉也。余以一指試之，猶熱甚。\n【乙】湯泉，在湯圍，廳治南四十里。遠望熱氣蒸騰，泉中若沸，附近田園多被泡傷。土人無冬夏，澡浴於此。\n【丙】不須調鼎釀烟濃，獨藉乾坤一氣鎔。昇月樓前泉滾滾，員山館下水淙淙。滌來汗垢千般去，療得皮膚百病鬆。浴罷倚欄舒望眼，龜峰聳峙對西峰。", "translation": "【甲】溪水在險峻的岩石間潺潺流動，水和石頭都呈現藍靛色。嚮導說這水是從硫磺穴底下流出來的，是滾燙的泉水。我用一根手指試探，還是非常燙。\n【乙】溫泉在湯圍，位於廳治南方四十里。遠遠看去熱氣蒸騰，泉水像在沸騰，附近的田地常被熱水泡壞。當地人不分冬夏，都在這裡洗澡。\n【丙】不必用鼎烹煮、燒出濃煙，單靠天地間的一股元氣就把泉水燒熱。昇月樓前泉水滾滾湧出，員山館下泉水淙淙流動。洗去各種汗垢，治好皮膚的各種毛病，全身輕鬆。洗完倚著欄杆放眼遠望，龜山島高高聳立，與西邊的山峰相對。", "keywords": [{"w": "巉石", "m": "險峻的岩石"}, {"w": "導人", "m": "嚮導"}, {"w": "廳治", "m": "廳的官署所在地"}, {"w": "土人", "m": "當地人"}, {"w": "調鼎", "m": "用鼎烹調"}, {"w": "乾坤一氣", "m": "天地間的元氣"}], "questions": [{"n": 20, "qtype": "單選", "stem": "關於甲、乙二文的敘述，何者正確？", "options": {"A": "甲文描寫溫泉流過陡峭山石間", "B": "乙文提到田園受惠於溫泉地熱", "C": "二文皆有作者親探水溫的描寫", "D": "二文皆提到居民常於溫泉洗浴"}, "answer": "A", "explain": "(A)甲文「水潺潺巉石間」，巉石是陡峭的岩石，正確。(B)乙文說田園「多被泡傷」，是受害不是受惠。(C)只有甲文「余以一指試之」親自試水溫，乙文沒有。(D)只有乙文寫「土人無冬夏，澡浴於此」，甲文沒有。", "skill": "「二文皆」的選項，要兩篇都找到證據才算對，只要一篇沒有就刪。"}, {"n": 21, "qtype": "單選", "stem": "關於乙文、丙詩的敘寫方式，最適當的是：", "options": {"A": "乙文依時間序，呈現從廳治出發的遊歷經過", "B": "乙文以人喻景，形容湯圍溫泉宛如人間仙境", "C": "丙詩透過對仗，凸顯湯圍溫泉今昔景觀之別", "D": "丙詩末句寫景，藉望遠所見表達浴後的舒暢"}, "answer": "D", "explain": "(D)丙詩「浴罷倚欄舒望眼，龜峰聳峙對西峰」，洗完澡放眼遠望龜山島和西峰，以景寫出身心舒暢，正確。(A)乙文是方志式的記載：位置、景象、用途，沒有按時間記錄遊歷。(B)乙文沒有用人來比喻景物，也沒說像仙境。(C)「昇月樓前泉滾滾，員山館下水淙淙」確實對仗，但寫的是兩處泉水，不是今昔對比。", "skill": "寫作手法題要「手法」和「效果」兩半都對：對仗對了，但效果說錯（今昔之別）一樣不選。"}, {"n": 22, "qtype": "單選", "stem": "依據下表（碳酸氫鹽泉：碳酸氫根離子為主，分布變質岩區，如礁溪溫泉，水溫約60°C，水清無味，pH 6.6～7.9；硫酸鹽泉：硫酸根離子為主，分布火成岩區，如陽明山溫泉，水溫約90°C，有刺鼻味，pH 2.0～6.5），下列敘述何者錯誤？", "options": {"A": "甲文的「硫穴」，地質屬於火成岩", "B": "乙文泉水的陰離子，主要為硫酸根離子", "C": "甲文的泉水氣味濃烈刺鼻，丙詩的泉水無味", "D": "乙文「泉中若沸」與丙詩「泉滾滾」水溫熱度相近"}, "answer": "B", "explain": "先對應地點：甲文硫穴在陽明山（硫酸鹽泉），乙文湯圍和丙詩湯圍溫泉都在宜蘭礁溪（碳酸氫鹽泉）。(B)乙文是礁溪溫泉，陰離子以碳酸氫根為主，說成硫酸根是錯的，所以選(B)。(A)陽明山屬火成岩區，正確。(C)陽明山泉水有刺鼻味，礁溪泉水清而無味，正確。(D)乙、丙寫的是同一處礁溪溫泉，水溫都約60°C，正確。", "skill": "文本＋表格題先做「配對」：把每篇文章的地點對到表格的哪一欄，再逐項核對。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-26", "exam": "tc110", "nums": [26, 27, 28, 29], "form": "題組", "img": "img/tc110-26.png", "source": "白居易租屋購屋資料（甲文白話、乙文唐代租屋契約，出處待查）", "author": "", "genre": "其他", "types": ["文意推論", "文化常識"], "passage": "【乙】元和二年五月一日，韓城縣人白居易向黃○○賃取＿＿中〔　〕堂舍。價每月銀錢捌拾文，並於一、十五日各與錢肆拾文。立契後，一年內不得悔，先悔者罰銀錢捌拾文，入不悔人。兩和立契，畫指為驗。舍主黃○○　賃舍人白居易（左拾遺）　保人楊○○（中書舍人）　知見人吳○○\n（甲文引：竹木池館，有林泉之致。識分知足，外無求焉。）", "translation": "元和二年五月一日，韓城縣人白居易向黃某租用＿＿坊中〔　〕規格的堂舍。租金每月銀錢八十文，在每月初一、十五日各付四十文。立約之後，一年內不得反悔，先反悔的人罰銀錢八十文，交給沒有反悔的一方。雙方同意立約，按指印作為憑證。\n（洛陽履道坊宅院：有竹林樹木、池塘館舍，富有山林泉石的情趣；讓白居易懂得安守本分、知足，不再向外追求。）", "keywords": [{"w": "賃", "m": "租"}, {"w": "悔", "m": "反悔、毀約"}, {"w": "入不悔人", "m": "（罰金）交給沒有反悔的一方"}, {"w": "兩和", "m": "雙方同意"}, {"w": "畫指", "m": "按指印、畫指節為憑"}, {"w": "間、架", "m": "房屋面寬以「間」計，縱深以「架」計"}], "questions": [{"n": 26, "qtype": "單選", "stem": "依據甲文，關於白居易租屋購屋的敘述，何者正確？", "options": {"A": "授官後任職下邽縣，就近於金氏村購置「渭北莊園」", "B": "婚後十餘年仍輾轉於長安常樂、宣平、昭國等坊租屋", "C": "曾租屋於長安新昌坊，是購屋時選擇該坊的原因之一", "D": "為購得柳宗元岳父的園林宅院，乃自請調職東都洛陽"}, "answer": "C", "explain": "(C)圖表顯示白居易36歲租過長安新昌坊，甲文說50歲選新昌坊買房「除了地段熟悉」，也因妻子娘家在隔街，正確。(A)他授校書郎在長安上班，買下邽房子是因為母親來投靠，不是自己任職下邽。(B)他36歲結婚，常樂坊是32歲（婚前）租的；婚後租的是新昌、宣平、昭國坊。(D)順序相反：他是先自請調職洛陽，才在履道坊買到那座宅院，並非為了買房才調職。", "skill": "人生年表題，把「年齡」當座標，每個選項都回到時間軸上對位置。"}, {"n": 27, "qtype": "單選", "stem": "依據上述資料，對於①、②的研判應是：①隨著官位品階上升，白居易租的房子也越來越靠長安繁華地區。②白居易寫〈琵琶行〉時（元和十一年），把長安的自有住宅出租他人。", "options": {"A": "①正確，②錯誤", "B": "①、②皆無法判斷", "C": "①無法判斷，②錯誤", "D": "①正確，②無法判斷"}, "answer": "C", "explain": "①資料只列出租屋的坊名，沒有任何一坊繁不繁華的說明，無法判斷。②元和二年白居易36歲，元和十一年就是45歲，正在江州司馬任上；他要到50歲才「終於在京城買房」，45歲時在長安根本沒有自有住宅可以出租，所以②錯誤。答案(C)。", "skill": "「無法判斷」和「錯誤」要分清：資料沒提到→無法判斷；資料能推出相反結論→錯誤。"}, {"n": 28, "qtype": "單選", "stem": "若乙文為白居易的租屋契約，依據甲文、丙表，下列敘述何者正確？", "options": {"A": "＿＿應是昭國坊", "B": "〔　〕應是五間九架", "C": "租金採逐月一次付清方式", "D": "一年內悔約者罰租金一個月"}, "answer": "D", "explain": "先讀懂契約。(D)「先悔者罰銀錢捌拾文」，而每月租金正是八十文，罰金等於一個月租金，正確。(A)契約寫於元和二年，白居易署名「左拾遺」，甲文說他35歲任縣尉、隔年（36歲）任左拾遺，圖表36歲租的是新昌坊，不是昭國坊（43歲）。(B)左拾遺是八品，依丙表「六、七品以下」最多只能三間五架；五間九架是三品以上官員才能有的規格。(C)「於一、十五日各與錢肆拾文」，每月分兩次付，不是一次付清。", "skill": "古代契約就像今天的租約：先找「租金多少、怎麼付、違約罰多少」，再交叉比對其他資料。"}, {"n": 29, "qtype": "單選", "stem": "依據丙表，白居易50歲購屋時，下列哪個房屋物件最符合他當時的身分？", "options": {"A": "五間九架豪華堂舍", "B": "緊鄰城東要道，堂舍五間七架", "C": "堂舍三間五架，格局方正", "D": "清新雅致三間四架堂舍"}, "answer": "B", "explain": "白居易50歲升為中書舍人，是五品官，依丙表「五品以上」可蓋到五間七架，(B)最符合。(A)五間九架是三品以上的規格，超過他的身分。(C)三間五架是六、七品以下的上限，不是最符合五品身分的。(D)三間四架是庶人的規格。", "skill": "查表題：先確定人物「當時」的身分（品級），再到表上找那一列，別用錯年紀的官職。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc110-32", "exam": "tc110", "nums": [32, 33, 34, 35], "form": "題組", "img": "img/tc110-32.png", "source": "屈原〈九歌‧少司命〉（簡媜《我為你灑下月光》、蔣勝男《羋月傳》引用）", "author": "屈原", "genre": "古典詩詞曲", "types": ["詩詞賞析", "比較閱讀", "文意推論"], "passage": "紛總總兮九州，何壽夭兮在予？（〈九歌‧大司命〉）\n秋蘭兮蘼蕪，羅生兮堂下。綠葉兮素華，芳菲菲兮襲予。\n秋蘭兮青青，綠葉兮紫莖。滿堂兮美人，忽獨與余兮目成。（〈九歌‧少司命〉）", "translation": "九州眾生紛紛擾擾，誰長壽誰短命，都掌握在我手中。\n秋天的蘭草和蘼蕪，茂密地長在堂下；綠色的葉子、白色的花，濃郁的香氣撲向我。\n秋蘭長得青翠茂盛，綠葉襯著紫色的莖。滿堂都是美人，(神)卻忽然單單和我眉目傳情、心意相通。", "keywords": [{"w": "總總", "m": "眾多紛雜"}, {"w": "壽夭", "m": "長壽與短命"}, {"w": "羅生", "m": "羅列叢生"}, {"w": "素華", "m": "白色的花"}, {"w": "襲", "m": "（香氣）侵入、撲來"}, {"w": "目成", "m": "以眉目傳情，彼此心意相通"}], "questions": [{"n": 32, "qtype": "單選", "stem": "甲文末尾的□□□□，若上承「忽獨與余兮目成」敘寫，最適當的詞語應是：", "options": {"A": "一見鍾情", "B": "一親芳澤", "C": "一顧傾城", "D": "一唱三嘆"}, "answer": "A", "explain": "「忽獨與余兮目成」是滿堂人中，忽然只和我四目相對、心意相通；甲文也說命中注定的兩人「無須繁複的鋪排」，在人群中一眼就認定對方，所以是(A)一見鍾情。(B)一親芳澤是親近女子，重點在身體接近，不是眼神相通。(C)一顧傾城形容女子美得讓人傾倒，只寫美貌，沒有雙方相通。(D)一唱三嘆形容詩文音樂優美、餘韻不絕，與情感無關。", "skill": "填空題要「上承」：先把引句翻成白話（一眼就心意相通），再找意思最貼的成語。"}, {"n": 33, "qtype": "單選", "stem": "依據乙文的描寫，下列圖示何者正確？（四圖分別標示少司命祠、高臺、祭壇、汨羅江與秦王駟的位置）", "options": {"A": "少司命祠前、汨羅江此岸為高臺，江的對岸為祭壇，秦王駟在祭壇附近", "B": "祭壇與高臺都在少司命祠這一側，秦王駟在江的另一側", "C": "祭壇在少司命祠這一側，高臺在江的對岸", "D": "高臺、祭壇與秦王駟都在江的對岸，與少司命祠隔江相望"}, "answer": "A", "explain": "乙文：「少司命祠前臨汩羅江處搭起一座高臺，高臺對岸是祭壇，人群圍在四周」，秦王駟在人群中遠遠看著。所以高臺要在祠前、江的這一側，祭壇在江的對岸，秦王駟在祭壇旁的人群中，(A)正確。(B)祭壇和高臺在同一側，不是「對岸」。(C)高臺跑到祠的對岸，不是「祠前」。(D)高臺不在祠前，祭壇也沒有和高臺隔江相對。", "skill": "文字轉地圖：先抓「定位詞」（前、對岸、四周），一個一個在圖上打勾。"}, {"n": 34, "qtype": "單選", "stem": "依據甲、乙二文，對於①、②的研判應是：①由甲文「詩中巫對神的追求」與乙文「齊聲歌舞迎神」可推知：〈少司命〉詞句會以巫祝口吻，表達對神的傾慕。②在乙文描述的祭典中，由羋月扮演巫祝，對黃歇扮演的神表達傾慕之情。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "C", "explain": "①甲文說「詩中巫對神的追求」，乙文寫巫祝們「齊聲歌舞迎神」唱出〈少司命〉詞句，可知詩是以巫祝的口吻表達對神的愛慕，正確。②乙文說「左為男祝，右為女祝」，羋月和黃歇各自上樓船，兩人都是巫祝；扮演大司命、少司命的是另外的「貴族男女」，所以說黃歇扮神是錯的。答案(C)。", "skill": "角色辨識題：把文中每個人「扮什麼」列成表，對照選項就不會被混淆。"}, {"n": 35, "qtype": "單選", "stem": "甲、乙二文皆引用「忽獨與余兮目成」，藉古典文學經營美感。關於二文運用此句的解讀，最不適當的是：", "options": {"A": "甲、乙二文皆從「忽獨與余兮目成」過渡到情竇敘寫", "B": "甲文藉「她」熟誦此句，表達愛情受命運擺布的感傷", "C": "乙文藉祭典中唱到此句，呼應羋月黃歇早已互有好感", "D": "乙文藉秦王駟聞見祭典唱到此句，觸發心儀羋月之情"}, "answer": "B", "explain": "(B)甲文說「她」喜愛這句，是因為它像命中注定的線索，讓兩人不必鋪排就能在人群中相遇，是對緣分的嚮往，並沒有「被命運擺布的感傷」，最不適當，選(B)。(A)甲文由此句寫命定的情事，乙文由此句寫羋月與黃歇四目含情，都由這句帶到情愛描寫，正確。(C)乙文說兩人「雖然情愫暗生」，唱到此句時「當真是獨與余兮目成」，正確。(D)秦王駟正好趕上這一節，心想「若這次聯姻楚國的公主是她便好了」，正確。", "skill": "「最不適當」題，最常見的錯法是情緒方向相反（嚮往說成感傷），先判斷原文的情緒是正向還是負向。"}], "difficulty": "中", "label": "110統測", "year": 110, "kind": "統測"}, {"id": "tc111-02", "exam": "tc111", "nums": [2], "form": "單題", "img": "img/tc111-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "", "translation": "(A)年少沒經歷過世事／客人高興地笑了，洗淨酒杯再斟酒。(B)使根本穩固／駝聽了說：很好，用這個名字稱呼我本來就很恰當。(C)舊習又出現／其餘的人也各自又邀請他到家裡，都拿出酒食款待。(D)正直有勇氣說話／如果滅掉鄭國對您有好處，那就冒昧地拿這件事來麻煩您的辦事人員。", "keywords": [{"w": "更", "m": "經歷；再"}, {"w": "固", "m": "使穩固；本來"}, {"w": "復", "m": "又、再"}, {"w": "敢", "m": "有勇氣；冒昧（謙詞）"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列各組「」內的字，何者意義相同？", "options": {"A": "少不「更」事／客喜而笑，洗盞「更」酌", "B": "深根「固」本／駝聞之，曰：甚善，名我「固」當", "C": "故態「復」萌／餘人各「復」延至其家，皆出酒食", "D": "正直「敢」言／若亡鄭而有益於君，「敢」以煩執事"}, "answer": "C", "explain": "(C)「故態復萌」是老毛病「又」出現；〈桃花源記〉「餘人各復延至其家」是其他人「又」各自邀漁人到家，兩個「復」都是「又、再」，正確。(A)「少不更事」的更是「經歷」；〈赤壁賦〉「洗盞更酌」是「再、重新」斟酒，不同。(B)「深根固本」的固是動詞「使穩固」；〈種樹郭橐駝傳〉「名我固當」是「本來」，不同。(D)「正直敢言」的敢是「有勇氣」；〈燭之武退秦師〉「敢以煩執事」的敢是謙詞「冒昧」，不同。", "skill": "成語裡的字義常保留古義，遇到字義比較題，先把成語翻成白話，再和課文句子逐字對照。"}], "difficulty": "易", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-08", "exam": "tc111", "nums": [8], "form": "單題", "img": "img/tc111-08.png", "source": "屈原〈漁父〉、蘇軾〈赤壁賦〉", "author": "屈原、蘇軾", "genre": "其他", "types": ["主旨寓意", "文意推論"], "passage": "聖人不凝滯於物，而能與世推移。世人皆濁，何不淈其泥而揚其波？眾人皆醉，何不餔其糟而歠其醨？……滄浪之水清兮，可以濯吾纓；滄浪之水濁兮，可以濯吾足。（〈漁父〉）\n蓋將自其變者而觀之，則天地曾不能以一瞬；自其不變者而觀之，則物與我皆無盡也，而又何羨乎！……惟江上之清風，與山間之明月，耳得之而為聲，目遇之而成色，取之無禁，用之不竭。（〈赤壁賦〉）", "translation": "聖人不會被外物拘束，能隨著世道變化而調整。世人都混濁，為什麼不攪動泥沙、揚起波浪（跟著一起）？眾人都醉了，為什麼不吃酒糟、喝薄酒（跟著一起）？……滄浪的水清，可以洗我的帽帶；滄浪的水濁，可以洗我的腳。\n如果從變的角度來看，天地連一眨眼的時間都不能保持不變；從不變的角度來看，萬物和我都是無窮無盡的，又有什麼好羨慕的呢！……只有江上的清風和山間的明月，耳朵聽到就成為聲音，眼睛看到就成為景色，取用沒人禁止，用也用不完。", "keywords": [{"w": "凝滯", "m": "拘泥、受束縛"}, {"w": "與世推移", "m": "隨世道變化而調整"}, {"w": "淈", "m": "攪混"}, {"w": "濯", "m": "洗"}, {"w": "纓", "m": "帽帶"}], "questions": [{"n": 8, "qtype": "單選", "stem": "下列「人生態度量表」，選「完全同意」至「完全不同意」依序得4至1分。若僅依〈漁父〉的「漁父」、〈赤壁賦〉的「蘇子」在文中字面所言，設想兩人回答此表的反應，則他們各自的5題分數總和，最可能落在哪個區間？（量表題目：1.我認為應該順應現實的人生際遇 2.我知道如何找到生活方式的平衡點 3.我知道人世間的事情是相對而非絕對 4.我認為堅守固定原則很重要，不應妥協 5.我不能預知命運，但懂得對變化泰然處之）", "options": {"A": "兩人均約5～10", "B": "兩人均約13～18", "C": "漁父約5～10；蘇子約13～18", "D": "漁父約13～18；蘇子約5～10"}, "answer": "B", "explain": "漁父說「聖人不凝滯於物，而能與世推移」，水清洗帽帶、水濁洗腳，主張順應、變通、看情況調整，所以第1、2、3、5題都會高分（3～4分），第4題「堅守原則不妥協」正是他勸屈原放下的態度，會拿低分（1分）。蘇子用「變」與「不變」兩種角度看世界，懂得相對；享受清風明月、隨遇而安，同樣第1、2、3、5題高分、第4題低分。兩人加起來大約都是13～18分，(B)正確。(A)(C)(D)把其中一人或兩人說成5～10分，等於說他們不認同順應、平衡、相對、泰然，和兩篇文字不合。", "skill": "人物性格量表題：先為每個人物下一個關鍵字（漁父＝與世推移，蘇子＝變與不變），再逐題判斷同意或不同意，最後才加總。"}], "difficulty": "中", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-09", "exam": "tc111", "nums": [9], "form": "單題", "img": "img/tc111-09.png", "source": "綜合（題辭）", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "出類拔萃　典範長存　鶯遷喬木　和氣致祥", "translation": "出類拔萃：才能遠遠超過同類。典範長存：逝者的模範永遠留存。鶯遷喬木：黃鶯從幽谷飛到高樹上，比喻遷居或升遷。和氣致祥：和睦融洽能招來吉祥。", "keywords": [{"w": "鶯遷喬木", "m": "語出《詩經‧小雅‧伐木》「出自幽谷，遷于喬木」，賀遷居、升遷"}, {"w": "典範長存", "m": "輓辭，用於哀悼"}], "questions": [{"n": 9, "qtype": "單選", "stem": "有些祝賀題辭可用於兩種不同情境。下圖有五種情境，直線兩端點間的選項，代表用於兩端情境的題辭，其中最不適當的是：（(A)連接「賀歌唱比賽優勝」與「賀獲選最佳球員」；(B)連接「賀升官」與「賀獲選最佳球員」；(C)連接「賀升官」與「賀搬新家」；(D)連接「賀新店開幕」與「賀搬新家」）", "options": {"A": "出類拔萃", "B": "典範長存", "C": "鶯遷喬木", "D": "和氣致祥"}, "answer": "B", "explain": "(B)「典範長存」是輓辭，用來哀悼過世的人，拿去賀升官、賀最佳球員非常失禮，最不適當，選(B)。(A)「出類拔萃」稱讚才能超群，歌唱比賽優勝、獲選最佳球員都適用。(C)「鶯遷喬木」出自《詩經》，黃鶯從山谷飛上高樹，可賀搬家，也可比喻升官。(D)「和氣致祥」說和睦能帶來吉祥，可賀新店開幕（和氣待客、生意興隆），也可賀新居。", "skill": "題辭題先把「喜事」和「喪事」分開：只要看到長存、千古、安息、典型等字，多半是輓辭，絕不能用在祝賀。"}], "difficulty": "易", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-10", "exam": "tc111", "nums": [10], "form": "單題", "img": "img/tc111-10.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "甲、開車時，則發票；車到時，則收票。\n乙、一則園子有專定之人修理，花木自有一年好似一年的，也不用臨時忙亂；二則也不至作踐，白辜負了東西。\n（說明框例句：凡鑑窪則照人面大。愛其子，擇師而教之，於其身也則恥師焉。朝暉夕陰，氣象萬千，此則岳陽樓之大觀也。）", "translation": "甲、火車開動時，就發票；車到站時，就收票。\n乙、一是園子有專人負責整理，花木自然一年比一年好，也不必臨時手忙腳亂；二是也不至於糟蹋，白白浪費了東西。\n（例句：凡是凹面鏡，就會把人臉照得大。愛自己的孩子，選擇老師來教他，對於自己，卻以向老師學習為恥。早晨陽光、傍晚陰暗，景象千變萬化，這就是岳陽樓的壯麗景觀。）", "keywords": [{"w": "則", "m": "就（表條件）；卻（表轉折）；是（表解釋）"}, {"w": "作踐", "m": "糟蹋"}], "questions": [{"n": 10, "qtype": "單選", "stem": "若參照下框「則」的用法說明（①表某條件下的狀態，相當於「就」；②表語意轉折，相當於「卻」；③表解釋，相當於「是」），下列甲、乙中的「則」，最適當的歸類是：", "options": {"A": "甲屬於①，乙屬於②", "B": "甲屬於①，乙屬於③", "C": "甲屬於②，乙屬於③", "D": "甲屬於③，乙屬於①"}, "answer": "B", "explain": "把「就／卻／是」代進去試讀。甲「開車時，則發票」：在開車的條件下「就」發票，屬①。乙「一則……二則……」：「一是……二是……」，在解釋理由，屬③。所以答案(B)。(A)乙沒有轉折語氣。(C)甲不是「卻」。(D)甲不是「是」，乙也不是「就」。", "skill": "虛詞歸類題最快的方法：把說明框裡的白話（就、卻、是）直接代入，哪個讀起來最順就是哪一類。"}], "difficulty": "中", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-14", "exam": "tc111", "nums": [14, 15], "form": "題組", "img": "img/tc111-14.png", "source": "周星譽《鷗堂日記》", "author": "周星譽", "genre": "筆記小品", "types": ["文意推論", "人物情感"], "passage": "五月二十五日丙戌，小暑，晴。申刻北風甚大，遂雨，有雷，傍晚霽，同寄公、季貺出門看荷花。行田埂上，雨後泥濘，失足落水中，雙踝皆沒，不覺自笑，從種花人周姓乞花三枝、蓮蓬一枝。歸，洗足早睡。鄉人種藕，以不花為豐年，蓋藕力盡泄於花，花愈多則藕愈瘦。今田中彌望如雪，為我曹吟賞計甚得矣，鄉人得無怨乎？種藕之家，藕為上利，葉次之，蓮子則不賣，賣亦不得價也。凡田上腴者，可兩年種藕，下此可一年，多則土瘠而收不豐，但可種荸薺耳。", "translation": "五月二十五日丙戌，小暑，晴天。下午申時北風很大，接著下雨，還打雷，傍晚雨停天晴，和寄公、季貺出門看荷花。走在田埂上，雨後泥濘，一腳踩空掉進水裡，兩個腳踝都淹沒了，忍不住自己笑起來，向種花的周姓人家討了三枝荷花、一枝蓮蓬。回家洗了腳早早睡了。鄉下人種藕，以不開花為豐年，因為藕的養分全洩到花上，花越多藕就越瘦。現在田裡放眼望去一片雪白，對我們吟詩賞花來說很好，鄉下人難道不抱怨嗎？種藕的人家，藕是最主要的收入，荷葉其次，蓮子則不賣，賣了也賣不到好價錢。凡是上等肥沃的田，可以連種兩年藕，次一等的只能種一年，種多了土地貧瘠收成就不好，只能改種荸薺了。", "keywords": [{"w": "申刻", "m": "申時，約下午三點到五點"}, {"w": "霽", "m": "雨停天晴"}, {"w": "乞", "m": "討、要"}, {"w": "蓋", "m": "因為"}, {"w": "泄", "m": "洩散"}, {"w": "彌望", "m": "滿眼望去"}, {"w": "我曹", "m": "我們"}, {"w": "得無……乎", "m": "難道不……嗎"}, {"w": "腴", "m": "肥沃"}], "questions": [{"n": 14, "qtype": "單選", "stem": "下列敘述，何者符合上文的記載？", "options": {"A": "觀荷當日，午後曾有雷陣雨", "B": "呼朋引伴，趕在雷雨前看荷", "C": "摘荷不慎，半身跌落泥水中", "D": "樂在賞荷，婉謝種花人饋贈"}, "answer": "A", "explain": "(A)「申刻北風甚大，遂雨，有雷」，申時是下午三到五點，午後有雷陣雨，正確。(B)他們是「傍晚霽」雨停後才出門，不是趕在雷雨前。(C)是走田埂「失足落水」，水只淹到「雙踝」（腳踝），不是摘荷時半身落水。(D)作者是主動向種花人「乞花三枝、蓮蓬一枝」，沒有婉拒。", "skill": "日記體先畫時間線：申刻→雨雷→傍晚霽→出門→落水→乞花→回家，選項的先後一對就知道真假。"}, {"n": 15, "qtype": "單選", "stem": "依據上文，作者對「田中彌望如雪」的感想為何？", "options": {"A": "讚許主人善栽荷花供遊客吟賞", "B": "猜想鄉人恐為蓮藕歉收而苦惱", "C": "希望種藕之家改種荸薺添獲利", "D": "慨歎人心遠不如荷花純淨高潔"}, "answer": "B", "explain": "作者先說「花愈多則藕愈瘦」，看到滿田荷花雪白一片，雖然對自己賞花很好，卻想到「鄉人得無怨乎」——鄉人恐怕要為藕收成不好而抱怨，(B)正確。(A)沒有讚美主人種得好，反而替主人擔心。(C)種荸薺是土地種藕太久變貧瘠後的退路，不是作者的建議。(D)文中沒有拿荷花和人心比較。", "skill": "「得無……乎」是委婉的推測（恐怕……吧），看到這個句型，作者的真正想法就在裡面。"}], "difficulty": "易", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-22", "exam": "tc111", "nums": [22, 23, 24], "form": "題組", "img": "img/tc111-22.png", "source": "沈起鳳《諧鐸》", "author": "沈起鳳", "genre": "寓言故事", "types": ["主旨寓意", "人物情感", "文意推論"], "passage": "蕭山陳景初，久客天津。後束裝歸里，路過山東界。時歲大饑，窮民死者無算。旅店蕭條，不留宿客。投止一寺院，見東廂積棺三十餘口，西廂一棺，巋然獨存。三更後，棺中盡出一手，皆焦瘦黃瘠者，惟西廂一手，稍覺肥白。陳素負膽力，左右顧盼，笑曰：「汝等窮鬼，想手頭窘矣，盡向我乞錢耶？」遂解青橐，各選一大錢予之。東廂鬼手盡縮，西廂一手伸出如故。陳曰：「一文錢恐不滿君意，吾當益之。」增至百數，兀然不動。陳怒曰：「是鬼太作喬，可謂貪得而無厭者矣！」竟提兩貫錢置其掌，鬼手頓縮。陳①之，移燈四照，見東廂之棺，皆書饑民某字樣；而西廂一棺，上書某縣典史某公之柩。固②曰：「饑民無大志，一錢便能滿願。而四公慣受書儀，不到其數不收也。」", "translation": "蕭山人陳景初，長年在天津作客。後來整理行李回鄉，經過山東境內。當時正逢大饑荒，窮苦百姓死了不計其數。旅店冷清，不肯留客人過夜。他只好投宿一座寺院，看見東廂房堆著三十多口棺材，西廂房只有一口棺材，孤零零地擺著。三更以後，每口棺材都伸出一隻手，都是乾枯瘦黃的，只有西廂那隻手稍微白胖。陳景初向來有膽量，左右看了看，笑著說：「你們這些窮鬼，想必手頭很緊，都向我討錢嗎？」就解開青布錢袋，每隻手挑一枚大錢給它。東廂的鬼手全縮回去了，西廂那隻手還像原來一樣伸著。陳景初說：「一文錢恐怕不合您的意，我再多給些。」加到一百文，那隻手還是一動也不動。陳景初生氣地說：「這鬼太會裝模作樣了，真是貪得無厭啊！」乾脆拿兩串錢放在它掌心，鬼手立刻縮回去。陳景初很驚訝，拿著燈四處照，看見東廂的棺材上都寫著「饑民某某」，而西廂那口棺材上寫著「某縣典史某公之柩」。於是感嘆說：「饑民沒有大志，一文錢就能滿足心願；這位老爺習慣收受紅包，沒到那個數目是不收的。」", "keywords": [{"w": "束裝", "m": "整理行裝"}, {"w": "歲大饑", "m": "年成大荒"}, {"w": "無算", "m": "無法計算，極多"}, {"w": "投止", "m": "投宿"}, {"w": "巋然", "m": "高聳獨立的樣子"}, {"w": "負膽力", "m": "有膽量"}, {"w": "青橐", "m": "青布錢袋"}, {"w": "作喬", "m": "裝模作樣"}, {"w": "典史", "m": "縣衙中掌管緝捕、監獄的小官"}, {"w": "書儀", "m": "送禮的錢財，即紅包"}], "questions": [{"n": 22, "qtype": "單選", "stem": "依據上文，下列敘述何者正確？", "options": {"A": "西廂棺材內為主人，東廂棺材內為下人", "B": "西廂鬼手需索無度，東廂鬼手不願乞討", "C": "東廂「鬼手盡縮」，係因只要食物不要錢", "D": "西廂「鬼手頓縮」，顯露急於占有的醜態"}, "answer": "D", "explain": "(D)一文、一百文都不收，直到兩貫錢放上去才「頓縮」，一拿到大錢立刻收手，寫出貪官急著把錢收進口袋的醜態，正確。(A)棺上寫的是「饑民」和「典史」，是百姓和小官，不是主人和下人。(B)東廂鬼手是伸手討錢的，拿到一文就滿足，不是不願乞討。(C)東廂鬼手拿到一文錢就縮回，說明它們要的就是錢，只是很容易滿足。", "skill": "對比寫法的故事，把兩組人（東廂／西廂）的「要多少、何時收手」並排比較，作者的褒貶就出來了。"}, {"n": 23, "qtype": "單選", "stem": "上文①、②分別填入哪一個詞語，最切合陳景初的感受？", "options": {"A": "訝／歎", "B": "歎／疑", "C": "疑／懼", "D": "懼／訝"}, "answer": "A", "explain": "①鬼手拿到兩貫錢才縮，陳景初覺得奇怪，於是「移燈四照」想查個究竟，此處填「訝」（驚訝）。②看了棺材上的字才明白真相，接著說出饑民和典史的對比，是感慨，填「歎」。所以(A)。(B)①不是感歎，他還沒弄懂原因。(C)(D)陳景初「素負膽力」，敢跟鬼開玩笑，不會「懼」；②是明白後的感慨，不是懷疑或驚訝。", "skill": "情緒填空看前後動作：後面接「去查看」多半是疑或訝，後面接「一番議論」多半是歎。"}, {"n": 24, "qtype": "單選", "stem": "上文對西廂棺木的描寫，旨在感慨：", "options": {"A": "富者愈富貧者愈貧", "B": "受災饑民流離失所", "C": "縣衙小吏弄錢成性", "D": "朝廷聚斂苛徵賦稅"}, "answer": "C", "explain": "西廂棺材裡是「某縣典史」，連死了都嫌一文錢太少，要兩貫錢才收，因為生前「慣受書儀，不到其數不收」，諷刺縣衙小官收紅包收成習慣，(C)正確。(A)重點不在貧富差距擴大。(B)饑民是東廂，題目問的是西廂。(D)典史是縣裡的小吏，文中沒有寫朝廷徵稅。", "skill": "諷刺題抓「身分＋行為」：棺材上寫的身分（典史）就是作者要罵的對象。"}], "difficulty": "易", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-28", "exam": "tc111", "nums": [28, 29, 30], "form": "題組", "img": "img/tc111-28.png", "source": "沈葆楨〈臺煤減稅片〉、劉璈〈詳論煤務屯銷利害由〉", "author": "沈葆楨、劉璈", "genre": "說理議論", "types": ["比較閱讀", "文意推論", "寫作手法"], "passage": "【甲】南北各省按日以煤炊爨，入冬以煤禦寒，若出口暢旺，煤價必昂，於民間不無窒礙。臺地則炊爨、禦寒均無藉於煤，除出口外，別無銷路。\n【乙】該礦（臺北煤礦）只開一處，每年已見煤百數十萬石，能值銀二十餘萬元，局用不過數萬兩，徒以存煤不銷，籌銷而未得其道，是以坐視上等之煤漸化為次等，次等之煤更化為下等，下等之煤一火自焚，不值一文，而更累及全埕之煤，且又添出盤棄搬運一切無名之費，指不勝屈，是本有大利，而轉為大害。苟能及時運籌，分別成色，廣其銷路，以每年出煤之數，衡厥用款，人不負礦，礦究何負於人？", "translation": "【甲】南北各省每天用煤燒飯，入冬用煤取暖，如果煤大量出口，煤價一定上漲，對百姓生活不是沒有妨礙。臺灣則燒飯、取暖都不靠煤，除了出口以外，沒有別的銷路。\n【乙】這座礦（臺北煤礦）只開採一處，每年已產煤一百幾十萬石，值銀二十多萬元，官局自己用不過幾萬兩，只因存煤賣不出去，想推銷又沒找到方法，所以眼睜睜看著上等煤漸漸變成次等，次等煤又變成下等，下等煤一著火就自燃，一文不值，還連累整個煤場的煤，又多出搬運、丟棄等各種名目不清的費用，多到數不完，這就是本來有大利，反而變成大害。如果能及時籌畫，分辨品質等級，擴大銷路，用每年的產煤量來衡量開支，人不辜負礦，礦又怎麼會辜負人呢？", "keywords": [{"w": "炊爨", "m": "燒火煮飯"}, {"w": "窒礙", "m": "阻礙"}, {"w": "無藉", "m": "不依靠"}, {"w": "坐視", "m": "眼睜睜看著不採取行動"}, {"w": "埕", "m": "堆放貨物的場地"}, {"w": "指不勝屈", "m": "扳著手指也數不完，形容很多"}, {"w": "運籌", "m": "籌畫"}, {"w": "成色", "m": "品質等級"}, {"w": "厥", "m": "其、那"}], "questions": [{"n": 28, "qtype": "單選", "stem": "下列何者最接近乙文「人不負礦，礦究何負於人」的想法？", "options": {"A": "民心向背，與煤無關", "B": "欲得煤利，先正民心", "C": "煤盡其用，民享其利", "D": "珍惜民力，煤不勝用"}, "answer": "C", "explain": "這句話是說：只要人好好經營、讓煤發揮用處（不辜負礦），礦自然會帶來利益（不會辜負人）。(C)「煤盡其用，民享其利」最接近，正確。(A)(B)乙文談的是經營銷售，沒有談民心。(D)文中沒有說要珍惜民力，「煤不勝用」也和存煤自燃、賣不出去的問題無關。", "skill": "「A不負B，B何負A」是互相回報的句型，翻成「你對它好，它就回報你」再去找選項。"}, {"n": 29, "qtype": "單選", "stem": "關於甲、乙二文的觀點，下列敘述何者正確？", "options": {"A": "甲文認為臺煤應以外銷為導向；乙文認為促銷臺煤宜積極行動", "B": "甲文認為臺煤應以外銷為導向；乙文認為促銷臺煤將所費不貲", "C": "甲文認為臺煤滯銷恐有礙民生；乙文認為促銷臺煤宜積極行動", "D": "甲文認為臺煤滯銷恐有礙民生；乙文認為促銷臺煤將所費不貲"}, "answer": "A", "explain": "甲文說會妨礙民生的是「南北各省」煤價上漲；臺灣本地不用煤，「除出口外，別無銷路」，所以臺煤應以外銷為主。乙文主張「及時運籌，分別成色，廣其銷路」，要積極推銷。(A)正確。(B)(D)乙文說的「無名之費」是存煤「不銷」造成的損失，不是說推銷很花錢。(C)(D)甲文沒有說臺煤滯銷會妨礙民生。", "skill": "兩個半句的選項，先判斷前半刪掉兩個，再判斷後半，四選一很快變二選一。"}, {"n": 30, "qtype": "單選", "stem": "關於甲、乙二文寫作手法的解說，何者最不適當？", "options": {"A": "甲文「南北各省……，臺地……」，以對比手法比較兩者差異", "B": "甲文「若出口暢旺……」，是提出一種假設的情況來推想結果", "C": "乙文「是以坐視上等之煤……更累及全埕之煤」，運用層層遞進的手法", "D": "乙文「人不負礦，礦究何負於人？」，為向對方徵求答案以解惑的疑問句"}, "answer": "D", "explain": "(D)「礦究何負於人？」是反問（激問），答案就在反面——礦不會辜負人，作者心中早有答案，不是向對方請教，最不適當，選(D)。(A)南北各省需要煤、臺灣不需要，是對比，正確。(B)「若出口暢旺，煤價必昂」是假設推論，正確。(C)上等→次等→下等→自焚→連累全埕，一層一層加重，是層遞，正確。", "skill": "問句分三種：真的不知道（疑問）、自問自答（設問）、答案在反面（激問）。公文、議論文結尾的問句幾乎都是激問。"}], "difficulty": "中", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-31", "exam": "tc111", "nums": [31, 32, 33, 34], "form": "題組", "img": "img/tc111-31.png", "source": "唐太宗《帝範‧審官》、劉基（篇名待查）", "author": "唐太宗、劉基", "genre": "說理議論", "types": ["比較閱讀", "主旨寓意", "文意推論"], "passage": "巧匠之制木，直者以為轅，曲者以為輪，長者以為棟梁，短者以為栱角。無曲直長短，各有所施。明主之任人，亦由是也。智者取其謀，愚者取其力，勇者取其威，怯者取其慎，無智愚勇怯，兼而用之。故良匠無棄材，明主無棄士。\n函牛之鼎，不可處以烹雞；捕鼠之貍，不可使以搏獸；一鈞之器，不能容以江漢之流；百石之車，不可滿以斗筲之粟。何則？大非小之量，輕非重之宜。（唐太宗）\n其取材也，惟其良，不問其所產。楓、柟、松、栝、杉、櫧、柞、檀無所不收，大者為棟為梁，小者為杙為栭，曲者為枅，直者為楹，長者為榱，短者為梲，非空中而液身者，無所不用。（劉基）", "translation": "巧匠處理木材，直的拿來做車轅，彎的做車輪，長的做棟梁，短的做斗栱和屋角。不論曲直長短，各有用處。英明的君主任用人才，也是這樣：聰明的用他的謀略，愚笨的用他的力氣，勇敢的用他的威猛，膽小的用他的謹慎，不論聰明、愚笨、勇敢、膽小，一併任用。所以好工匠沒有丟棄的木材，明君沒有閒置的人才。\n能裝下一頭牛的大鼎，不能拿來煮雞；捉老鼠的貓，不能派去和猛獸搏鬥；三十斤重的容器，裝不下長江漢水；能載百石的大車，不能只裝一斗一筲的小米。為什麼？大的不是小的容量能承受，輕的不適合擔負重的。\n他選取木材，只看品質好不好，不問產地。楓、柟、松、栝、杉、櫧、柞、檀沒有不收的，大的做棟做梁，小的做木樁、斗栱，彎的做柱上的橫木，直的做柱子，長的做椽子，短的做梁上短柱；只要不是中心空了、樹身朽爛的，沒有不用的。", "keywords": [{"w": "轅", "m": "車前駕牲口的直木"}, {"w": "施", "m": "用處"}, {"w": "由是", "m": "像這樣"}, {"w": "函", "m": "容納"}, {"w": "鈞", "m": "古代重量單位，三十斤"}, {"w": "斗筲", "m": "容量很小的器具"}, {"w": "楹", "m": "廳堂前的柱子"}, {"w": "榱", "m": "椽子"}], "questions": [{"n": 31, "qtype": "單選", "stem": "依據唐太宗、特雷默所述，何者是兩人共同的人事管理觀點？（特雷默：每個人的才能不同，都有可發揮之處。老闆要看到他們的優點，授予相應的職務。如果專長跟職務不相應，不但專長無法發揮，還會使同事們互不信服，衝突加劇。）", "options": {"A": "遴選原則：才德兼備", "B": "用人原則：適才適所", "C": "分工原則：一視同仁", "D": "升遷原則：進善黜惡"}, "answer": "B", "explain": "唐太宗說木材「各有所施」、人才「智者取其謀，愚者取其力」，大鼎不煮雞、貓不搏獸；特雷默說要依優點「授予相應的職務」。兩人都主張把對的人放在對的位置，(B)適才適所正確。(A)兩人都沒談品德。(C)「一視同仁」是一律平等對待，和「依特質分配不同工作」相反。(D)兩人沒談升遷與獎懲。", "skill": "找兩人共同觀點，先各自濃縮成四個字，再找交集；就像公司排班，讓會修機器的去修機器、會接待的去接待。"}, {"n": 32, "qtype": "單選", "stem": "依據下列劉基所述，他在同以「制木」為喻談人事管理時，較唐太宗又多一層思考的是：", "options": {"A": "無所不用應以良材為前提", "B": "樗櫟庸材有時比良材好用", "C": "大材小用的情況難免發生", "D": "材大難用的問題不易解決"}, "answer": "A", "explain": "唐太宗只說各種木材都有用處；劉基開頭就說「惟其良」，結尾又說「非空中而液身者，無所不用」——中空、朽爛的不用。也就是「無所不用」有個前提：必須是好木材，(A)正確。(B)劉基強調選良材，沒說庸材比較好用。(C)(D)劉基是說大小材各有所用，沒有談大材小用或材大難用的問題。", "skill": "「多一層思考」題，就找第二人有、第一人沒有的條件句（惟……、非……者）。"}, {"n": 33, "qtype": "單選", "stem": "下列是人事管理常談到的「彼得原理」（許多案例顯示：員工會從「適任」逐步升遷到「不適任」的位置。因為老闆常按績效或年資決定升遷，看似公平，但事實上，超級業務員可能欠缺管理能力，若當上主管，不僅不稱職而沒法繼續升遷，甚至會拉低部門整體績效）。若綜合上文唐太宗、特雷默所述，對「彼得原理」解讀最不適當的是：", "options": {"A": "若老闆能「勇者取其威，怯者取其慎」，員工應可處於「適任」狀態", "B": "當員工升遷到「不適任」的位置，情況頗近於「一鈞之器，容以江漢之流」", "C": "為減少特雷默擔心的「專長跟職務不相應」問題，老闆應「按績效或年資決定升遷」", "D": "特雷默不樂見的「同事們互不信服，衝突加劇」，部分原因可能來自部門中出現「彼得原理」案例"}, "answer": "C", "explain": "(C)彼得原理正是說「按績效或年資決定升遷」才會讓人升到不適任的位置，用它來減少「專長跟職務不相應」，等於拿病因當藥方，最不適當，選(C)。(A)依各人特質安排工作，就能讓員工適任，正確。(B)能力不夠卻擔大位，就像小容器裝江河之水，正確。(D)不稱職的主管會讓部屬不服、引發衝突，正確。", "skill": "綜合判斷題要先看清楚資料把什麼當「原因」，選項若把原因說成解方，通常就是錯的。"}, {"n": 34, "qtype": "單選", "stem": "依據下列「彼得原理」示意圖（圖中人物持同一根釣竿，從「業務」升到「課長」「襄理」「經理」，站的台子越來越高，釣到的魚越來越少，到經理時釣竿已碰不到水），研判①、②兩項推論，是否合理？①若員工的專長條件不變，採升職方式獎勵，容易形成「彼得原理」案例。②欲往高階職位發展的員工，應擴充專長，否則將成為「彼得原理」案例。", "options": {"A": "①、②皆合理", "B": "①、②皆不合理", "C": "①合理，②不合理", "D": "①不合理，②合理"}, "answer": "A", "explain": "圖中釣竿（專長）一直沒變長，台子（職位）越升越高，釣到的魚（績效）越來越少，最後完全釣不到。①專長不變卻一直升職，就會變成不適任，合理。②反過來說，想往上升就要把釣竿加長（擴充專長），否則會變成圖中的經理，合理。答案(A)。", "skill": "圖示題先找圖中的「符號對應」（釣竿＝專長、台子＝職位、魚＝績效），再把推論翻譯成圖上的變化來檢查。"}], "difficulty": "中", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc111-35", "exam": "tc111", "nums": [35, 36, 37, 38], "form": "題組", "img": "img/tc111-35.png", "source": "沈括《夢溪筆談》（與高羅佩《大唐狄公案》對讀）", "author": "沈括", "genre": "筆記小品", "types": ["比較閱讀", "文意推論", "寫作手法"], "passage": "歐陽公嘗得一古畫──牡丹叢其下有一貓，未知其精粗。丞相正肅吳公與歐公姻家，一見曰：「此正午牡丹也。何以明之？其花披哆而色燥，此日中時花也；貓眼黑睛如線，此正午貓眼也。」", "translation": "歐陽脩曾經得到一幅古畫，畫的是一叢牡丹，花下有一隻貓，他不知道這幅畫好不好。丞相吳育（諡正肅）和歐陽脩是親家，一看就說：「這是正午的牡丹。怎麼證明呢？花瓣張開下垂，顏色乾燥，這是中午時候的花；貓眼的黑瞳孔細得像一條線，這是正午時候的貓眼。」", "keywords": [{"w": "精粗", "m": "好壞、優劣"}, {"w": "姻家", "m": "兒女親家"}, {"w": "披哆", "m": "花瓣張開下垂"}, {"w": "黑睛", "m": "瞳孔"}], "questions": [{"n": 35, "qtype": "單選", "stem": "下列何者是從上文可明確獲悉的訊息？", "options": {"A": "狄仁傑察知玉鏡遭人毒殺", "B": "玉鏡宣講時真智留在現場", "C": "真智已向狄仁傑坦承犯行", "D": "孫天師上樓時殺真智滅口"}, "answer": "A", "explain": "(A)狄公明白說出「真智來與玉鏡喝茶，暗將毒藥撒入玉鏡的茶盅」，可知他已察覺玉鏡是被毒死的，正確。(B)文中只說真智離開時告訴門外道士，沒說玉鏡宣講時他在場。(C)真智還沒開口就墜樓了，沒有坦承。(D)孫天師可疑，但文中沒有明寫他殺人，不能「明確獲悉」。", "skill": "「明確獲悉」題只認原文白紙黑字，靠推理猜到的都不算。"}, {"n": 36, "qtype": "單選", "stem": "小說常透過人物神情的描寫，讓讀者感到不尋常，為下文預做鋪墊。在上文中，對哪個人物有如此安排？", "options": {"A": "真智", "B": "玉鏡", "C": "孫天師", "D": "狄仁傑"}, "answer": "C", "explain": "孫天師「瞥了真智一眼」「臉色慘白」「盯著狄公」「臉上有些惱意」，最後「捂著眼睛，不看狄公」，一連串神情都透著古怪，讓讀者懷疑他有問題，(C)正確。(A)真智幾乎沒有神情描寫就墜樓了。(B)玉鏡早已死亡，只在推理中出現。(D)狄仁傑是推理者，神情沒有刻意寫得異常。", "skill": "推理小說裡，作者多寫了幾次「臉色、眼神」的人，通常就是伏筆所在。"}, {"n": 37, "qtype": "單選", "stem": "關於上文寫作手法的分析，何者最不適當？", "options": {"A": "以「真智真人欲述一件舊事……」製造懸念，吸引讀者一探謎底", "B": "除「我推測事發日……」那段採回溯敘寫，整體以順時直敘為主", "C": "僅以言語、動作、表情反映人物的可能心緒，不做內心深入刻畫", "D": "透過角色的移動路線與周邊景物的描寫，襯托對話者的性格差異"}, "answer": "D", "explain": "(D)文中雖寫了上樓、露臺、書房的移動，但只是交代場景，沒有用景物來襯托人物性格的不同，最不適當，選(D)。(A)「欲述一件舊事」卻沒說是什麼事，引起好奇，是製造懸念，正確。(B)全文照時間順序寫，只有狄公推測案發經過那段是回頭講過去，正確。(C)全文只寫人物說什麼、做什麼、表情如何，沒有直接寫他們心裡想什麼，正確。", "skill": "寫作手法題逐項回原文「找證據」：找得到對應句子的才算對，找不到的（景物襯托性格）就是答案。"}, {"n": 38, "qtype": "單選", "stem": "上文借用下框文獻（《夢溪筆談》吳丞相論畫）以編寫情節。若對照二者提出①、②，最適當的研判是：①《夢溪筆談》中的吳丞相，推斷的是「畫中物體所處的時間」，而非「繪圖者作畫的時間」。②《大唐狄公案》中的狄仁傑，是以「畫中物體所處的時間」即「繪圖者作畫的時間」做為推斷案情的基礎。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "A", "explain": "①吳丞相看花瓣張開、貓瞳如線，判斷畫的是「正午的牡丹和貓」，說的是畫中景物的時間，並沒有說畫家何時作畫，正確。②狄仁傑說玉鏡很重視細節描繪，看到最後一幅畫的貓瞳仁很大（不是正午），就斷定「作畫時間絕非如真智所言」，等於把畫中的時間當成作畫的時間，正確。答案(A)。", "skill": "文白對讀時，先把文言材料的「推論依據」和「結論」各抓出來，再看白話文借用了哪一部分、又改了哪一部分。"}], "difficulty": "中", "label": "111統測", "year": 111, "kind": "統測"}, {"id": "tc112-02", "exam": "tc112", "nums": [2], "form": "單題", "img": "img/tc112-02.png", "source": "《莊子‧養生主》", "author": "莊子", "genre": "寓言故事", "types": ["典故出處", "字詞解釋"], "passage": "技經肯綮之未嘗，而況大軱乎！", "translation": "（我的刀）連經絡相連、筋骨盤結的地方都不曾碰過，更何況是大骨頭呢！", "keywords": [{"w": "肯綮", "m": "筋骨結合的地方，比喻事情的要害、關鍵"}, {"w": "軱", "m": "大骨"}], "questions": [{"n": 2, "qtype": "單選", "stem": "《射雕英雄傳》：「郭靖把南山刀法使發了，已不用顧盼擬合，信手而應，縱橫前後，悉逢肯綮。」文中「肯綮」的意思、典故出處依序是：", "options": {"A": "關鍵／莊子〈庖丁解牛〉", "B": "關鍵／左傳〈燭之武退秦師〉", "C": "時機／莊子〈庖丁解牛〉", "D": "時機／左傳〈燭之武退秦師〉"}, "answer": "A", "explain": "「肯綮」原指筋骨結合的地方，出自《莊子‧養生主》庖丁解牛「技經肯綮之未嘗」，後來比喻要害、關鍵。郭靖刀法「悉逢肯綮」，就是每一刀都打在要害上。所以意思是「關鍵」、出處是〈庖丁解牛〉，(A)正確。(B)(D)〈燭之武退秦師〉講的是燭之武說服秦伯退兵，沒有「肯綮」。(C)(D)「時機」講的是時間點，肯綮講的是位置、要害，意思不對。", "skill": "成語典故題，回想課文中「最有畫面的那一段」：庖丁的刀遊走在骨節縫隙之間，肯綮就是那些關鍵部位。"}], "difficulty": "易", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-03", "exam": "tc112", "nums": [3], "form": "單題", "img": "img/tc112-03.png", "source": "綜合（清代章程與明清小說）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "客位貨物，不准以多報少；倘有此弊，定即議罰革退不用。", "translation": "乘客的貨物，不准把多的報成少的；如果有這種舞弊，一定立刻議定處罰，革職、不再任用。", "keywords": [{"w": "客位", "m": "乘客"}, {"w": "倘", "m": "如果"}, {"w": "革退", "m": "革職辭退"}, {"w": "不用", "m": "題幹中為「不任用」"}], "questions": [{"n": 3, "qtype": "單選", "stem": "下列文句的「不用」，何者與「客位貨物，不准以多報少；倘有此弊，定即議罰革退不用」的「不用」，意義最接近？", "options": {"A": "闞澤大呼曰：若「不用」陸伯言，則東吳休矣", "B": "三藏道：「不用」化齋，我那包袱裡還有些乾糧", "C": "花木自有一年好似一年的，也「不用」臨時忙亂", "D": "你向那差人說，我得了暴病，請鄧老爺「不用」來"}, "answer": "A", "explain": "題幹說員工舞弊就「革退不用」，被開除、不再「任用」。(A)《三國演義》闞澤說如果「不任用」陸遜，東吳就完了，「不用」是不任用，正確。(B)《西遊記》三藏說「不必」去化齋，包袱裡還有乾糧。(C)《紅樓夢》說花木有人照顧，也「不必」臨時忙亂。(D)請鄧老爺「不必」來。(B)(C)(D)都是「不必」，和題幹不同。", "skill": "「不用」古今兩義：不任用（古）與不必（今）。看前後有沒有「人」被用或不被用，就能分辨。"}], "difficulty": "易", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-04", "exam": "tc112", "nums": [4], "form": "單題", "img": "img/tc112-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "虛詞句式"], "passage": "甲、北通巫峽，南極瀟湘，遷客騷人，多會於此。（范仲淹〈岳陽樓記〉）\n乙、寶釵道：「……如此一行，你們辦的又至公，於事又甚妥。」李紈、平兒都道：「是極。」（《紅樓夢》）\n（說明框例句：無所不用其極。足以極視聽之娛。初極狹，纔通人。）", "translation": "甲、（洞庭湖）北邊通到巫峽，南邊直達瀟水、湘水的盡頭，被貶的官員和詩人，大多在這裡聚會。\n乙、李紈、平兒都說：「對極了。」\n（例句：沒有一處不用盡心力。足以窮盡耳目的享受。一開始非常狹窄，只能讓一個人通過。）", "keywords": [{"w": "極", "m": "①名詞，盡頭 ②動詞，窮盡、到達盡頭 ③副詞，很、非常"}, {"w": "遷客騷人", "m": "被貶的官員與詩人"}], "questions": [{"n": 4, "qtype": "單選", "stem": "參照右框「極」的用法說明（①〔名詞〕盡頭。如：無所不用其極。②〔動詞〕窮盡。如：足以極視聽之娛。③〔副詞〕很，非常。如：初極狹，纔通人。），下列甲、乙中的「極」，最適當的歸類是：", "options": {"A": "甲屬於①，乙屬於②", "B": "甲屬於②，乙屬於①", "C": "甲屬於②，乙屬於③", "D": "甲屬於③，乙屬於①"}, "answer": "C", "explain": "甲「北通巫峽，南極瀟湘」和「通」對稱，「極」是動詞：往南直達瀟湘的盡頭，屬②。乙「是極」就是「對極了、很對」，「極」修飾「是」，表程度，屬③副詞。所以(C)。(A)甲不是名詞「盡頭」，乙也不是動詞。(B)乙不是名詞。(D)甲不是副詞，乙也不是名詞。", "skill": "詞性判斷看「位置」：和動詞對仗的是動詞（通／極），放在形容詞旁加強程度的是副詞。"}], "difficulty": "中", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-05", "exam": "tc112", "nums": [5], "form": "單題", "img": "img/tc112-05.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "虛詞句式"], "passage": "", "translation": "(A)我愚笨的見解，不知道恰不恰當。(B)但是鄭國滅亡，對您也有不利的地方。(C)這是正午的牡丹。怎麼證明呢？(D)為什麼最初創造船和車的人，反而得不到後人祭祀的報答呢？", "keywords": [{"w": "何其", "m": "為什麼那麼……"}, {"w": "尸祝", "m": "主持祭祀的人，此指祭祀"}, {"w": "報", "m": "報答、酬謝"}], "questions": [{"n": 5, "qtype": "單選", "stem": "下列文句，何者以反問語氣表達慨歎之意？", "options": {"A": "愚昧之見，是否有當", "B": "然鄭亡，子亦有不利焉", "C": "此正午牡丹也。何以明之", "D": "何其始造舟車者，不食尸祝之報也"}, "answer": "D", "explain": "(D)「何其……也」用問句說出「最初造船造車的人，竟然得不到祭祀報答」，答案就在問句裡，是感嘆功勞被遺忘，屬反問慨歎，正確。(A)是謙虛地請教「是否恰當」，真心等對方回答，屬詢問，沒有慨歎。(B)〈燭之武退秦師〉這句是直述句，分析利害。(C)《夢溪筆談》吳丞相先問「何以明之」再自己回答，是設問。", "skill": "問句三分法：等人回答＝詢問；自問自答＝設問；答案在反面、帶情緒＝反問（激問）。「何其……也」常帶感嘆。"}], "difficulty": "中", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-10", "exam": "tc112", "nums": [10], "form": "單題", "img": "img/tc112-10.png", "source": "綜合（李清照、蘇軾）", "author": "", "genre": "古典詩詞曲", "types": ["文化常識", "詩詞賞析"], "passage": "", "translation": "", "keywords": [{"w": "婉約", "m": "詞風含蓄柔美，以李清照為代表"}, {"w": "豪放", "m": "詞風開闊奔放，以蘇軾為代表"}, {"w": "笠屐", "m": "斗笠與木屐"}], "questions": [{"n": 10, "qtype": "單選", "stem": "在「古畫動起來」展覽中，若要讓〈李清照酴醿春去圖〉（左）、〈東坡笠屐圖〉（右）的人物跨時代對話，依據畫題、畫面及兩人作品的相關認知，下列對話內容，設計不適當的是：", "options": {"A": "（李清照）後世的人讀詞，常說我是婉約詞的代表，你是豪放詞的代表", "B": "（蘇軾）但我的詞不受音律束縛，完全無法入樂演唱，是個缺點", "C": "（李清照）後世把你畫成戴斗笠、穿木屐的模樣，應是想凸顯你即使遇到雨天或困境，仍懂得自我調適", "D": "（蘇軾）相較於我是戴笠穿屐，你聞花惜春，既符合女性感覺細膩的形象，也給人你的詞多含蓄溫柔的暗示"}, "answer": "B", "explain": "(B)蘇軾填詞確實較不拘泥音律，但不是「完全無法入樂」，他的詞仍可演唱，例如有人說他的〈念奴嬌〉要「關西大漢，執鐵板」來唱，所以「完全無法入樂演唱」說錯了，選(B)。(A)李清照是婉約派代表、蘇軾是豪放派代表，正確。(C)〈東坡笠屐圖〉畫的是蘇軾在海南遇雨，借斗笠木屐回家的樣子，表現他身處困境仍曠達自適，正確。(D)李清照手拈花朵、惜春的畫面，符合她細膩柔婉的詞風，正確。", "skill": "文學常識題遇到「完全」「絕對」「從未」這類極端字眼，要特別警覺，常常就是錯的地方。"}], "difficulty": "易", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-18", "exam": "tc112", "nums": [18, 19, 20, 21], "form": "題組", "img": "img/tc112-18.png", "source": "袁宏道《瓶史》、張謙德《瓶花譜》", "author": "袁宏道、張謙德", "genre": "筆記小品", "types": ["比較閱讀", "文意推論", "句意理解"], "passage": "插花不可太繁，亦不可太瘦，多不過二種三種，高低疏密，如畫苑布置，方妙。置瓶忌一律，忌以繩束縛。夫花之所謂整齊者，正以參差不倫，意態天然，如子瞻之文，隨意斷續，青蓮之詩，不拘對偶，此真整齊也。若夫枝葉相當，紅白相配，此省曹墀下樹，墓門華表也，惡得為整齊哉！（袁宏道《瓶史》）\n大率插花須要花與瓶稱，令花稍高於瓶。假如瓶高一尺，花出瓶口一尺三四寸，瓶高六七寸，花出瓶口八九寸，乃佳。忌太高，太高瓶易仆；忌太低，太低雅趣失。小瓶插花，宜瘦巧，不宜繁雜。若止插一枝，須擇枝柯奇古，屈曲斜裊者。欲插二種，須分高下合插，儼若一枝天生者；或兩枝彼此各向，先湊簇像生，用麻絲縛定插之。（張謙德《瓶花譜》）", "translation": "插花不能太繁多，也不能太稀疏，最多不超過兩三種，高低疏密的安排像畫院作畫的構圖，才算美妙。擺放花瓶忌諱一成不變，忌諱用繩子捆綁。所謂花的整齊，正是在於參差不齊、姿態自然，就像蘇軾的文章隨意斷續，李白的詩不拘對偶，這才是真正的整齊。如果枝葉兩兩對稱、紅白刻意搭配，那就像官署臺階下排排站的樹、墳墓前成對的華表，怎能算是整齊呢！\n大致說來，插花要花和瓶相稱，讓花稍微高過瓶子。例如瓶高一尺，花露出瓶口一尺三四寸；瓶高六七寸，花露出瓶口八九寸，才好看。忌太高，太高瓶子容易倒；忌太低，太低就失去雅趣。小瓶插花，適合瘦巧，不適合繁雜。如果只插一枝，要選枝幹奇特古雅、彎曲斜垂的；想插兩種，要分出高低一起插，看起來像一枝天然長成的；或者兩枝各朝不同方向，先湊攏成自然生長的樣子，再用麻絲綁好插進去。", "keywords": [{"w": "畫苑", "m": "畫院，指繪畫構圖"}, {"w": "一律", "m": "一成不變、同一樣式"}, {"w": "參差不倫", "m": "長短不齊、不一致"}, {"w": "子瞻", "m": "蘇軾"}, {"w": "青蓮", "m": "李白（號青蓮居士）"}, {"w": "省曹墀下樹", "m": "官署臺階下排列整齊的樹"}, {"w": "華表", "m": "立在墓前、宮殿前成對的石柱"}, {"w": "惡", "m": "怎麼"}, {"w": "大率", "m": "大致"}, {"w": "仆", "m": "倒下"}], "questions": [{"n": 18, "qtype": "單選", "stem": "依據上列資料（宏道流簡介、《宏道流插華圖 附瓶史國字觧》封面：文化六年己巳秋開彫，徚雲齋先生觧，諸先生合編；圖書館藏書目錄：《瓶史國字觧》，袁宏道作，桐谷鳥習註觧，文化6年（1809）出版，書誌註記有文化5年龜田鵬齋〈序〉、文化5年藤雲齋（望月義達）〈序〉），下列敘述何者錯誤？", "options": {"A": "徚雲齋先生即桐谷鳥習", "B": "望月義想曾為《瓶史國字觧》寫序", "C": "《宏道流插花圖》開彫時，《瓶史》在日本已刊行約百年", "D": "《瓶史國字觧》或單獨出版，或與《宏道流插花圖》合併出版"}, "answer": "B", "explain": "(B)目錄記載的兩篇序，是龜田鵬齋和「藤雲齋（望月義達）」寫的；望月義想號「梨雲齋」，而且1804年就過世了，不可能為1808年（文化5年）的書寫序，說法錯誤，選(B)。(A)封面寫「徚雲齋先生觧」，目錄寫「桐谷鳥習註觧」，註解者是同一人，正確。(C)封面「文化六年」開彫是1809年，《瓶史》1696年在日本出版，相隔一百多年，約百年，正確。(D)目錄有單獨的《瓶史國字觧》，封面又是「宏道流插華圖 附瓶史國字觧」，兩種出版方式都有，正確。", "skill": "書目資料題就像查證件：名字、別號、生卒年、出版年逐一核對，年代對不上的就是錯。"}, {"n": 19, "qtype": "單選", "stem": "依據下列《瓶史》文字，何者最可能是宏道流的看法？", "options": {"A": "型態不拘繁簡", "B": "美感來自參差", "C": "布局忌如畫苑", "D": "整齊無非對稱"}, "answer": "B", "explain": "宏道流以《瓶史》為根據。《瓶史》說真正的整齊在於「參差不倫，意態天然」，(B)美感來自參差，正確。(A)《瓶史》說「不可太繁，亦不可太瘦」，對繁簡是有要求的。(C)原文是「如畫苑布置，方妙」，要像畫院構圖才好，不是忌諱。(D)原文說枝葉對稱、紅白相配像「墓門華表」，算不上整齊，和「整齊就是對稱」相反。", "skill": "「最可能是某人的看法」，就找原文中作者用「真、正、方妙」等字肯定的那一句。"}, {"n": 20, "qtype": "單選", "stem": "下列《瓶花譜》文字，與上列《瓶史》的相同觀點為何？", "options": {"A": "瓶身宜瘦巧，瓶高與瓶口相稱", "B": "枝葉任其自然，不可人為加工", "C": "樹枝須曲斜，否則如墓門華表", "D": "用兩種以上花材，應高低搭配"}, "answer": "D", "explain": "《瓶花譜》說「欲插二種，須分高下合插」，《瓶史》說「多不過二種三種，高低疏密」，兩書都主張多種花材要有高低變化，(D)正確。(A)《瓶花譜》說的是「花」與瓶相稱、小瓶插花宜瘦巧，不是瓶身瘦巧、瓶高與瓶口相稱。(B)《瓶花譜》說要「用麻絲縛定」，有人為加工；《瓶史》才說忌以繩束縛，兩書這點反而不同。(C)「屈曲斜裊」只是《瓶花譜》說插一枝時的選材；「墓門華表」是《瓶史》批評對稱，兩者沒有連在一起。", "skill": "比較兩文相同點：每個選項都要「兩邊各找到一句」才成立，只在一邊出現或兩邊說法相反的都刪。"}, {"n": 21, "qtype": "單選", "stem": "甲、乙二圖出自《宏道流插花圖》（甲圖：梅與水仙，分插在高低不同的兩件花器；乙圖：富士松與菊插於一瓶，枝幹高出瓶身數倍），若就整體型態觀察，對①、②的研判應是：①甲圖符合《瓶史》「種類」與「置瓶」的觀點。②乙圖符合《瓶花譜》「花與瓶稱」與「欲插兩種」的觀點。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "C", "explain": "①甲圖只用梅和水仙兩種花，合乎《瓶史》「多不過二種三種」；兩件花器一高一低、樣式不同，合乎「置瓶忌一律」，正確。②乙圖用富士松和菊兩種、分高低合插，合乎「欲插二種」；但枝幹高出瓶子好幾倍，《瓶花譜》要「花稍高於瓶」（瓶高一尺，花出一尺三四寸），乙圖不合「花與瓶稱」，所以②錯誤。答案(C)。", "skill": "一個判斷包含兩個條件時，兩個都要成立才算對；只要有一個不合就整句錯。"}], "difficulty": "難", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-22", "exam": "tc112", "nums": [22, 23], "form": "題組", "img": "img/tc112-22.png", "source": "古代律文罰則（應改寫自《唐律疏議‧廄庫律》，待查）", "author": "", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "一、殺他人馬牛者，笞七十，徒一年半。傷而不堪乘用，笞五十，賠減價。價不減者，笞三十。【註】減價，謂畜產值十貫，殺訖唯值兩貫，即減價八貫。價不減者，謂雖有殺傷，仍值原價，笞三十，無所賠償。\n二、殺傷他人豬羊等畜者，賠減價。價不減者，笞三十。\n三、任犬殺傷他人畜產者，賠減價。價不減者，笞二十。", "translation": "一、殺死別人的馬或牛，打七十下竹板，判勞役一年半。打傷到不能騎乘使用，打五十下，並賠償減少的價值。價值沒有減少的，打三十下。【註】減價：例如牲畜原值十貫，被殺後只值兩貫，就是減價八貫。價不減：雖然被殺傷，仍值原價，打三十下，不必賠償。\n二、殺傷別人的豬、羊等牲畜，賠償減少的價值。價值沒減少的，打三十下。\n三、放任狗去殺傷別人的牲畜，賠償減少的價值。價值沒減少的，打二十下。", "keywords": [{"w": "笞", "m": "用竹板打的刑罰"}, {"w": "徒", "m": "徒刑，罰做勞役"}, {"w": "不堪乘用", "m": "不能再騎乘使用"}, {"w": "減價", "m": "減少的價值"}, {"w": "訖", "m": "完畢"}, {"w": "任", "m": "放任"}], "questions": [{"n": 22, "qtype": "單選", "stem": "關於上列罰則的理解，何者最適當？", "options": {"A": "殺或傷他人馬牛，必處以徒刑", "B": "殺他人畜產，皆可以受笞代替賠錢", "C": "傷他人馬牛以外畜產，須賠償他人損失或受笞", "D": "殺他人畜產，罰責由重至輕為馬牛＞豬羊＞犬"}, "answer": "C", "explain": "(C)第二條：殺傷豬羊等畜，價值減少就「賠減價」，沒減少就「笞三十」，所以不是賠錢就是挨打，正確。(A)只有「殺」馬牛才判徒刑一年半；「傷」馬牛只有笞刑和賠償。(B)價值有減少就要賠，只有「價不減」時才是挨打不賠，並不能隨意用挨打代替賠錢。(D)第三條是「放任狗去」殺傷別人的牲畜，狗是加害的一方，不是被殺的牲畜，不能這樣排序。", "skill": "法條題要分清「行為」（殺／傷／任犬）和「對象」（馬牛／豬羊），一條一條對號入座，就像看公司的獎懲辦法。"}, {"n": 23, "qtype": "單選", "stem": "依據罰則（小吳：「大人，他砍傷我家的馬，害我只好把原來值二十貫的馬，用十貫賣了。」小周：「大人，是他的惡犬先咬死我家的羊。雖然羊還是能賣原本值的十貫錢，但我嚥不下這口氣。」），對小吳的處罰應是：", "options": {"A": "笞二十", "B": "笞三十", "C": "賠小周十貫", "D": "笞五十並賠小周十貫"}, "answer": "A", "explain": "小吳犯的是：他家的狗咬死小周的羊，屬第三條「任犬殺傷他人畜產」；羊「還是能賣原本值的十貫」，價值沒減少，所以「笞二十」，不必賠，(A)正確。(B)笞三十是自己動手殺傷豬羊、價不減的罰則，不適用。(C)羊價沒減少，不用賠。(D)笞五十並賠十貫，是小周砍傷小吳的馬（二十貫降成十貫）該受的處罰，搞錯對象了。", "skill": "案例套法條，先問三件事：誰做的？用什麼方式？對象價值有沒有減少？三個答案一出來，罰則就定了。"}], "difficulty": "中", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-24", "exam": "tc112", "nums": [24, 25, 26, 27], "form": "題組", "img": "img/tc112-24.png", "source": "馮夢龍《智囊》", "author": "馮夢龍", "genre": "筆記小品", "types": ["文意推論", "人物情感", "字詞解釋"], "passage": "嘉靖間，一士人候選京邸。有官矣，然久客橐空，欲貸千金，與所故遊客談。數日報命，曰：「某中貴允爾五百。」士人猶恨少，客曰：「凡貸者例以厚贄先。內相性喜諛，苟得其歡，即請益非難也。」士人拮据，湊貸器幣，約值百金，為期入謁及門。堂軒巨麗，蒼頭、廬兒皆曳綺縞，兩壁米袋充棟，皆有「御用」字。久之，主人出，壯橫肥，以兩童子頭抵背而行，享禮微笑，許貸八百。廬兒曰：「已晚，須明日。」主人可之。士人既出，喜不自勝，客復屬耳：「當早至，我俟於此。」及明往，寥然空宅，堂下煤土兩堆，皆袋所傾。問主宅者，曰：「昨有內相賃宅半日，知是誰何？」客亦滅跡，方悟其詐。", "translation": "明朝嘉靖年間，有位讀書人在京城住所等候分派官職。官職已經有了，但長期作客、錢袋空空，想借一千兩銀子，就去找以前有來往的一位門客商量。過了幾天，門客回報說：「某位宦官答應借你五百兩。」讀書人還嫌少，門客說：「凡是借錢的人，照慣例要先送厚禮。這位內相生性喜歡人奉承，如果能討他歡心，再請他多借一些並不難。」讀書人手頭很緊，東湊西借弄來器物錢幣，大約值一百兩，約好日期登門拜見。到了門口，只見廳堂高大華麗，僕役都穿著絲綢，兩邊牆壁堆滿米袋直到屋梁，袋上都印著「御用」二字。過了很久，主人才出來，身材高大肥胖，由兩個童子用頭頂著他的背走路，收下禮物微微一笑，答應借八百兩。僕人說：「天色已晚，要等明天。」主人同意了。讀書人出來後高興得不得了，門客又湊到耳邊說：「明天要早點來，我在這裡等你。」等到第二天前往，卻是一座空蕩蕩的宅子，堂下有兩堆煤土，都是從那些袋子倒出來的。問屋主，屋主說：「昨天有位內相租這座宅子半天，誰知道他是誰？」門客也不見蹤影，讀書人這才明白自己被騙了。", "keywords": [{"w": "候選", "m": "等候分派官職"}, {"w": "橐", "m": "錢袋"}, {"w": "貸", "m": "借"}, {"w": "報命", "m": "回覆"}, {"w": "中貴、內相", "m": "宦官"}, {"w": "贄", "m": "初次見面送的禮物"}, {"w": "請益", "m": "請求增加"}, {"w": "拮据", "m": "手頭緊、缺錢"}, {"w": "曳綺縞", "m": "穿著華美的絲綢"}, {"w": "享禮", "m": "接受禮物"}, {"w": "屬耳", "m": "附耳低語"}, {"w": "俟", "m": "等候"}, {"w": "賃", "m": "租"}], "questions": [{"n": 24, "qtype": "單選", "stem": "關於上文的理解，何者最適當？", "options": {"A": "因不想讓朋友為難，士人只好出面向內相借錢", "B": "士人前往拜謁的內相邸，實際上是皇家的糧倉", "C": "內相邸的陳設與僮僕，提高了士人對出借方的信任", "D": "當士人再次前往內相邸取借款，宅院已經租給他人"}, "answer": "C", "explain": "(C)廳堂華麗、僕人穿絲綢、滿牆印著「御用」的米袋，主人排場十足，讓士人深信對方真有錢，才高興地付了厚禮，正確。(A)是士人自己缺錢要借，不是替朋友出面。(B)那裡是騙子租來的民宅，米袋裡裝的其實是煤土，不是皇家糧倉。(D)屋主說「昨有內相賃宅半日」，宅子只被騙子租了半天，隔天是空宅，不是又租給別人。", "skill": "詐騙故事看「道具」：作者特別描寫的排場、標記，通常就是騙子取信於人的手段。"}, {"n": 25, "qtype": "單選", "stem": "依據上文，廬兒、客對士人說的話（廬兒曰：「已晚，須明日。」客復屬耳：「當早至，我俟於此。」），主要用意為何？", "options": {"A": "廬兒：拖延時間以便潛逃；客：讓士人相信隔天定可拿到錢", "B": "廬兒：拖延時間以便潛逃；客：讓士人不好意思不出面取錢", "C": "廬兒：利用時間找人頂罪；客：讓士人相信隔天定可拿到錢", "D": "廬兒：利用時間找人頂罪；客：讓士人不好意思不出面取錢"}, "answer": "A", "explain": "禮物已經收了，騙子不能真的給錢，僕人說「已晚，須明日」是拖延，好讓他們連夜撤走；門客附耳叮嚀「當早至，我俟於此」，裝出一副明天一定拿得到錢的樣子，穩住士人。所以(A)正確。(C)(D)文中沒有找人頂罪的情節。(B)(D)士人本來就急著拿錢，門客不必讓他「不好意思不來」，而是要讓他放心、不起疑。", "skill": "分析騙子的台詞，問一句「這句話對騙子有什麼好處？」就能看出真正用意。"}, {"n": 26, "qtype": "單選", "stem": "依據上文與下圖（小心因這樣而受騙！①達克效應：自認為很聰明，不會上別人的當。②隧道效應：因急迫而只就當下訊息做決定，思慮不周。③貪多心理：想得更多、貪小便宜而受騙。④需求心理：真實需求遭人利用而受騙。⑤同情心理：同情他人遭遇而受騙。⑥恐懼心理：害怕政府、法律而受騙。），哪些是士人受騙的原因？", "options": {"A": "①③⑤", "B": "②③④", "C": "①②④⑥", "D": "②③④⑤"}, "answer": "B", "explain": "士人「久客橐空」急著要錢，看到排場就相信，沒有多查證，是②隧道效應；別人答應借五百他「猶恨少」，聽說送禮可以多借，就湊錢送厚禮，是③貪多心理；他真的缺錢，這個需求被騙子利用，是④需求心理。①文中沒寫他自認聰明；⑤他沒有同情誰；⑥他也沒有害怕官府或法律。所以(B)。", "skill": "心理清單題：把清單每一項都拿去原文找「行為證據」，找得到才勾選。"}, {"n": 27, "qtype": "單選", "stem": "依據上文，下列各組「」內詞語的意義，何者相同？", "options": {"A": "與所「故」遊客談／「故」列敘時人，錄其所述", "B": "某中貴允「爾」五百／官命促「爾」耕，勗爾植", "C": "為期入謁「及」門／指爪「及」碗唇上皆可為之", "D": "苟得其歡，即請「益」非難也／聖「益」聖，愚益愚"}, "answer": "B", "explain": "(B)「允爾五百」是答應借「你」五百；〈種樹郭橐駝傳〉「官命促爾耕」是官府命令督促「你們」耕種，兩個「爾」都是第二人稱「你（們）」，相同，正確。(A)「所故遊客」的故是「舊日、以前的」；〈蘭亭集序〉「故列敘時人」的故是「所以」，不同。(C)「及門」的及是「到達」；「指爪及碗唇上」的及是「和」，不同。(D)「請益」的益是動詞「增加」；〈師說〉「聖益聖」的益是副詞「更加」，不同。", "skill": "字義比較題把每個字換成白話代回原句：故（舊／所以）、及（到／和）、益（增加／更加），一代就分出來了。"}], "difficulty": "中", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-28", "exam": "tc112", "nums": [28, 29, 30], "form": "題組", "img": "img/tc112-28.png", "source": "沈括《夢溪筆談》", "author": "沈括", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "古人鑄鑑，鑑大則平，鑑小則凸。凡鑑窪則照人面大，凸則照人面小。小鑑不能全視人面，故令微凸，收人面令小，則鑑雖小而能全納人面。仍復量鑑之小大，增損高下，常令人面與鑑大小相若。此工之巧智，後人不能造。", "translation": "古人鑄造銅鏡，鏡子大就做成平面，鏡子小就做成凸面。凡是凹面鏡，照出的人臉就變大；凸面鏡，照出的人臉就變小。小鏡子照不到整張臉，所以讓它微微凸起，把臉縮小，這樣鏡子雖小也能照出整張臉。而且還要衡量鏡子的大小，增減凸起的高低，常讓照出來的人臉和鏡面大小差不多。這是工匠的巧妙智慧，後人做不出來。", "keywords": [{"w": "鑑", "m": "鏡子"}, {"w": "窪", "m": "凹"}, {"w": "納", "m": "容納"}, {"w": "增損", "m": "增加或減少"}, {"w": "相若", "m": "相近、差不多"}], "questions": [{"n": 28, "qtype": "單選", "stem": "「呈現異同」是說明事物常用的方式，其基礎常來自作者對事物異、同的科學觀察。依據沈括所述，何者不是他的觀察結果？", "options": {"A": "同樣是銅鏡，有凹面、凸面之別", "B": "同樣是凸面鏡，凸起程度有高、低之別", "C": "無論凹面鏡、凸面鏡，其尺寸均與人臉的大小相同", "D": "無論凸起程度高低，凸面鏡製作均以能照到全臉為原則"}, "answer": "C", "explain": "(C)沈括說「常令人面與鑑大小相若」，是讓「鏡中照出的臉」和鏡子差不多大，不是鏡子本身的尺寸和人臉一樣大；而且這句只針對凸面鏡，所以(C)不是他的觀察，選(C)。(A)「凡鑑窪則照人面大，凸則照人面小」，提到凹面、凸面兩種，是他的觀察。(B)「量鑑之小大，增損高下」，凸起有高有低，是他的觀察。(D)小鏡微凸是為了「全納人面」，是他的觀察。", "skill": "小心「偷換主詞」：原文說「照出來的臉」，選項改成「鏡子尺寸」，一字之差就錯。"}, {"n": 29, "qtype": "單選", "stem": "依據銅鏡演變簡圖（殷商：直徑約7～13cm，鏡面近平或微凸，直徑小的凸起明顯；西周：直徑約6～14cm，有微凸者但大多平直；春秋戰國：鏡面大多平直；兩漢三國：凸面鏡頗多，有些直徑10cm者微凸，有些直徑20cm者凸起明顯）及沈括之文，關於①、②的研判應是：①從圖中所舉的古鏡大小看，完全符合沈括所云「鑑大則平，鑑小則凸」。②沈括所說「工之巧智」的「工」，應該是指殷商時候的製鏡工匠。", "options": {"A": "①、②皆正確", "B": "①正確，②錯誤", "C": "①無法判斷，②正確", "D": "①錯誤，②無法判斷"}, "answer": "D", "explain": "①圖中兩漢三國「有些直徑20cm者鏡面凸起明顯」，大鏡反而很凸，和「鑑大則平」不合，所以不是「完全符合」，①錯誤。②沈括只說「古人」「此工」，沒說是哪個朝代的工匠，無法判斷是不是殷商。答案(D)。", "skill": "看到「完全符合」，只要找到一個反例就能推翻；看到「應該是指某朝代」，就回原文找有沒有寫年代。"}, {"n": 30, "qtype": "單選", "stem": "上列資料內若要概括「當代學者」的觀點（當代學者：位於鏡背中心的鏡紐，漢代銅鏡比戰國銅鏡大。由於銅液澆注進模具後會收縮，即使改變鏡背紋飾的造型，以利暫存較多銅液，鏡體中央仍會出現鑄造缺陷。故進行鏡面加工時，圓心附近的磨削會比外圍略少，避免缺陷外露，因而形成鏡面凸起。），「凸面鏡，＿＿＿」內最適合填入的是：", "options": {"A": "為減省製鏡流程而興起", "B": "因解決製鏡難題而誕生", "C": "出自鑄造師偶然的錯誤", "D": "得自前代工藝品的靈感"}, "answer": "B", "explain": "當代學者認為：銅液冷卻收縮使鏡子中央有缺陷，為了不讓缺陷露出來，磨鏡時中央少磨一點，結果鏡面就凸起來了。凸面鏡是為了「解決鑄造缺陷這個難題」而產生的，(B)正確。(A)沒有減省流程，反而要特別控制磨削。(C)是工匠有意的處理方式，不是偶然出錯。(D)文中沒提到受前代工藝品啟發。", "skill": "概括觀點題，抓「由於……故……因而……」這條因果鏈，起點的問題和終點的結果連起來就是答案。"}], "difficulty": "中", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc112-37", "exam": "tc112", "nums": [37, 38], "form": "題組", "img": "img/tc112-37.png", "source": "綜合（多篇古文）（焦桐〈論吃飯〉文白對讀）", "author": "", "genre": "其他", "types": ["句意理解", "文意推論"], "passage": "飯之甘，在百味之上，知味者，遇好飯不必用菜。（袁枚語，焦桐文引）\n(A)批大郤，導大窾，因其固然\n(B)大行不顧細謹，大禮不辭小讓\n(C)聖人不凝滯於物，而能與世推移\n(D)人工繼晷以襄事，豈好勞而惡逸哉", "translation": "米飯的甘美，在各種滋味之上，懂得品味的人，遇到好飯就不必配菜。\n(A)劈開筋骨間的大縫隙，順著骨節間的空處進刀，依照牛本來的結構。\n(B)做大事不必顧慮小節，行大禮不必計較小的謙讓。\n(C)聖人不被外物拘束，能隨著世道變化而調整。\n(D)工人日夜不停地完成工作，難道是喜歡勞苦、討厭安逸嗎？", "keywords": [{"w": "郤", "m": "同「隙」，縫隙"}, {"w": "窾", "m": "空處"}, {"w": "細謹", "m": "小節"}, {"w": "凝滯", "m": "拘泥"}, {"w": "繼晷", "m": "夜以繼日（晷：日影）"}, {"w": "襄事", "m": "完成事情"}], "questions": [{"n": 37, "qtype": "單選", "stem": "上文所述長米蒸煮後所呈現的特性（長米有點像騎牆派，蒸煮後不具黏性，顆粒各自獨立，善變，不強調自我，適合用來製作各式菜飯或炒飯），與何者最接近？", "options": {"A": "批大郤，導大窾，因其固然", "B": "大行不顧細謹，大禮不辭小讓", "C": "聖人不凝滯於物，而能與世推移", "D": "人工繼晷以襄事，豈好勞而惡逸哉"}, "answer": "C", "explain": "長米「善變，不強調自我」，加什麼料就成什麼飯，能隨環境改變。(C)〈漁父〉「聖人不凝滯於物，而能與世推移」，不固執、隨世變化，最接近，正確。(A)〈庖丁解牛〉講順著牛的天然結構下刀，重點是順應規律，不是自身多變。(B)〈鴻門宴〉樊噲勸劉邦做大事不拘小節，與隨物變化無關。(D)講工人夜以繼日辛勤工作，強調勤勞，與善變無關。", "skill": "文白對應題：先把白話特性濃縮成一個關鍵詞（長米＝隨物而變），再把每句文言翻成白話比對。"}, {"n": 38, "qtype": "單選", "stem": "上文對「米的天性既純真又深情」、「白飯之於佳肴，好比畫布之於色彩和線條」的解說，依序相當於右圖（臺灣人喜歡吃飯的原因：①吃飯才有飽足感 ②米食種類變化多 ③飯讓桌菜呈美味 ④稻米平價最實惠 ⑤米飯營養好消化）的哪個理由？", "options": {"A": "①、④", "B": "②、③", "C": "②、④", "D": "③、⑤"}, "answer": "B", "explain": "「米的天性既純真又深情」，後文解說：跟什麼汁液一起煮，就變成雞飯、薑飯、檸檬飯、椰漿飯、墨魚飯，說的是米食變化多，對應②。「白飯之於佳肴，好比畫布之於色彩和線條」，後文說筵席少了白飯調和，菜肴會彼此扞格，白飯讓整桌菜更協調美味，對應③。所以(B)。①飽足感、④價格、⑤營養，文中都沒有談到。", "skill": "比喻句的意思通常在下一句就解釋了，往後讀一兩句找「例如、若、但若」，答案就在那裡。"}], "difficulty": "中", "label": "112統測", "year": 112, "kind": "統測"}, {"id": "tc113-02", "exam": "tc113", "nums": [2], "form": "單題", "img": "img/tc113-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "他植者雖窺伺傚慕，莫能如也。（柳宗元〈種樹郭橐駝傳〉）", "translation": "別的種樹人雖然偷偷觀察、模仿，卻沒有人比得上他。", "keywords": [{"w": "如", "m": "及、比得上（莫能如：沒有人比得上）"}, {"w": "窺伺", "m": "暗中觀察"}, {"w": "傚慕", "m": "仿效羨慕"}], "questions": [{"n": 2, "qtype": "單選", "stem": "下列文句的「如」，何者與「他植者雖窺伺傚慕，莫能如也」的「如」意義最接近？", "options": {"A": "縱一葦之所「如」，凌萬頃之茫然", "B": "貓眼黑睛「如」線，此正午貓眼也", "C": "其中往來種作，男女衣著，悉「如」外人", "D": "臣之壯也，猶不「如」人，今老矣，無能為也已"}, "answer": "D", "explain": "題幹「莫能如也」是說別人怎麼模仿都「比不上」郭橐駝，「如」是「及、比得上」。(D)〈燭之武退秦師〉「猶不如人」＝還比不上別人，意思相同，正確。(A)〈赤壁賦〉「一葦之所如」是任小船漂到它要去的地方，「如」是「往、到」。(B)《夢溪筆談》「黑睛如線」是瞳孔細得像一條線，「如」是「像」。(C)〈桃花源記〉「悉如外人」是穿著全都像外面的人，「如」也是「像」。", "skill": "「如」常見三義：像、往、比得上；看到「不如」「莫能如」這種否定加如的結構，多半就是「比得上」。"}], "difficulty": "易", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-03", "exam": "tc113", "nums": [3], "form": "單題", "img": "img/tc113-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋", "寫作手法"], "passage": "沙鷗翔集，錦鱗游泳。／月明星稀，烏鵲南飛。／寧赴湘流，葬於江魚之腹中。／夫秦王有虎狼之心，殺人如不能舉。", "translation": "沙鷗時飛時停，美麗的魚兒游來游去。／月色明亮、星星稀少，烏鴉向南飛去。／我寧可跳進湘江，葬身江魚腹中。／秦王有像虎狼一樣兇殘的心，殺人多得好像唯恐殺不完。", "keywords": [{"w": "錦鱗", "m": "有錦紋的鱗，借指美麗的魚"}, {"w": "虎狼之心", "m": "像虎狼一樣兇殘的心"}], "questions": [{"n": 3, "qtype": "單選", "stem": "「他是鵝蛋臉，臥蠶眉。」句中「鵝蛋」、「臥蠶」用來修飾其後的臉、眉，意指鵝蛋般的臉，臥蠶般的眉。下列「」內的詞，何者有相同用法？", "options": {"A": "沙鷗翔集，「錦鱗」游泳", "B": "月明星稀，「烏鵲」南飛", "C": "寧赴湘流，葬於「江魚」之腹中", "D": "夫秦王有「虎狼」之心，殺人如不能舉"}, "answer": "D", "explain": "題幹的重點是「名詞放在名詞前，當作比喻來修飾」：鵝蛋臉＝像鵝蛋的臉。(D)〈鴻門宴〉樊噲說秦王有「虎狼之心」，就是像虎狼一樣兇狠的心，是同樣的比喻修飾，正確。(A)〈岳陽樓記〉「錦鱗」是用鱗片借代魚，屬借代，不是「像錦的鱗」這種比喻。(B)曹操〈短歌行〉「烏鵲」就是烏鴉這種鳥的名稱。(C)〈漁父〉「江魚」是「江裡的魚」，「江」表示所在地點，不是比喻。", "skill": "判斷「名詞＋名詞」時，把它翻成「像○○的□□」念念看，通順又合理的才是比喻式修飾。"}], "difficulty": "中", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-06", "exam": "tc113", "nums": [6], "form": "單題", "img": "img/tc113-06.png", "source": "傳統對聯", "author": "", "genre": "其他", "types": ["文化常識"], "passage": "萬石家風惟孝弟，百年世業在詩書。", "translation": "像萬石君那樣的好家風，靠的只是孝順父母、友愛兄弟；家族能興旺百年，根本在於讀書傳家。", "keywords": [{"w": "萬石家風", "m": "漢代石奮與四個兒子都官至二千石，號「萬石君」，全家以孝謹聞名"}, {"w": "孝弟", "m": "孝順父母、敬愛兄長（弟音同悌）"}, {"w": "詩書", "m": "儒家經典，泛指讀書"}], "questions": [{"n": 6, "qtype": "單選", "stem": "右圖是一副具有儒家內涵的對聯，依上、下聯規則，○○、□□最適當的詞語應是：", "options": {"A": "詩書、孝弟", "B": "孝弟、詩書", "C": "無為、齊物", "D": "齊物、無為"}, "answer": "B", "explain": "先刪去道家用語：「無為」是老子思想，「齊物」是莊子思想，和「儒家內涵」不合，(C)(D)錯。再看上下聯規則：對聯直排，右邊是上聯「萬石家風惟○○」，左邊是下聯「百年世業在□□」。上聯最後一字要用仄聲、下聯最後一字要用平聲。「弟」是仄聲、「書」是平聲，所以○○填「孝弟」、□□填「詩書」，(B)正確；(A)把順序顛倒，上聯會以平聲「書」結尾，不合規則。", "skill": "對聯題兩步走：先看內容合不合題意，再用「上聯尾字仄、下聯尾字平」定上下。"}], "difficulty": "中", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-08", "exam": "tc113", "nums": [8], "form": "單題", "img": "img/tc113-08.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式"], "passage": "提刀而立，為之四顧。／滿目蕭然，感極而悲者矣。／郁離子之市，見壞宅而哭之慟。／惑而不從師，其為惑也終不解矣。", "translation": "提著刀站起來，為此環顧四周。／滿眼淒涼，感慨到了極點而悲傷起來。／郁離子到市集去，看到毀壞的房子就哭得很傷心。／有疑惑卻不去向老師請教，那疑惑終究解不開。", "keywords": [{"w": "而", "m": "連詞，可表順承（然後、就）、修飾（著）、轉折（卻）"}], "questions": [{"n": 8, "qtype": "單選", "stem": "「視而不見」、「口惠而實不至」的「而」，相當於「卻」，用來表示其前、後詞語有轉折關係。下列文句中的「而」，何者有相同用法？", "options": {"A": "提刀「而」立，為之四顧", "B": "滿目蕭然，感極「而」悲者矣", "C": "郁離子之市，見壞宅「而」哭之慟", "D": "惑「而」不從師，其為惑也終不解矣"}, "answer": "D", "explain": "轉折的「而」前後意思相反或出乎意料，可代入「卻」。(D)〈師說〉「惑而不從師」＝有疑惑卻不去求教，前後語意相反，是轉折，正確。(A)〈庖丁解牛〉「提刀而立」＝提著刀站起來，是動作接連（順承／修飾）。(B)〈岳陽樓記〉「感極而悲」＝感慨到極點就悲傷，前因後果，是順承。(C)《郁離子》「見壞宅而哭」＝看到壞房子就哭，也是順承。", "skill": "判斷「而」的用法，直接代入「卻」「就」「著」試讀，哪個最通順就是哪一種。"}], "difficulty": "易", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-09", "exam": "tc113", "nums": [9], "form": "單題", "img": "img/tc113-09.png", "source": "《左傳》〈燭之武退秦師〉、《楚辭》〈漁父〉", "author": "", "genre": "史傳人物", "types": ["文意推論", "人物情感"], "passage": "秦伯說，與鄭人盟，使杞子、逢孫、楊孫戍之，乃還。（〈燭之武退秦師〉）／屈原曰：「安能以身之察察，受物之汶汶者乎？寧赴湘流，葬於江魚之腹中。」（〈漁父〉）", "translation": "秦穆公很高興，和鄭國訂立盟約，派杞子等人替鄭國守城，便撤兵回國。／屈原說：「怎能讓自己潔白的身心，去沾染外界的汙濁？我寧可跳進湘江，葬身魚腹。」", "keywords": [{"w": "說", "m": "通「悅」，高興"}, {"w": "察察", "m": "潔白的樣子"}, {"w": "汶汶", "m": "汙濁的樣子"}], "questions": [{"n": 9, "qtype": "單選", "stem": "雙方立場不一致時，通常會就下圖所示五種策略擇一回應。依據〈燭之武退秦師〉、〈漁父〉，對①、②的研判應是：①秦穆公與燭之武對談後，以「對立」策略回應燭之武。②屈原與漁父對談時，以「順應」策略回應漁父。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "B", "explain": "①秦穆公聽完燭之武分析後「與鄭人盟」，還派兵替鄭國守城——既達成自己的利益，也配合了鄭國，是「合作」，不是「對立」，①錯。②漁父勸屈原「與世推移」、隨波逐流，屈原卻堅持「安能以身之察察，受物之汶汶者乎」，寧死也不改變，是高度堅持自我、不配合對方，屬「對立」而非「順應」，②錯。所以①②皆錯，選(B)；(A)(C)(D)都至少判對其中一項錯誤敘述。", "skill": "策略圖題先找人物最後「怎麼做」：有沒有堅持自己？有沒有配合對方？兩軸各判一次就能定位。"}], "difficulty": "中", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-10", "exam": "tc113", "nums": [10], "form": "單題", "img": "img/tc113-10.png", "source": "《天工開物‧舟車》", "author": "宋應星", "genre": "說理議論", "types": ["句意理解", "文意推論"], "passage": "人有貴而必出，行畏周行；物有賤而必須，坐窮負販。四海之內，南資舟而北資車。", "translation": "人有地位尊貴卻非出門不可的，怕走遠路辛苦；貨物有價格便宜卻是生活必需的，坐在家裡就沒辦法挑擔販運。所以天下各地，南方靠船、北方靠車。", "keywords": [{"w": "周行", "m": "走遍遠路"}, {"w": "坐窮負販", "m": "待在原地就無法背負販運"}, {"w": "資", "m": "憑藉、依靠"}], "questions": [{"n": 10, "qtype": "單選", "stem": "《天工開物‧舟車》：「人有貴而必出，行畏周行；物有賤而必須，坐窮負販。四海之內，南資舟而北資車。」這段話若依下框所示，繪製常用於「分析原因」的「魚骨圖」，｛｝、〔〕最適合填入何者？（表格：①／①－1／②／②－1）", "options": {"A": "載人／重視人權／運貨／貶抑物價", "B": "載人／怕走路累／運貨／互通有無", "C": "北方／重視人權／南方／貶抑物價", "D": "北方／怕走路累／南方／互通有無"}, "answer": "B", "explain": "魚頭的問題是「需要交通工具的原因」，主因要回答「為什麼需要」：前半講人（人有貴而必出）→「載人」，後半講物（物有賤而必須）→「運貨」。小原因：人是「行畏周行」＝怕走遠路累；物是「坐窮負販」＝不運就沒法流通，所以要「互通有無」。(B)全對。(A)(C)「重視人權」「貶抑物價」原文沒有。(C)(D)把「南、北」當主因，但南舟北車是結果（用什麼工具），不是需要交通工具的原因。", "skill": "魚骨圖就是「問題→主因→細因」：先把原文切成平行的兩半，各自再找「為什麼」。"}], "difficulty": "中", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-11", "exam": "tc113", "nums": [11, 12, 13, 14, 15], "form": "題組", "img": "img/tc113-11.png", "source": "大伴旅人〈梅花歌序〉、王羲之〈蘭亭集序〉、盧照鄰〈梅花落〉、蘇子卿〈梅花落〉", "author": "大伴旅人、王羲之等", "genre": "書信序跋", "types": ["比較閱讀", "詩詞賞析", "文意推論"], "passage": "天平二年正月十三日，萃于帥老之宅，申宴會也。于時，初春令月，氣淑風和。梅披鏡前之粉，蘭薰珮後之香。……於是蓋天坐地，促膝飛觴。忘言一室之裡，開衿烟霞之外。淡然自放，快然自足。（大伴旅人〈梅花歌序〉）／永和九年，歲在癸丑，暮春之初，會於會稽山陰之蘭亭，脩禊事也。……是日也，天朗氣清，惠風和暢。……夫人之相與，俯仰一世，或取諸懷抱，悟言一室之內；或因寄所託，放浪形骸之外。雖趣舍萬殊，靜躁不同，當其欣於所遇，暫得於己，快然自足，不知老之將至。（王羲之〈蘭亭集序〉）／梅嶺花初發，天山雪未開。雪處疑花滿，花邊似雪回。因風入舞袖，雜粉向妝臺。匈奴幾萬里，春至不知來。（盧照鄰〈梅花落〉）／窗外一株梅，寒花五出開。影隨朝日遠，香逐便風來。泣對銅鉤障，愁看玉鏡臺。行人斷消息，春恨幾裴回。（蘇子卿〈梅花落〉）", "translation": "〈梅花歌序〉：天平二年正月十三日，大家聚集在大宰帥的府邸舉行宴會。正值初春好月，天氣清和。梅花像鏡前女子撲的白粉般綻開，蘭草散發像佩囊般的香氣。……於是以天為蓋、以地為席，促膝而坐、舉杯暢飲。在屋裡相對忘言，對著雲霞敞開胸懷，淡泊自在，痛快滿足。〈蘭亭集序〉：永和九年暮春，在會稽山陰的蘭亭聚會修禊。這天天氣晴朗、和風舒暢。人與人相處一生，有人喜歡在室內傾談抱負，有人寄情外物、放縱不拘。雖然取捨不同、性情動靜有別，但當他們遇到喜歡的事、暫時稱心時，都會感到痛快滿足，忘了老年將至。兩首〈梅花落〉：前一首寫梅與雪相映難分，末兩句轉寫遠戍匈奴之地、春天遲遲不來；後一首寫窗前梅影梅香，後半寫女子對鏡流淚、思念斷了音信的遠行人。", "keywords": [{"w": "萃", "m": "聚集"}, {"w": "令月", "m": "美好的月份"}, {"w": "脩禊", "m": "三月上巳日到水邊洗濯以除不祥的習俗"}, {"w": "快然自足", "m": "痛快而自我滿足"}, {"w": "欣於所遇", "m": "對所遇到的事物感到喜悅"}], "questions": [{"n": 11, "qtype": "單選", "stem": "下列何者最符合上文所述？", "options": {"A": "大宰府的梅花宴，通常是為送別或迎接遣唐使而舉行", "B": "山上憶良與大伴旅人曾同往唐朝，故能先識梅花之美", "C": "唐朝賞梅之風傳入日本後，成為上層社會的時尚活動", "D": "長屋王因謀反獲罪，大伴旅人亦受牽連而貶為大宰帥"}, "answer": "C", "explain": "山上憶良說：唐朝賞梅之風吹到日本，「貴族競相模仿」，可見成了上層社會的流行，(C)正確。(A)文中梅花宴是大伴旅人邀賓客賞梅賦歌，和送別、迎接遣唐使無關。(B)只有山上憶良曾隨遣唐使到唐朝，大伴旅人沒有。(D)大伴旅人是先被藤原家族排擠才離京，長屋王是在他到任後隔年才被賜死，不是受牽連而貶官。", "skill": "細節題逐項回原文找「主角是誰、先後順序」，很多錯誤選項就是把人或時間接錯。"}, {"n": 12, "qtype": "單選", "stem": "依據上文，山上憶良認為大伴旅人從〈蘭亭集序〉得到的啟發，主要為何？", "options": {"A": "藉景抒情的筆法", "B": "欣於所遇的自適", "C": "生死齊一的領悟", "D": "樂以天下的胸懷"}, "answer": "B", "explain": "山上憶良說大伴旅人用了「快然自足」，想必希望大家「一同體驗『欣於所遇』的境界」，(B)正確。(A)他談的是心境，不是寫作筆法。(C)大伴旅人自己說序文沒有「死生亦大矣」的省思；而且〈蘭亭集序〉本身也否定「一死生」，談不上「生死齊一」。(D)「樂以天下」是與天下同樂的政治胸懷，文中沒提。", "skill": "問「某人認為」時，直接找那個人說的話，答案常就是他引用的原句。"}, {"n": 13, "qtype": "單選", "stem": "若將大伴旅人〈梅花歌序〉、王羲之〈蘭亭集序〉的部分文字相比較，何者理解不適當？", "options": {"A": "①與❶，皆依「時間→地點→事件」敘寫", "B": "②與❷，皆寫當日氣候給人的感受", "C": "③與❸，皆強調自然美景令人忘我", "D": "④與❹，皆形容內心獲得愉悅和滿足"}, "answer": "C", "explain": "題目要選「不適當」。(C)❸「或取諸懷抱，悟言一室之內；或因寄所託，放浪形骸之外」是在說人有兩種不同的處世性情（內斂傾談、放縱不拘），不是在寫自然美景讓人忘我，所以不適當，選(C)。(A)①天平二年正月十三日（時）→帥老之宅（地）→申宴會（事），❶永和九年暮春（時）→蘭亭（地）→脩禊事（事），正確。(B)②「氣淑風和」、❷「天朗氣清，惠風和暢」都寫天氣宜人，正確。(D)④「快然自足」與❹「快然自足」都寫心滿意足，正確。", "skill": "比較兩段文言時，先各自翻成白話，再看選項說的「共同點」是否兩邊都成立，只要一邊不成立就錯。"}, {"n": 14, "qtype": "單選", "stem": "若山上憶良讀過下列兩首詩，①、②、③、④何者屬於文末他說「早知要由此著筆」的「此」的範圍？", "options": {"A": "①、③", "B": "②、④", "C": "①、②、④", "D": "②、③、④"}, "answer": "A", "explain": "「此」指大伴旅人說的「單純投入欣賞、充滿美感聯想」的寫法，不要抒發戍邊、思鄉之情。①「雪處疑花滿，花邊似雪回」把梅和雪互相比擬，是美感聯想，符合。③「影隨朝日遠，香逐便風來」寫梅影梅香，是單純欣賞，符合。②「匈奴幾萬里，春至不知來」寫遠戍邊地，是戍邊之情，不符。④「泣對銅鉤障，愁看玉鏡臺」寫女子對鏡哭泣思念遠人，是相思愁情，不符。所以選(A)。", "skill": "先把「此」的範圍定義清楚（要什麼、不要什麼），再逐句貼標籤篩選。"}, {"n": 15, "qtype": "單選", "stem": "下圖為公元730年大宰府梅花宴的部分歌詞。依據上文，關於①、②的研判應是：①甲可能是大伴旅人；丙可能是山上憶良。②丁比乙符合大伴旅人對以梅賦歌的期待。（甲：園中梅花飄零，直似雪傾，降自天空。乙：折梅插上頭，見眾人遊，憶起京城時候。丙：院中梅，春光綻枝頭。怎能獨自觀賞，送此春日晝？丁：園中梅花伴翠柳，折來插滿頭，整日盡興遊。）", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "A", "explain": "①山上憶良稱讚大伴旅人的歌「以雪喻梅」，甲「梅花飄零，直似雪傾」正是以雪喻梅，可能是大伴旅人；山上憶良說自己的歌「只呼籲相偕同樂，莫負良辰」，丙「怎能獨自觀賞，送此春日晝」正是呼籲同樂，可能是山上憶良，①正確。②大伴旅人不希望大家抒發思鄉之情，乙「憶起京城時候」是思鄉；丁「整日盡興遊」是單純享受賞梅之樂，所以丁比乙符合期待，②正確。選(A)。", "skill": "把文中每個人物的「自我描述」當成線索卡，拿去和選項內容一一配對。"}], "difficulty": "難", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-23", "exam": "tc113", "nums": [23, 24, 25, 26], "form": "題組", "img": "img/tc113-23.png", "source": "「嚴禁自盡圖賴碑」（清光緒二年福建巡撫丁日昌示）", "author": "丁日昌", "genre": "其他", "types": ["文意推論", "句意理解", "文化常識"], "passage": "凡自盡命案均限一月審結，倘有聳令自盡、誣告圖賴等情，即嚴究主使棍徒，一併從重治罪。則爾等縱或自拚一死，總不能貽害他人。其親屬雖欲逞刁，一經審出實情，不過自取罪戾，亦無人肯與賄和，是不但死者枉送性命，不值一錢，即生者因此又犯刑章，更屬無益有損。本欲害人，適以自害，徒為讎人所快，復何利之可圖？何忿之能洩哉？試為反覆籌思：與其枉死無償，聽他人之入室；曷若餘生自愛，冀飽煖於將來？且本部院業經嚴禁書差需索，爾等如有身受重冤，儘可瀝情控訴，並不須花費分毫，又何必自投絕路，至以性命博錙銖哉？", "translation": "凡是自殺命案，一律限一個月內審結；如果有人慫恿別人自殺、誣告他人來訛詐，就嚴查背後主使的無賴，一起從重判罪。這樣一來，你們就算拚上一死，也終究害不到別人。死者的親屬即使想耍刁，一旦查出實情，只是自找罪受，也沒有人肯出錢私下和解；不但死者白白送命、一文不值，活著的人還因此觸犯法律，更是有害無益。本來想害人，反而害了自己，只讓仇人高興，又能圖到什麼好處？又能出什麼氣呢？請反覆想想：與其白白死去得不到賠償，任別人來占你的家；何不好好愛惜餘生，盼望將來能吃飽穿暖？而且本巡撫已嚴禁書吏差役索取財物，你們如果真有重大冤屈，盡可詳細陳情控告，不必花一分錢，又何必走上絕路，用性命去換一點點錢呢？", "keywords": [{"w": "圖賴", "m": "藉故誣賴他人以謀利"}, {"w": "棍徒", "m": "無賴、惡棍"}, {"w": "貽害", "m": "留下禍害"}, {"w": "罪戾", "m": "罪過"}, {"w": "曷若", "m": "何如、不如"}, {"w": "需索", "m": "勒索財物"}, {"w": "錙銖", "m": "極微小的錢財"}], "questions": [{"n": 23, "qtype": "單選", "stem": "依據上文，「常見案例」中「訟師」所稱「幫你討個公道」，意指：（讓地主：／讓阿吉：）", "options": {"A": "接受「圖賴」罪／獲賠喪葬費", "B": "接受「圖賴」罪／獲再次上訴權利", "C": "接受「威逼人致死」罪／獲賠喪葬費", "D": "接受「威逼人致死」罪／獲再次上訴權利"}, "answer": "C", "explain": "訟師說：若確定死者是被地主施壓而死，地主犯「威逼人致死」罪，要杖責並「賠償喪葬費」；又說被控的人多半「無奈接受『威逼人致死』」，失去親人的一方拿到錢。所以「討公道」就是讓地主認「威逼人致死」罪、讓阿吉拿到喪葬費，(C)正確。(A)(B)「圖賴」是阿吉誣賴被揭穿時阿吉方要受的罪，不是地主。(B)(D)文中說只要兩邊接受判決就不會上告，「再次上訴權利」不是訟師要爭取的。", "skill": "遇到法律、制度類閱讀，先畫出「誰犯什麼罪→受什麼罰→誰得利」的對應表再作答。"}, {"n": 24, "qtype": "單選", "stem": "下列的告誡對象與重點，何者最符合碑文「部分內容」？", "options": {"A": "主使棍徒：不要找官府洩忿", "B": "想拚一死者：你的犧牲毫無價值", "C": "死者的親屬：關說衙役，罪名不輕", "D": "縣府首長：薪水足夠溫飽，切莫貪財"}, "answer": "B", "explain": "碑文說「爾等縱或自拚一死，總不能貽害他人」「死者枉送性命，不值一錢」，就是告訴想以死訛詐的人：你死了也害不到別人，犧牲毫無價值，(B)正確。(A)對主使棍徒是「從重治罪」，而且碑文反而鼓勵有冤就「瀝情控訴」，沒有叫人別找官府。(C)碑文警告親屬「逞刁」會自取罪戾，沒提關說衙役。(D)碑文是「嚴禁書差需索」，對象是書吏差役，不是縣府首長，也沒提薪水。", "skill": "告示類文言要先抓「對象＋要對方做什麼」，常見句型是「爾等……」「倘有……即……」。"}, {"n": 25, "qtype": "單選", "stem": "「訟師有話要說」末尾，「訟師」意在揭露何種社會現象？", "options": {"A": "只要民生壓力與官場現實仍在，想藉自殺謀財便難以禁絕", "B": "窮人觸法即受罰，富人犯罪卻能買通官員而逃過法律制裁", "C": "官府往往優先處理上司重視的案件，忽略百姓在意的小事", "D": "犯罪事件審理速度的快慢，常與市井小民的期待落差極大"}, "answer": "A", "explain": "訟師指出：窮人生存壓力大，才會「拿命換家庭生計」；縣官又怕被翻案影響仕途，樂得以「威逼人致死」結案。最後反問「限一月審結」能解開這個死結嗎？意思是根源（民生壓力、官場心態）不除，自殺圖賴禁不掉，(A)正確。(B)文中沒提富人買通官員。(C)沒有說官府只處理上司重視的案子。(D)重點不是審理速度合不合期待。", "skill": "文末反問句通常就是作者真正的觀點，把反問改成肯定句就能讀出主旨。"}, {"n": 26, "qtype": "單選", "stem": "敘述時，依照述說者、閱聽者的身分差異，會使用不同述說口吻。碑文「部分內容」所使用的口吻，與下列何者最接近？", "options": {"A": "問者嘻曰：不亦善夫！吾問養樹，得養人術", "B": "如蒙天恩允准，伏懇飭下總理衙門劄行總稅司", "C": "倘有額外索費等弊，准該商民投局稟揭，以憑究辦。切切。特示", "D": "客亦知夫水與月乎？逝者如斯，而未嘗往也；盈虛者如彼，而卒莫消長也"}, "answer": "C", "explain": "碑文是巡撫對百姓發布的告示，屬「上對下」的官方口吻，帶有規定與警告（倘有……即……）。(C)「倘有……准該商民投局稟揭，以憑究辦。切切。特示」同樣是官府告示，連「倘有」句型都一樣，正確。(A)〈種樹郭橐駝傳〉是問者聽完故事的讚嘆，屬一般對話。(B)「如蒙天恩允准，伏懇……」是臣子上奏皇帝的奏摺，屬「下對上」的恭敬口吻。(D)〈赤壁賦〉蘇子對客人說理，是朋友間的對話。", "skill": "應用文口吻看關鍵詞：「特示、切切」是告示（上對下），「伏懇、恭請」是奏摺（下對上）。"}], "difficulty": "難", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-30", "exam": "tc113", "nums": [30, 31, 32, 33], "form": "題組", "img": "img/tc113-30.png", "source": "「納貓契」「納貓法」（古代民間日用類書）；H先生罵貓文、Z先生詠貓詩（出處待查）", "author": "", "genre": "其他", "types": ["文意推論", "句意理解", "文化常識"], "passage": "一隻貓兒是黑斑，本在西方諸佛前。三藏帶歸家長養，護持經卷在民間。行契李四是某甲，賣與鄰居某人看。三面斷價錢一兩，一兩隨契已交還。買主願如石崇富，壽如彭祖福高遷。倉禾自此巡無怠，鼠賊從茲補不閒。不害頭牲並六畜，不得偷盜食諸般。日夜在家看守物，莫走東畔與西邊。如有故違走外去，堂前引過受笞鞭。（納貓契）／用斗桶等物以袋盛之，毋令人見，至其家討箸一根，和貓置於桶內盛去。每過水溝缺處，將石置之，使不過家。從吉方歸，取貓出，拜堂灶、犬畢，貓箸插於土堆，使不在家撒糞，然後復床睡，勿令走往。（納貓法）／家有白雄雞，畜之久矣，乃者棲於樹顛，而橫遭貓嚙。乃呼貓俾前而罵之曰：咄，汝貓！汝無他職，職在捕鼠。以茲大蠟，古也迎汝。不鼠之捕，曰職不舉，而又司晨之禽，焉是食？計汝之罪，匪直不職而已也！（H先生罵曰）／老人長夜每醒然，兀坐昏昏抵晝眠。怪爾也來爭此席，公然睡暖舊青氊。（Z先生責曰）", "translation": "納貓契：這隻黑斑貓原本在西方諸佛座前，唐三藏把牠帶回人間養大，守護經卷不被老鼠咬。立契的賣方是李四，把貓賣給鄰居某人。三方議定價錢一兩，錢已隨契約交清。祝買主像石崇一樣富有、像彭祖一樣長壽、福氣高升。從此貓要勤快巡守糧倉，不停捕捉鼠賊；不可傷害家禽和六畜，不可偷吃各種食物；日夜在家看守財物，不要往東往西亂跑。如果故意違約跑到外面，就要在堂前認錯挨鞭子。納貓法：用斗或桶裝著，再套上袋子，別讓人看見；到賣家討一根筷子，和貓一起放進桶裡帶走。每經過水溝缺口，就放塊石頭，讓貓不會跑回原來的家。從吉利的方位回家，把貓取出，拜過廳堂、灶神和狗後，把筷子插在土堆上，讓貓不在家裡大小便，然後讓牠回床上睡，別讓牠亂跑。H先生：家裡養了一隻白公雞很久了，前些時候牠棲在樹頂，竟被貓咬死。於是把貓叫到面前罵道：「哼，你這隻貓！你沒有別的職責，職責就是抓老鼠。古代年終大蠟祭時還要迎接你。你不抓老鼠，已經叫失職；竟然還把報曉的雞吃了？算算你的罪，可不只是失職而已！」Z先生：我這老人長夜常常醒著，只能昏昏沉沉地呆坐，直到白天才睡得著。怪你也來搶這張座位，大剌剌地睡暖了我的舊青氈。", "keywords": [{"w": "行契", "m": "立契約"}, {"w": "三面斷價", "m": "買方、賣方、中人三方議定價格"}, {"w": "頭牲", "m": "泛指家禽、家畜"}, {"w": "笞鞭", "m": "用鞭子抽打"}, {"w": "大蠟", "m": "古代年終祭祀百神的祭典，迎貓以食田鼠"}, {"w": "司晨之禽", "m": "報曉的雞"}, {"w": "匪直", "m": "不只"}, {"w": "青氊", "m": "青色毛氈"}], "questions": [{"n": 30, "qtype": "單選", "stem": "依據「納貓契」，交易雙方最可能是：", "options": {"A": "三藏、石崇", "B": "三藏、李四", "C": "李四的鄰居、石崇", "D": "李四的鄰居、李四"}, "answer": "D", "explain": "契約寫「行契李四是某甲，賣與鄰居某人看」：賣方是李四，買方是李四的鄰居，(D)正確。(A)(B)三藏只是傳說中把貓帶到人間的人，不是買賣雙方。(A)(C)石崇是祝福語「買主願如石崇富」裡用來比喻富有的人物，不是交易者。", "skill": "契約題先找「誰賣給誰」的句子，典故人物多半只是祝福或比喻。"}, {"n": 31, "qtype": "單選", "stem": "下列何者最符合「納貓契」所述？", "options": {"A": "祝福買貓者吉祥好運，長壽多財", "B": "指出貓長年聆聽佛經，善解人意", "C": "強調貓行動靈敏矯健，神明可證", "D": "提醒買主善加對待貓，以防離家"}, "answer": "A", "explain": "「買主願如石崇富，壽如彭祖福高遷」就是祝買主富有、長壽、福氣高，(A)正確。(B)「護持經卷」是說貓保護經書不被老鼠咬，不是聽佛經、善解人意。(C)契中沒有強調貓靈敏矯健或神明作證。(D)「如有故違走外去，堂前引過受笞鞭」是警告貓別亂跑，不是提醒買主善待貓。", "skill": "讀到典故人物（石崇、彭祖）先想他們代表什麼特質（富、壽），就能看懂祝福語。"}, {"n": 32, "qtype": "單選", "stem": "下列何者不是「納貓法」的建議作為？", "options": {"A": "請賣家給根筷子同貓攜回", "B": "自吉利方位帶貓回主人家", "C": "帶貓到廚房睡覺以便捕鼠", "D": "引導貓知道應在屋外排泄"}, "answer": "C", "explain": "題目問「不是」。納貓法最後說拜完堂、灶、犬，插好筷子後「復床睡」，是讓貓到床上睡，沒有說帶到廚房睡覺，(C)不是建議，選(C)。(A)「至其家討箸一根，和貓置於桶內」是。(B)「從吉方歸」是。(D)「貓箸插於土堆，使不在家撒糞」是。", "skill": "「何者不是」的題目，把原文步驟逐一列出打勾，沒被勾到的就是答案。"}, {"n": 33, "qtype": "單選", "stem": "如果喵星人想就H、Z先生提出下列辯駁，請研判①、②是否尚稱合理？①給H先生：我雖沒做到「鼠賊從茲補不閒」，但至少「不害六畜」啊！②給Z先生：我雖沒做到「倉禾自此巡無怠」，但至少沒「走外去」啊！", "options": {"A": "①、②皆是", "B": "①、②皆否", "C": "①是，②否", "D": "①否，②是"}, "answer": "D", "explain": "①H先生罵貓咬死了家裡的白雄雞，雞正是六畜之一，貓已經「害了六畜」，說「至少不害六畜」不成立，①否。②Z先生抱怨貓跑來搶他的座位、睡暖他的青氈，代表貓整天待在家裡，雖然沒去巡糧倉，但確實沒「走外去」，②合理。所以選(D)。", "skill": "判斷辯解合不合理，就拿辯解的內容去對照對方指控的「事實」，有矛盾就不成立。"}], "difficulty": "中", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc113-34", "exam": "tc113", "nums": [34, 35, 36], "form": "題組", "img": "img/tc113-34.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["比較閱讀", "主旨寓意"], "passage": "失其所與，不知。（〈燭之武退秦師〉）／不以物喜，不以己悲。（范仲淹〈岳陽樓記〉）／苟非吾之所有，雖一毫而莫取。（蘇軾〈赤壁賦〉）／此人巧聰明，不知於何稟度也。", "translation": "失去盟友，是不明智的。／不因外物好壞而歡喜，不因自身得失而悲傷。／如果不是屬於我的東西，就算一絲一毫也不拿。／這人手巧又聰明，不知道他的本事是從哪裡學來的。", "keywords": [{"w": "所與", "m": "盟友、與自己友好的人"}, {"w": "知", "m": "通「智」，明智"}, {"w": "苟", "m": "如果"}], "questions": [{"n": 34, "qtype": "單選", "stem": "乙、丙二文敘寫魚的「從容」，即甲文所說的「擬人化」。下列敘述，何者最符合文意？", "options": {"A": "乙文的魚被設想為「從容」，出自甲文①的期待", "B": "丙文的魚被設想為「從容」，出自甲文②的需求", "C": "乙文由「從容」出發，進而揣摩魚的眼神，設想魚傲然無畏", "D": "丙文由「從容」出發，進而推測魚的年齡，設想魚老奸巨猾"}, "answer": "C", "explain": "乙文寫鬼頭刀「游水的姿態竟然還十分從容」，接著寫牠「狠狠瞪我，那眼神毫無畏懼」「射出倨傲的神采」，正是從從容延伸到傲然無畏，(C)正確。(A)甲文①是為了「產生情感互動，成為家族成員」，乙文作者和魚是搏鬥關係，不是在期待親密互動。(B)甲文②是拿動物當鏡子界定什麼是人，丙文沒有這種用意。(D)丙文推測魚至少十二歲，但沒有說牠老奸巨猾。", "skill": "選項說「由A進而B」時，要確認原文真有A，也真有B，兩段都找得到才對。"}, {"n": 35, "qtype": "單選", "stem": "乙、丙二文的獵捕，皆以失敗收場，下列敘述，何者最符合文意？", "options": {"A": "乙文的「我」因發覺漁具不夠精良而「悵惘」", "B": "丙文的「我」因潛水技術不好而自慚為「輸家」", "C": "乙文「強烈的意識瞬間進入我的腦中」，流露征服其他生物的意志", "D": "丙文「收獲比自己大的魚是不吉利的」，隱含對人類能力有限的覺察"}, "answer": "D", "explain": "丙文作者被大魚拖到海底、憋不住氣，承認「我是輸家」，再用「收獲比自己大的魚是不吉利的」說服自己放手，隱含人力有限、不該強求的體悟，(D)正確。(A)乙文悵惘是因為失去了魚，不是怪漁具不好。(B)丙文輸是因為魚太大太有力、鋼條沒射穿，不是潛水技術差。(C)那股意識告訴他「你已經失去了這條魚」，是預感失敗，不是想征服。", "skill": "情緒詞（悵惘、輸家）要回原文找「前一句發生什麼事」，原因就在那裡。"}, {"n": 36, "qtype": "單選", "stem": "乙、丙二文的獵捕結局，或可就「反省人類中心主義」延伸思考―亦即不應自居萬物主宰而妄施掠奪。下列文句，何者最接近此意？", "options": {"A": "失其所與，不知", "B": "不以物喜，不以己悲", "C": "茍非吾之所有，雖一毫而莫取", "D": "此人巧聰明，不知於何稟度也"}, "answer": "C", "explain": "「不妄施掠奪」就是不拿不屬於自己的東西。(C)〈赤壁賦〉「苟非吾之所有，雖一毫而莫取」＝不是我的，一絲一毫也不取，最接近，正確。(A)〈燭之武退秦師〉晉文公說失去盟友是不明智，講的是外交，和掠奪自然無關。(B)〈岳陽樓記〉講個人不被外物和得失影響心情，是修養，不是反省掠奪。(D)是讚嘆某人手巧聰明，不知從何學來，與題意無關。", "skill": "先把題目的抽象概念換成一句白話（不拿不屬於你的），再拿去和選項比對。"}], "difficulty": "中", "label": "113統測", "year": 113, "kind": "統測"}, {"id": "tc114-03", "exam": "tc114", "nums": [3], "form": "單題", "img": "img/tc114-03.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["字詞解釋"], "passage": "仰觀宇宙之大，俯察品類之盛。／若各居而老死，何藉有群類哉？／病僂，隆然伏行，有類橐駝者。", "translation": "抬頭看宇宙的廣大，低頭看萬物種類的繁多。／如果各自獨居到老死，又何必要有同類群體呢？／他患了駝背病，背脊高高隆起、彎著身子走路，有點像駱駝。", "keywords": [{"w": "類", "m": "①種類、類別 ②像、類似"}, {"w": "品類", "m": "萬物的種類"}, {"w": "僂", "m": "駝背"}], "questions": [{"n": 3, "qtype": "單選", "stem": "新冠肺炎疫情嚴峻時期，多家航空公司推出「類出國航班」，飛至鄰近國家上空再返航停國內機場。下列文句的「類」，何者與「類出國」的「類」意義相近？", "options": {"A": "稻香村一帶凡有菜蔬稻稗之「類」", "B": "仰觀宇宙之大，俯察品「類」之盛", "C": "若各居而老死，何藉有群「類」哉", "D": "病僂，隆然伏行，有「類」橐駝者"}, "answer": "D", "explain": "「類出國」是「像出國一樣」，飛出去又飛回來，並沒有真的入境別國，「類」是「像、類似」。(D)〈種樹郭橐駝傳〉「有類橐駝」＝有點像駱駝，意思相同，正確。(A)「菜蔬稻稗之類」是這一類東西，「類」是名詞「種類」。(B)〈蘭亭集序〉「品類之盛」是萬物種類繁多，也是「種類」。(C)「群類」指同類的群體，仍是名詞。", "skill": "「類」當動詞（後面接名詞）多半是「像」；當名詞（前面有之、品、群）多半是「種類」。"}], "difficulty": "易", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-06", "exam": "tc114", "nums": [6], "form": "單題", "img": "img/tc114-06.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "寫作手法"], "passage": "彼節者有間，而刀刃者無厚。（〈庖丁解牛〉）／餘音嫋嫋，不絕如縷。舞幽壑之潛蛟，泣孤舟之嫠婦。（蘇軾〈赤壁賦〉）／句讀之不知，惑之不解，或師焉，或不焉。（韓愈〈師說〉）", "translation": "牛的骨節之間有空隙，而刀刃薄得幾乎沒有厚度。／簫聲的餘音悠長婉轉，像細絲一樣不斷；能使深谷中潛藏的蛟龍起舞，使孤舟上的寡婦哭泣。／不懂句讀的去向老師學，有疑惑解不開的卻不去學。", "keywords": [{"w": "有間", "m": "有空隙"}, {"w": "嫋嫋", "m": "聲音悠長婉轉"}, {"w": "嫠婦", "m": "寡婦"}, {"w": "句讀", "m": "文章的斷句"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下表四種因果論證圖解，是比爾茲利(Monroe Curtis Beardsley)在1950年所提出。表中搭配的例句，何者最適當？（A：Ⅰ導致了Ⅱ；B：Ⅰ導致了Ⅱ，Ⅱ導致了Ⅲ；C：Ⅰ導致了Ⅱ與Ⅲ；D：Ⅰ與Ⅱ導致了Ⅲ）", "options": {"A": "彼節者有間，而刀刃者無厚", "B": "搭客一等座，洋三角；二等座，洋二角；三等座，洋一角", "C": "餘音嫋嫋，不絕如縷。舞幽壑之潛蛟，泣孤舟之嫠婦", "D": "句讀之不知，惑之不解，或師焉，或不焉"}, "answer": "C", "explain": "(C)〈赤壁賦〉簫聲「餘音嫋嫋」（Ⅰ）造成兩個結果：潛蛟起舞（Ⅱ）、嫠婦哭泣（Ⅲ），正是「Ⅰ導致了Ⅱ與Ⅲ」，正確。(A)〈庖丁解牛〉「節有間」和「刃無厚」是兩個並列的條件，兩者合起來才導致「游刃有餘」，題目只引前半，彼此之間也不是「Ⅰ導致Ⅱ」。(B)只是依座位等級列出票價，沒有因果，也談不上連鎖。(D)〈師說〉是「不懂句讀的去學，有疑惑的卻不學」的交錯對應，批評小學而大遺，不是兩個原因共同導致一個結果。", "skill": "判斷因果圖，先把句子切成小單位，問自己「哪一個是因、哪一個是果」，再數因、果各有幾個。"}], "difficulty": "中", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-07", "exam": "tc114", "nums": [7], "form": "單題", "img": "img/tc114-07.png", "source": "綜合（宋詞高頻字詞研究）", "author": "", "genre": "古典詩詞曲", "types": ["詩詞賞析"], "passage": "", "translation": "", "keywords": [{"w": "婉約詞", "m": "以男女情愛、離愁別緒、傷春悲秋為主，風格柔美細膩"}, {"w": "豪放詞", "m": "題材擴及懷古、報國、人生感慨，風格雄渾奔放"}], "questions": [{"n": 7, "qtype": "單選", "stem": "前人認為宋詞可分「婉約詞」、「豪放詞」。有一研究從兩類作品取樣發現：其高頻率字、詞前六名如下表所示，確有差異，則①、②、③、④依序應是何種詞風的高頻率字、詞？（①風、君、江、古、北、劍；②春、憐、花、鴛、愁、芳；③人間、西風、風流、白髮、風雨、歸來；④東風、相逢、何處、天涯、春風、相思）", "options": {"A": "婉約／豪放／婉約／豪放", "B": "婉約／豪放／豪放／婉約", "C": "豪放／婉約／豪放／婉約", "D": "豪放／婉約／婉約／豪放"}, "answer": "C", "explain": "①有「江、古、北、劍」，讓人想到大江東去、懷古、北伐、寶劍，是豪放詞。②「春、憐、花、鴛、愁、芳」全是花草、鴛鴦、愁情，是婉約詞。③「人間、風流、白髮、風雨、歸來」帶有人生感慨、歷史滄桑，偏豪放（如「人間如夢」「風流人物」「白髮」）。④「東風、相逢、何處、天涯、相思」是離別相思，偏婉約。依序為豪放／婉約／豪放／婉約，選(C)；其他選項的配對都至少錯一組。", "skill": "看詞風先找「題材關鍵字」：劍、江、古、北是豪放；花、愁、鴛、相思是婉約。"}], "difficulty": "易", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-09", "exam": "tc114", "nums": [9], "form": "單題", "img": "img/tc114-09.png", "source": "《夢溪筆談‧書畫》", "author": "沈括", "genre": "筆記小品", "types": ["文意推論", "句意理解"], "passage": "藏書畫者，多取空名。偶傳為鍾、王、顧、陸之筆，見者爭售，此所謂「耳鑒」。又有觀畫而以手摸之，相傳以謂色不隱指者為佳畫，此又在耳鑒之下，謂之「揣骨聽聲」。", "translation": "收藏書畫的人，大多只看重虛名。偶然聽說某件是鍾繇、王羲之、顧愷之、陸探微的手筆，看到的人就搶著買，這叫做「用耳朵鑑定」。還有人看畫時用手去摸，相傳顏料摸起來不硌手指的就是好畫，這比「耳鑒」還差，叫做「揣骨聽聲」（像算命的摸骨聽聲一樣）。", "keywords": [{"w": "空名", "m": "虛名"}, {"w": "爭售", "m": "搶著購買（售在此指買）"}, {"w": "隱指", "m": "硌手指，摸起來不平"}, {"w": "揣骨聽聲", "m": "原指算命者摸骨聽聲斷人貴賤，此喻用手摸畫鑑定"}], "questions": [{"n": 9, "qtype": "單選", "stem": "「雙氣泡圖」通常用於呈現兩個事物的共同點、相異點。若要將下文所述「耳鑒」、「揣骨聽聲」繪成雙氣泡圖：介於二者間的實線圈表示共同點，二者朝外側延伸的虛線圈表示各自的特性，則①、②、③分別應是：", "options": {"A": "鑑定粗糙／憑畫者名聲／憑視覺觸感", "B": "鑑定粗糙／憑畫作年代／憑畫者名聲", "C": "吝出高價／憑畫者名聲／憑視覺觸感", "D": "吝出高價／憑視覺觸感／憑畫作年代"}, "answer": "A", "explain": "①是共同點：兩者都不是真正看懂畫的好壞，沈括都在批評，所以是「鑑定粗糙」。②耳鑒：聽說是鍾、王、顧、陸的手筆就搶買，靠的是「畫者名聲」。③揣骨聽聲：用手摸畫、看顏料平不平，靠的是「視覺觸感」。(A)正確。(C)(D)「吝出高價」錯，原文是「見者爭售」，搶著買，不是捨不得花錢。(B)(D)「畫作年代」原文沒提。", "skill": "雙氣泡圖：中間放「兩邊都成立」的，外側放「只有這一邊有」的，先找共同點最快刪選項。"}], "difficulty": "中", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-10", "exam": "tc114", "nums": [10], "form": "單題", "img": "img/tc114-10.png", "source": "《左傳》〈燭之武退秦師〉、《史記‧項羽本紀》", "author": "左丘明、司馬遷", "genre": "史傳人物", "types": ["人物情感", "文意推論"], "passage": "（秦、晉圍鄭，鄭文公請燭之武協助。）辭曰：「臣之壯也，猶不如人。今老矣，無能為也已。」公曰：「吾不能早用子，今急而求子，是寡人之過也。然鄭亡，子亦有不利焉。」／（項羽準備擊破劉邦，項伯暗中通知張良。）良乃入，具告沛公。沛公大驚，曰：「為之奈何？」張良曰：「誰為大王為此計者？」曰：「鯫生說我曰：『距關，毋內諸侯，秦地可盡王也。』故聽之。」", "translation": "燭之武推辭說：「我壯年時尚且比不上別人，現在老了，什麼也做不了。」鄭文公說：「我沒能早點重用您，現在危急了才來求您，這是我的過錯。不過鄭國滅亡，對您也不利啊。」／張良進去把事情全告訴劉邦。劉邦大驚說：「該怎麼辦？」張良問：「是誰替大王出這個主意的？」劉邦說：「有個淺陋的小人勸我：『守住函谷關，別讓諸侯進來，就可以占有整個秦地稱王。』所以我聽了他的。」", "keywords": [{"w": "過", "m": "過錯"}, {"w": "鯫生", "m": "淺陋無知的小人"}, {"w": "距", "m": "通「拒」，把守"}, {"w": "內", "m": "通「納」，接納"}], "questions": [{"n": 10, "qtype": "單選", "stem": "危機發生時，當事人為凝聚同陣營者，通常會使用形象修護策略。下列案例中的鄭文公面對燭之武、劉邦面對張良時，使用的策略為何？（①道歉，表示懺悔②卸責，指錯誤由他人造成③強調事件導因於無法控制的外力④強調出自好意，或行為本屬正當⑤抨擊責問者，貶損其言論可信度⑥提醒責問者，事情與你切身相關）", "options": {"A": "鄭文公①④／劉邦⑤", "B": "鄭文公①⑥／劉邦②", "C": "鄭文公②④／劉邦①③", "D": "鄭文公③⑤／劉邦④⑥"}, "answer": "B", "explain": "鄭文公說「是寡人之過也」，主動認錯，是①道歉；接著說「鄭亡，子亦有不利焉」，提醒燭之武國亡你也受害，是⑥切身相關。劉邦把責任推給「鯫生說我」，說是別人出的主意，是②卸責。所以選(B)。(A)鄭文公沒有說自己出於好意（④），劉邦也沒抨擊張良（⑤）。(C)鄭文公沒有卸責，劉邦也沒道歉。(D)鄭文公沒推給外力或抨擊燭之武，劉邦沒說自己行為正當。", "skill": "策略題先把人物原話逐句翻成白話，再替每句貼上「認錯／推責／拉關係」等標籤。"}], "difficulty": "易", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-11", "exam": "tc114", "nums": [11, 12, 13, 14, 15], "form": "題組", "img": "img/tc114-11.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["文意推論", "寫作手法", "句意理解"], "passage": "威寡者，則下侵上。／法雖不善，猶勝於無法。／與其殺不辜，寧失有罪。（《尚書‧大禹謨》）／刑罰不中，則民無所措手足。（《論語‧子路》）", "translation": "威嚴不足的人，部下就會冒犯上司。／法律即使不完善，也比沒有法律好。／與其錯殺無辜的人，寧可放過有罪的人。／刑罰不公正恰當，百姓就會手足無措，不知如何是好。", "keywords": [{"w": "寡", "m": "少、不足"}, {"w": "不辜", "m": "無罪的人"}, {"w": "失", "m": "放過、漏失"}, {"w": "中", "m": "恰當、公正"}, {"w": "措", "m": "安放"}], "questions": [{"n": 11, "qtype": "單選", "stem": "關於甲文巡警、乙文查大人的逞威尋釁，下列敘述何者正確？", "options": {"A": "巡警因秦得參對斤兩錙銖必較而不滿", "B": "巡警捏造毀損公物之罪而嚴懲秦得參", "C": "查大人因兒童隱瞞事實而怒摑他巴掌", "D": "查大人為立官威而須讓兒童接受訊問"}, "answer": "D", "explain": "乙文說查大人本來沒有為難兒童的意思，但民眾一插嘴，他怕被誤會是「受到抗議才釋放」，「很關礙做官的尊嚴」，所以非把兒童拉進衙門審問不可，(D)正確。(A)參其實還自己打了折，不是錙銖必較；巡警不滿是因為參沒有白送。(B)巡警的藉口是「稱仔不堪用」，不是毀損公物。(C)查大人打孩子是因為討厭哭聲，不是孩子隱瞞事實。", "skill": "人物動機題要找「因為……所以……」或心理描寫句，別被表面動作誤導。"}, {"n": 12, "qtype": "單選", "stem": "甲、乙文畫底線處的解釋，何者最適當？", "options": {"A": "①意謂秦得參對於自售的貨品頗有信心", "B": "②意謂巡警故意設圈套誘使秦得參犯罪", "C": "③意謂查大人視啼哭為諷刺他執法無能", "D": "④意謂民眾介入反令查大人懲罰無辜者"}, "answer": "D", "explain": "④「被人們的同情心，拖累得更不幸了」：民眾出面替兒童說話，反而讓查大人為了面子非審不可，無辜的孩子更倒楣，(D)正確。(A)①「大人要的，不用問價」是想討好巡警、表示要送他，不是對貨品有信心。(B)②巡警推辭、要求稱一稱，是故作客氣，暗示參該懂規矩，並不是設計讓他犯罪。(C)③查大人認為啼哭是弱者卑劣的舉動，有損「一等國民的面子」，不是覺得被諷刺執法無能。", "skill": "解釋畫線句時，把前後兩句一起讀，才知道說話者真正的用意。"}, {"n": 13, "qtype": "單選", "stem": "關於甲、乙文敘寫手法的說明，何者最適當？", "options": {"A": "二文皆透過街上路人的視角，以客觀而冷靜的口吻描述事件經過", "B": "甲文側重記述巡警的外在言行與情緒轉變，乙文另揭示查大人的內在想法", "C": "甲文「誠實的參」來自巡警的感受，乙文「不幸這個兒童」來自查大人的感受", "D": "二文「不去嗎」、「不說嗎」皆既凸顯施暴者的蠻橫，又洩露其受群眾威脅的不安"}, "answer": "B", "explain": "甲文寫巡警「變色地說」「赫怒了」「怒叱著」，都是外在言行與情緒；乙文則直接寫「在查大人的思想，官事一點也不容許人民過問」「怕被世間誤解」，揭露他的內心，(B)正確。(A)二文都是敘述者的觀點，而且帶有同情與諷刺，不是路人客觀冷靜的口吻。(C)「誠實的參」「不幸這個兒童」是敘述者的評語，不是巡警或查大人的感受。(D)兩句只凸顯蠻橫，看不出他們害怕群眾。", "skill": "判斷寫法時問兩件事：作者只寫人物「做什麼」，還是也寫他「想什麼」？評語是誰說的？"}, {"n": 14, "qtype": "單選", "stem": "依據下框所示的諷刺手法常見特徵，下列乙文中作者使用的兩項諷刺，最可能含有何種特徵？Ⅰ、（查大人）輕輕地打他一掌說：……那兒童立刻止住哭聲，偷偷地用手來摩擦著印有指痕紅腫的嘴巴。Ⅱ、做官的不會錯，現在已經成爲定理。（①故意說偏離常理的反話②話中有互斥的訊息③話中稱頌裡含譏誚④話中有虛偽的對比）", "options": {"A": "Ⅰ②／Ⅱ①③", "B": "Ⅰ③／Ⅱ②④", "C": "Ⅰ①②／Ⅱ④", "D": "Ⅰ③④／Ⅱ①"}, "answer": "A", "explain": "Ⅰ說「輕輕地打」，結果孩子嘴巴卻「印有指痕紅腫」，前後訊息互相矛盾，是②互斥的訊息。Ⅱ「做官的不會錯，已經成為定理」明明不合常理，是故意說的反話（①）；表面像在稱讚官員永遠正確，其實是譏諷（③）。所以選(A)。(B)Ⅰ沒有稱頌，Ⅱ也沒有對比。(C)Ⅱ沒有「我不如他」式的虛偽對比。(D)Ⅰ沒有稱頌或對比。", "skill": "諷刺句常是「字面意思和事實相反」：把字面意思和文中事實並排，就能看出是哪一種。"}, {"n": 15, "qtype": "單選", "stem": "若要形容「巡警和查大人的心態」、「賴和對巡警和查大人行徑的批評」，最適合的文句分別是：", "options": {"A": "威寡者，則下侵上／法雖不善，猶勝於無法", "B": "威寡者，則下侵上／刑罰不中，則民無所措手足", "C": "與其殺不辜，寧失有罪／法雖不善，猶勝於無法", "D": "與其殺不辜，寧失有罪／刑罰不中，則民無所措手足"}, "answer": "B", "explain": "巡警、查大人時時要維持官威，生怕百姓不怕他們，正是「威寡者，則下侵上」（威嚴不夠，下面的人就會冒犯上面）的心態。賴和批評他們濫用權力、隨意處罰，讓百姓無所適從，正是「刑罰不中，則民無所措手足」。所以選(B)。(C)(D)「與其殺不辜，寧失有罪」是寧可放過壞人也不冤枉好人，跟他們隨便懲罰無辜正好相反。(A)(C)「法雖不善，猶勝於無法」是替不完善的法律辯護，不是批評。", "skill": "用文言名句形容人物時，先把名句翻成白話，再問「這是他會說的話，還是作者會說的話」。"}], "difficulty": "中", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-16", "exam": "tc114", "nums": [16, 17, 18, 19], "form": "題組", "img": "img/tc114-16.png", "source": "陶淵明〈桃花源記〉、宋應星《天工開物》（引文）", "author": "", "genre": "其他", "types": ["文意推論", "句意理解"], "passage": "自云先世避秦時亂，率妻子、邑人來此絕境，……乃不知有漢，無論魏、晉。（陶淵明〈桃花源記〉）／草木之實，其中韞藏膏液，而不能自流；假媒水火，憑藉木石，而後傾注而出焉。（宋應星《天工開物》）", "translation": "他們說祖先為了躲避秦朝的戰亂，帶著妻兒和同鄉來到這個與世隔絕的地方……竟然不知道有漢朝，更不用說魏、晉了。／草木的果實裡蘊藏著油脂，但不會自己流出來；要借助水、火，靠木製、石製的器具壓榨，油才會流出來。", "keywords": [{"w": "絕境", "m": "與外界隔絕的地方"}, {"w": "無論", "m": "更不必說"}, {"w": "韞藏", "m": "蘊藏"}, {"w": "假媒", "m": "憑藉、借助"}], "questions": [{"n": 16, "qtype": "單選", "stem": "依據上文，下列構造位於各燈何處？（長信宮燈導煙管／夾燈盞放水處／銅牛燈放油處）", "options": {"A": "ㄅ／ㄇ／ㄊ", "B": "ㄅ／ㄈ／ㄉ", "C": "ㄆ／ㄈ／ㄊ", "D": "ㄆ／ㄇ／ㄉ"}, "answer": "B", "explain": "長信宮燈「中空的右臂是導煙管」，煙從燈罩往上進入右臂，圖中ㄅ標在燈罩頂端連接右臂處；ㄆ標的是左手托燈盤處，不是導煙管。夾燈盞「上層盛油，下層則從側邊小孔注水」，放水處在下層ㄈ，ㄇ是上層盛油處。銅牛燈放油處是燈罩內的燈盤，即ㄉ；ㄊ標的是牛腹，那是裝水的地方。所以選(B)。", "skill": "圖文對照題先在文中圈出每個構造的位置描述（上層、下層、右臂、腹部），再對回圖上的符號。"}, {"n": 17, "qtype": "單選", "stem": "依據上文，關於燈具的敘述，何者正確？", "options": {"A": "青銅容易導熱，自漢至宋皆是燈具製作材料的主流", "B": "兩座銅燈與夾燈盞雖然大小有別，但皆可拆開清潔", "C": "兩座銅燈著重造型設計，無法調光；夾燈盞雖無造型，但可調光", "D": "兩座銅燈的燈盤結構考量燃料屬性；夾燈盞省油效能受氣溫影響"}, "answer": "D", "explain": "銅燈燈盤有針錐，是為了插固態的動物油脂；夾燈盞省油「要夏天才有這水準」，受氣溫影響，(D)正確。(A)漢代民間普遍用陶燈，宋代夾燈盞是瓷製，青銅從來不是主流。(B)夾燈盞是「一體成型」，不能拆。(C)長信宮燈的燈罩板子「可調節光的亮度與方向」，並非無法調光；夾燈盞也沒說能調光。", "skill": "多燈比較題，先做一張「材質／燃料／能否拆／能否調光」的小表格，選項一對就知道。"}, {"n": 18, "qtype": "單選", "stem": "上文三個燈具，在設計上的共同考量要素為何？", "options": {"A": "燃料種類、起居環境", "B": "經濟實惠、節能減碳", "C": "安全保護、氣氛營造", "D": "用者身分、觀賞價值"}, "answer": "A", "explain": "燃料：銅燈用固態動物油脂所以有針錐，夾燈盞用植物油並設計夾層降溫省油。起居環境：漢代人席地而坐，燈高配合俯角；宋代人坐椅子，小燈方便移上燈架。三盞燈都考量這兩點，(A)正確。(B)省油只有夾燈盞強調，銅燈是豪門排場，不講經濟實惠。(C)文中沒談安全保護與氣氛。(D)講究身分排場的只有兩座銅燈，夾燈盞是一般讀書人用。", "skill": "「共同」考量要三個都符合，只要找到一個不符合的就刪。"}, {"n": 19, "qtype": "單選", "stem": "依據上文，下列①、②兩項陳述是否適當，正確的研判是：①由〈桃花源記〉「自云先世避秦時亂，率妻子、邑人來此絕境，……乃不知有漢，無論魏、晉」來看，桃花源中的居民不知有油燈，也不知桃花源外使用青銅燈。②由《天工開物》「草木之實，其中韞藏膏液，而不能自流；假媒水火，憑藉木石，而後傾注而出焉」可知，因油品生產不易，為了省油，夾燈盞越做越大。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "B", "explain": "①上文說「油燈在商、周時代就有了」，桃花源居民秦末才入山，不可能不知道油燈；「不知有漢」只表示不知朝代更替，推不出不知油燈或青銅燈，①錯。②《天工開物》確實說植物油要靠水火、器具壓榨才得來；但上文明說「也不是夾層水多就省油效果強，所以燈盞也不用大」，夾燈盞並沒有越做越大，②錯。選(B)。", "skill": "引古文推論時，先確定古文本身說了什麼，再檢查推論有沒有和本文資料衝突。"}], "difficulty": "中", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-20", "exam": "tc114", "nums": [20, 21, 22, 23], "form": "題組", "img": "img/tc114-20.png", "source": "《諧鐸‧壯夫縛虎》", "author": "沈起鳳", "genre": "筆記小品", "types": ["人物情感", "寫作手法", "主旨寓意", "句意理解"], "passage": "沂州山峻險，故多猛虎，邑宰時令獵戶捕之，往往反為所噬。有焦奇者，陝人，投親不值，流寓於沂。素神勇，曾挾千佛寺前石鼎，飛騰大雄殿左脊，故人呼為焦石鼎云。知沂嶺多虎，日徒步入山，遇虎輒手格斃之，負以歸，如是為常。一日入山，遇兩虎帥一小虎至。焦性起，連斃兩虎，左右肩負之，而以小虎生擒而返。眾皆辟易，焦笑語自若。富家某，欽其勇，設筵款之。焦於座上，自述其平昔縛虎狀，聽者俱色變。而焦益張大其詞，口講指畫，意氣自豪。倏有一貓，登筵攫食，腥汁淋漓滿座上，焦以為主人之貓也，聽其大嚼而去。主人曰：「鄰家孽畜，可厭乃爾！」亡何，貓又來。焦急起奮拳擊之，座上肴核盡傾碎，而貓已躍伏窗隅。焦怒，又逐擊之，窗櫺盡裂，貓一躍登屋角，目耽耽視焦。焦愈怒，張臂作擒縛狀，而貓嗥然一聲，曳尾徐步，過鄰牆而去，焦計無所施，面牆呆望而已。主人撫掌笑，焦大慚而退。", "translation": "沂州山勢險峻，所以老虎很多，縣官常派獵戶去捕，獵戶卻常反被老虎咬死。有個叫焦奇的陝西人，來投靠親戚沒找到，就流落住在沂州。他向來神勇，曾挾著千佛寺前的石鼎，飛身躍上大雄寶殿左邊的屋脊，所以人稱「焦石鼎」。他知道沂州山嶺多虎，每天徒步進山，遇到老虎就徒手打死，扛回家，習以為常。有一天進山，遇到兩隻大虎帶著一隻小虎。焦奇性子一起，接連打死兩隻大虎，左右肩各扛一隻，還活捉了小虎回來。眾人都嚇得退避，焦奇卻談笑自若。有個富人佩服他的勇猛，設宴款待。焦奇在席上講述自己平日縛虎的情形，聽的人都變了臉色；焦奇更加誇大其詞，邊說邊比劃，意氣自豪。忽然有一隻貓跳上宴席搶食，腥湯灑滿座位。焦奇以為是主人的貓，任牠大吃一頓才走。主人說：「這是鄰居家的壞畜生，討厭得很！」不久，貓又來了。焦奇急忙起身揮拳打牠，桌上菜餚果品全打翻了，貓卻已跳到窗角伏著。焦奇發怒，又追著打，把窗格全打裂了，貓一躍跳上屋角，眼睛直直盯著焦奇。焦奇更怒，張開手臂作出要擒拿的樣子，貓卻「嗷」地叫了一聲，拖著尾巴慢慢走，翻過鄰居的牆走了。焦奇無計可施，只能對著牆發呆。主人拍手大笑，焦奇非常慚愧地告退。", "keywords": [{"w": "不值", "m": "沒遇到"}, {"w": "手格", "m": "徒手搏擊"}, {"w": "辟易", "m": "驚退躲避"}, {"w": "口講指畫", "m": "邊說邊用手比劃"}, {"w": "亡何", "m": "不久（亡通無）"}, {"w": "耽耽", "m": "注視的樣子"}, {"w": "計無所施", "m": "想不出辦法"}], "questions": [{"n": 20, "qtype": "單選", "stem": "關於焦奇的人物形象解讀，何者最符合上文所述？", "options": {"A": "「連斃兩虎，生擒小虎」暗示他雖暴戾，仍有好生之德", "B": "「眾皆辟易」暗示來自外地的他過於驕橫，遂遭排擠", "C": "「富家設筵款之」暗示打虎使他成名，漸開啟社交", "D": "「口講指畫」暗示他雖性格粗豪，但思慮縝密"}, "answer": "C", "explain": "富人「欽其勇，設筵款之」，可見他靠打虎出名，開始被人請去應酬，(C)正確。(A)生擒小虎是展現神力，文中沒有憐惜小虎的意思，談不上好生之德。(B)「辟易」是眾人被他扛虎的樣子嚇得退開，不是排擠他。(D)「口講指畫，意氣自豪」是誇誇其談、得意忘形，看不出思慮縝密。", "skill": "人物形象題要抓原文的「因果」：誰因為什麼對他做了什麼，就能看出別人眼中的他。"}, {"n": 21, "qtype": "單選", "stem": "關於上文寫作技巧的敘述，何者最適當？", "options": {"A": "以獵戶常鹵莽捕虎而遭噬，襯托焦奇擒虎有勇有謀", "B": "以對擊貓、擒虎的描述詳、略有別，凸顯主人恨貓勝於虎", "C": "透過描述貓的行動、眼神，呈現貓在危亂中依然敏捷而從容", "D": "透過主人笑、焦奇慚的對比，諷刺憑空杜撰者的謊言必被揭穿"}, "answer": "C", "explain": "貓「躍伏窗隅」「一躍登屋角」寫敏捷，「目耽耽視焦」「嗥然一聲，曳尾徐步」寫從容不迫，焦奇越打越亂，貓卻越來越悠閒，(C)正確。(A)獵戶反被虎咬是襯托焦奇神勇，但焦奇是徒手硬拚，文中看不出「有謀」，也沒說獵戶鹵莽。(B)詳寫擊貓是為了寫焦奇的狼狽，不是寫主人恨貓。(D)焦奇打虎是真的（日日負虎而歸），不是憑空杜撰；主人笑是笑他打不著一隻小貓。", "skill": "寫作技巧題常考「對比」：找出文中誰在動、誰在靜，誰慌、誰從容。"}, {"n": 22, "qtype": "單選", "stem": "上文作者說完此故事後，認為焦奇並非「大敵勇而小敵怯」，而是「函牛之鼎不可以烹小鮮，千斤之弩不可以中鼷鼠」，這句話的意思與何者最接近？", "options": {"A": "不斫柱以為椽", "B": "幸於始者怠於終", "C": "人為刀俎，我為魚肉", "D": "不凝滯於物，而能與世推移"}, "answer": "A", "explain": "能裝一頭牛的大鼎不能拿來煮小魚，千斤的強弩射不中小老鼠——大才不適合用在小地方。(A)「不斫柱以為椽」＝不把做柱子的大木頭砍小去當椽子，同樣是大材不可小用，正確。(B)是開頭幸運、後來懈怠。(C)〈鴻門宴〉比喻自己處境危險、任人宰割。(D)〈漁父〉是說聖人不拘泥，能隨世事變通。", "skill": "比喻句先翻出「本體」：鼎、弩是大器，小鮮、鼷鼠是小事，意思就是「大器不宜小用」。"}, {"n": 23, "qtype": "單選", "stem": "上文描寫焦奇擊貓，使用「焦怒……→焦愈怒……」的遞進手法。下列文句，何者也有類似敘寫方式？", "options": {"A": "車中派驗票司事一人，專管裝卸貨物、稽查客車", "B": "其煤質鬆脆，不敵西洋所産，而與東洋之煤尚相去不遠", "C": "固知一死生爲虛誕，齊彭殤爲妄作。後之視今，亦猶今之視昔", "D": "旦視而暮撫，已去而復顧。甚者爪其膚以驗其生枯，搖其本以觀其疏密"}, "answer": "D", "explain": "遞進是程度一層比一層深。(D)〈種樹郭橐駝傳〉先寫早上看、晚上摸，走了又回頭看，「甚者」更進一步抓破樹皮、搖動樹根，程度越來越嚴重，是遞進，正確。(A)只是說明一個職位的職責，屬並列。(B)比較煤質不如西洋、接近東洋，是比較。(C)〈蘭亭集序〉先否定一死生、齊彭殤，再推論後人看今人如同今人看古人，是推論，不是程度加深。", "skill": "遞進的訊號詞：愈、更、甚者、況、而且；看到這些字，再確認後面是不是更進一層。"}], "difficulty": "中", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-24", "exam": "tc114", "nums": [24, 25, 26, 27], "form": "題組", "img": "img/tc114-24.png", "source": "金九容〈岳陽樓〉、權近〈息波亭記〉、鄭道傳〈二樂亭記〉、姜弘重《東槎錄》、李穡〈詠月〉〈對菊有感〉", "author": "金九容、權近、鄭道傳、姜弘重、李穡", "genre": "其他", "types": ["比較閱讀", "文意推論", "典故出處", "字詞解釋"], "passage": "舟中遙望岳陽樓，未得登臨作勝遊。何日東歸重過此，倚欄吟賞洞庭秋。（金九容〈岳陽樓〉）／二樂亭，乃義安伯別墅也……諸山端重，如仁者以靜自守；江水通注，如智者動而不括；宜君子所當樂也……昔范文正公登岳陽樓嘆曰：「先天下之憂而憂，後天下之樂而樂」，我思古人，實獲我心。予亦以為待諸公戮力王室，底定生民，功成謝事，然後尊俎杖履，翱翔於此亭之上，恣心志之娛樂。（鄭道傳）／（公）嘗慕范文正公「先天下之憂而憂，後天下之樂而樂」之語……夫岳陽樓，天下之勝，概凡寓目者，可悲可娛，皆繫所感，而范公憂樂則獨關於天下。今公於此亭，既得以與人同其樂，且推其憂於息波，是其心之憂樂，皆在於及人而不繫於一己者可見矣。（權近）／洞庭之岳陽，雖未曾目見，景致之勝絕，氣勢之雄壯，想未必過於此矣。惜乎在蠻邦鄙野之地，不使文人才士品題於其間也。（姜弘重）／憶年八九學堂遊，似鏡如鉤誦不休。中歲始知真樂處，躍金沉璧岳陽樓。（李穡〈詠月〉）／人情那似物無情，觸境年來漸不平。偶向東籬羞滿面，真黃花對僞淵明。（李穡〈對菊有感〉）", "translation": "金九容：在船上遠遠望見岳陽樓，可惜沒能登樓暢遊。哪天東歸故國時再經過這裡，一定要倚著欄杆吟賞洞庭秋色。鄭道傳：二樂亭是義安伯的別墅……群山端莊穩重，像仁者以靜自守；江水流通不息，像智者行動而無阻礙；正是君子該享受的樂趣……從前范仲淹登岳陽樓感嘆「先天下之憂而憂，後天下之樂而樂」，我思念古人，這話說中我的心。我也認為要等大家為王室盡力、安定百姓、功成身退後，再帶著酒器、拄著手杖，在這亭上逍遙，盡情享受心中的快樂。權近：（這位朋友）曾仰慕范仲淹「先憂後樂」的話……岳陽樓是天下勝景，凡是看到的人，或悲或喜，都繫於個人的感受，只有范公的憂樂關乎天下。如今您在這座亭子，既能與人同樂，又把憂心推及到希望波濤平息（讓渡口行人平安），可見您心中的憂樂都在惠及他人，而不只為自己。姜弘重：洞庭湖邊的岳陽樓我雖沒親眼見過，但它景致的絕美、氣勢的雄壯，想來也未必超過這裡。可惜在蠻荒偏遠之地，沒有讓文人雅士來題詠。李穡〈詠月〉：記得八九歲在學堂時，不停誦讀「似鏡」「如鉤」的詠月詩句；到中年才明白真正的快樂，在於岳陽樓那「浮光躍金，靜影沉璧」的境界。〈對菊有感〉：人情哪像無情的外物（那樣平靜），近年來觸景總是心中不平；偶然走到東籬下，羞得滿臉通紅——真正的菊花，面對的是我這個假陶淵明。", "keywords": [{"w": "東歸", "m": "向東回到故國（高麗）"}, {"w": "二樂", "m": "仁者樂山、智者樂水"}, {"w": "戮力", "m": "盡力"}, {"w": "底定", "m": "安定"}, {"w": "尊俎杖履", "m": "酒器與手杖、鞋子，指閒居遊樂"}, {"w": "息波", "m": "使波浪平息"}, {"w": "躍金沉璧", "m": "出自〈岳陽樓記〉「浮光躍金，靜影沉璧」，寫月光照湖"}, {"w": "東籬", "m": "出自陶淵明「采菊東籬下」"}], "questions": [{"n": 24, "qtype": "單選", "stem": "依據上列資料，可以確知的是：", "options": {"A": "金九容和權近皆在訪問中國時，親蒞岳陽樓", "B": "鄭道傳〈二樂亭記〉，姜弘重因學習諺文而無法閱讀", "C": "在李穡引領下，十四世紀末曾有韓國士大夫接受儒家思想", "D": "十四世紀的韓國士大夫，大多不能直接閱讀漢文的〈岳陽樓記〉"}, "answer": "C", "explain": "鄭道傳、權近都「師承高麗王朝大儒李穡」，權近著有《五經淺見錄》，鄭道傳讚同范仲淹先憂後樂的儒家襟懷，可確知十四世紀末有韓國士大夫接受儒家思想，(C)正確。(A)金九容詩說「未得登臨」，沒有登上岳陽樓；權近也沒寫到親自登樓。(B)姜弘重自己就用漢文寫作，看不出無法閱讀漢文。(D)資料說創造諺文之前「士大夫皆閱讀並書寫漢文」，他們還引用〈岳陽樓記〉原句，顯然能直接閱讀。", "skill": "「可以確知」要找資料中有明文依據的，凡是需要猜測或和原文相反的都刪。"}, {"n": 25, "qtype": "單選", "stem": "若要就上列資料，說明古代韓國士大夫兩種想法：①視岳陽樓為勝景的代表，②視〈岳陽樓記〉作者為理想人格的表徵，分別適合以誰的言論為證？", "options": {"A": "①金九容／②姜弘重", "B": "①鄭道傳／②權近", "C": "①權近／②金九容", "D": "①姜弘重／②鄭道傳"}, "answer": "D", "explain": "①姜弘重拿岳陽樓當標準，說日本草津湖的景致「想未必過於此矣」，正是把岳陽樓視為勝景代表。②鄭道傳說范仲淹的先憂後樂「我思古人，實獲我心」，把范仲淹當成理想人格。所以選(D)。(A)姜弘重只談景色，沒有推崇范仲淹人格。(B)鄭道傳文中談的是二樂亭與范公襟懷，沒有把岳陽樓當勝景標準。(C)金九容只是想登樓遊賞，沒有談到范仲淹的人格。", "skill": "配對題先把每個人的「重點句」各用一句話摘要，再和題目要找的兩種想法對號入座。"}, {"n": 26, "qtype": "單選", "stem": "李穡的詩頗多漢文典故。關於右框二詩運用「岳陽樓」、「陶淵明」典故的解說，正確的研判是：①〈詠月〉以「岳陽樓」的湖中倒影浮蕩飄忽，寄託童年逝去的感傷。②〈對菊有感〉以「偽淵明」自比，表達身在田園但心難悠然的慨嘆。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "D", "explain": "①「躍金沉璧」出自〈岳陽樓記〉月光照湖的美景，「中歲始知真樂處」是說到中年才體會真正的快樂，是悟道的喜悅，不是童年逝去的感傷，①錯。②他走到「東籬」看菊，但「觸境年來漸不平」，心中不能像陶淵明那樣悠然，所以羞愧地自稱「偽淵明」，②正確。選(D)。", "skill": "解典故先還原原典的意思（躍金沉璧＝月光美景、東籬＝悠然隱居），再看作者用它表達什麼。"}, {"n": 27, "qtype": "單選", "stem": "上列資料中的詞語解釋，何者最適當？", "options": {"A": "金九容詩中的「東歸」，意指奉派出使中國", "B": "鄭道傳文中的「二樂」，意指先天下之樂、後天下之樂", "C": "權近讚許友人有心繫群眾的胸懷，故云「推其憂於息波」", "D": "姜弘重自慚韓國文人才士不足，恐將淪為「蠻邦鄙野之地」"}, "answer": "C", "explain": "權近說友人「既得以與人同其樂，且推其憂於息波」，憂的是渡口波濤危及行人，所以把亭子取名「息波」，正是心繫眾人的胸懷，(C)正確。(A)韓國在中國東邊，「東歸」是回到故國，不是出使中國。(B)「二樂」指文中「諸山端重如仁者」「江水通注如智者」，即仁者樂山、智者樂水。(D)姜弘重是在日本看到草津湖，「蠻邦鄙野之地」指日本，可惜那裡沒有文人題詠，不是自慚韓國。", "skill": "詞語解釋題要回到上下文：看說話者人在哪裡、前一句講什麼，才不會望文生義。"}], "difficulty": "難", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc114-31", "exam": "tc114", "nums": [31, 32, 33, 34, 35], "form": "題組", "img": "img/tc114-31.png", "source": "《海錄》", "author": "謝清高", "genre": "其他", "types": ["文意推論", "字詞解釋"], "passage": "乾隆中，有粵人羅芳伯者貿易於此，豪俠善技擊，頗得眾心。時土番竊發，商賈不安，芳伯屢率眾平之。又鱷魚為害，芳伯為壇於海旁，陳列犧牲，取韓昌黎祭文宣讀而焚之，鱷魚遁去。華夷敬畏，尊為客長。", "translation": "乾隆年間，有個廣東人羅芳伯在這裡做生意，為人豪爽講義氣，擅長武術，很得人心。當時土著常暗中作亂，商人不得安寧，羅芳伯多次帶領眾人平定他們。又有鱷魚為害，羅芳伯在海邊設壇，擺上祭品，拿韓愈的〈祭鱷魚文〉宣讀後燒掉，鱷魚就逃走了。華人和當地人都敬畏他，尊稱他為「客長」。", "keywords": [{"w": "豪俠", "m": "豪爽講義氣"}, {"w": "技擊", "m": "武術"}, {"w": "土番", "m": "當地土著"}, {"w": "竊發", "m": "暗中作亂"}, {"w": "犧牲", "m": "祭祀用的牲畜"}, {"w": "韓昌黎祭文", "m": "韓愈〈祭鱷魚文〉"}, {"w": "客長", "m": "客家人的首領（尊稱）"}], "questions": [{"n": 31, "qtype": "單選", "stem": "依據上文，關於蘭芳公司的敘述，何者正確？", "options": {"A": "羅芳伯聯合張阿財、江戊伯所創，總廳設於東萬律", "B": "建創時得到坤甸蘇丹、荷蘭東印度公司的共同支持", "C": "由採金業起家，是西婆羅洲第一家成立的華人公司", "D": "在公司首長的推選上，很注重故鄉地域和宗族背景"}, "answer": "D", "explain": "文中說「按規矩，總廳大哥須是嘉應州人」，後段也說這些公司「講求地緣與宗族」，(D)正確。(A)張阿財是金礦被羅芳伯拿下後留任管財務的人，江戊伯是1778年才合作，都不是共同創辦人。(B)當時荷蘭東印度公司「尚未插足西婆羅洲」，談不上支持。(C)婆羅洲早有潮州人公司等華人公司，蘭芳不是第一家。", "skill": "有年份的歷史文，把事件依年份排成時間線，就能抓出選項中「時間錯置」的陷阱。"}, {"n": 32, "qtype": "單選", "stem": "依據上文，關於婆羅洲華人公司的敘述，何者正確？", "options": {"A": "有公司以兼併策略擴張，也有公司透過聯盟尋求發展", "B": "多數公司揚棄中國村社體制，改學習美國而實行民主", "C": "各公司對荷蘭東印度公司勢力西伸，皆抗拒而不屈服", "D": "其優點及成員被荷蘭東印度公司吸收，因而走向覆滅"}, "answer": "A", "explain": "蘭芳「兼併茅恩多家華人公司」，大港等公司則「組成『和順聯盟』」，兩種方式都有，(A)正確。(B)華人公司是「沿用中國村社選賢舉能」的體制，「堪比美國」只是後人的比喻。(C)蘭芳後來接受荷蘭授予的「甲太」職銜，是「妥協」，並非都不屈服。(D)大港被荷蘭「踏平」、蘭芳「毀於荷蘭人的進逼」，是被武力消滅，不是被吸收。", "skill": "注意「多數」「皆」這類全稱字眼，只要找到一個反例就能刪去。"}, {"n": 33, "qtype": "單選", "stem": "蘭芳公司的某些情況，常成為「婆羅洲華人公司是否為共和國」的論證事例。依據上文，不同觀點的言論最可能以①、②、③何者為支持事例？①總廳大哥的資格有籍貫限制。②總廳大哥須經由推舉程序產生。③總廳大哥頭銜改為「蘭芳大總制甲太」。（主張是共和國／不同意是共和國）", "options": {"A": "②／①", "B": "②／③", "C": "③／①", "D": "③／②"}, "answer": "A", "explain": "主張是共和國的人看重「選賢舉能、事務共決」，所以會舉②「總廳大哥須經推舉」為證。反對者認為這些公司「不脫講求地緣與宗族的村社本質」，所以會舉①「必須是嘉應州人」的籍貫限制為證。選(A)。③頭銜改為荷蘭授予的「甲太」，說的是蘭芳因妥協而獨立性減弱，和是否為「共和國」的民主性質無直接關係，(B)(C)(D)都誤用了③或把②放錯邊。", "skill": "論證題先寫出雙方的「判準」（民主推舉 vs. 地緣宗族），再把事例分別歸隊。"}, {"n": 34, "qtype": "單選", "stem": "某篇敘述蘭芳公司歷史的文章說：「羅芳伯未號稱『大唐總長』，也未以『蘭芳』紀元」。依據上文，可推知其採用文獻的作法及理由為何？", "options": {"A": "取時代早的記載：或許較接近當時事實", "B": "取時代晚的記載：提出較新的考證方法", "C": "取荷蘭官方的記載：看華人公司較客觀", "D": "取客家人立場的記載：寫當事人較深入"}, "answer": "A", "explain": "「大唐總長」「蘭芳紀元」出自1912年林鳳超《坤甸歷史》與1961年羅香林的書；1856年的《蘭芳公司歷代年冊》對此「隻字未提」。這篇文章採信沒有這些說法的年冊，就是取時代較早的記載，因為離事件較近、可能較可信，(A)正確。(B)它沒採用較晚的說法。(C)年冊作者是末代甲太劉生的女婿，是華人，不是荷蘭官方記載。(D)文中沒有說哪份資料是客家人立場。", "skill": "史料題先比「年代」與「作者身分」，再看結論和哪份史料一致。"}, {"n": 35, "qtype": "單選", "stem": "《海錄》是嘉應州人謝清高的南洋經歷紀錄，1820年刊行。下列是書中關於羅芳伯的記載，①～⑤的解釋，何者符合上文？①此：指坤甸、東萬律一帶　②眾：指客家人　③商賈：指荷蘭東印度公司　④之：指達雅人　⑤客長：指蘭芳大總制", "options": {"A": "①②③", "B": "①②④", "C": "②③⑤", "D": "③④⑤"}, "answer": "B", "explain": "①羅芳伯「貿易於此」，上文說他抵達坤甸、轉往東萬律，正確。②「頗得眾心」，他「成功吸引坤甸附近的客家人投靠」，眾指客家人，正確。④「土番竊發……芳伯屢率眾平之」，上文說蘭芳「能壓制土著達雅人」，「之」指達雅人，正確。③商賈是一般商人，荷蘭東印度公司當時尚未插足西婆羅洲，錯。⑤「客長」是華夷對他的尊稱，「蘭芳大總制」是後人之說，「大總制甲太」更是荷蘭後來授予的職銜，錯。選(B)。", "skill": "代詞「之、此」要往前找它代替的名詞，再拿去和白話資料對照。"}], "difficulty": "中", "label": "114統測", "year": 114, "kind": "統測"}, {"id": "tc115-02", "exam": "tc115", "nums": [2], "form": "單題", "img": "img/tc115-02.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["虛詞句式", "字詞解釋"], "passage": "蘇子愀然，正襟危坐而問客曰：「何為其然也？」（蘇軾〈赤壁賦〉）", "translation": "我（蘇軾）臉色變得憂傷，整理衣襟端正坐好，問客人說：「為什麼（簫聲）會這樣悲涼呢？」", "keywords": [{"w": "愀然", "m": "臉色改變、憂傷的樣子（然為形容詞詞尾）"}, {"w": "然", "m": "①形容詞詞尾，……的樣子 ②如此、這樣 ③但是"}], "questions": [{"n": 2, "qtype": "單選", "stem": "依據下文兩個「然」的用法，下列敘述，何者正確？蘇子愀①然，正襟危坐而問客曰︰「何為其②然也？」", "options": {"A": "「屋舍儼然」、「項王默然不應」的「然」，用法皆同於①", "B": "「奏刀騞然」、「然鄭亡，子亦有不利焉」的「然」，用法皆同於①", "C": "「滿目蕭然」、「然臺煤雖富，年來開採仍不甚旺」的「然」，用法皆同於②", "D": "「他植者則不然」、「梯航萬國，能使帝京元氣充然」的「然」，用法皆同於②"}, "answer": "A", "explain": "①「愀然」的「然」是形容詞詞尾，表示「……的樣子」；②「其然」的「然」是代詞「如此、這樣」。(A)〈桃花源記〉「儼然」＝整齊的樣子，〈鴻門宴〉「默然」＝沉默的樣子，都是詞尾，同①，正確。(B)〈庖丁解牛〉「騞然」是詞尾，同①；但〈燭之武退秦師〉「然鄭亡」的「然」是「但是」，不同。(C)〈岳陽樓記〉「蕭然」是詞尾，同①不同②；「然臺煤雖富」的「然」是「但是」，也不同②。(D)〈種樹郭橐駝傳〉「不然」＝不是這樣，同②；但「元氣充然」是「充沛的樣子」，屬詞尾，不同②。", "skill": "「然」黏在形容詞或狀聲詞後面多是詞尾；放在句首多是「但是」；放在「其、不、使」後面多是「如此」。"}], "difficulty": "中", "label": "115統測", "year": 115, "kind": "統測"}, {"id": "tc115-04", "exam": "tc115", "nums": [4], "form": "單題", "img": "img/tc115-04.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["句意理解", "寫作手法"], "passage": "長者為榱，短者為梲。／道之所存，師之所存也。（韓愈〈師說〉）／彼節者有間，而刀刃者無厚。（〈庖丁解牛〉）／縱一葦之所如，凌萬頃之茫然。（蘇軾〈赤壁賦〉）／凡鑑窪則照人面大，凸則照人面小。（沈括《夢溪筆談》）", "translation": "長的木材做椽子，短的木材做梁上短柱。／道理在哪裡，老師就在哪裡。／牛的骨節有空隙，刀刃薄得沒有厚度。／任憑小船隨意漂流，越過茫茫無邊的江面。／凡是鏡面凹的照出來人臉大，凸的照出來人臉小。", "keywords": [{"w": "榱", "m": "椽子"}, {"w": "梲", "m": "梁上的短柱"}, {"w": "鑑", "m": "鏡子"}, {"w": "窪", "m": "凹下"}], "questions": [{"n": 4, "qtype": "單選", "stem": "下框例句為「就一事物區分為兩個類別，呈現不同的功能或用途」。下列文句，何者也屬此一表述方式？（例句：長者為榱，短者為梲。）", "options": {"A": "道之所存，師之所存也", "B": "彼節者有間，而刀刃者無厚", "C": "縱一葦之所如，凌萬頃之茫然", "D": "凡鑑窪則照人面大，凸則照人面小"}, "answer": "D", "explain": "例句把「木材」依長短分兩類，各有不同用途。(D)把「鏡子」依凹、凸分兩類，照出來的人臉一大一小，功能不同，結構完全一樣，正確。(A)〈師說〉說道與師同在，是等同關係，沒有分類。(B)〈庖丁解牛〉說的是「牛的骨節」和「刀刃」兩種不同的東西，不是同一事物分兩類。(C)〈赤壁賦〉描寫小舟在江上漂流，沒有分類。", "skill": "套用框中的公式：同一個東西＋同一個分類標準（長短、凹凸）＋各自的結果。三樣都到齊才對。"}], "difficulty": "易", "label": "115統測", "year": 115, "kind": "統測"}, {"id": "tc115-06", "exam": "tc115", "nums": [6], "form": "單題", "img": "img/tc115-06.png", "source": "綜合（歐陽修、王安石、黃仲元評韓柳語）", "author": "歐陽修、王安石、黃仲元", "genre": "說理議論", "types": ["文意推論", "文化常識"], "passage": "自唐以來，言文章者惟韓、柳。柳豈韓之徒哉？真韓門之罪人也。（歐陽修）／柳文卒配韓以傳，亦豪傑可畏者也。（王安石）／柳之醇正固不及韓，柳之奇崛亦韓所不及。（黃仲元）", "translation": "歐陽修：自唐代以來，談文章的人只推韓愈、柳宗元。柳宗元哪裡是韓愈一路的人？簡直是韓門的罪人。王安石：柳宗元的文章終究和韓愈並列而流傳，也算是令人敬畏的豪傑。黃仲元：柳文的純正固然比不上韓文，但柳文的奇特峻拔也是韓文比不上的。", "keywords": [{"w": "徒", "m": "同一類的人、門人"}, {"w": "卒", "m": "終於"}, {"w": "配", "m": "匹配、並列"}, {"w": "醇正", "m": "純正"}, {"w": "奇崛", "m": "奇特峻拔"}], "questions": [{"n": 6, "qtype": "單選", "stem": "下圖是某講解單元的內容摘要，此單元的名稱最可能為何？（圖示：唐代韓愈、柳宗元；宋代歐陽修、王安石、黃仲元評語）", "options": {"A": "韓愈、柳宗元的相識互動", "B": "「韓、柳並稱」如何形成", "C": "韓、柳對六朝駢文的態度", "D": "「唐宋八大家」的代表作"}, "answer": "B", "explain": "三段宋人評論都在談韓、柳能不能相提並論：歐陽修承認世人「言文章者惟韓、柳」卻不服柳；王安石說柳文「卒配韓以傳」；黃仲元說兩人各有所長。整條時間軸呈現「韓柳並稱」在宋代被討論、確立的過程，(B)正確。(A)圖中都是後人評價，沒寫兩人如何交往。(C)沒有提到駢文。(D)沒有列舉任何代表作，也只談韓柳兩家。", "skill": "找單元名稱就是找「所有材料的共同話題」，每段都提到的關鍵詞（韓、柳）就是核心。"}], "difficulty": "易", "label": "115統測", "year": 115, "kind": "統測"}, {"id": "tc115-07", "exam": "tc115", "nums": [7], "form": "單題", "img": "img/tc115-07.png", "source": "綜合（多篇古文）", "author": "", "genre": "其他", "types": ["寫作手法"], "passage": "屈原既放，遊於江潭，行吟澤畔，顏色憔悴。（〈漁父〉）／登斯樓也，則有心曠神怡，寵辱偕忘。（范仲淹〈岳陽樓記〉）／人群分而物異產，來往貿遷，以成宇宙。（宋應星《天工開物》）／林盡水源，便得一山，山有小口，彷彿若有光。（陶淵明〈桃花源記〉）／雖無絲竹管絃之盛，一觴一詠，亦足以暢敘幽情。（王羲之〈蘭亭集序〉）", "translation": "屈原被放逐後，在江邊遊蕩，在水澤邊邊走邊吟，臉色憔悴。／登上這座樓，就會心胸開闊、精神愉快，榮辱全都忘了。／人分居各地、物產各不相同，互相往來貿易，才構成這個世界。／桃花林到了溪水源頭就沒了，眼前出現一座山，山上有個小洞口，隱隱約約好像有光。／雖然沒有音樂演奏的熱鬧，但喝酒吟詩，也足以盡情抒發深藏的情懷。", "keywords": [{"w": "放", "m": "放逐"}, {"w": "貿遷", "m": "貿易往來"}, {"w": "彷彿", "m": "隱約、好像"}], "questions": [{"n": 7, "qtype": "單選", "stem": "「屈原既放，遊於江潭，行吟澤畔，顏色憔悴」，敘述者的視線是由整體（屈原）聚焦到局部（面容）。下列文字，何者也運用類似的敘述方式？", "options": {"A": "登斯樓也，則有心曠神怡，寵辱偕忘", "B": "人群分而物異產，來往貿遷，以成宇宙", "C": "林盡水源，便得一山，山有小口，彷彿若有光", "D": "雖無絲竹管絃之盛，一觴一詠，亦足以暢敘幽情"}, "answer": "C", "explain": "(C)〈桃花源記〉的視線從「一座山」縮小到「山上的小口」，再聚焦到洞口裡「彷彿若有光」，由整體到局部，就像鏡頭拉近，正確。(A)〈岳陽樓記〉寫登樓後的心情，沒有視線移動。(B)《天工開物》是說理，從人、物到整個世界，反而是由局部推到整體。(D)〈蘭亭集序〉寫宴會的樂趣，是抒情說明，不是視覺聚焦。", "skill": "把句子想成攝影鏡頭：從大景推到特寫，就是「整體到局部」。"}], "difficulty": "易", "label": "115統測", "year": 115, "kind": "統測"}, {"id": "tc115-08", "exam": "tc115", "nums": [8], "form": "單題", "img": "img/tc115-08.png", "source": "《莊子‧養生主》〈庖丁解牛〉、柳宗元〈種樹郭橐駝傳〉", "author": "莊子、柳宗元", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "文惠君曰：「善哉！吾聞庖丁之言，得養生焉。」（〈庖丁解牛〉）／問者嘻曰：「不亦善夫！吾問養樹，得養人術。」（〈種樹郭橐駝傳〉）", "translation": "文惠君說：「好啊！我聽了庖丁的話，懂得了養生的道理。」／發問的人笑著說：「不是很好嗎！我問種樹的方法，卻得到了治理百姓的方法。」", "keywords": [{"w": "游刃有餘", "m": "刀刃在骨節空隙中運轉自如"}, {"w": "順木之天", "m": "順應樹木的天性"}, {"w": "養人術", "m": "治理百姓的方法"}], "questions": [{"n": 8, "qtype": "單選", "stem": "〈庖丁解牛〉的文惠君，因庖丁闡述「游刃有餘」而「得養生焉」；〈種樹郭橐駝傳〉的問者，因郭橐駝闡述「順木之天」而「得養人術」。依據下框，文惠君、問者因聽聞之所得，屬於何種聯想方式？（I.接近聯想 II.相似聯想 III.對比聯想 IV.因果聯想）", "options": {"A": "文惠君、問者皆屬於Ⅱ", "B": "文惠君、問者皆屬於Ⅲ", "C": "文惠君屬於Ⅰ，問者屬於Ⅳ", "D": "文惠君屬於Ⅱ，問者屬於Ⅲ"}, "answer": "A", "explain": "文惠君從「刀順著牛的骨節空隙走、不硬碰」聯想到「人順應自然、避開衝突來保養生命」；問者從「種樹要順著樹的天性、不過度干擾」聯想到「治民也要順應百姓、不擾民」。兩者都是看出兩件事有相似的道理，屬Ⅱ相似聯想，(A)正確。(B)(D)兩件事不是相反性質，不是對比聯想。(C)解牛和養生、種樹和治民並非時空相鄰，也不是誰造成誰的因果關係。", "skill": "「從A悟出B」的寓言，多半是A和B有共同道理，也就是相似聯想。"}], "difficulty": "易", "label": "115統測", "year": 115, "kind": "統測"}, {"id": "tc115-10", "exam": "tc115", "nums": [10], "form": "單題", "img": "img/tc115-10.png", "source": "范五老〈述懷〉", "author": "范五老（越南陳朝）", "genre": "古典詩詞曲", "types": ["典故出處", "詩詞賞析"], "passage": "橫槊江山恰幾秋，三軍貔虎氣吞牛。男兒未了功名債，羞聽人間說武侯。", "translation": "手持長矛守衛江山已經好幾年，三軍將士像猛獸般勇猛，氣勢足以吞下牛。男子漢還沒完成建功立業的心願，聽到世人談論諸葛武侯的功業，就覺得慚愧。", "keywords": [{"w": "槊", "m": "長矛"}, {"w": "橫槊", "m": "橫持長矛；典出曹操「橫槊賦詩」"}, {"w": "貔虎", "m": "猛獸，比喻勇猛的軍隊"}, {"w": "武侯", "m": "諸葛亮，封武鄉侯，死後諡忠武侯"}], "questions": [{"n": 10, "qtype": "單選", "stem": "下列對話______內應填入的是：（「范五老」是我們越南古代的名將，能用漢文寫詩，例如：「橫槊江山恰幾秋，三軍貔虎氣吞牛。男兒未了功名債，羞聽人間說武侯。」這詩真豪邁，還用了關於______的典故。）", "options": {"A": "陶淵明", "B": "范仲淹", "C": "劉邦與項羽", "D": "曹操與諸葛亮"}, "answer": "D", "explain": "「橫槊」出自曹操在長江上「釃酒臨江，橫槊賦詩」（蘇軾〈赤壁賦〉也寫到），「武侯」是諸葛亮的封號，所以是曹操與諸葛亮的典故，(D)正確。(A)陶淵明是田園隱逸的代表，詩中沒有相關用語。(B)范仲淹雖也守過邊，但詩中沒有指向他的詞語，「范五老」的「范」只是同姓。(C)詩中沒有提到劉、項的事蹟。", "skill": "典故題先圈出專有名詞（武侯）和特殊動作（橫槊），再回想課文裡誰做過這件事。"}], "difficulty": "易", "label": "115統測", "year": 115, "kind": "統測"}, {"id": "tc115-19", "exam": "tc115", "nums": [19, 20, 21, 22], "form": "題組", "img": "img/tc115-19.png", "source": "《郁離子》", "author": "劉基", "genre": "寓言故事", "types": ["主旨寓意", "文意推論"], "passage": "鄭之鄙人學為蓋，三年藝成而大旱，蓋無所用，乃棄而為桔槔。又三年藝成而大雨，桔槔無所用，則又還為蓋焉。未幾而盜起，民盡改戎服，鮮有用蓋者。欲學為兵，則老矣。", "translation": "鄭國有個鄉下人學做雨傘，花了三年學成，卻遇上大旱，雨傘沒人要，他就改學做汲水的桔槔。又過三年學成，卻碰上大雨，桔槔沒人用，他又回頭做雨傘。不久盜賊四起，百姓都改穿軍服，很少有人用傘。他想去學當兵，卻已經老了。", "keywords": [{"w": "鄙人", "m": "鄉下人、見識淺的人"}, {"w": "蓋", "m": "雨傘、傘蓋"}, {"w": "桔槔", "m": "利用槓桿原理汲水的工具"}, {"w": "戎服", "m": "軍服"}, {"w": "鮮", "m": "少"}], "questions": [{"n": 19, "qtype": "單選", "stem": "依據上文與右圖，何者最符合鄭國匠人的想法？（右圖：縱軸上為專用技能足以勝任、下為難以勝任；橫軸左為市場需求低、右為市場需求高；①右上、②左上、③左下、④右下）（轉職前，他自認所做的工作屬於：／他希望，轉職後所做的工作屬於：）", "options": {"A": "①／②", "B": "②／①", "C": "③／①", "D": "④／②"}, "answer": "B", "explain": "轉職前：他做傘的手藝已經「藝成」，技能足以勝任，但大旱沒人用傘，市場需求低，屬②。他之所以轉行，是希望去做需求高、又能練到勝任的工作，所以轉職後希望是①。選(B)。(A)把前後顛倒。(C)他轉職前技能並非難以勝任。(D)他轉職前是需求低，轉職後也不會希望需求低。", "skill": "四象限題先替兩條軸各下一個判斷（技能夠不夠？市場要不要？），交叉就能定位。"}, {"n": 20, "qtype": "單選", "stem": "依據上文所述的白圭從商經驗，他最可能提出哪句箴言？", "options": {"A": "買賣虧損時，切忌賭徒式加碼求攤平", "B": "市場氣氛低迷時，潛在的漲幅更可觀", "C": "別想買在最低、賣在最高，要知足常樂", "D": "花錢滿足瞬間欲望，存錢滿足夢想渴望"}, "answer": "B", "explain": "白圭「人棄我取，人取我與」：豐收價低、大家不要時他收購，等市面缺貨再賣出。也就是市場低迷時進場，未來上漲空間大，(B)正確。(A)談的是虧損時別加碼，文中沒提。(C)白圭恰恰是在低點買、高點賣，與「別想買低賣高」相反。(D)談個人消費與儲蓄，和經商策略無關。", "skill": "把古人名言「人棄我取」翻成現代語（別人不要時我買進），再去對應選項。"}, {"n": 21, "qtype": "單選", "stem": "上文農會理事談「時間落後」，主要是想對「與會人員」表達何種觀點？", "options": {"A": "鄭國匠人僅是少數特例，勿以偏概全", "B": "個人造的業，無關老天，勿推諉卸責", "C": "難以當下訊息研判未來，勿後見之明", "D": "學就有用，非有用才學，勿倒因為果"}, "answer": "C", "explain": "農會理事說：農民只能參考上一期價格決定這期種多少，結果常常供需錯開；學技能也要花時間，匠人依當時需求去學，三年後市場已經變了。意思是：用當下的資訊很難預測未來，事後才批評他目光短淺，是後見之明，(C)正確。(A)他反而說這是普遍現象（農民也一樣），不是特例。(B)他是在替匠人說話，不是要他別怪老天。(D)他沒有主張「學就有用」。", "skill": "發言者舉例（農產品）通常是為了類比主角（匠人），找出兩者的共同處就是他的觀點。"}, {"n": 22, "qtype": "單選", "stem": "依據上文，何者最可能是鄭國匠人的「可轉移技能」？①領導力②執行力③人際溝通④學習新知⑤工作流程優化", "options": {"A": "②④", "B": "③⑤", "C": "①②⑤", "D": "②③④"}, "answer": "A", "explain": "匠人每次轉行都能「三年藝成」，說明他有學會新手藝的能力（④學習新知），也能按計畫把事情做完（②執行力），這兩項無論做哪一行都用得上，(A)正確。文中看不出他帶領別人（①領導力）、與人溝通協調（③人際溝通）或改善工作流程（⑤），所以(B)(C)(D)都含有沒有根據的項目。", "skill": "推論人物能力，一定要找到「文中做過的事」當證據，找不到證據的就刪。"}], "difficulty": "中", "label": "115統測", "year": 115, "kind": "統測"}, {"id": "tc115-27", "exam": "tc115", "nums": [27, 28, 29, 30], "form": "題組", "img": "img/tc115-27.png", "source": "陳元靚《事林廣記》、《武經總要》、沈括《夢溪筆談》", "author": "陳元靚、曾公亮等、沈括", "genre": "筆記小品", "types": ["文意推論", "句意理解", "文化常識"], "passage": "指南魚是：「以木刻魚子一個，如姆指大，開腹一竅，陷好磁石一塊子，卻以臘填滿。用針一半僉從魚子口中鉤入，令沒放水中，自然指南。以手撥轉，又復如初。」指南龜是：「以木刻龜子一個，一如前法製造，但於尾邊敲針入去。用小板子，上安以竹釘子，如箸尾大。龜腹下微陷一穴，安釘子上，撥轉常指北，須是釘尾後。」（《事林廣記》）／方家以磁石磨針鋒，則能指南。（《夢溪筆談》）／用薄鐵葉剪裁，長二寸，闊五分，首尾銳如魚形。置炭火中燒之，候通赤，以鐵鈐鈐魚首，出火。以尾正對子位，蘸水盆中，沒尾數分則止。以密器收之。用時，置水碗於無風處，平放魚在水面令浮，其首常南向午也。（《武經總要》）／磁石之指南，……莫可原其理。（《夢溪筆談》）", "translation": "指南魚：用木頭刻一條魚，大約拇指大，在魚腹開一個洞，把磁石嵌進去，再用蠟封滿。拿一根針，一半從魚嘴插進去，把魚放到水中，自然會指向南方；用手撥轉它，又會回到原來方向。指南龜：用木頭刻一隻烏龜，照前面的方法製作，只是把針從尾部敲進去。用一塊小木板，上面裝一根像筷子尾端粗細的竹釘；龜腹下挖一個淺洞，套在竹釘上，撥轉後總是指向北方，而且一定是龜尾所指。方士用磁石磨針尖，針就能指南。武經總要的指南魚：用薄鐵片剪成長二寸、寬五分、頭尾尖尖的魚形，放進炭火裡燒到通紅，用鐵鉗夾住魚頭取出，讓魚尾正對北方（子位），浸入水盆中，淹沒尾部幾分就停，再用密封的容器收起來。使用時，把水碗放在沒風的地方，讓魚平浮在水面，魚頭總會朝向南方（午位）。磁石為什麼會指南……沒有人能推究出其中的道理。", "keywords": [{"w": "陷", "m": "嵌入"}, {"w": "僉", "m": "同「簽」，插入"}, {"w": "箸", "m": "筷子"}, {"w": "通赤", "m": "整個燒紅"}, {"w": "鈐", "m": "鉗子；作動詞為夾住"}, {"w": "子位", "m": "北方"}, {"w": "午", "m": "南方"}, {"w": "原", "m": "推究"}], "questions": [{"n": 27, "qtype": "單選", "stem": "依據上文，右圖兩種指南魚若靜止於預設的方位，方位甲、乙依序為何？（甲：木刻魚子尾端；乙：鐵魚頭端）", "options": {"A": "南；北", "B": "北；南", "C": "南；南", "D": "北；北"}, "answer": "B", "explain": "木刻魚子：針從魚嘴插入，「自然指南」，魚嘴那頭朝南，所以另一端魚尾（甲）朝北。鐵魚：「其首常南向午也」，魚頭（乙）朝南。依序是北、南，選(B)。(A)把兩個方向都弄反了。(C)(D)誤以為兩條魚標示的位置方向相同，沒注意甲標在木魚的尾巴、乙標在鐵魚的頭。", "skill": "圖文方位題先確認標記在「頭」還是「尾」，再用原文「指南」「首南向」推另一端。"}, {"n": 28, "qtype": "單選", "stem": "依據上文，關於《事林廣記》的指南魚、指南龜，何者正確？", "options": {"A": "二者皆如姆指大，釘於筷箸上", "B": "二者皆內嵌磁石，且與磁針並用", "C": "前者用於幻術表演，後者用於占卜問事", "D": "前者以絲線懸於半空，後者以底座撐離桌面"}, "answer": "B", "explain": "指南魚「陷好磁石一塊子」又「用針……鉤入」；指南龜「一如前法製造」，也嵌磁石，再「於尾邊敲針入去」。兩者都嵌磁石又插針，(B)正確。(A)只有指南魚說如拇指大；指南龜是套在「如箸尾大」的竹釘上，不是釘在筷子上。(C)文中說陳元靚把兩者都視為「具表演效果的幻術」，沒有說指南龜用來占卜。(D)指南魚是「放水中」，不是用絲線懸掛。", "skill": "「一如前法製造」這種省略句，要把前面的步驟套進來，才知道兩者有哪些共同點。"}, {"n": 29, "qtype": "單選", "stem": "依據上文所述「當代研究甚多」，這些研究的共同課題為何？", "options": {"A": "是否任何材質所製成的密器，皆能讓鐵片磁化", "B": "是否須選天然磁石所製成的鐵片，才能打造指南魚", "C": "燒紅、冷卻、收入密器諸步驟中，何者影響鐵片磁化", "D": "《夢溪筆談》與《武經總要》，何者對鐵片磁化認識較深"}, "answer": "C", "explain": "三種說法分別認為：對準南北淬火（冷卻）讓鐵片順著地磁磁化；鐵鉗的熱剩磁（燒紅夾出時）造成磁化；密器內置磁石才是關鍵。大家爭論的都是「哪一個步驟讓鐵片有磁性」，(C)正確。(A)只有一種說法談到密器，且沒說任何材質都可以。(B)鐵魚是用薄鐵葉剪成，不是天然磁石。(D)研究沒有比較兩本書誰懂得多。", "skill": "「共同課題」就是幾種說法在爭論的同一個問題，先把每種說法的「主張原因」列出來比對。"}, {"n": 30, "qtype": "單選", "stem": "依據上文，關於①、②兩項推論，最適當的研判是：①古人連接子位和午位的直線，與現今將地球分為南北半球的赤道平行。②古人雖不明白地球磁場，但知道如何讓原本不帶磁性的物質獲得磁性。", "options": {"A": "①、②皆正確", "B": "①、②皆錯誤", "C": "①正確，②錯誤", "D": "①錯誤，②正確"}, "answer": "D", "explain": "①子位是北、午位是南，子午連線是南北向；赤道是東西向，兩者互相垂直，不是平行，①錯。②古人會「以磁石磨針鋒」，也會把鐵片燒紅、淬水來做鐵魚，確實懂得讓不帶磁性的東西變得有磁性；但《夢溪筆談》坦承「莫可原其理」，文末也說不能因此認為古人已認識地磁，所以②正確。選(D)。", "skill": "地支方位要記：子北、午南、卯東、酉西；子午線就是南北線。"}], "difficulty": "難", "label": "115統測", "year": 115, "kind": "統測"}];
window.METHOD="<h2 style=\"margin-top:0\">統測的文言文，其實有跡可循</h2>\n<p>統測的文言文常常和現代生活、產業或圖表放在一起考：一段古文配上一張圖、一則新聞，或是一篇現代文章。題目要你做的，是<b>把古人的想法和眼前的資料連起來</b>。</p>\n<p>好消息是，近年和課文有關的題目越來越多。課本裡的<b>十四篇核心古文</b>讀熟了，很多題目就像遇到老朋友。</p>\n<p>下面七個步驟，每次讀文言文都照著做一遍，做久了就會變成手感。</p>\n\n<h2>讀文言文的七個步驟</h2>\n<div class=\"step\"><div class=\"num\">1</div><div><b>先看題目：知道要找什麼</b><br>先讀題幹和四個選項，再讀文章。把「依據上文」「何者正確／錯誤」「最適當」「無法判斷」這些限制詞圈起來，讀文章時才知道要找什麼。<br><span class=\"meta\">口訣：先看題，再看文，帶著問題去找答案。</span></div></div>\n<div class=\"step\"><div class=\"num\">2</div><div><b>想一想：這是哪一種題目？</b><br>先看題組前的說明和圖表標題，判斷是哪一類：課文延伸、課外古文、古今對讀，還是古文配圖表。如果是學過的課文，先回想它的主旨和作者的立場。<br><span class=\"meta\">口訣：先認題型，再下手。</span></div></div>\n<div class=\"step\"><div class=\"num\">3</div><div><b>切成小段：看到「<span class=\"yue\">曰</span>」、人名就切一刀</b><br>文言句子很長，先切小一點。看到「<span class=\"yue\">曰</span>」（說，不是太陽的「日」）、人名，或句尾的「也、矣、乎、焉」，就畫一條斜線。生難字先圈起來跳過，不要卡住。<br><span class=\"meta\">口訣：見到「<span class=\"yue\">曰</span>」、見到人，就切一刀；不懂先圈，不要停。</span></div></div>\n<div class=\"step\"><div class=\"num\">4</div><div><b>每句都問：這句是「誰」做的？</b><br>文言常把主角省略不寫，這是最容易錯的地方。每一句前面補上「誰」，看到「之」「其」就畫箭頭連回它指的人或事。<br><span class=\"meta\">口訣：每句問誰，沒寫就補。</span></div></div>\n<div class=\"step\"><div class=\"num\">5</div><div><b>整理成一句白話（或一張圖）</b><br>不用逐字翻譯，看懂六七成就能作答。每一段寫成一句「誰＋做了什麼＋結果」。遇到圖表題，就把文章的意思對到圖上的位置，例如哪個象限、哪條線。<br><span class=\"meta\">口訣：抓大放小，一段一句白話。</span></div></div>\n<div class=\"step\"><div class=\"num\">6</div><div><b>逐項找證據，認出陷阱</b><br>每個選項都要指得出「是哪一句說的」。常見陷阱：把人換掉、範圍說太大、感情讀反、只對一半、加進文章沒說的事、時間先後顛倒、虛詞意思偷換。<br><span class=\"meta\">口訣：指不出證據的選項，就不要選。</span></div></div>\n<div class=\"step\"><div class=\"num\">7</div><div><b>回頭驗證，注意時間</b><br>選出答案後，把「題幹＋答案」念一遍，確認和文章一致。統測選擇題每題大約 1.5 分鐘，記得留 30 分鐘以上寫作文。<br><span class=\"meta\">口訣：題幹＋答案念一遍，說得通再作答。</span></div></div>\n\n<h2>課本裡的十四篇核心古文</h2>\n<p>這幾篇常被拿來和課外文章、圖表一起考，至少要知道每篇在講什麼、作者想表達什麼：</p>\n<table>\n<tr><th>篇章</th><th>一句話記住它</th></tr>\n<tr><td>〈燭之武退秦師〉</td><td>一個老臣，靠分析利害說退大軍</td></tr>\n<tr><td>〈庖丁解牛〉</td><td>順著紋理做事，刀用十九年還像新的</td></tr>\n<tr><td>〈蘭亭集序〉</td><td>聚會的快樂，引出人生短暫的感慨</td></tr>\n<tr><td>〈桃花源記〉</td><td>一個找得到、卻回不去的理想世界</td></tr>\n<tr><td>〈師說〉</td><td>誰懂道理，誰就是老師，不分年紀身分</td></tr>\n<tr><td>〈種樹郭橐駝傳〉</td><td>種樹要順著樹的天性，管理人也是</td></tr>\n<tr><td>《夢溪筆談》選</td><td>宋代的科學觀察：鏡子、船塢、指南針</td></tr>\n<tr><td>〈岳陽樓記〉</td><td>先天下之憂而憂，後天下之樂而樂</td></tr>\n<tr><td>〈赤壁賦〉</td><td>從變與不變看人生，放下得失</td></tr>\n<tr><td>《郁離子》選</td><td>用寓言講道理：魯般、鄙人學蓋</td></tr>\n<tr><td>《天工開物》選</td><td>古代的工藝技術：舟車、榨油、造紙</td></tr>\n<tr><td>〈賈探春敏慧興利〉</td><td>探春管理大觀園，把花草變成收入</td></tr>\n<tr><td>〈臺煤減稅片〉</td><td>為臺灣煤礦爭取減稅的奏摺</td></tr>\n<tr><td>〈清代臺灣鐵路買票收費章程〉</td><td>清代臺灣火車的票價與規則</td></tr>\n</table>\n\n<h2>最常掉進去的六個坑</h2>\n<table>\n<tr><th>坑</th><th>長什麼樣子</th><th>怎麼避開</th></tr>\n<tr><td>搞錯是誰做的</td><td>選項把 A 做的事說成 B 做的</td><td>每句補上「誰」；人多就畫人物關係圖</td></tr>\n<tr><td>說得太滿</td><td>文章說「有些」，選項說「全部」；文章沒提，選項卻下了結論</td><td>看到「一定、都、已經不存在」這類字要特別小心</td></tr>\n<tr><td>感情讀反或讀過頭</td><td>作者是無奈，選項說是憤怒；作者淡淡一提，選項說是強烈批判</td><td>找出表達心情的字，看看程度對不對</td></tr>\n<tr><td>只對一半</td><td>選項前半句完全正確，後半句偷偷改掉</td><td>選項要整句檢查，前後兩半都要有證據</td></tr>\n<tr><td>加進文章外的知識</td><td>看到熟悉的名字就自動聯想，例如看到「武侯」就想到楚漢相爭</td><td>只用文章裡給的線索判斷</td></tr>\n<tr><td>虛詞、句式偷換</td><td>「然」「焉」「乃」「既」在不同句子裡意思不同</td><td>把每個可能的意思放回句子，看哪個說得通</td></tr>\n</table>\n\n<h2>怎麼用這個練習場</h2>\n<ul>\n<li><b>剛開始</b>：在「練習」選「單題」加「易」，先找回讀文言文的手感。</li>\n<li><b>練熟了</b>：選「題組」，練習讀一整段文章、搭配圖表作答。</li>\n<li><b>想挑戰</b>：選「難」，這些是最能拉開分數的題目。</li>\n<li><b>做錯了</b>：看解析裡的「解題小撇步」，再到「錯題本」重做一次。錯題本會告訴你最常錯哪一種題型，就多練那一種。</li>\n</ul>\n";
